                                         '# BASIC HELPERS\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def fisher_z(r):\n'
                                         '    r = np.asarray(r, dtype=np.float64)\n'
                                         '    return np.arctanh(np.clip(r, -0.999999, 0.999999))\n'
                                         '\n'
                                         '\n'
                                         'def inv_fisher_z(z):\n'
                                         '    return np.tanh(z)\n'
                                         '\n'
                                         '\n'
                                         'def zscore_1d(x):\n'
                                         '    x = np.asarray(x, dtype=np.float64)\n'
                                         '    mu = np.nanmean(x)\n'
                                         '    sd = np.nanstd(x, ddof=1)\n'
                                         '    if not np.isfinite(sd) or sd == 0:\n'
                                         '        return np.zeros_like(x, dtype=np.float64)\n'
                                         '    return (x - mu) / sd\n'
                                         '\n'
                                         '\n'
                                         'def normalize_subject_id(value):\n'
                                         '    return re.sub(r"\\.0$", "", str(value).strip())\n'
                                         '\n'
                                         '\n'
                                         'def get_subject_id_from_path(path):\n'
                                         '    match = re.search(r"(sub-[A-Za-z0-9]+)", path.name)\n'
                                         '    if match is None:\n'
                                         '        match = re.search(r"(sub-[A-Za-z0-9]+)", str(path))\n'
                                         '    if match is None:\n'
                                         '        raise ValueError(f"Cannot parse subject ID from: {path}")\n'
                                         '    return normalize_subject_id(match.group(1))\n'
                                         '\n'
                                         '\n'
                                         'def assert_unique_ids(ids, label):\n'
                                         '    ids = pd.Series([normalize_subject_id(x) for x in ids])\n'
                                         '    duplicated = ids[ids.duplicated()].unique().tolist()\n'
                                         '    if duplicated:\n'
                                         '        raise ValueError(f"Duplicated subject IDs in {label}: '
                                         '{duplicated[:10]}")\n'
                                         '\n'
                                         '\n'
                                         'def save_json(obj, path):\n'
                                         '    with open(path, "w", encoding="utf-8") as file:\n'
                                         '        json.dump(obj, file, ensure_ascii=False, indent=2)\n'
                                         '\n'
                                         '\n'
                                         'def load_json(path):\n'
                                         '    with open(path, "r", encoding="utf-8") as file:\n'
                                         '        return json.load(file)\n'
                                         '\n'
                                         '\n'
                                         'def safe_quantile(values, probs=(0.025, 0.975)):\n'
                                         '    values = np.asarray(values, dtype=float)\n'
                                         '    values = values[np.isfinite(values)]\n'
                                         '    if len(values) == 0:\n'
                                         '        return np.nan, np.nan\n'
                                         '    return tuple(np.quantile(values, probs))\n'
                                         '\n'
                                         '\n'
                                         'def two_sided_resampling_p(null_values, observed):\n'
                                         '    null_values = np.asarray(null_values, dtype=float)\n'
                                         '    null_values = null_values[np.isfinite(null_values)]\n'
                                         '    if len(null_values) == 0 or not np.isfinite(observed):\n'
                                         '        return np.nan\n'
                                         '    return float(\n'
                                         '        (1 + np.sum(np.abs(null_values) >= abs(observed)))\n'
                                         '        / (len(null_values) + 1)\n'
                                         '    )\n'
                                         '\n'
                                         '\n'
                                         'def upper_tail_resampling_p(null_values, observed):\n'
                                         '    null_values = np.asarray(null_values, dtype=float)\n'
                                         '    null_values = null_values[np.isfinite(null_values)]\n'
                                         '    if len(null_values) == 0 or not np.isfinite(observed):\n'
                                         '        return np.nan\n'
                                         '    return float(\n'
                                         '        (1 + np.sum(null_values >= observed))\n'
                                         '        / (len(null_values) + 1)\n'
                                         '    )\n'
                                         '\n'
                                         '\n'
                                         'def sign_based_p(values):\n'
                                         '    values = np.asarray(values, dtype=float)\n'
                                         '    values = values[np.isfinite(values)]\n'
                                         '    if len(values) == 0:\n'
                                         '        return np.nan\n'
                                         '    p_le = (np.sum(values <= 0) + 1) / (len(values) + 1)\n'
                                         '    p_ge = (np.sum(values >= 0) + 1) / (len(values) + 1)\n'
                                         '    return float(min(1.0, 2.0 * min(p_le, p_ge)))\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def print_section(title, width=108):\n'
                                         '    print("\\n" + "=" * width)\n'
                                         '    print(title)\n'
                                         '    print("=" * width)\n'
                                         '\n'
                                         '\n'
                                         'def format_elapsed(seconds):\n'
                                         '    seconds = max(0.0, float(seconds))\n'
                                         '    if seconds < 60:\n'
                                         '        return f"{seconds:5.1f}s"\n'
                                         '    minutes, seconds = divmod(seconds, 60)\n'
                                         '    if minutes < 60:\n'
                                         '        return f"{int(minutes):02d}:{seconds:04.1f}"\n'
                                         '    hours, minutes = divmod(minutes, 60)\n'
                                         '    return f"{int(hours):02d}:{int(minutes):02d}:{seconds:04.1f}"\n'
                                         '\n'
                                         '\n'
                                         'def print_progress(label, current, total, start_time=None, extra="", '
                                         'done=False):\n'
                                         '    """Update one progress line instead of printing a new line each '
                                         'time."""\n'
                                         '    total = max(int(total), 1)\n'
                                         '    current = int(current)\n'
                                         '    percent = 100.0 * current / total\n'
                                         '\n'
                                         '    timing = ""\n'
                                         '    if start_time is not None:\n'
                                         '        elapsed = time.time() - start_time\n'
                                         '        timing = f" | elapsed={format_elapsed(elapsed)}"\n'
                                         '        if current > 0 and current < total:\n'
                                         '            eta = elapsed * (total - current) / current\n'
                                         '            timing += f" | ETA={format_elapsed(eta)}"\n'
                                         '\n'
                                         '    extra_text = f" | {extra}" if extra else ""\n'
                                         '    message = (\n'
                                         '        f"{label} | {current:,}/{total:,} "\n'
                                         '        f"({percent:6.2f}%)"\n'
                                         '        f"{timing}{extra_text}"\n'
                                         '    )\n'
                                         '\n'
                                         '    # Padding clears characters left over from the previous, longer update.\n'
                                         '    padded = f"{message:<{PROGRESS_LINE_WIDTH}}"\n'
                                         '    print(padded, end="\\n" if done else "\\r", flush=True)\n'
                                         '\n'
                                         '\n'
                                         'def style_axis(axis, grid_axis=None):\n'
                                         '    axis.spines["top"].set_visible(False)\n'
                                         '    axis.spines["right"].set_visible(False)\n'
                                         '    if grid_axis is not None:\n'
                                         '        axis.grid(axis=grid_axis, alpha=GRID_ALPHA, linewidth=0.8)\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# ATLAS / DMN DEFINITION\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def load_atlas():\n'
                                         '    if not SHEN_ATLAS_PATH.exists():\n'
                                         '        raise FileNotFoundError(SHEN_ATLAS_PATH)\n'
                                         '\n'
                                         '    atlas = pd.read_csv(SHEN_ATLAS_PATH)\n'
                                         '    required = ["ROI_num", "NTW"]\n'
                                         '    missing = [column for column in required if column not in '
                                         'atlas.columns]\n'
                                         '    if missing:\n'
                                         '        raise ValueError(\n'
                                         '            f"shen268.csv is missing required columns: {missing}. "\n'
                                         '            f"Available columns: {list(atlas.columns)}"\n'
                                         '        )\n'
                                         '\n'
                                         '    atlas = atlas.copy()\n'
                                         '    atlas["NTW"] = atlas["NTW"].astype(str).str.strip()\n'
                                         '    return atlas\n'
                                         '\n'
                                         '\n'
                                         'def candidate_columns_from_atlas_rows(atlas_rows):\n'
                                         '    candidates = []\n'
                                         '\n'
                                         '    roi_num = (\n'
                                         '        pd.to_numeric(atlas_rows["ROI_num"], errors="coerce")\n'
                                         '        .dropna()\n'
                                         '        .astype(int)\n'
                                         '    )\n'
                                         '\n'
                                         '    # ROI_num may be zero-based or one-based.\n'
                                         '    candidates.append([str(value) for value in roi_num])\n'
                                         '    candidates.append([str(value - 1) for value in roi_num])\n'
                                         '\n'
                                         '    # DataFrame index may correspond to zero-based ROI IDs.\n'
                                         '    candidates.append([str(value) for value in atlas_rows.index])\n'
                                         '    candidates.append([str(value + 1) for value in atlas_rows.index])\n'
                                         '\n'
                                         '    return candidates\n'
                                         '\n'
                                         '\n'
                                         'def resolve_dmn_columns(atlas, neural_columns):\n'
                                         '    neural_columns = [str(column) for column in neural_columns]\n'
                                         '\n'
                                         '    dmn_rows = atlas.loc[\n'
                                         '        atlas["NTW"].astype(str).str.casefold().eq("dmn")\n'
                                         '    ].copy()\n'
                                         '\n'
                                         '    if dmn_rows.empty:\n'
                                         '        raise ValueError("No DMN rows found in shen268.csv.")\n'
                                         '\n'
                                         '    candidates = candidate_columns_from_atlas_rows(dmn_rows)\n'
                                         '    best = max(\n'
                                         '        candidates,\n'
                                         '        key=lambda columns: sum(column in neural_columns for column in '
                                         'columns),\n'
                                         '    )\n'
                                         '    matched = [column for column in best if column in neural_columns]\n'
                                         '\n'
                                         '    if not matched:\n'
                                         '        matched = [\n'
                                         '            str(value)\n'
                                         '            for value in DMN_NODES_FALLBACK_ZERO_BASED\n'
                                         '            if str(value) in neural_columns\n'
                                         '        ]\n'
                                         '\n'
                                         '    if not matched:\n'
                                         '        raise ValueError(\n'
                                         '            "No neural columns matched the DMN definition. "\n'
                                         '            "Check ROI_num indexing and atlas labels."\n'
                                         '        )\n'
                                         '\n'
                                         '    metadata = pd.DataFrame([{\n'
                                         '        "roi": ROI_NAME,\n'
                                         '        "roi_label": ROI_LABELS[ROI_NAME],\n'
                                         '        "n_atlas_rows": len(dmn_rows),\n'
                                         '        "n_matched_columns": len(matched),\n'
                                         '        "matched_columns": ", ".join(matched),\n'
                                         '    }])\n'
                                         '\n'
                                         '    print(\n'
                                         '        f"[ROI MATCH] {ROI_NAME}: "\n'
                                         '        f"{len(matched)} columns -> {matched}"\n'
                                         '    )\n'
                                         '\n'
                                         '    return matched, metadata\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# LOAD DMN NEURAL DATA\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def get_neural_files(movie):\n'
                                         '    if movie in ("movieTP", "movieDM"):\n'
                                         '        files = sorted(\n'
                                         '            DATA_DIR_TPDM.glob(\n'
                                         '                f"sub-*/func/*_{movie}_6mmblur-regression_shen268.csv"\n'
                                         '            )\n'
                                         '        )\n'
                                         '    elif movie == "movieBD":\n'
                                         '        files = sorted(BD_DIR.glob("sub-*_268ROI_shen268.csv"))\n'
                                         '    else:\n'
                                         '        raise ValueError(f"Unknown movie: {movie}")\n'
                                         '\n'
                                         '    files = [path for path in files if not path.name.startswith("._")]\n'
                                         '\n'
                                         '    max_n = MAX_BRAIN_SUBJECTS[movie]\n'
                                         '    if max_n is not None:\n'
                                         '        files = files[:max_n]\n'
                                         '\n'
                                         '    if len(files) < 2:\n'
                                         '        raise ValueError(\n'
                                         '            f"Need at least two neural files for {movie}; found '
                                         '{len(files)}"\n'
                                         '        )\n'
                                         '\n'
                                         '    return files\n'
                                         '\n'
                                         '\n'
                                         'def load_neural_dmn_by_movie(movie, atlas):\n'
                                         '    """Load one whole-DMN mean BOLD time series per participant."""\n'
                                         '    files = get_neural_files(movie)\n'
                                         '\n'
                                         '    first = pd.read_csv(files[0])\n'
                                         '    first.columns = first.columns.astype(str)\n'
                                         '    dmn_columns, roi_metadata = resolve_dmn_columns(atlas, first.columns)\n'
                                         '\n'
                                         '    output = {}\n'
                                         '    load_start = time.time()\n'
                                         '\n'
                                         '    for file_index, path in enumerate(files, start=1):\n'
                                         '        subject_id = get_subject_id_from_path(path)\n'
                                         '        df = pd.read_csv(path)\n'
                                         '        df.columns = df.columns.astype(str)\n'
                                         '\n'
                                         '        missing = [column for column in dmn_columns if column not in '
                                         'df.columns]\n'
                                         '        if missing:\n'
                                         '            raise ValueError(f"{path} is missing DMN columns: '
                                         '{missing[:10]}")\n'
                                         '\n'
                                         '        roi_values = (\n'
                                         '            df[dmn_columns]\n'
                                         '            .apply(pd.to_numeric, errors="coerce")\n'
                                         '            .to_numpy(dtype=np.float64)\n'
                                         '        )\n'
                                         '        whole_dmn_signal = np.nanmean(roi_values, axis=1)\n'
                                         '\n'
                                         '        if subject_id in output:\n'
                                         '            raise ValueError(f"Duplicated neural subject in {movie}: '
                                         '{subject_id}")\n'
                                         '        output[subject_id] = whole_dmn_signal\n'
                                         '\n'
                                         '        if file_index % NEURAL_LOAD_PROGRESS_EVERY == 0 or file_index == '
                                         'len(files):\n'
                                         '            print_progress(\n'
                                         '                label=f"[NEURAL LOAD] {movie}",\n'
                                         '                current=file_index,\n'
                                         '                total=len(files),\n'
                                         '                start_time=load_start,\n'
                                         '                extra="participant loaded",\n'
                                         '                done=(file_index == len(files)),\n'
                                         '            )\n'
                                         '\n'
                                         '    return output, roi_metadata\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def align_neural_dmn(atlas):\n'
                                         '    """Align each neural dataset using matching IDs when supplied.\n'
                                         '\n'
                                         '    No cross-dataset overlap pattern is hard-coded. Repeated participants '
                                         'are\n'
                                         '    identified solely by matching IDs in the local configuration '
                                         '(or,\n'
                                         '    when no list is supplied, by IDs present in the local files).\n'
                                         '    """\n'
                                         '    raw = {}\n'
                                         '    metadata = None\n'
                                         '    for movie in MOVIES:\n'
                                         '        raw[movie], current_metadata = load_neural_dmn_by_movie(movie, '
                                         'atlas)\n'
                                         '        if metadata is None:\n'
                                         '            metadata = current_metadata\n'
                                         '\n'
                                         '    ids = {}\n'
                                         '    whole_matrices = {}\n'
                                         '    master = set()\n'
                                         '    for movie in MOVIES:\n'
                                         '        requested = configured_id_list("neural", movie)\n'
                                         '        selected = select_configured_ids(raw[movie].keys(), requested, '
                                         'f"neural {movie}")\n'
                                         '        ids[movie] = np.asarray(selected, dtype=str)\n'
                                         '        whole_matrices[movie] = np.vstack([raw[movie][sid] for sid in '
                                         'selected])\n'
                                         '        master.update(selected)\n'
                                         '        print(f"[NEURAL ALIGN] {movie}: n={len(selected)}")\n'
                                         '\n'
                                         '    neural_master_ids = np.asarray(sorted(master), dtype=str)\n'
                                         '    print(\n'
                                         '        f"[NEURAL DEPENDENCE] mode={DEPENDENCE_MODE}; "\n'
                                         '        f"master matching units={len(neural_master_ids)}"\n'
                                         '    )\n'
                                         '    return ids, whole_matrices, metadata, neural_master_ids\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# BEHAVIOR AND LOW-LEVEL COVARIATES\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def behavior_path(movie, affect):\n'
                                         '    return BASE_DIR / "behav" / "sISC" / f"merged_{affect}_{movie}.csv"\n'
                                         '\n'
                                         '\n'
                                         'def load_behavior_matrix(movie, affect):\n'
                                         '    path = behavior_path(movie, affect)\n'
                                         '    if not path.exists():\n'
                                         '        raise FileNotFoundError(path)\n'
                                         '\n'
                                         '    df = pd.read_csv(path)\n'
                                         '    if "subject" not in df.columns:\n'
                                         '        raise ValueError(f"\'subject\' column not found in {path}")\n'
                                         '\n'
                                         '    ids = np.asarray(\n'
                                         '        [normalize_subject_id(value) for value in df["subject"]],\n'
                                         '        dtype=str,\n'
                                         '    )\n'
                                         '    assert_unique_ids(ids, f"{movie}-{affect}")\n'
                                         '    values = (\n'
                                         '        df.drop(columns=["subject"])\n'
                                         '        .apply(pd.to_numeric, errors="coerce")\n'
                                         '        .to_numpy(dtype=np.float64)\n'
                                         '    )\n'
                                         '\n'
                                         '    requested = configured_id_list("behavior", movie, affect)\n'
                                         '    if requested is not None:\n'
                                         '        lookup = {sid: i for i, sid in enumerate(ids)}\n'
                                         '        selected = select_configured_ids(ids, requested, f"behavior '
                                         '{movie}-{affect}")\n'
                                         '        row_index = np.asarray([lookup[sid] for sid in selected], '
                                         'dtype=int)\n'
                                         '        ids = np.asarray(selected, dtype=str)\n'
                                         '        values = values[row_index]\n'
                                         '\n'
                                         '    return ids, values\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def load_all_behavior_data():\n'
                                         '    data = {}\n'
                                         '    master_ids = set()\n'
                                         '\n'
                                         '    for movie in MOVIES:\n'
                                         '        data[movie] = {}\n'
                                         '        for affect in AFFECTS:\n'
                                         '            ids, values = load_behavior_matrix(movie, affect)\n'
                                         '            data[movie][affect] = {\n'
                                         '                "subject_ids": ids,\n'
                                         '                "values": values,\n'
                                         '            }\n'
                                         '            master_ids.update(ids.tolist())\n'
                                         '            print(\n'
                                         '                f"[BEHAVIOR] {movie} | {affect}: "\n'
                                         '                f"n={len(ids)}, TR={values.shape[1]}"\n'
                                         '            )\n'
                                         '\n'
                                         '    master_ids = np.asarray(sorted(master_ids), dtype=str)\n'
                                         '    print(f"[BEHAVIOR MASTER] unique raters={len(master_ids)}")\n'
                                         '    return data, master_ids\n'
                                         '\n'
                                         '\n'
                                         'def find_covariate_column(df, target):\n'
                                         '    return next(\n'
                                         '        (\n'
                                         '            column\n'
                                         '            for column in COVARIATE_ALIASES[target]\n'
                                         '            if column in df.columns\n'
                                         '        ),\n'
                                         '        None,\n'
                                         '    )\n'
                                         '\n'
                                         '\n'
                                         'def load_lowlevel_covariates(movie, n_windows):\n'
                                         '    path = (\n'
                                         '        LOWLEVEL_DIR\n'
                                         '        / movie\n'
                                         '        / f"{movie}_window-{WINDOW_SIZE[movie]}TR_step-1TR.csv"\n'
                                         '    )\n'
                                         '\n'
                                         '    if not path.exists():\n'
                                         '        raise FileNotFoundError(path)\n'
                                         '\n'
                                         '    df = pd.read_csv(path)\n'
                                         '    if len(df) < n_windows:\n'
                                         '        raise ValueError(\n'
                                         '            f"Insufficient low-level rows for {movie}: "\n'
                                         '            f"expected {n_windows}, found {len(df)}"\n'
                                         '        )\n'
                                         '\n'
                                         '    df = df.iloc[:n_windows].reset_index(drop=True)\n'
                                         '    output = pd.DataFrame({\n'
                                         '        "movie": movie,\n'
                                         '        "window": np.arange(n_windows),\n'
                                         '    })\n'
                                         '\n'
                                         '    for target in LOWLEVEL_TARGET_COLS:\n'
                                         '        source = find_covariate_column(df, target)\n'
                                         '        if source is None:\n'
                                         '            raise ValueError(\n'
                                         '                f"{target} not found in {path}. "\n'
                                         '                f"Available columns: {list(df.columns)}"\n'
                                         '            )\n'
                                         '        values = pd.to_numeric(df[source], errors="coerce").to_numpy(float)\n'
                                         '        output[target] = zscore_1d(values)\n'
                                         '\n'
                                         '    linear_time = np.linspace(-1, 1, n_windows)\n'
                                         '    output["linear_time"] = linear_time\n'
                                         '    output["quadratic_time"] = zscore_1d(linear_time ** 2)\n'
                                         '\n'
                                         '    return output\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# WINDOW x DISTINCT-PAIR CACHE\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def cache_paths(name):\n'
                                         '    return {\n'
                                         '        "z": CACHE_DIR / f"{name}_pair_z.npy",\n'
                                         '        "valid": CACHE_DIR / f"{name}_pair_valid.npy",\n'
                                         '        "meta": CACHE_DIR / f"{name}_meta.json",\n'
                                         '    }\n'
                                         '\n'
                                         '\n'
                                         'def cache_metadata_matches(meta, ids, n_time, window_size):\n'
                                         '    # Participant identities are intentionally not persisted. '
                                         'Public-release\n'
                                         '    # runs rebuild pairwise caches, so only non-identifying shape checks '
                                         'remain.\n'
                                         '    return (\n'
                                         '        meta.get("n_subjects") == int(len(ids))\n'
                                         '        and meta.get("n_time") == int(n_time)\n'
                                         '        and meta.get("window_size") == int(window_size)\n'
                                         '    )\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def load_cache_arrays(paths, all_valid):\n'
                                         '    mmap_mode = None if LOAD_PAIR_CACHE_TO_RAM else "r"\n'
                                         '    z_values = np.load(paths["z"], mmap_mode=mmap_mode)\n'
                                         '    valid_values = (\n'
                                         '        None\n'
                                         '        if all_valid\n'
                                         '        else np.load(paths["valid"], mmap_mode=mmap_mode)\n'
                                         '    )\n'
                                         '    return z_values, valid_values\n'
                                         '\n'
                                         '\n'
                                         'def compute_pairwise_window_cache(values, ids, window_size, name):\n'
                                         '    """\n'
                                         '    Saves a window x distinct-subject-pair Fisher-z matrix.\n'
                                         '\n'
                                         '    It does not create a dyad x window pandas long table, so memory usage '
                                         'stays\n'
                                         '    manageable while retaining the participant-pair information required '
                                         'for\n'
                                         '    participant-weighted bootstrap means.\n'
                                         '    """\n'
                                         '\n'
                                         '    values = np.asarray(values, dtype=np.float64, order="C")\n'
                                         '    ids = np.asarray(ids, dtype=str)\n'
                                         '\n'
                                         '    n_subjects, n_time = values.shape\n'
                                         '    n_windows = n_time - window_size + 1\n'
                                         '    if n_windows < 1:\n'
                                         '        raise ValueError(f"Window exceeds available time for {name}")\n'
                                         '\n'
                                         '    pair_i, pair_j = np.triu_indices(n_subjects, k=1)\n'
                                         '    n_pairs = len(pair_i)\n'
                                         '    paths = cache_paths(name)\n'
                                         '\n'
                                         '    can_load = (\n'
                                         '        not REBUILD_PAIR_CACHE\n'
                                         '        and all(path.exists() for path in paths.values())\n'
                                         '    )\n'
                                         '\n'
                                         '    if can_load:\n'
                                         '        meta = load_json(paths["meta"])\n'
                                         '        if cache_metadata_matches(meta, ids, n_time, window_size):\n'
                                         '            z_values, valid_values = load_cache_arrays(\n'
                                         '                paths,\n'
                                         '                bool(meta["all_pairs_valid"]),\n'
                                         '            )\n'
                                         '            print(\n'
                                         '                f"[CACHE LOAD] {name}: "\n'
                                         '                f"windows={n_windows}, pairs={n_pairs:,}"\n'
                                         '            )\n'
                                         '            return {\n'
                                         '                "name": name,\n'
                                         '                "subject_ids": ids,\n'
                                         '                "pair_i": pair_i,\n'
                                         '                "pair_j": pair_j,\n'
                                         '                "z": z_values,\n'
                                         '                "valid": valid_values,\n'
                                         '                "all_pairs_valid": bool(meta["all_pairs_valid"]),\n'
                                         '                "n_windows": n_windows,\n'
                                         '                "n_pairs": n_pairs,\n'
                                         '            }\n'
                                         '        warnings.warn(f"Cache metadata mismatch for {name}; rebuilding.")\n'
                                         '\n'
                                         '    z_memmap = np.lib.format.open_memmap(\n'
                                         '        paths["z"],\n'
                                         '        mode="w+",\n'
                                         '        dtype=np.float32,\n'
                                         '        shape=(n_windows, n_pairs),\n'
                                         '    )\n'
                                         '    valid_memmap = np.lib.format.open_memmap(\n'
                                         '        paths["valid"],\n'
                                         '        mode="w+",\n'
                                         '        dtype=np.uint8,\n'
                                         '        shape=(n_windows, n_pairs),\n'
                                         '    )\n'
                                         '\n'
                                         '    all_valid = True\n'
                                         '    cache_start = time.time()\n'
                                         '\n'
                                         '    for window in range(n_windows):\n'
                                         '        x = values[:, window:window + window_size]\n'
                                         '        sd = np.nanstd(x, axis=1, ddof=1)\n'
                                         '        valid_subject = (\n'
                                         '            np.all(np.isfinite(x), axis=1)\n'
                                         '            & np.isfinite(sd)\n'
                                         '            & (sd > 0)\n'
                                         '        )\n'
                                         '\n'
                                         '        z_standardized = np.zeros_like(x, dtype=np.float64)\n'
                                         '        valid_x = x[valid_subject]\n'
                                         '        if len(valid_x):\n'
                                         '            z_standardized[valid_subject] = (\n'
                                         '                valid_x - valid_x.mean(axis=1, keepdims=True)\n'
                                         '            ) / valid_x.std(axis=1, ddof=1, keepdims=True)\n'
                                         '\n'
                                         '        correlation = (z_standardized @ z_standardized.T) / (window_size - '
                                         '1)\n'
                                         '        pair_valid = valid_subject[pair_i] & valid_subject[pair_j]\n'
                                         '\n'
                                         '        row = np.zeros(n_pairs, dtype=np.float32)\n'
                                         '        row[pair_valid] = fisher_z(\n'
                                         '            correlation[pair_i[pair_valid], pair_j[pair_valid]]\n'
                                         '        ).astype(np.float32)\n'
                                         '\n'
                                         '        z_memmap[window] = row\n'
                                         '        valid_memmap[window] = pair_valid.astype(np.uint8)\n'
                                         '        all_valid &= bool(np.all(pair_valid))\n'
                                         '\n'
                                         '        completed = window + 1\n'
                                         '        if (\n'
                                         '            completed % CACHE_PROGRESS_EVERY == 0\n'
                                         '            or completed == n_windows\n'
                                         '        ):\n'
                                         '            print_progress(\n'
                                         '                label=f"[CACHE BUILD] {name}",\n'
                                         '                current=completed,\n'
                                         '                total=n_windows,\n'
                                         '                start_time=cache_start,\n'
                                         '                extra=f"pairs={n_pairs:,}",\n'
                                         '                done=(completed == n_windows),\n'
                                         '            )\n'
                                         '\n'
                                         '    z_memmap.flush()\n'
                                         '    valid_memmap.flush()\n'
                                         '\n'
                                         '    meta = {\n'
                                         '        "name": name,\n'
                                         '        "n_subjects": n_subjects,\n'
                                         '        "n_time": n_time,\n'
                                         '        "window_size": window_size,\n'
                                         '        "n_windows": n_windows,\n'
                                         '        "n_pairs": n_pairs,\n'
                                         '        "all_pairs_valid": bool(all_valid),\n'
                                         '    }\n'
                                         '    save_json(meta, paths["meta"])\n'
                                         '\n'
                                         '    z_values, valid_values = load_cache_arrays(paths, all_valid)\n'
                                         '    print(\n'
                                         '        f"[CACHE READY] {name}: subjects={n_subjects}, "\n'
                                         '        f"pairs={n_pairs:,}, windows={n_windows}, all_valid={all_valid}"\n'
                                         '    )\n'
                                         '\n'
                                         '    return {\n'
                                         '        "name": name,\n'
                                         '        "subject_ids": ids,\n'
                                         '        "pair_i": pair_i,\n'
                                         '        "pair_j": pair_j,\n'
                                         '        "z": z_values,\n'
                                         '        "valid": valid_values,\n'
                                         '        "all_pairs_valid": all_valid,\n'
                                         '        "n_windows": n_windows,\n'
                                         '        "n_pairs": n_pairs,\n'
                                         '    }\n'
                                         '\n'
                                         '\n'
                                         'def weighted_window_mean(cache, participant_weights):\n'
                                         '    """\n'
                                         '    Participant bootstrap counts c_i become distinct-dyad weights c_i*c_j.\n'
                                         '\n'
                                         '    Duplicate bootstrap copies of the same original participant are not '
                                         'treated\n'
                                         '    as a valid self-pair ISC observation.\n'
                                         '    """\n'
                                         '\n'
                                         '    participant_weights = np.asarray(participant_weights, dtype=np.float64)\n'
                                         '    pair_weights = (\n'
                                         '        participant_weights[cache["pair_i"]]\n'
                                         '        * participant_weights[cache["pair_j"]]\n'
                                         '    )\n'
                                         '\n'
                                         '    total_weight = pair_weights.sum()\n'
                                         '    if not np.isfinite(total_weight) or total_weight <= 0:\n'
                                         '        raise ValueError(f"No positive distinct-dyad weight for '
                                         '{cache[\'name\']}")\n'
                                         '\n'
                                         '    pair_weights_32 = pair_weights.astype(np.float32, copy=False)\n'
                                         '    numerator = np.asarray(cache["z"] @ pair_weights_32, dtype=np.float64)\n'
                                         '\n'
                                         '    if cache["all_pairs_valid"]:\n'
                                         '        denominator = np.full(\n'
                                         '            cache["n_windows"],\n'
                                         '            total_weight,\n'
                                         '            dtype=np.float64,\n'
                                         '        )\n'
                                         '    else:\n'
                                         '        denominator = np.asarray(\n'
                                         '            cache["valid"] @ pair_weights_32,\n'
                                         '            dtype=np.float64,\n'
                                         '        )\n'
                                         '\n'
                                         '    with np.errstate(divide="ignore", invalid="ignore"):\n'
                                         '        result = numerator / denominator\n'
                                         '    result[denominator <= 0] = np.nan\n'
                                         '    return result\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# PREPARE DMN CACHES\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def prepare_all_data():\n'
                                         '    atlas = load_atlas()\n'
                                         '    neural_ids, neural_whole_matrices, roi_metadata, neural_master_ids = '
                                         'align_neural_dmn(atlas)\n'
                                         '    behavior_data, behavior_master_ids = load_all_behavior_data()\n'
                                         '\n'
                                         '    roi_metadata.to_csv(OUT_DIR / "DMN_definition_summary.csv", '
                                         'index=False)\n'
                                         '\n'
                                         '    neural_caches = {ROI_NAME: {}}\n'
                                         '    behavior_caches = {movie: {} for movie in MOVIES}\n'
                                         '    covariates = {}\n'
                                         '    n_time_by_movie = {}\n'
                                         '\n'
                                         '    alignment_rows = []\n'
                                         '\n'
                                         '    for movie in MOVIES:\n'
                                         '        # The neural series defines the analysis endpoint.  Behavior and\n'
                                         '        # window-level covariates may be longer, but only their TRAILING '
                                         'excess\n'
                                         '        # is removed.  A shorter behavioral series is an alignment error; '
                                         'the\n'
                                         '        # neural series is never shortened to accommodate it.\n'
                                         '        neural_available_tr = int(neural_whole_matrices[movie].shape[1])\n'
                                         '        neural_reference_tr = int(min(N_TR[movie], neural_available_tr))\n'
                                         '        behavior_lengths = {\n'
                                         '            affect: int(behavior_data[movie][affect]["values"].shape[1])\n'
                                         '            for affect in AFFECTS\n'
                                         '        }\n'
                                         '        too_short = {\n'
                                         '            affect: length for affect, length in behavior_lengths.items()\n'
                                         '            if length < neural_reference_tr\n'
                                         '        }\n'
                                         '        if too_short:\n'
                                         '            raise ValueError(\n'
                                         '                f"{movie}: behavior is shorter than the neural reference "\n'
                                         '                f"({neural_reference_tr} TR): {too_short}. Only trailing "\n'
                                         '                "behavior/covariate trimming is allowed."\n'
                                         '            )\n'
                                         '\n'
                                         '        n_time = neural_reference_tr\n'
                                         '        n_time_by_movie[movie] = int(n_time)\n'
                                         '        neural_caches[ROI_NAME][movie] = compute_pairwise_window_cache(\n'
                                         '            neural_whole_matrices[movie][:, :n_time],\n'
                                         '            neural_ids[movie],\n'
                                         '            WINDOW_SIZE[movie],\n'
                                         '            f"neural_{ROI_NAME}_{movie}",\n'
                                         '        )\n'
                                         '\n'
                                         '        n_windows = int(neural_caches[ROI_NAME][movie]["n_windows"])\n'
                                         '        covariate_path = (\n'
                                         '            LOWLEVEL_DIR / movie /\n'
                                         '            f"{movie}_window-{WINDOW_SIZE[movie]}TR_step-1TR.csv"\n'
                                         '        )\n'
                                         '        covariate_source_rows = int(len(pd.read_csv(covariate_path)))\n'
                                         '        if covariate_source_rows < n_windows:\n'
                                         '            raise ValueError(\n'
                                         '                f"{movie}: covariates have {covariate_source_rows} rows, "\n'
                                         '                f"shorter than neural windows={n_windows}."\n'
                                         '            )\n'
                                         '        covariates[movie] = load_lowlevel_covariates(movie, n_windows)\n'
                                         '\n'
                                         '        row = {\n'
                                         '            "dataset": movie,\n'
                                         '            "policy": "neural windows are reference; trim trailing excess '
                                         'from behavior and covariates only",\n'
                                         '            "neural_available_tr": neural_available_tr,\n'
                                         '            "configured_max_tr": int(N_TR[movie]),\n'
                                         '            "neural_used_tr": int(n_time),\n'
                                         '            "window_size_tr": int(WINDOW_SIZE[movie]),\n'
                                         '            "neural_windows": n_windows,\n'
                                         '            "covariate_source_windows": covariate_source_rows,\n'
                                         '            "covariate_front_dropped_windows": 0,\n'
                                         '            "covariate_tail_dropped_windows": int(covariate_source_rows - '
                                         'n_windows),\n'
                                         '        }\n'
                                         '\n'
                                         '        for affect in AFFECTS:\n'
                                         '            item = behavior_data[movie][affect]\n'
                                         '            behavior_caches[movie][affect] = compute_pairwise_window_cache(\n'
                                         '                item["values"][:, :n_time],\n'
                                         '                item["subject_ids"],\n'
                                         '                WINDOW_SIZE[movie],\n'
                                         '                f"behavior_{movie}_{affect}",\n'
                                         '            )\n'
                                         '            behavior_windows_before = int(\n'
                                         '                behavior_lengths[affect] - WINDOW_SIZE[movie] + 1\n'
                                         '            )\n'
                                         '            if behavior_caches[movie][affect]["n_windows"] != n_windows:\n'
                                         '                raise ValueError(f"Window mismatch: {movie}-{affect}")\n'
                                         '            row[f"behavior_{affect}_source_tr"] = behavior_lengths[affect]\n'
                                         '            row[f"behavior_{affect}_source_windows"] = '
                                         'behavior_windows_before\n'
                                         '            row[f"behavior_{affect}_front_dropped_windows"] = 0\n'
                                         '            row[f"behavior_{affect}_tail_dropped_windows"] = int(\n'
                                         '                behavior_windows_before - n_windows\n'
                                         '            )\n'
                                         '            row[f"behavior_{affect}_used_windows"] = n_windows\n'
                                         '\n'
                                         '        alignment_rows.append(row)\n'
                                         '\n'
                                         '    return {\n'
                                         '        "neural_caches": neural_caches,\n'
                                         '        "behavior_caches": behavior_caches,\n'
                                         '        "neural_master_ids": neural_master_ids,\n'
                                         '        "behavior_master_ids": behavior_master_ids,\n'
                                         '        "covariates": covariates,\n'
                                         '        "n_time_by_movie": n_time_by_movie,\n'
                                         '        "roi_metadata": roi_metadata,\n'
                                         '        "alignment_summary": pd.DataFrame(alignment_rows),\n'
                                         '        "alignment_policy_version": CHEN_ALIGNMENT_POLICY_VERSION,\n'
                                         '    }\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def map_master_weights(master_ids, master_weights, target_ids):\n'
                                         '    mapping = {\n'
                                         '        normalize_subject_id(subject): float(weight)\n'
                                         '        for subject, weight in zip(master_ids, master_weights)\n'
                                         '    }\n'
                                         '    return np.asarray([\n'
                                         '        mapping.get(normalize_subject_id(subject), 0.0)\n'
                                         '        for subject in target_ids\n'
                                         '    ], dtype=np.float64)\n'
                                         '\n'
                                         '\n'
                                         'def standardize_window_table(df):\n'
                                         '    output = df.copy()\n'
                                         '    columns = [\n'
                                         '        "z_neural_ISC",\n'
                                         '        "z_valence_ISC",\n'
                                         '        "z_arousal_ISC",\n'
                                         '    ]\n'
                                         '\n'
                                         '    for column in columns:\n'
                                         '        output[f"raw_{column}"] = output[column]\n'
                                         '        if STANDARDIZE_WITHIN_MOVIE:\n'
                                         '            output[column] = output.groupby(\n'
                                         '                "movie",\n'
                                         '                observed=True,\n'
                                         '            )[column].transform(\n'
                                         '                lambda values: zscore_1d(values.to_numpy(float))\n'
                                         '            )\n'
                                         '\n'
                                         '    return output\n'
                                         '\n'
                                         '\n'
                                         'def build_window_table(\n'
                                         '    prepared,\n'
                                         '    roi_name,\n'
                                         '    neural_weights_by_dataset,\n'
                                         '    behavior_master_weights,\n'
                                         '):\n'
                                         '    """Build the Study 1 window table under independent-modality sampling.\n'
                                         '\n'
                                         '    Neural weights are supplied per dataset. Datasets with identical local\n'
                                         '    matching-ID sets receive the same draw from '
                                         'generate_bootstrap_weight_plan;\n'
                                         '    disjoint neural samples receive independent draws. Behavioral raters use '
                                         'a\n'
                                         '    separate master-ID bootstrap, preserving overlap across '
                                         'datasets/affects.\n'
                                         '    """\n'
                                         '    tables = []\n'
                                         '    for movie in MOVIES:\n'
                                         '        neural_cache = prepared["neural_caches"][roi_name][movie]\n'
                                         '        if movie not in neural_weights_by_dataset:\n'
                                         '            raise KeyError(f"Missing neural weights for {movie}")\n'
                                         '        neural_weights = np.asarray(neural_weights_by_dataset[movie], '
                                         'dtype=float)\n'
                                         '        if len(neural_weights) != len(neural_cache["subject_ids"]):\n'
                                         '            raise ValueError(\n'
                                         '                f"{movie}: neural weight length={len(neural_weights)} does '
                                         'not "\n'
                                         '                f"match n_subjects={len(neural_cache[\'subject_ids\'])}"\n'
                                         '            )\n'
                                         '        neural_z = weighted_window_mean(neural_cache, neural_weights)\n'
                                         '\n'
                                         '        table = prepared["covariates"][movie].copy()\n'
                                         '        table["roi"] = roi_name\n'
                                         '        table["z_neural_ISC"] = neural_z\n'
                                         '        table["neural_ISC_r"] = inv_fisher_z(neural_z)\n'
                                         '\n'
                                         '        for affect in AFFECTS:\n'
                                         '            cache = prepared["behavior_caches"][movie][affect]\n'
                                         '            affect_weights = map_master_weights(\n'
                                         '                prepared["behavior_master_ids"],\n'
                                         '                behavior_master_weights,\n'
                                         '                cache["subject_ids"],\n'
                                         '            )\n'
                                         '            affect_z = weighted_window_mean(cache, affect_weights)\n'
                                         '            table[f"z_{affect}_ISC"] = affect_z\n'
                                         '            table[f"{affect}_ISC_r"] = inv_fisher_z(affect_z)\n'
                                         '        tables.append(table)\n'
                                         '\n'
                                         '    output = pd.concat(tables, ignore_index=True)\n'
                                         '    output["movie"] = pd.Categorical(output["movie"], categories=MOVIES, '
                                         'ordered=False)\n'
                                         '    output = output.sort_values(["movie", "window"]).reset_index(drop=True)\n'
                                         '    return standardize_window_table(output)\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# SEPARATE MARGINAL MODELS\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# SEPARATE MARGINAL MODELS ONLY\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def build_numpy_reduced_design(df):\n'
                                         '    needed = ["z_neural_ISC", "movie", *MODEL_COVARIATES]\n'
                                         '    data = df[needed].dropna().copy()\n'
                                         '\n'
                                         '    movie = data["movie"].astype(str).to_numpy()\n'
                                         '    dm = (movie == "movieDM").astype(float)\n'
                                         '    bd = (movie == "movieBD").astype(float)\n'
                                         '\n'
                                         '    columns = [np.ones(len(data)), dm, bd]\n'
                                         '    names = ["Intercept", "movieDM", "movieBD"]\n'
                                         '\n'
                                         '    for covariate in MODEL_COVARIATES:\n'
                                         '        values = data[covariate].to_numpy(float)\n'
                                         '        columns.extend([values, dm * values, bd * values])\n'
                                         '        names.extend([\n'
                                         '            covariate,\n'
                                         '            f"movieDM:{covariate}",\n'
                                         '            f"movieBD:{covariate}",\n'
                                         '        ])\n'
                                         '\n'
                                         '    return (\n'
                                         '        np.column_stack(columns),\n'
                                         '        data["z_neural_ISC"].to_numpy(float),\n'
                                         '        names,\n'
                                         '        data,\n'
                                         '    )\n'
                                         '\n'
                                         '\n'
                                         'def build_numpy_marginal_design(df, affect):\n'
                                         '    predictor = f"z_{affect}_ISC"\n'
                                         '    needed = ["z_neural_ISC", predictor, "movie", *MODEL_COVARIATES]\n'
                                         '    data = df[needed].dropna().copy()\n'
                                         '\n'
                                         '    movie = data["movie"].astype(str).to_numpy()\n'
                                         '    dm = (movie == "movieDM").astype(float)\n'
                                         '    bd = (movie == "movieBD").astype(float)\n'
                                         '    x = data[predictor].to_numpy(float)\n'
                                         '\n'
                                         '    columns = [np.ones(len(data)), dm, bd, x, dm * x, bd * x]\n'
                                         '    names = [\n'
                                         '        "Intercept",\n'
                                         '        "movieDM",\n'
                                         '        "movieBD",\n'
                                         '        predictor,\n'
                                         '        f"movieDM:{predictor}",\n'
                                         '        f"movieBD:{predictor}",\n'
                                         '    ]\n'
                                         '\n'
                                         '    for covariate in MODEL_COVARIATES:\n'
                                         '        values = data[covariate].to_numpy(float)\n'
                                         '        columns.extend([values, dm * values, bd * values])\n'
                                         '        names.extend([\n'
                                         '            covariate,\n'
                                         '            f"movieDM:{covariate}",\n'
                                         '            f"movieBD:{covariate}",\n'
                                         '        ])\n'
                                         '\n'
                                         '    return (\n'
                                         '        np.column_stack(columns),\n'
                                         '        data["z_neural_ISC"].to_numpy(float),\n'
                                         '        names,\n'
                                         '        data,\n'
                                         '    )\n'
                                         '\n'
                                         '\n'
                                         'def calculate_r_squared(y, fitted, n_parameters):\n'
                                         '    y = np.asarray(y, dtype=float)\n'
                                         '    fitted = np.asarray(fitted, dtype=float)\n'
                                         '    residual = y - fitted\n'
                                         '    sse = float(np.dot(residual, residual))\n'
                                         '    centered = y - np.mean(y)\n'
                                         '    sst = float(np.dot(centered, centered))\n'
                                         '\n'
                                         '    if sst <= 0:\n'
                                         '        return np.nan, np.nan\n'
                                         '\n'
                                         '    r2 = 1.0 - sse / sst\n'
                                         '    n = len(y)\n'
                                         '    adjusted = (\n'
                                         '        np.nan\n'
                                         '        if n <= n_parameters + 1\n'
                                         '        else 1.0 - (1.0 - r2) * (n - 1) / (n - n_parameters)\n'
                                         '    )\n'
                                         '    return float(r2), float(adjusted)\n'
                                         '\n'
                                         '\n'
                                         'def fit_numpy_marginal_effects(df, affect):\n'
                                         '    design, outcome, names, complete_case_data = '
                                         'build_numpy_marginal_design(\n'
                                         '        df, affect\n'
                                         '    )\n'
                                         '    beta, _, rank, _ = np.linalg.lstsq(design, outcome, rcond=None)\n'
                                         '    if rank < design.shape[1]:\n'
                                         '        raise np.linalg.LinAlgError(\n'
                                         '            f"Rank-deficient marginal design for {affect}: "\n'
                                         '            f"{rank}/{design.shape[1]}"\n'
                                         '        )\n'
                                         '\n'
                                         "    # The reduced model must use exactly the full model's complete-case "
                                         'rows.\n'
                                         '    reduced_design, reduced_outcome, _, _ = build_numpy_reduced_design(\n'
                                         '        complete_case_data\n'
                                         '    )\n'
                                         '    if (\n'
                                         '        len(outcome) != len(reduced_outcome)\n'
                                         '        or not np.allclose(outcome, reduced_outcome, equal_nan=True)\n'
                                         '    ):\n'
                                         '        raise ValueError(\n'
                                         '            f"Full and reduced model rows are not aligned for {affect}: "\n'
                                         '            f"full n={len(outcome)}, reduced n={len(reduced_outcome)}"\n'
                                         '        )\n'
                                         '    reduced_beta = np.linalg.lstsq(\n'
                                         '        reduced_design, reduced_outcome, rcond=None\n'
                                         '    )[0]\n'
                                         '\n'
                                         '    index = {name: position for position, name in enumerate(names)}\n'
                                         '    predictor = f"z_{affect}_ISC"\n'
                                         '    tp = beta[index[predictor]]\n'
                                         '    dm = tp + beta[index[f"movieDM:{predictor}"]]\n'
                                         '    bd = tp + beta[index[f"movieBD:{predictor}"]]\n'
                                         '    slopes = np.asarray([tp, dm, bd], dtype=float)\n'
                                         '\n'
                                         '    full_r2, full_adjusted_r2 = calculate_r_squared(\n'
                                         '        outcome, design @ beta, design.shape[1]\n'
                                         '    )\n'
                                         '    reduced_r2, reduced_adjusted_r2 = calculate_r_squared(\n'
                                         '        reduced_outcome,\n'
                                         '        reduced_design @ reduced_beta,\n'
                                         '        reduced_design.shape[1],\n'
                                         '    )\n'
                                         '\n'
                                         '    return {\n'
                                         '        f"marginal_{affect}_movieTP_slope": float(tp),\n'
                                         '        f"marginal_{affect}_movieDM_slope": float(dm),\n'
                                         '        f"marginal_{affect}_movieBD_slope": float(bd),\n'
                                         '        f"marginal_{affect}_pooled_slope": float(np.mean(slopes)),\n'
                                         '        f"marginal_{affect}_heterogeneity": float(\n'
                                         '            np.sum((slopes - np.mean(slopes)) ** 2)\n'
                                         '        ),\n'
                                         '        f"marginal_{affect}_full_r2": full_r2,\n'
                                         '        f"marginal_{affect}_full_adjusted_r2": full_adjusted_r2,\n'
                                         '        f"marginal_{affect}_reduced_r2": reduced_r2,\n'
                                         '        f"marginal_{affect}_reduced_adjusted_r2": reduced_adjusted_r2,\n'
                                         '        f"marginal_{affect}_delta_r2": float(full_r2 - reduced_r2),\n'
                                         '    }\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def build_numpy_conditional_valence_design(df):\n'
                                         '    """\n'
                                         '    Joint model with movie-specific valence and arousal slopes.\n'
                                         '\n'
                                         '    The valence coefficients quantify the unique valence association after\n'
                                         '    controlling for arousal ISC, audiovisual features, and temporal trends.\n'
                                         '    """\n'
                                         '    needed = [\n'
                                         '        "z_neural_ISC",\n'
                                         '        "z_valence_ISC",\n'
                                         '        "z_arousal_ISC",\n'
                                         '        "movie",\n'
                                         '        *MODEL_COVARIATES,\n'
                                         '    ]\n'
                                         '    data = df[needed].dropna().copy()\n'
                                         '\n'
                                         '    movie = data["movie"].astype(str).to_numpy()\n'
                                         '    dm = (movie == "movieDM").astype(float)\n'
                                         '    bd = (movie == "movieBD").astype(float)\n'
                                         '    valence = data["z_valence_ISC"].to_numpy(float)\n'
                                         '    arousal = data["z_arousal_ISC"].to_numpy(float)\n'
                                         '\n'
                                         '    columns = [\n'
                                         '        np.ones(len(data)),\n'
                                         '        dm,\n'
                                         '        bd,\n'
                                         '        valence,\n'
                                         '        dm * valence,\n'
                                         '        bd * valence,\n'
                                         '        arousal,\n'
                                         '        dm * arousal,\n'
                                         '        bd * arousal,\n'
                                         '    ]\n'
                                         '    names = [\n'
                                         '        "Intercept",\n'
                                         '        "movieDM",\n'
                                         '        "movieBD",\n'
                                         '        "z_valence_ISC",\n'
                                         '        "movieDM:z_valence_ISC",\n'
                                         '        "movieBD:z_valence_ISC",\n'
                                         '        "z_arousal_ISC",\n'
                                         '        "movieDM:z_arousal_ISC",\n'
                                         '        "movieBD:z_arousal_ISC",\n'
                                         '    ]\n'
                                         '\n'
                                         '    for covariate in MODEL_COVARIATES:\n'
                                         '        values = data[covariate].to_numpy(float)\n'
                                         '        columns.extend([values, dm * values, bd * values])\n'
                                         '        names.extend([\n'
                                         '            covariate,\n'
                                         '            f"movieDM:{covariate}",\n'
                                         '            f"movieBD:{covariate}",\n'
                                         '        ])\n'
                                         '\n'
                                         '    return (\n'
                                         '        np.column_stack(columns),\n'
                                         '        data["z_neural_ISC"].to_numpy(float),\n'
                                         '        names,\n'
                                         '        data,\n'
                                         '    )\n'
                                         '\n'
                                         '\n'
                                         'def fit_numpy_conditional_valence_effects(df):\n'
                                         '    """Estimate valence slopes conditional on arousal ISC."""\n'
                                         '    design, outcome, names, complete_case_data = (\n'
                                         '        build_numpy_conditional_valence_design(df)\n'
                                         '    )\n'
                                         '    beta, _, rank, _ = np.linalg.lstsq(design, outcome, rcond=None)\n'
                                         '    if rank < design.shape[1]:\n'
                                         '        raise np.linalg.LinAlgError(\n'
                                         '            "Rank-deficient conditional valence design: "\n'
                                         '            f"{rank}/{design.shape[1]}"\n'
                                         '        )\n'
                                         '\n'
                                         '    # Reduced model retains arousal ISC and all covariates. Therefore, the\n'
                                         '    # full-minus-reduced R² is the unique contribution of valence ISC.\n'
                                         '    reduced_design, reduced_outcome, _, _ = build_numpy_marginal_design(\n'
                                         '        complete_case_data,\n'
                                         '        "arousal",\n'
                                         '    )\n'
                                         '    if (\n'
                                         '        len(outcome) != len(reduced_outcome)\n'
                                         '        or not np.allclose(outcome, reduced_outcome, equal_nan=True)\n'
                                         '    ):\n'
                                         '        raise ValueError(\n'
                                         '            "Full and arousal-control reduced model rows are not aligned: "\n'
                                         '            f"full n={len(outcome)}, reduced n={len(reduced_outcome)}"\n'
                                         '        )\n'
                                         '    reduced_beta = np.linalg.lstsq(\n'
                                         '        reduced_design,\n'
                                         '        reduced_outcome,\n'
                                         '        rcond=None,\n'
                                         '    )[0]\n'
                                         '\n'
                                         '    index = {name: position for position, name in enumerate(names)}\n'
                                         '    tp = beta[index["z_valence_ISC"]]\n'
                                         '    dm = tp + beta[index["movieDM:z_valence_ISC"]]\n'
                                         '    bd = tp + beta[index["movieBD:z_valence_ISC"]]\n'
                                         '    slopes = np.asarray([tp, dm, bd], dtype=float)\n'
                                         '\n'
                                         '    full_r2, full_adjusted_r2 = calculate_r_squared(\n'
                                         '        outcome,\n'
                                         '        design @ beta,\n'
                                         '        design.shape[1],\n'
                                         '    )\n'
                                         '    reduced_r2, reduced_adjusted_r2 = calculate_r_squared(\n'
                                         '        reduced_outcome,\n'
                                         '        reduced_design @ reduced_beta,\n'
                                         '        reduced_design.shape[1],\n'
                                         '    )\n'
                                         '\n'
                                         '    prefix = "conditional_valence_given_arousal"\n'
                                         '    return {\n'
                                         '        f"{prefix}_movieTP_slope": float(tp),\n'
                                         '        f"{prefix}_movieDM_slope": float(dm),\n'
                                         '        f"{prefix}_movieBD_slope": float(bd),\n'
                                         '        f"{prefix}_pooled_slope": float(np.mean(slopes)),\n'
                                         '        f"{prefix}_heterogeneity": float(\n'
                                         '            np.sum((slopes - np.mean(slopes)) ** 2)\n'
                                         '        ),\n'
                                         '        f"{prefix}_full_r2": full_r2,\n'
                                         '        f"{prefix}_full_adjusted_r2": full_adjusted_r2,\n'
                                         '        f"{prefix}_reduced_r2": reduced_r2,\n'
                                         '        f"{prefix}_reduced_adjusted_r2": reduced_adjusted_r2,\n'
                                         '        f"{prefix}_delta_r2": float(full_r2 - reduced_r2),\n'
                                         '    }\n'
                                         '\n'
                                         '\n'
                                         'def add_valence_arousal_contrasts(metrics, include_delta_r2=False):\n'
                                         '    for movie in MOVIES:\n'
                                         '        metrics[f"marginal_valence_minus_arousal_{movie}_slope"] = (\n'
                                         '            metrics[f"marginal_valence_{movie}_slope"]\n'
                                         '            - metrics[f"marginal_arousal_{movie}_slope"]\n'
                                         '        )\n'
                                         '    metrics["marginal_valence_minus_arousal_pooled_slope"] = (\n'
                                         '        metrics["marginal_valence_pooled_slope"]\n'
                                         '        - metrics["marginal_arousal_pooled_slope"]\n'
                                         '    )\n'
                                         '    if include_delta_r2:\n'
                                         '        metrics["marginal_valence_minus_arousal_delta_r2"] = (\n'
                                         '            metrics["marginal_valence_delta_r2"]\n'
                                         '            - metrics["marginal_arousal_delta_r2"]\n'
                                         '        )\n'
                                         '    return metrics\n'
                                         '\n'
                                         '\n'
                                         'def fit_all_effects(df):\n'
                                         '    output = {}\n'
                                         '    for affect in AFFECTS:\n'
                                         '        output.update(fit_numpy_marginal_effects(df, affect))\n'
                                         '    output.update(fit_numpy_conditional_valence_effects(df))\n'
                                         '    add_valence_arousal_contrasts(output, include_delta_r2=True)\n'
                                         '    return output\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# ACF-PRESERVING TEMPORAL PERMUTATION\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def estimate_block_length_from_acf(values, threshold=0.10):\n'
                                         '    values = np.asarray(values, dtype=float)\n'
                                         '    values = values[np.isfinite(values)]\n'
                                         '    n = len(values)\n'
                                         '    if n < 3:\n'
                                         '        return max(1, n)\n'
                                         '    values = values - np.mean(values)\n'
                                         '    denominator = np.sum(values ** 2)\n'
                                         '    if denominator <= 0 or not np.isfinite(denominator):\n'
                                         '        return n\n'
                                         '    for lag in range(1, n):\n'
                                         '        acf_lag = np.sum(values[:-lag] * values[lag:]) / denominator\n'
                                         '        if abs(acf_lag) < threshold:\n'
                                         '            return lag\n'
                                         '    return n\n'
                                         '\n'
                                         '\n'
                                         'def choose_block_lengths(observed_df):\n'
                                         '    rows = []\n'
                                         '    result = {}\n'
                                         '    for movie in MOVIES:\n'
                                         '        subset = observed_df.loc[observed_df["movie"].eq(movie)]\n'
                                         '        estimated = {\n'
                                         '            affect: estimate_block_length_from_acf(\n'
                                         '                subset[f"z_{affect}_ISC"].to_numpy(float),\n'
                                         '                threshold=ACF_THRESHOLD,\n'
                                         '            )\n'
                                         '            for affect in AFFECTS\n'
                                         '        }\n'
                                         '        estimated_max = max(estimated.values())\n'
                                         '        configured = FIXED_BLOCK_LEN_BY_MOVIE.get(movie)\n'
                                         '        final = estimated_max if configured is None else int(configured)\n'
                                         '        final = max(1, min(final, len(subset) - 1))\n'
                                         '        result[movie] = final\n'
                                         '        rows.append({\n'
                                         '            "movie": movie,\n'
                                         '            **{f"{affect}_acf_lag": estimated[affect] for affect in '
                                         'AFFECTS},\n'
                                         '            "estimated_max_lag": estimated_max,\n'
                                         '            "configured_block_len": configured,\n'
                                         '            "final_block_len": final,\n'
                                         '        })\n'
                                         '    summary = pd.DataFrame(rows)\n'
                                         '    summary.to_csv(OUT_DIR / "Study1_acf_block_length_summary.csv", '
                                         'index=False)\n'
                                         '    return result, summary\n'
                                         '\n'
                                         '\n'
                                         'def block_permutation_indices(n, block_len, block_order):\n'
                                         '    """Concatenate intact temporal blocks in a genuinely random order."""\n'
                                         '    blocks = [\n'
                                         '        np.arange(start, min(start + block_len, n))\n'
                                         '        for start in range(0, n, block_len)\n'
                                         '    ]\n'
                                         '    order = np.asarray(block_order, dtype=int)\n'
                                         '    if len(order) != len(blocks):\n'
                                         '        raise ValueError(f"Block-order length mismatch: {len(order)} vs '
                                         '{len(blocks)}")\n'
                                         '    return np.concatenate([blocks[index] for index in order])\n'
                                         '\n'
                                         '\n'
                                         'def generate_permutation_plan(block_lengths, n_windows_by_movie):\n'
                                         '    path = DRAW_DIR / "Study1_block_order_permutation_plan.npz"\n'
                                         '    metadata_path = DRAW_DIR / "Study1_block_order_permutation_plan.json"\n'
                                         '    n_blocks = {\n'
                                         '        movie: math.ceil(n_windows_by_movie[movie] / block_lengths[movie])\n'
                                         '        for movie in MOVIES\n'
                                         '    }\n'
                                         '    expected_metadata = {\n'
                                         '        "method": "random_block_order",\n'
                                         '        "n_permutations": int(N_PERMUTATIONS),\n'
                                         '        "seed": int(RANDOM_SEED + 20000),\n'
                                         '        "block_lengths": {movie: int(value) for movie, value in '
                                         'block_lengths.items()},\n'
                                         '        "n_windows_by_movie": {\n'
                                         '            movie: int(value) for movie, value in '
                                         'n_windows_by_movie.items()\n'
                                         '        },\n'
                                         '        "n_blocks": {movie: int(value) for movie, value in '
                                         'n_blocks.items()},\n'
                                         '    }\n'
                                         '    if path.exists() and metadata_path.exists() and RESUME_RESAMPLING:\n'
                                         '        metadata = load_json(metadata_path)\n'
                                         '        if metadata == expected_metadata:\n'
                                         '            loaded = np.load(path)\n'
                                         '            plan = {movie: loaded[movie] for movie in MOVIES}\n'
                                         '            if all(\n'
                                         '                plan[movie].shape == (N_PERMUTATIONS, n_blocks[movie])\n'
                                         '                for movie in MOVIES\n'
                                         '            ):\n'
                                         '                print(f"[PERM PLAN LOAD] {path}")\n'
                                         '                return plan\n'
                                         '\n'
                                         '    rng = np.random.default_rng(RANDOM_SEED + 20000)\n'
                                         '    plan = {}\n'
                                         '    for movie in MOVIES:\n'
                                         '        identity = np.arange(n_blocks[movie], dtype=np.int16)\n'
                                         '        orders = np.empty((N_PERMUTATIONS, n_blocks[movie]), '
                                         'dtype=np.int16)\n'
                                         '        for index in range(N_PERMUTATIONS):\n'
                                         '            order = rng.permutation(n_blocks[movie]).astype(np.int16)\n'
                                         '            while np.array_equal(order, identity):\n'
                                         '                order = rng.permutation(n_blocks[movie]).astype(np.int16)\n'
                                         '            orders[index] = order\n'
                                         '        plan[movie] = orders\n'
                                         '    np.savez_compressed(path, **plan)\n'
                                         '    save_json(expected_metadata, metadata_path)\n'
                                         '    print(f"[PERM PLAN SAVED] {path}")\n'
                                         '    return plan\n'
                                         '\n'
                                         '\n'
                                         'def residualize_vector(values, covariates):\n'
                                         '    values = np.asarray(values, dtype=float)\n'
                                         '    covariates = np.asarray(covariates, dtype=float)\n'
                                         '    valid = np.isfinite(values) & np.all(np.isfinite(covariates), axis=1)\n'
                                         '    output = np.full(len(values), np.nan, dtype=float)\n'
                                         '    if valid.sum() < 3:\n'
                                         '        return output\n'
                                         '    c = covariates[valid]\n'
                                         '    means = np.mean(c, axis=0)\n'
                                         '    sds = np.std(c, axis=0, ddof=1)\n'
                                         '    keep = np.isfinite(sds) & (sds > 0)\n'
                                         '    c = (c[:, keep] - means[keep]) / sds[keep]\n'
                                         '    design = np.column_stack([np.ones(valid.sum()), c])\n'
                                         '    beta = np.linalg.lstsq(design, values[valid], rcond=None)[0]\n'
                                         '    output[valid] = values[valid] - design @ beta\n'
                                         '    return output\n'
                                         '\n'
                                         '\n'
                                         'def prepare_partial_series_for_permutation(df):\n'
                                         '    """\n'
                                         '    Prepare Frisch-Waugh-Lovell residual series for temporal permutation.\n'
                                         '\n'
                                         '    Marginal models residualize neural and affect ISC on audiovisual/time\n'
                                         '    covariates. The conditional valence model additionally residualizes '
                                         'both\n'
                                         '    neural ISC and valence ISC on arousal ISC.\n'
                                         '    """\n'
                                         '    prepared = {\n'
                                         '        "marginal": {affect: {} for affect in AFFECTS},\n'
                                         '        "conditional_valence": {},\n'
                                         '    }\n'
                                         '\n'
                                         '    for movie in MOVIES:\n'
                                         '        subset = (\n'
                                         '            df.loc[df["movie"].eq(movie)]\n'
                                         '            .sort_values("window")\n'
                                         '            .reset_index(drop=True)\n'
                                         '        )\n'
                                         '        base_covariates = subset[MODEL_COVARIATES].to_numpy(float)\n'
                                         '        neural = subset["z_neural_ISC"].to_numpy(float)\n'
                                         '\n'
                                         '        y_marginal = residualize_vector(neural, base_covariates)\n'
                                         '        for affect in AFFECTS:\n'
                                         '            x_marginal = residualize_vector(\n'
                                         '                subset[f"z_{affect}_ISC"].to_numpy(float),\n'
                                         '                base_covariates,\n'
                                         '            )\n'
                                         '            valid = np.isfinite(y_marginal) & np.isfinite(x_marginal)\n'
                                         '            prepared["marginal"][affect][movie] = {\n'
                                         '                "y": y_marginal[valid],\n'
                                         '                "x": x_marginal[valid],\n'
                                         '            }\n'
                                         '\n'
                                         '        conditional_controls = np.column_stack([\n'
                                         '            base_covariates,\n'
                                         '            subset["z_arousal_ISC"].to_numpy(float),\n'
                                         '        ])\n'
                                         '        y_conditional = residualize_vector(neural, conditional_controls)\n'
                                         '        x_conditional = residualize_vector(\n'
                                         '            subset["z_valence_ISC"].to_numpy(float),\n'
                                         '            conditional_controls,\n'
                                         '        )\n'
                                         '        valid = np.isfinite(y_conditional) & np.isfinite(x_conditional)\n'
                                         '        prepared["conditional_valence"][movie] = {\n'
                                         '            "y": y_conditional[valid],\n'
                                         '            "x": x_conditional[valid],\n'
                                         '        }\n'
                                         '\n'
                                         '    return prepared\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def residual_marginal_metrics(partial_series, shifted_x):\n'
                                         '    slopes = []\n'
                                         '    partial_r2 = []\n'
                                         '    for movie in MOVIES:\n'
                                         '        y = partial_series[movie]["y"]\n'
                                         '        x = shifted_x[movie]\n'
                                         '        denominator = float(np.dot(x, x))\n'
                                         '        slope = np.nan if denominator <= 0 else float(np.dot(x, y) / '
                                         'denominator)\n'
                                         '        slopes.append(slope)\n'
                                         '        if np.nanstd(x, ddof=1) == 0 or np.nanstd(y, ddof=1) == 0:\n'
                                         '            partial_r2.append(np.nan)\n'
                                         '        else:\n'
                                         '            r = float(np.corrcoef(x, y)[0, 1])\n'
                                         '            partial_r2.append(r ** 2)\n'
                                         '\n'
                                         '    slopes = np.asarray(slopes, dtype=float)\n'
                                         '    partial_r2 = np.asarray(partial_r2, dtype=float)\n'
                                         '    output = {}\n'
                                         '    for movie, slope, r2 in zip(MOVIES, slopes, partial_r2):\n'
                                         '        output[f"{movie}_slope"] = float(slope)\n'
                                         '        output[f"{movie}_partial_r2"] = float(r2)\n'
                                         '    output.update({\n'
                                         '        "pooled_slope": float(np.mean(slopes)),\n'
                                         '        "heterogeneity": float(np.sum((slopes - np.mean(slopes)) ** 2)),\n'
                                         '        "pooled_partial_r2": float(np.nanmean(partial_r2)),\n'
                                         '    })\n'
                                         '    return output\n'
                                         '\n'
                                         '\n'
                                         'PERMUTATION_METRICS = []\n'
                                         'for _affect in AFFECTS:\n'
                                         '    for _movie in MOVIES:\n'
                                         '        PERMUTATION_METRICS.extend([\n'
                                         '            f"marginal_{_affect}_{_movie}_slope",\n'
                                         '            f"marginal_{_affect}_{_movie}_partial_r2",\n'
                                         '        ])\n'
                                         '    PERMUTATION_METRICS.extend([\n'
                                         '        f"marginal_{_affect}_pooled_slope",\n'
                                         '        f"marginal_{_affect}_heterogeneity",\n'
                                         '        f"marginal_{_affect}_pooled_partial_r2",\n'
                                         '    ])\n'
                                         '\n'
                                         'for _movie in MOVIES:\n'
                                         '    PERMUTATION_METRICS.extend([\n'
                                         '        f"conditional_valence_given_arousal_{_movie}_slope",\n'
                                         '        f"conditional_valence_given_arousal_{_movie}_partial_r2",\n'
                                         '    ])\n'
                                         'PERMUTATION_METRICS.extend([\n'
                                         '    "conditional_valence_given_arousal_pooled_slope",\n'
                                         '    "conditional_valence_given_arousal_heterogeneity",\n'
                                         '    "conditional_valence_given_arousal_pooled_partial_r2",\n'
                                         '])\n'
                                         '\n'
                                         'for _movie in MOVIES:\n'
                                         '    PERMUTATION_METRICS.append(\n'
                                         '        f"marginal_valence_minus_arousal_{_movie}_slope"\n'
                                         '    )\n'
                                         'PERMUTATION_METRICS.append("marginal_valence_minus_arousal_pooled_slope")\n'
                                         '\n'
                                         'def permutation_draw_paths():\n'
                                         '    return {\n'
                                         '        "draws": DRAW_DIR / '
                                         '"Study1_block_order_permutation_draws_joint_v3.npy",\n'
                                         '        "progress": DRAW_DIR / '
                                         '"Study1_block_order_permutation_progress_joint_v3.json",\n'
                                         '        "metrics": DRAW_DIR / '
                                         '"Study1_block_order_permutation_metrics_joint_v3.json",\n'
                                         '    }\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def run_temporal_permutation(observed_df, block_lengths, permutation_plan):\n'
                                         '    partial = prepare_partial_series_for_permutation(observed_df)\n'
                                         '\n'
                                         '    observed_metrics = {}\n'
                                         '    for affect in AFFECTS:\n'
                                         '        original = {\n'
                                         '            movie: partial["marginal"][affect][movie]["x"]\n'
                                         '            for movie in MOVIES\n'
                                         '        }\n'
                                         '        metrics = residual_marginal_metrics(\n'
                                         '            partial["marginal"][affect],\n'
                                         '            original,\n'
                                         '        )\n'
                                         '        for key, value in metrics.items():\n'
                                         '            observed_metrics[f"marginal_{affect}_{key}"] = value\n'
                                         '\n'
                                         '    conditional_original = {\n'
                                         '        movie: partial["conditional_valence"][movie]["x"]\n'
                                         '        for movie in MOVIES\n'
                                         '    }\n'
                                         '    conditional_metrics = residual_marginal_metrics(\n'
                                         '        partial["conditional_valence"],\n'
                                         '        conditional_original,\n'
                                         '    )\n'
                                         '    for key, value in conditional_metrics.items():\n'
                                         '        observed_metrics[\n'
                                         '            f"conditional_valence_given_arousal_{key}"\n'
                                         '        ] = value\n'
                                         '\n'
                                         '    add_valence_arousal_contrasts(observed_metrics)\n'
                                         '\n'
                                         '    paths = permutation_draw_paths()\n'
                                         '    n_metrics = len(PERMUTATION_METRICS)\n'
                                         '    start_index = 0\n'
                                         '    if (\n'
                                         '        RESUME_RESAMPLING\n'
                                         '        and paths["draws"].exists()\n'
                                         '        and paths["progress"].exists()\n'
                                         '        and paths["metrics"].exists()\n'
                                         '        and load_json(paths["metrics"]) == PERMUTATION_METRICS\n'
                                         '    ):\n'
                                         '        draws = np.lib.format.open_memmap(\n'
                                         '            paths["draws"],\n'
                                         '            mode="r+",\n'
                                         '            dtype=np.float64,\n'
                                         '            shape=(N_PERMUTATIONS, n_metrics),\n'
                                         '        )\n'
                                         '        start_index = int(load_json(paths["progress"]).get("completed", 0))\n'
                                         '        print(f"[PERM RESUME] starting at {start_index}")\n'
                                         '    else:\n'
                                         '        draws = np.lib.format.open_memmap(\n'
                                         '            paths["draws"],\n'
                                         '            mode="w+",\n'
                                         '            dtype=np.float64,\n'
                                         '            shape=(N_PERMUTATIONS, n_metrics),\n'
                                         '        )\n'
                                         '        save_json(PERMUTATION_METRICS, paths["metrics"])\n'
                                         '        save_json({"completed": 0}, paths["progress"])\n'
                                         '\n'
                                         '    start = time.time()\n'
                                         '    for permutation_index in range(start_index, N_PERMUTATIONS):\n'
                                         '        current = {}\n'
                                         '\n'
                                         '        for affect in AFFECTS:\n'
                                         '            shifted = {}\n'
                                         '            for movie in MOVIES:\n'
                                         '                n = len(partial["marginal"][affect][movie]["y"])\n'
                                         '                indices = block_permutation_indices(\n'
                                         '                    n,\n'
                                         '                    block_lengths[movie],\n'
                                         '                    permutation_plan[movie][permutation_index],\n'
                                         '                )\n'
                                         '                shifted[movie] = '
                                         'partial["marginal"][affect][movie]["x"][indices]\n'
                                         '            metrics = residual_marginal_metrics(\n'
                                         '                partial["marginal"][affect],\n'
                                         '                shifted,\n'
                                         '            )\n'
                                         '            for key, value in metrics.items():\n'
                                         '                current[f"marginal_{affect}_{key}"] = value\n'
                                         '\n'
                                         '        shifted_conditional = {}\n'
                                         '        for movie in MOVIES:\n'
                                         '            n = len(partial["conditional_valence"][movie]["y"])\n'
                                         '            indices = block_permutation_indices(\n'
                                         '                n,\n'
                                         '                block_lengths[movie],\n'
                                         '                permutation_plan[movie][permutation_index],\n'
                                         '            )\n'
                                         '            shifted_conditional[movie] = (\n'
                                         '                partial["conditional_valence"][movie]["x"][indices]\n'
                                         '            )\n'
                                         '        metrics = residual_marginal_metrics(\n'
                                         '            partial["conditional_valence"],\n'
                                         '            shifted_conditional,\n'
                                         '        )\n'
                                         '        for key, value in metrics.items():\n'
                                         '            current[f"conditional_valence_given_arousal_{key}"] = value\n'
                                         '\n'
                                         '        add_valence_arousal_contrasts(current)\n'
                                         '\n'
                                         '        draws[permutation_index] = [\n'
                                         '            current[metric] for metric in PERMUTATION_METRICS\n'
                                         '        ]\n'
                                         '        completed = permutation_index + 1\n'
                                         '        if completed % CHECKPOINT_EVERY == 0 or completed == '
                                         'N_PERMUTATIONS:\n'
                                         '            draws.flush()\n'
                                         '            save_json({"completed": completed}, paths["progress"])\n'
                                         '        if completed % PERM_PROGRESS_EVERY == 0 or completed == '
                                         'N_PERMUTATIONS:\n'
                                         '            print_progress(\n'
                                         '                "[STUDY 1 TEMPORAL PERMUTATION]",\n'
                                         '                completed,\n'
                                         '                N_PERMUTATIONS,\n'
                                         '                start_time=start,\n'
                                         '                extra=(\n'
                                         '                    f"marginal valence="\n'
                                         '                    f"{current[\'marginal_valence_pooled_slope\']:+.3f}, "\n'
                                         '                    f"conditional valence="\n'
                                         '                    '
                                         'f"{current[\'conditional_valence_given_arousal_pooled_slope\']:+.3f}"\n'
                                         '                ),\n'
                                         '                done=(completed == N_PERMUTATIONS),\n'
                                         '            )\n'
                                         '\n'
                                         '    draws_array = np.asarray(draws)\n'
                                         '    rows = []\n'
                                         '    for metric_index, metric in enumerate(PERMUTATION_METRICS):\n'
                                         '        null_values = draws_array[:, metric_index]\n'
                                         '        observed = float(observed_metrics[metric])\n'
                                         '        if metric.endswith("partial_r2") or '
                                         'metric.endswith("heterogeneity"):\n'
                                         '            p_value = upper_tail_resampling_p(null_values, observed)\n'
                                         '            tail = "upper"\n'
                                         '        else:\n'
                                         '            p_value = two_sided_resampling_p(null_values, observed)\n'
                                         '            tail = "two-sided"\n'
                                         '        null_low, null_high = safe_quantile(null_values)\n'
                                         '        rows.append({\n'
                                         '            "effect": metric,\n'
                                         '            "observed_estimate": observed,\n'
                                         '            "p_perm": p_value,\n'
                                         '            "permutation_tail": tail,\n'
                                         '            "null_mean": float(np.nanmean(null_values)),\n'
                                         '            "null_sd": float(np.nanstd(null_values, ddof=1)),\n'
                                         '            "null_q025": null_low,\n'
                                         '            "null_q975": null_high,\n'
                                         '            "n_permutations": int(np.isfinite(null_values).sum()),\n'
                                         '        })\n'
                                         '\n'
                                         '    summary = pd.DataFrame(rows)\n'
                                         '    summary.to_csv(\n'
                                         '        OUT_DIR / '
                                         '"Study1_block_order_permutation_summary_joint_valence.csv",\n'
                                         '        index=False,\n'
                                         '    )\n'
                                         '    return observed_metrics, draws_array, summary\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# PARTICIPANT BOOTSTRAP\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def draw_multinomial_weights(rng, n_subjects):\n'
                                         '    while True:\n'
                                         '        counts = rng.multinomial(\n'
                                         '            n_subjects, np.full(n_subjects, 1.0 / n_subjects)\n'
                                         '        ).astype(np.int16)\n'
                                         '        if np.count_nonzero(counts) >= 2:\n'
                                         '            return counts\n'
                                         '\n'
                                         '\n'
                                         'def generate_bootstrap_weight_plan(prepared):\n'
                                         '    """Build dependency-aware dependency-aware bootstrap plans.\n'
                                         '\n'
                                         '    Neural datasets are grouped at runtime from their matching IDs:\n'
                                         '    datasets with identical participant sets share one multinomial draw, '
                                         'while\n'
                                         '    disjoint sets are resampled independently. A partial-but-not-identical\n'
                                         '    neural overlap is rejected because that design requires an explicitly\n'
                                         '    specified coupling rule rather than a silent approximation.\n'
                                         '\n'
                                         '    Behavioral participants are sampled from a separate master-ID '
                                         'namespace,\n'
                                         '    matching the independent neural/behavioral design.\n'
                                         '    """\n'
                                         '    path = DRAW_DIR / "Study1_participant_bootstrap_weights.npz"\n'
                                         '    metadata_path = DRAW_DIR / "Study1_participant_bootstrap_weights.json"\n'
                                         '\n'
                                         '    dataset_ids = {\n'
                                         '        movie: np.asarray(\n'
                                         '            prepared["neural_caches"][ROI_NAME][movie]["subject_ids"], '
                                         'dtype=str\n'
                                         '        )\n'
                                         '        for movie in MOVIES\n'
                                         '    }\n'
                                         '    # Reject ambiguous partial overlap while revealing no participant '
                                         'labels.\n'
                                         '    for i, left in enumerate(MOVIES):\n'
                                         '        left_set = set(dataset_ids[left])\n'
                                         '        for right in MOVIES[i + 1:]:\n'
                                         '            right_set = set(dataset_ids[right])\n'
                                         '            overlap = left_set & right_set\n'
                                         '            if overlap and left_set != right_set:\n'
                                         '                raise ValueError(\n'
                                         '                    "Neural datasets contain partial but non-identical '
                                         'participant "\n'
                                         '                    f"overlap ({left} vs {right}). Public release code does '
                                         'not "\n'
                                         '                    "guess a bootstrap coupling rule for this case. Supply '
                                         'matching "\n'
                                         '                    "IDs/resampling groups appropriate to the design."\n'
                                         '                )\n'
                                         '\n'
                                         '    # Group datasets by exact participant set. The code learns the '
                                         'dependency\n'
                                         '    # pattern from matching IDs; no overlap pattern is hard-coded in the '
                                         'release.\n'
                                         '    grouped = {}\n'
                                         '    for movie, ids in dataset_ids.items():\n'
                                         '        key = frozenset(map(str, ids))\n'
                                         '        grouped.setdefault(key, []).append(movie)\n'
                                         '\n'
                                         '    n_behavior = len(prepared["behavior_master_ids"])\n'
                                         '    expected_metadata = {\n'
                                         '        "n_bootstrap": int(N_BOOTSTRAP),\n'
                                         '        "seed": int(RANDOM_SEED + 10000),\n'
                                         '        "mode": DEPENDENCE_MODE,\n'
                                         '        "n_neural_dependency_groups": len(grouped),\n'
                                         '        "neural_dataset_n": {m: int(len(dataset_ids[m])) for m in MOVIES},\n'
                                         '        "n_behavior_master": int(n_behavior),\n'
                                         '        "validation": ">=2 nonzero resampled units in every dataset/modality '
                                         'target",\n'
                                         '    }\n'
                                         '\n'
                                         '    if path.exists() and metadata_path.exists() and RESUME_RESAMPLING:\n'
                                         '        if load_json(metadata_path) == expected_metadata:\n'
                                         '            loaded = np.load(path)\n'
                                         '            neural_by_dataset = {\n'
                                         '                movie: loaded[f"neural__{movie}"] for movie in MOVIES\n'
                                         '            }\n'
                                         '            return {"neural_by_dataset": neural_by_dataset, "behavior": '
                                         'loaded["behavior"]}\n'
                                         '\n'
                                         '    rng = np.random.default_rng(RANDOM_SEED + 10000)\n'
                                         '    neural_by_dataset = {\n'
                                         '        movie: np.empty((N_BOOTSTRAP, len(dataset_ids[movie])), '
                                         'dtype=np.int16)\n'
                                         '        for movie in MOVIES\n'
                                         '    }\n'
                                         '    behavior = np.empty((N_BOOTSTRAP, n_behavior), dtype=np.int16)\n'
                                         '\n'
                                         '    # Precompute group canonical ordering and dataset order mappings.\n'
                                         '    neural_groups = []\n'
                                         '    for member_set, movies in grouped.items():\n'
                                         '        canonical = np.asarray(sorted(member_set), dtype=str)\n'
                                         '        lookup = {sid: i for i, sid in enumerate(canonical)}\n'
                                         '        mappings = {\n'
                                         '            movie: np.asarray([lookup[sid] for sid in dataset_ids[movie]], '
                                         'dtype=int)\n'
                                         '            for movie in movies\n'
                                         '        }\n'
                                         '        neural_groups.append((canonical, movies, mappings))\n'
                                         '\n'
                                         '    behavior_target_ids = [\n'
                                         '        prepared["behavior_caches"][movie][affect]["subject_ids"]\n'
                                         '        for movie in MOVIES for affect in AFFECTS\n'
                                         '    ]\n'
                                         '\n'
                                         '    start = time.time()\n'
                                         '    for index in range(N_BOOTSTRAP):\n'
                                         '        for canonical, movies, mappings in neural_groups:\n'
                                         '            counts = draw_multinomial_weights(rng, len(canonical))\n'
                                         '            for movie in movies:\n'
                                         '                neural_by_dataset[movie][index] = counts[mappings[movie]]\n'
                                         '\n'
                                         '        while True:\n'
                                         '            candidate = draw_multinomial_weights(rng, n_behavior)\n'
                                         '            if all(\n'
                                         '                np.count_nonzero(\n'
                                         '                    map_master_weights(prepared["behavior_master_ids"], '
                                         'candidate, target_ids)\n'
                                         '                ) >= 2\n'
                                         '                for target_ids in behavior_target_ids\n'
                                         '            ):\n'
                                         '                behavior[index] = candidate\n'
                                         '                break\n'
                                         '\n'
                                         '        completed = index + 1\n'
                                         '        if completed % BOOT_PROGRESS_EVERY == 0 or completed == '
                                         'N_BOOTSTRAP:\n'
                                         '            print_progress(\n'
                                         '                "[STUDY 1 BOOTSTRAP PLAN]", completed, N_BOOTSTRAP,\n'
                                         '                start_time=start,\n'
                                         '                extra=(\n'
                                         '                    f"neural dependency groups={len(neural_groups)}, "\n'
                                         '                    f"behavior master={n_behavior}"\n'
                                         '                ),\n'
                                         '                done=(completed == N_BOOTSTRAP),\n'
                                         '            )\n'
                                         '\n'
                                         '    np.savez_compressed(\n'
                                         '        path,\n'
                                         '        behavior=behavior,\n'
                                         '        **{f"neural__{movie}": matrix for movie, matrix in '
                                         'neural_by_dataset.items()},\n'
                                         '    )\n'
                                         '    save_json(expected_metadata, metadata_path)\n'
                                         '    return {"neural_by_dataset": neural_by_dataset, "behavior": behavior}\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'BOOTSTRAP_METRICS = []\n'
                                         'for _affect in AFFECTS:\n'
                                         '    BOOTSTRAP_METRICS.extend([\n'
                                         '        f"marginal_{_affect}_movieTP_slope",\n'
                                         '        f"marginal_{_affect}_movieDM_slope",\n'
                                         '        f"marginal_{_affect}_movieBD_slope",\n'
                                         '        f"marginal_{_affect}_pooled_slope",\n'
                                         '        f"marginal_{_affect}_heterogeneity",\n'
                                         '        f"marginal_{_affect}_full_r2",\n'
                                         '        f"marginal_{_affect}_full_adjusted_r2",\n'
                                         '        f"marginal_{_affect}_reduced_r2",\n'
                                         '        f"marginal_{_affect}_reduced_adjusted_r2",\n'
                                         '        f"marginal_{_affect}_delta_r2",\n'
                                         '    ])\n'
                                         '\n'
                                         'BOOTSTRAP_METRICS.extend([\n'
                                         '    "conditional_valence_given_arousal_movieTP_slope",\n'
                                         '    "conditional_valence_given_arousal_movieDM_slope",\n'
                                         '    "conditional_valence_given_arousal_movieBD_slope",\n'
                                         '    "conditional_valence_given_arousal_pooled_slope",\n'
                                         '    "conditional_valence_given_arousal_heterogeneity",\n'
                                         '    "conditional_valence_given_arousal_full_r2",\n'
                                         '    "conditional_valence_given_arousal_full_adjusted_r2",\n'
                                         '    "conditional_valence_given_arousal_reduced_r2",\n'
                                         '    "conditional_valence_given_arousal_reduced_adjusted_r2",\n'
                                         '    "conditional_valence_given_arousal_delta_r2",\n'
                                         '])\n'
                                         '\n'
                                         'for _movie in MOVIES:\n'
                                         '    BOOTSTRAP_METRICS.append(\n'
                                         '        f"marginal_valence_minus_arousal_{_movie}_slope"\n'
                                         '    )\n'
                                         'BOOTSTRAP_METRICS.extend([\n'
                                         '    "marginal_valence_minus_arousal_pooled_slope",\n'
                                         '    "marginal_valence_minus_arousal_delta_r2",\n'
                                         '])\n'
                                         '\n'
                                         'def bootstrap_draw_paths():\n'
                                         '    return {\n'
                                         '        "draws": DRAW_DIR / '
                                         '"Study1_participant_bootstrap_draws_joint_v3.npy",\n'
                                         '        "progress": DRAW_DIR / '
                                         '"Study1_participant_bootstrap_progress_joint_v3.json",\n'
                                         '        "metrics": DRAW_DIR / '
                                         '"Study1_participant_bootstrap_metrics_joint_v3.json",\n'
                                         '    }\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def run_participant_bootstrap(prepared, observed_effects, bootstrap_plan):\n'
                                         '    paths = bootstrap_draw_paths()\n'
                                         '    n_metrics = len(BOOTSTRAP_METRICS)\n'
                                         '    start_index = 0\n'
                                         '\n'
                                         '    can_resume = (\n'
                                         '        RESUME_RESAMPLING\n'
                                         '        and paths["draws"].exists()\n'
                                         '        and paths["progress"].exists()\n'
                                         '        and paths["metrics"].exists()\n'
                                         '        and load_json(paths["metrics"]) == BOOTSTRAP_METRICS\n'
                                         '    )\n'
                                         '\n'
                                         '    if can_resume:\n'
                                         '        draws = np.lib.format.open_memmap(\n'
                                         '            paths["draws"],\n'
                                         '            mode="r+",\n'
                                         '            dtype=np.float64,\n'
                                         '            shape=(N_BOOTSTRAP, n_metrics),\n'
                                         '        )\n'
                                         '        start_index = int(load_json(paths["progress"]).get("completed", 0))\n'
                                         '        print(f"[BOOT RESUME] starting at {start_index}")\n'
                                         '    else:\n'
                                         '        draws = np.lib.format.open_memmap(\n'
                                         '            paths["draws"],\n'
                                         '            mode="w+",\n'
                                         '            dtype=np.float64,\n'
                                         '            shape=(N_BOOTSTRAP, n_metrics),\n'
                                         '        )\n'
                                         '        save_json(BOOTSTRAP_METRICS, paths["metrics"])\n'
                                         '        save_json({"completed": 0}, paths["progress"])\n'
                                         '\n'
                                         '    start = time.time()\n'
                                         '    for bootstrap_index in range(start_index, N_BOOTSTRAP):\n'
                                         '        neural_weights = {\n'
                                         '            movie: '
                                         'bootstrap_plan["neural_by_dataset"][movie][bootstrap_index]\n'
                                         '            for movie in MOVIES\n'
                                         '        }\n'
                                         '        behavior_weights = bootstrap_plan["behavior"][bootstrap_index]\n'
                                         '\n'
                                         '        boot_df = build_window_table(\n'
                                         '            prepared,\n'
                                         '            ROI_NAME,\n'
                                         '            neural_weights_by_dataset=neural_weights,\n'
                                         '            behavior_master_weights=behavior_weights,\n'
                                         '        )\n'
                                         '        metrics = fit_all_effects(boot_df)\n'
                                         '        draws[bootstrap_index] = [\n'
                                         '            metrics[metric] for metric in BOOTSTRAP_METRICS\n'
                                         '        ]\n'
                                         '\n'
                                         '        completed = bootstrap_index + 1\n'
                                         '        if completed % CHECKPOINT_EVERY == 0 or completed == N_BOOTSTRAP:\n'
                                         '            draws.flush()\n'
                                         '            save_json({"completed": completed}, paths["progress"])\n'
                                         '        if completed % BOOT_PROGRESS_EVERY == 0 or completed == '
                                         'N_BOOTSTRAP:\n'
                                         '            print_progress(\n'
                                         '                "[STUDY 1 PARTICIPANT BOOTSTRAP]",\n'
                                         '                completed,\n'
                                         '                N_BOOTSTRAP,\n'
                                         '                start_time=start,\n'
                                         '                extra=(\n'
                                         '                    f"marginal valence="\n'
                                         '                    f"{metrics[\'marginal_valence_pooled_slope\']:+.3f}, "\n'
                                         '                    f"conditional valence="\n'
                                         '                    '
                                         'f"{metrics[\'conditional_valence_given_arousal_pooled_slope\']:+.3f}"\n'
                                         '                ),\n'
                                         '                done=(completed == N_BOOTSTRAP),\n'
                                         '            )\n'
                                         '\n'
                                         '    draws_array = np.asarray(draws)\n'
                                         '    rows = []\n'
                                         '    for metric_index, metric in enumerate(BOOTSTRAP_METRICS):\n'
                                         '        values = draws_array[:, metric_index]\n'
                                         '        values = values[np.isfinite(values)]\n'
                                         '        observed = float(observed_effects[metric])\n'
                                         '        mean_value = float(np.mean(values))\n'
                                         '        standard_error = float(np.std(values, ddof=1))\n'
                                         '        ci_low, ci_high = safe_quantile(values)\n'
                                         '\n'
                                         '        if standard_error > 0 and np.isfinite(standard_error):\n'
                                         '            z_approx = observed / standard_error\n'
                                         '            p_normal = math.erfc(abs(z_approx) / math.sqrt(2.0))\n'
                                         '        else:\n'
                                         '            z_approx = np.nan\n'
                                         '            p_normal = np.nan\n'
                                         '\n'
                                         '        signed_metric = (\n'
                                         '            metric.endswith("_slope")\n'
                                         '            or metric == "marginal_valence_minus_arousal_delta_r2"\n'
                                         '        )\n'
                                         '        rows.append({\n'
                                         '            "effect": metric,\n'
                                         '            "observed_estimate": observed,\n'
                                         '            "bootstrap_mean": mean_value,\n'
                                         '            "bootstrap_bias": mean_value - observed,\n'
                                         '            "bootstrap_se": standard_error,\n'
                                         '            "bootstrap_z_approx": z_approx,\n'
                                         '            "bootstrap_p_normal_approx": p_normal,\n'
                                         '            "bootstrap_p_sign_approx": (\n'
                                         '                sign_based_p(values) if signed_metric else np.nan\n'
                                         '            ),\n'
                                         '            "bootstrap_ci_low": ci_low,\n'
                                         '            "bootstrap_ci_high": ci_high,\n'
                                         '            "n_bootstrap": len(values),\n'
                                         '        })\n'
                                         '\n'
                                         '    summary = pd.DataFrame(rows)\n'
                                         '    summary.to_csv(\n'
                                         '        OUT_DIR / "Study1_participant_bootstrap_summary_joint_valence.csv",\n'
                                         '        index=False,\n'
                                         '    )\n'
                                         '    return draws_array, summary\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# DIAGNOSTIC FIGURE HELPERS\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def finish_figure(fig, output_path):\n'
                                         '    fig.patch.set_facecolor("white")\n'
                                         '    fig.savefig(output_path, dpi=400, bbox_inches="tight", '
                                         'facecolor="white")\n'
                                         '    if SHOW_PLOTS:\n'
                                         '        plt.show()\n'
                                         '    plt.close(fig)\n'
                                         '    print(f"[FIGURE SAVED] {output_path}")\n'
                                         '\n'
                                         'def finite_pair(x, y):\n'
                                         '    x = np.asarray(x, dtype=float)\n'
                                         '    y = np.asarray(y, dtype=float)\n'
                                         '    valid = np.isfinite(x) & np.isfinite(y)\n'
                                         '    return x[valid], y[valid]\n'
                                         '\n'
                                         '\n'
                                         'def pearson_r_safe(x, y):\n'
                                         '    x, y = finite_pair(x, y)\n'
                                         '    if len(x) < 3:\n'
                                         '        return np.nan\n'
                                         '    if np.std(x, ddof=1) == 0 or np.std(y, ddof=1) == 0:\n'
                                         '        return np.nan\n'
                                         '    return float(np.corrcoef(x, y)[0, 1])\n'
                                         '\n'
                                         '\n'
                                         'def regression_r2(y, predictors):\n'
                                         '    y = np.asarray(y, dtype=float)\n'
                                         '    predictors = np.asarray(predictors, dtype=float)\n'
                                         '    valid = np.isfinite(y) & np.all(np.isfinite(predictors), axis=1)\n'
                                         '    if valid.sum() < predictors.shape[1] + 2:\n'
                                         '        return np.nan\n'
                                         '    y_valid = y[valid]\n'
                                         '    centered = y_valid - np.mean(y_valid)\n'
                                         '    sst = float(np.dot(centered, centered))\n'
                                         '    if sst <= 0:\n'
                                         '        return np.nan\n'
                                         '    design = np.column_stack([np.ones(valid.sum()), predictors[valid]])\n'
                                         '    beta = np.linalg.lstsq(design, y_valid, rcond=None)[0]\n'
                                         '    residual = y_valid - design @ beta\n'
                                         '    sse = float(np.dot(residual, residual))\n'
                                         '    return float(1.0 - sse / sst)\n'
                                         '\n'
                                         '\n'
                                         'def autocorrelation_values(values, max_lag):\n'
                                         '    """Biased ACF used only for descriptive plotting."""\n'
                                         '    values = np.asarray(values, dtype=float)\n'
                                         '    values = values[np.isfinite(values)]\n'
                                         '    if len(values) < 3:\n'
                                         '        return np.asarray([1.0])\n'
                                         '\n'
                                         '    values = values - np.mean(values)\n'
                                         '    denominator = float(np.dot(values, values))\n'
                                         '    if denominator <= 0 or not np.isfinite(denominator):\n'
                                         '        return np.full(min(max_lag, len(values) - 1) + 1, np.nan)\n'
                                         '\n'
                                         '    final_lag = min(int(max_lag), len(values) - 1)\n'
                                         '    output = np.empty(final_lag + 1, dtype=float)\n'
                                         '    output[0] = 1.0\n'
                                         '    for lag in range(1, final_lag + 1):\n'
                                         '        output[lag] = float(\n'
                                         '            np.dot(values[:-lag], values[lag:]) / denominator\n'
                                         '        )\n'
                                         '    return output\n'
                                         '\n'
                                         '\n'
                                         'def add_linear_fit(axis, x, y, color, label=None):\n'
                                         '    x, y = finite_pair(x, y)\n'
                                         '    if len(x) < 3 or np.std(x, ddof=1) == 0:\n'
                                         '        return\n'
                                         '    slope, intercept = np.polyfit(x, y, deg=1)\n'
                                         '    grid = np.linspace(np.min(x), np.max(x), 100)\n'
                                         '    axis.plot(\n'
                                         '        grid,\n'
                                         '        intercept + slope * grid,\n'
                                         '        color=color,\n'
                                         '        linewidth=2.0,\n'
                                         '        alpha=0.90,\n'
                                         '        label=label,\n'
                                         '    )\n'
                                         '\n'
                                         '\n'
                                         'def create_dataset_overview(prepared, observed_df, block_lengths):\n'
                                         '    """Save and plot the sample/window structure of each movie dataset."""\n'
                                         '    rows = []\n'
                                         '\n'
                                         '    for movie in MOVIES:\n'
                                         '        neural_cache = prepared["neural_caches"][ROI_NAME][movie]\n'
                                         '        valence_cache = prepared["behavior_caches"][movie]["valence"]\n'
                                         '        arousal_cache = prepared["behavior_caches"][movie]["arousal"]\n'
                                         '        n_windows = int(observed_df["movie"].eq(movie).sum())\n'
                                         '\n'
                                         '        rows.append({\n'
                                         '            "movie": movie,\n'
                                         '            "movie_label": MOVIE_LABELS[movie],\n'
                                         '            "neural_participants": int(len(neural_cache["subject_ids"])),\n'
                                         '            "neural_distinct_pairs": int(neural_cache["n_pairs"]),\n'
                                         '            "valence_raters": int(len(valence_cache["subject_ids"])),\n'
                                         '            "arousal_raters": int(len(arousal_cache["subject_ids"])),\n'
                                         '            "n_timepoints_used": int(prepared["n_time_by_movie"][movie]),\n'
                                         '            "window_size_TR": int(WINDOW_SIZE[movie]),\n'
                                         '            "n_windows": n_windows,\n'
                                         '            "acf_block_len_windows": int(block_lengths[movie]),\n'
                                         '        })\n'
                                         '\n'
                                         '    overview = pd.DataFrame(rows)\n'
                                         '    overview.to_csv(OUT_DIR / "DMN_dataset_overview.csv", index=False)\n'
                                         '\n'
                                         '    display_rows = [\n'
                                         '        ("Neural participants", "neural_participants"),\n'
                                         '        ("Neural distinct pairs", "neural_distinct_pairs"),\n'
                                         '        ("Valence raters", "valence_raters"),\n'
                                         '        ("Arousal raters", "arousal_raters"),\n'
                                         '        ("Time points used", "n_timepoints_used"),\n'
                                         '        ("Window size (TR)", "window_size_TR"),\n'
                                         '        ("Number of windows", "n_windows"),\n'
                                         '        ("Permutation block length", "acf_block_len_windows"),\n'
                                         '    ]\n'
                                         '\n'
                                         '    cell_text = []\n'
                                         '    for row_label, column in display_rows:\n'
                                         '        cell_text.append([\n'
                                         '            row_label,\n'
                                         '            *[f"{int(value):,}" for value in overview[column].to_numpy()],\n'
                                         '        ])\n'
                                         '\n'
                                         '    fig, axis = plt.subplots(figsize=(11.2, 5.0))\n'
                                         '    axis.axis("off")\n'
                                         '    table = axis.table(\n'
                                         '        cellText=cell_text,\n'
                                         '        colLabels=["Dataset characteristic", '
                                         '*overview["movie_label"].tolist()],\n'
                                         '        loc="center",\n'
                                         '        cellLoc="center",\n'
                                         '        colLoc="center",\n'
                                         '        colWidths=[0.40, 0.20, 0.20, 0.20],\n'
                                         '    )\n'
                                         '    table.auto_set_font_size(False)\n'
                                         '    table.set_fontsize(10)\n'
                                         '    table.scale(1.0, 1.55)\n'
                                         '\n'
                                         '    for (row, column), cell in table.get_celld().items():\n'
                                         '        cell.set_edgecolor("white")\n'
                                         '        if row == 0:\n'
                                         '            cell.set_facecolor(NEUTRAL_COLOR)\n'
                                         '            cell.set_text_props(color="white", weight="bold")\n'
                                         '        elif column == 0:\n'
                                         '            cell.set_facecolor("#F2F4F7")\n'
                                         '            cell.set_text_props(ha="left", color=NEUTRAL_COLOR)\n'
                                         '        else:\n'
                                         '            cell.set_facecolor("#FAFAFA" if row % 2 else "#F7F7F7")\n'
                                         '            cell.set_text_props(color=NEUTRAL_COLOR)\n'
                                         '\n'
                                         '    axis.set_title("Dataset and window structure", pad=18)\n'
                                         '    fig.tight_layout()\n'
                                         '    finish_figure(fig, FIG_DIR / "DMN_dataset_overview.png")\n'
                                         '    return overview\n'
                                         '\n'
                                         '\n'
                                         'def save_dataset_descriptive_tables(observed_df, block_lengths):\n'
                                         '    """Save compact movie-wise summaries used by the diagnostic figures."""\n'
                                         '    descriptive_rows = []\n'
                                         '    correlation_rows = []\n'
                                         '\n'
                                         '    variables = {\n'
                                         '        "DMN neural ISC": "z_neural_ISC",\n'
                                         '        "Valence ISC": "z_valence_ISC",\n'
                                         '        "Arousal ISC": "z_arousal_ISC",\n'
                                         '        "Brightness": "brightness_z",\n'
                                         '        "Audio RMS": "audio_rms_z",\n'
                                         '        "Optical flow": "optical_flow_z",\n'
                                         '    }\n'
                                         '\n'
                                         '    for movie in MOVIES:\n'
                                         '        subset = (\n'
                                         '            observed_df.loc[observed_df["movie"].eq(movie)]\n'
                                         '            .sort_values("window")\n'
                                         '            .reset_index(drop=True)\n'
                                         '        )\n'
                                         '\n'
                                         '        for label, column in variables.items():\n'
                                         '            values = pd.to_numeric(subset[column], '
                                         'errors="coerce").to_numpy(float)\n'
                                         '            finite = values[np.isfinite(values)]\n'
                                         '            descriptive_rows.append({\n'
                                         '                "movie": movie,\n'
                                         '                "movie_label": MOVIE_LABELS[movie],\n'
                                         '                "variable": label,\n'
                                         '                "n_windows": int(len(finite)),\n'
                                         '                "mean": float(np.mean(finite)) if len(finite) else np.nan,\n'
                                         '                "sd": float(np.std(finite, ddof=1)) if len(finite) > 1 else '
                                         'np.nan,\n'
                                         '                "minimum": float(np.min(finite)) if len(finite) else '
                                         'np.nan,\n'
                                         '                "q25": float(np.quantile(finite, 0.25)) if len(finite) else '
                                         'np.nan,\n'
                                         '                "median": float(np.median(finite)) if len(finite) else '
                                         'np.nan,\n'
                                         '                "q75": float(np.quantile(finite, 0.75)) if len(finite) else '
                                         'np.nan,\n'
                                         '                "maximum": float(np.max(finite)) if len(finite) else '
                                         'np.nan,\n'
                                         '                "acf_block_len_used": int(block_lengths[movie]),\n'
                                         '            })\n'
                                         '\n'
                                         '        for label_x, column_x in variables.items():\n'
                                         '            for label_y, column_y in variables.items():\n'
                                         '                correlation_rows.append({\n'
                                         '                    "movie": movie,\n'
                                         '                    "movie_label": MOVIE_LABELS[movie],\n'
                                         '                    "variable_x": label_x,\n'
                                         '                    "variable_y": label_y,\n'
                                         '                    "pearson_r": pearson_r_safe(\n'
                                         '                        subset[column_x].to_numpy(float),\n'
                                         '                        subset[column_y].to_numpy(float),\n'
                                         '                    ),\n'
                                         '                })\n'
                                         '\n'
                                         '    descriptive = pd.DataFrame(descriptive_rows)\n'
                                         '    correlations = pd.DataFrame(correlation_rows)\n'
                                         '    descriptive.to_csv(\n'
                                         '        OUT_DIR / "DMN_dataset_descriptive_summary.csv",\n'
                                         '        index=False,\n'
                                         '    )\n'
                                         '    correlations.to_csv(\n'
                                         '        OUT_DIR / "DMN_dataset_correlation_summary.csv",\n'
                                         '        index=False,\n'
                                         '    )\n'
                                         '    return descriptive, correlations\n'
                                         '\n'
                                         '\n'
                                         'def plot_movie_timeseries(observed_df):\n'
                                         '    """Standardized DMN, valence, and arousal ISC across movie progress."""\n'
                                         '    fig, axes = plt.subplots(\n'
                                         '        len(MOVIES),\n'
                                         '        1,\n'
                                         '        figsize=(13.6, 9.6),\n'
                                         '        sharex=False,\n'
                                         '        sharey=True,\n'
                                         '    )\n'
                                         '\n'
                                         '    for axis, movie in zip(axes, MOVIES):\n'
                                         '        subset = (\n'
                                         '            observed_df.loc[observed_df["movie"].eq(movie)]\n'
                                         '            .sort_values("window")\n'
                                         '            .reset_index(drop=True)\n'
                                         '        )\n'
                                         '        progress = np.linspace(0, 100, len(subset))\n'
                                         '\n'
                                         '        axis.plot(\n'
                                         '            progress,\n'
                                         '            subset["z_neural_ISC"],\n'
                                         '            color=NEURAL_COLOR,\n'
                                         '            linewidth=1.5,\n'
                                         '            alpha=PLOT_ALPHA,\n'
                                         '            label="DMN neural ISC",\n'
                                         '        )\n'
                                         '        axis.plot(\n'
                                         '            progress,\n'
                                         '            subset["z_valence_ISC"],\n'
                                         '            color=VALENCE_COLOR,\n'
                                         '            linewidth=1.5,\n'
                                         '            alpha=PLOT_ALPHA,\n'
                                         '            label="Valence ISC",\n'
                                         '        )\n'
                                         '        axis.plot(\n'
                                         '            progress,\n'
                                         '            subset["z_arousal_ISC"],\n'
                                         '            color=AROUSAL_COLOR,\n'
                                         '            linewidth=1.5,\n'
                                         '            alpha=PLOT_ALPHA,\n'
                                         '            label="Arousal ISC",\n'
                                         '        )\n'
                                         '        axis.axhline(0, color=NEUTRAL_COLOR, linewidth=0.8, alpha=0.5)\n'
                                         '        axis.set_title(\n'
                                         '            f"{MOVIE_LABELS[movie]} | {len(subset):,} windows | "\n'
                                         '            f"window={WINDOW_SIZE[movie]} TR"\n'
                                         '        )\n'
                                         '        axis.set_ylabel("Within-movie z")\n'
                                         '        style_axis(axis, grid_axis="y")\n'
                                         '\n'
                                         '    axes[-1].set_xlabel("Movie progress (%)")\n'
                                         '    axes[0].legend(frameon=False, ncol=3, loc="upper right")\n'
                                         '    fig.suptitle(\n'
                                         '        "Whole DMN and affective synchrony across each movie",\n'
                                         '        y=1.005,\n'
                                         '    )\n'
                                         '    fig.tight_layout()\n'
                                         '    finish_figure(fig, FIG_DIR / "DMN_dataset_timeseries.png")\n'
                                         '\n'
                                         '\n'
                                         'def plot_movie_distributions(observed_df):\n'
