                                         '    labels = ["DMN neural", "Valence", "Arousal"]\n'
                                         '    colors = [NEURAL_COLOR, VALENCE_COLOR, AROUSAL_COLOR]\n'
                                         '\n'
                                         '    fig, axes = plt.subplots(1, len(MOVIES), figsize=(13.8, 5.1), '
                                         'sharey=True)\n'
                                         '\n'
                                         '    for axis, movie in zip(axes, MOVIES):\n'
                                         '        subset = observed_df.loc[observed_df["movie"].eq(movie)]\n'
