                                         '        axis.axhline(0, color=NEUTRAL_COLOR, linewidth=0.8, linestyle="--")\n'
                                         '        axis.set_title(f"{MOVIE_LABELS[movie]} ({len(subset):,} windows)")\n'
                                         '        axis.tick_params(axis="x", rotation=18)\n'
