                                         '    fig.tight_layout()\n'
                                         '    finish_figure(fig, FIG_DIR / "DMN_dataset_distributions.png")\n'
                                         '\n'
                                         '\n'
                                         'def plot_movie_acf(observed_df, block_lengths):\n'
                                         '    """ACF of DMN neural, valence, and arousal ISC for each movie."""\n'
                                         '    fig, axes = plt.subplots(1, len(MOVIES), figsize=(14.4, 5.2), '
                                         'sharey=True)\n'
                                         '\n'
                                         '    for axis, movie in zip(axes, MOVIES):\n'
                                         '        subset = (\n'
                                         '            observed_df.loc[observed_df["movie"].eq(movie)]\n'
                                         '            .sort_values("window")\n'
                                         '            .reset_index(drop=True)\n'
                                         '        )\n'
                                         '        series = [\n'
                                         '            ("DMN neural", "z_neural_ISC", NEURAL_COLOR),\n'
                                         '            ("Valence", "z_valence_ISC", VALENCE_COLOR),\n'
                                         '            ("Arousal", "z_arousal_ISC", AROUSAL_COLOR),\n'
