                                         '    finish_figure(fig, FIG_DIR / "DMN_valence_arousal_relationship.png")\n'
                                         '\n'
                                         '\n'
                                         'def plot_partial_neural_affect_relationships(observed_df):\n'
                                         '    """Plot marginal and arousal-adjusted valence relationships."""\n'
                                         '    partial = prepare_partial_series_for_permutation(observed_df)\n'
                                         '    rows = [\n'
                                         '        ("Marginal valence", "marginal", "valence", VALENCE_COLOR),\n'
                                         '        ("Marginal arousal", "marginal", "arousal", AROUSAL_COLOR),\n'
                                         '        (\n'
                                         '            "Valence controlling arousal",\n'
                                         '            "conditional_valence",\n'
                                         '            None,\n'
                                         '            CONTRAST_COLOR,\n'
                                         '        ),\n'
                                         '    ]\n'
                                         '\n'
                                         '    fig, axes = plt.subplots(\n'
                                         '        len(rows),\n'
                                         '        len(MOVIES),\n'
                                         '        figsize=(14.8, 4.25 * len(rows)),\n'
                                         '        sharex=False,\n'
                                         '        sharey="row",\n'
                                         '    )\n'
                                         '\n'
                                         '    for row_index, (label, family, affect, color) in enumerate(rows):\n'
                                         '        for movie_index, movie in enumerate(MOVIES):\n'
                                         '            axis = axes[row_index, movie_index]\n'
                                         '            if family == "marginal":\n'
