                                         '            axis.axvline(0, color=NEUTRAL_COLOR, linewidth=0.7, alpha=0.5)\n'
                                         '            axis.set_title(\n'
                                         '                f"{MOVIE_LABELS[movie]} | partial r={correlation:.3f}"\n'
                                         '            )\n'
                                         '            axis.set_xlabel(f"Residual predictor: {label}")\n'
