                                         '\n'
                                         'def plot_covariate_influence_summary(observed_df):\n'
                                         '    labels = {\n'
                                         '        "brightness_z": "Brightness",\n'
                                         '        "audio_rms_z": "Audio",\n'
                                         '        "optical_flow_z": "Motion",\n'
                                         '        "linear_time": "Linear time",\n'
                                         '        "quadratic_time": "Quadratic time",\n'
                                         '    }\n'
                                         '    rows = []\n'
                                         '    r2_rows = []\n'
                                         '    for movie in MOVIES:\n'
                                         '        subset = (\n'
                                         '            observed_df.loc[observed_df["movie"].eq(movie)]\n'
                                         '            .sort_values("window")\n'
                                         '            .reset_index(drop=True)\n'
                                         '        )\n'
                                         '        y = subset["z_neural_ISC"].to_numpy(float)\n'
                                         '        covariates = subset[MODEL_COVARIATES].to_numpy(float)\n'
                                         '        r2_rows.append({\n'
                                         '            "movie": movie,\n'
                                         '            "movie_label": MOVIE_LABELS[movie],\n'
                                         '            "covariate_only_r2": regression_r2(y, covariates),\n'
                                         '        })\n'
                                         '        for covariate in MODEL_COVARIATES:\n'
                                         '            rows.append({\n'
                                         '                "movie": movie,\n'
                                         '                "movie_label": MOVIE_LABELS[movie],\n'
                                         '                "covariate": covariate,\n'
                                         '                "covariate_label": labels[covariate],\n'
                                         '                "neural_zero_order_r": pearson_r_safe(\n'
                                         '                    subset[covariate].to_numpy(float),\n'
                                         '                    y,\n'
                                         '                ),\n'
                                         '            })\n'
                                         '\n'
                                         '    correlations = pd.DataFrame(rows)\n'
                                         '    r2_table = pd.DataFrame(r2_rows)\n'
                                         '    correlations.to_csv(\n'
                                         '        OUT_DIR / "DMN_covariate_neural_correlations.csv", index=False\n'
                                         '    )\n'
                                         '    r2_table.to_csv(OUT_DIR / "DMN_covariate_only_R2.csv", index=False)\n'
                                         '\n'
                                         '    matrix = (\n'
                                         '        correlations.pivot(\n'
                                         '            index="movie_label",\n'
                                         '            columns="covariate_label",\n'
                                         '            values="neural_zero_order_r",\n'
                                         '        )\n'
                                         '        .reindex([MOVIE_LABELS[movie] for movie in MOVIES])\n'
                                         '        .reindex([labels[covariate] for covariate in MODEL_COVARIATES], '
                                         'axis=1)\n'
                                         '        .to_numpy(float)\n'
                                         '    )\n'
                                         '\n'
                                         '    fig, axes = plt.subplots(\n'
                                         '        1,\n'
                                         '        2,\n'
                                         '        figsize=(13.2, 5.1),\n'
                                         '        gridspec_kw={"width_ratios": [1.45, 1.0]},\n'
                                         '    )\n'
                                         '    image = axes[0].imshow(\n'
                                         '        matrix,\n'
                                         '        cmap=AFFECT_DIVERGING_CMAP,\n'
                                         '        vmin=-1,\n'
                                         '        vmax=1,\n'
                                         '        aspect="auto",\n'
                                         '        alpha=0.90,\n'
                                         '    )\n'
                                         '    axes[0].set_xticks(np.arange(len(MODEL_COVARIATES)))\n'
                                         '    axes[0].set_xticklabels(\n'
                                         '        [labels[covariate] for covariate in MODEL_COVARIATES],\n'
                                         '        rotation=35,\n'
                                         '        ha="right",\n'
                                         '    )\n'
                                         '    axes[0].set_yticks(np.arange(len(MOVIES)))\n'
                                         '    axes[0].set_yticklabels([MOVIE_LABELS[movie] for movie in MOVIES])\n'
                                         '    axes[0].set_title("Covariate correlation with DMN ISC")\n'
                                         '    for row in range(matrix.shape[0]):\n'
                                         '        for column in range(matrix.shape[1]):\n'
                                         '            value = matrix[row, column]\n'
                                         '            color = "white" if abs(value) > 0.55 else NEUTRAL_COLOR\n'
                                         '            axes[0].text(\n'
                                         '                column,\n'
                                         '                row,\n'
                                         '                f"{value:.2f}",\n'
                                         '                ha="center",\n'
                                         '                va="center",\n'
                                         '                fontsize=8,\n'
                                         '                color=color,\n'
                                         '            )\n'
                                         '    for spine in axes[0].spines.values():\n'
                                         '        spine.set_visible(False)\n'
                                         '    fig.colorbar(image, ax=axes[0], shrink=0.82, label="Pearson r")\n'
                                         '\n'
                                         '    r2_values = r2_table["covariate_only_r2"].to_numpy(float)\n'
                                         '    positions = np.arange(len(MOVIES))\n'
                                         '    axes[1].bar(\n'
                                         '        positions,\n'
                                         '        r2_values,\n'
                                         '        color=NEUTRAL_COLOR,\n'
                                         '        alpha=PLOT_ALPHA,\n'
                                         '        width=0.62,\n'
                                         '    )\n'
                                         '    axes[1].set_xticks(positions)\n'
                                         '    axes[1].set_xticklabels([MOVIE_LABELS[movie] for movie in MOVIES])\n'
                                         '    axes[1].set_ylabel("Covariate-only R2")\n'
                                         '    axes[1].set_title("DMN variance explained by covariates")\n'
                                         '    axes[1].set_ylim(0, max(0.05, np.nanmax(r2_values) * 1.20))\n'
                                         '    style_axis(axes[1], grid_axis="y")\n'
                                         '\n'
                                         '    fig.suptitle("Audiovisual/time covariate influence diagnostics", '
                                         'y=1.02)\n'
                                         '    fig.tight_layout()\n'
                                         '    finish_figure(fig, FIG_DIR / "DMN_covariate_influence_summary.png")\n'
                                         '    return correlations, r2_table\n'
                                         '\n'
                                         '\n'
                                         'def run_dataset_diagnostics(prepared, observed_df, block_lengths):\n'
                                         '    print_section("DMN | DATASET DIAGNOSTICS")\n'
                                         '    overview = create_dataset_overview(\n'
                                         '        prepared,\n'
                                         '        observed_df,\n'
                                         '        block_lengths,\n'
                                         '    )\n'
                                         '    print(overview.to_string(index=False))\n'
                                         '\n'
                                         '    descriptive, correlations = save_dataset_descriptive_tables(\n'
                                         '        observed_df,\n'
                                         '        block_lengths,\n'
                                         '    )\n'
                                         '\n'
                                         '    compact = descriptive.loc[\n'
                                         '        descriptive["variable"].isin(\n'
                                         '            ["DMN neural ISC", "Valence ISC", "Arousal ISC"]\n'
                                         '        ),\n'
                                         '        ["movie_label", "variable", "n_windows", "mean", "sd", "minimum", '
                                         '"maximum"],\n'
                                         '    ]\n'
                                         '    print(compact.to_string(index=False))\n'
                                         '\n'
                                         '    plot_movie_timeseries(observed_df)\n'
                                         '    plot_movie_distributions(observed_df)\n'
                                         '    plot_movie_acf(observed_df, block_lengths)\n'
                                         '    plot_valence_arousal_relationship(observed_df)\n'
                                         '    plot_partial_neural_affect_relationships(observed_df)\n'
                                         '    plot_predictor_correlation_heatmaps(observed_df)\n'
                                         '    covariate_correlations, covariate_r2 = '
                                         'plot_covariate_influence_summary(\n'
                                         '        observed_df\n'
                                         '    )\n'
                                         '\n'
                                         '    print(f"[SAVED] {OUT_DIR / \'DMN_dataset_overview.csv\'}")\n'
                                         '    print(f"[SAVED] {OUT_DIR / \'DMN_dataset_descriptive_summary.csv\'}")\n'
                                         '    print(f"[SAVED] {OUT_DIR / \'DMN_dataset_correlation_summary.csv\'}")\n'
                                         '    print(f"[SAVED] {OUT_DIR / \'DMN_covariate_neural_correlations.csv\'}")\n'
                                         '    print(f"[SAVED] {OUT_DIR / \'DMN_covariate_only_R2.csv\'}")\n'
                                         '    return overview, descriptive, correlations\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '# '
                                         '=============================================================================\n'
                                         '# RESULT FIGURES AND REPORT TABLES\n'
                                         '# '
                                         '=============================================================================\n'
                                         '\n'
                                         '\n'
                                         'def plot_resampling_distributions(\n'
                                         '    observed_effects, permutation_draws, bootstrap_draws\n'
                                         '):\n'
                                         '    perm_index = {\n'
                                         '        metric: index for index, metric in enumerate(PERMUTATION_METRICS)\n'
                                         '    }\n'
                                         '    boot_index = {\n'
                                         '        metric: index for index, metric in enumerate(BOOTSTRAP_METRICS)\n'
                                         '    }\n'
                                         '    targets = [\n'
                                         '        ("Marginal valence", "marginal_valence_pooled_slope", '
                                         'VALENCE_COLOR),\n'
                                         '        ("Marginal arousal", "marginal_arousal_pooled_slope", '
                                         'AROUSAL_COLOR),\n'
                                         '        (\n'
                                         '            "Conditional valence | arousal",\n'
                                         '            "conditional_valence_given_arousal_pooled_slope",\n'
                                         '            CONTRAST_COLOR,\n'
                                         '        ),\n'
                                         '        (\n'
                                         '            "Marginal valence - arousal",\n'
                                         '            "marginal_valence_minus_arousal_pooled_slope",\n'
                                         '            NEUTRAL_COLOR,\n'
                                         '        ),\n'
                                         '    ]\n'
                                         '    fig, axes = plt.subplots(len(targets), 2, figsize=(12.8, 12.8))\n'
                                         '\n'
                                         '    for row_index, (label, metric, color) in enumerate(targets):\n'
                                         '        observed = observed_effects[metric]\n'
                                         '\n'
                                         '        null_values = permutation_draws[:, perm_index[metric]]\n'
                                         '        axis = axes[row_index, 0]\n'
                                         '        axis.hist(null_values, bins=50, color=color, alpha=PLOT_ALPHA)\n'
                                         '        axis.axvline(observed, color=color, linewidth=2.2)\n'
                                         '        axis.axvline(-abs(observed), color=NEUTRAL_COLOR, linestyle="--")\n'
                                         '        axis.set_title(f"{label}\\nTemporal null")\n'
                                         '        axis.set_xlabel("Null pooled slope")\n'
                                         '        axis.set_ylabel("Frequency")\n'
                                         '        style_axis(axis, grid_axis="y")\n'
                                         '\n'
                                         '        values = bootstrap_draws[:, boot_index[metric]]\n'
                                         '        axis = axes[row_index, 1]\n'
                                         '        axis.hist(values, bins=50, color=color, alpha=PLOT_ALPHA)\n'
                                         '        axis.axvline(observed, color=color, linewidth=2.2)\n'
                                         '        axis.axvline(0, color=NEUTRAL_COLOR, linestyle="--")\n'
                                         '        axis.set_title(f"{label}\\nParticipant bootstrap")\n'
                                         '        axis.set_xlabel("Bootstrap pooled slope")\n'
                                         '        axis.set_ylabel("Frequency")\n'
                                         '        style_axis(axis, grid_axis="y")\n'
                                         '\n'
                                         '    fig.suptitle("Study 1 pooled-effect uncertainty", y=1.005)\n'
                                         '    fig.tight_layout()\n'
                                         '    finish_figure(fig, FIG_DIR / '
                                         '"Study1_resampling_distributions_joint_valence.png")\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def plot_explained_variance(observed_effects, bootstrap_summary):\n'
                                         '    targets = [\n'
                                         '        ("Marginal valence", "marginal_valence_delta_r2", VALENCE_COLOR),\n'
                                         '        ("Marginal arousal", "marginal_arousal_delta_r2", AROUSAL_COLOR),\n'
                                         '        (\n'
                                         '            "Unique valence | arousal",\n'
                                         '            "conditional_valence_given_arousal_delta_r2",\n'
                                         '            CONTRAST_COLOR,\n'
                                         '        ),\n'
                                         '    ]\n'
                                         '    fig, axis = plt.subplots(figsize=(9.2, 5.1))\n'
                                         '\n'
                                         '    for position, (label, metric, color) in enumerate(targets):\n'
                                         '        row = bootstrap_summary.loc[\n'
                                         '            bootstrap_summary["effect"].eq(metric)\n'
                                         '        ].iloc[0]\n'
                                         '        estimate = observed_effects[metric]\n'
                                         '        error = np.asarray([\n'
                                         '            [max(0.0, estimate - row["bootstrap_ci_low"])],\n'
                                         '            [max(0.0, row["bootstrap_ci_high"] - estimate)],\n'
                                         '        ])\n'
                                         '        axis.errorbar(\n'
                                         '            position,\n'
                                         '            estimate,\n'
                                         '            yerr=error,\n'
                                         '            fmt="o",\n'
                                         '            markersize=9,\n'
                                         '            capsize=5,\n'
                                         '            color=color,\n'
                                         '            ecolor=color,\n'
                                         '            alpha=0.85,\n'
                                         '        )\n'
                                         '\n'
                                         '    axis.axhline(0, color=NEUTRAL_COLOR, linestyle="--")\n'
                                         '    axis.set_xticks(np.arange(len(targets)))\n'
                                         '    axis.set_xticklabels([item[0] for item in targets], rotation=12)\n'
                                         '    axis.set_ylabel("Incremental ΔR²")\n'
                                         '    axis.set_title("Additional explained variance beyond each reduced '
                                         'model")\n'
                                         '    style_axis(axis, grid_axis="y")\n'
                                         '    fig.tight_layout()\n'
                                         '    finish_figure(fig, FIG_DIR / '
                                         '"Study1_incremental_delta_R2_joint_valence.png")\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def plot_affect_contrast_results(final_summary):\n'
                                         '    effects = [\n'
                                         '        f"marginal_valence_minus_arousal_{movie}_slope"\n'
                                         '        for movie in MOVIES\n'
                                         '    ]\n'
                                         '    effects.append("marginal_valence_minus_arousal_pooled_slope")\n'
                                         '    labels = [MOVIE_LABELS[movie] for movie in MOVIES] + ["Pooled"]\n'
                                         '    subset = (\n'
                                         '        final_summary.loc[final_summary["effect"].isin(effects)]\n'
                                         '        .set_index("effect")\n'
                                         '        .reindex(effects)\n'
                                         '    )\n'
                                         '    estimates = subset["observed_estimate"].to_numpy(float)\n'
                                         '    lower = subset["bootstrap_ci_low"].to_numpy(float)\n'
                                         '    upper = subset["bootstrap_ci_high"].to_numpy(float)\n'
                                         '    errors = np.vstack([\n'
                                         '        np.maximum(0.0, estimates - lower),\n'
                                         '        np.maximum(0.0, upper - estimates),\n'
                                         '    ])\n'
                                         '\n'
                                         '    fig, axis = plt.subplots(figsize=(8.8, 5.3))\n'
                                         '    positions = np.arange(len(labels))\n'
                                         '    axis.errorbar(\n'
                                         '        estimates,\n'
                                         '        positions,\n'
                                         '        xerr=errors,\n'
                                         '        fmt="o",\n'
                                         '        markersize=8,\n'
                                         '        capsize=4,\n'
                                         '        color=CONTRAST_COLOR,\n'
                                         '        ecolor=CONTRAST_COLOR,\n'
                                         '        alpha=0.86,\n'
                                         '        linewidth=2,\n'
                                         '    )\n'
                                         '    axis.axvline(0, color=NEUTRAL_COLOR, linestyle="--", linewidth=1)\n'
                                         '    axis.set_yticks(positions)\n'
                                         '    axis.set_yticklabels(labels)\n'
                                         '    axis.invert_yaxis()\n'
                                         '    axis.set_xlabel("Valence minus arousal standardized slope")\n'
                                         '    axis.set_title("Do valence and arousal effects differ?")\n'
                                         '    for position, effect in enumerate(effects):\n'
                                         '        p_perm = subset.loc[effect, "p_perm"] if "p_perm" in subset else '
                                         'np.nan\n'
                                         '        if np.isfinite(p_perm):\n'
                                         '            axis.text(\n'
                                         '                estimates[position],\n'
                                         '                position + 0.24,\n'
                                         '                f"perm p={p_perm:.3f}",\n'
                                         '                ha="center",\n'
                                         '                va="bottom",\n'
                                         '                fontsize=8,\n'
                                         '                color=NEUTRAL_COLOR,\n'
                                         '            )\n'
                                         '    style_axis(axis, grid_axis="x")\n'
                                         '    fig.tight_layout()\n'
                                         '    finish_figure(fig, FIG_DIR / '
                                         '"Study1_valence_minus_arousal_contrasts.png")\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def plot_conditional_valence_results(final_summary):\n'
                                         '    effects = [\n'
                                         '        f"conditional_valence_given_arousal_{movie}_slope"\n'
                                         '        for movie in MOVIES\n'
                                         '    ]\n'
                                         '    effects.append("conditional_valence_given_arousal_pooled_slope")\n'
                                         '    labels = [MOVIE_LABELS[movie] for movie in MOVIES] + ["Pooled"]\n'
                                         '    subset = (\n'
                                         '        final_summary.loc[final_summary["effect"].isin(effects)]\n'
                                         '        .set_index("effect")\n'
                                         '        .reindex(effects)\n'
                                         '    )\n'
                                         '\n'
                                         '    estimates = subset["observed_estimate"].to_numpy(float)\n'
                                         '    lower = subset["bootstrap_ci_low"].to_numpy(float)\n'
                                         '    upper = subset["bootstrap_ci_high"].to_numpy(float)\n'
                                         '    errors = np.vstack([\n'
                                         '        np.maximum(0.0, estimates - lower),\n'
                                         '        np.maximum(0.0, upper - estimates),\n'
                                         '    ])\n'
                                         '\n'
                                         '    fig, axis = plt.subplots(figsize=(9.0, 5.4))\n'
                                         '    positions = np.arange(len(labels))\n'
                                         '    axis.errorbar(\n'
                                         '        estimates,\n'
                                         '        positions,\n'
                                         '        xerr=errors,\n'
                                         '        fmt="o",\n'
                                         '        markersize=8,\n'
                                         '        capsize=4,\n'
                                         '        color=CONTRAST_COLOR,\n'
                                         '        ecolor=CONTRAST_COLOR,\n'
                                         '        alpha=0.86,\n'
                                         '        linewidth=2,\n'
                                         '    )\n'
                                         '    axis.axvline(0, color=NEUTRAL_COLOR, linestyle="--", linewidth=1)\n'
                                         '    axis.set_yticks(positions)\n'
                                         '    axis.set_yticklabels(labels)\n'
                                         '    axis.invert_yaxis()\n'
                                         '    axis.set_xlabel("Valence slope controlling arousal ISC")\n'
                                         '    axis.set_title("Unique valence–DMN ISC association")\n'
                                         '\n'
                                         '    for position, effect in enumerate(effects):\n'
                                         '        p_perm = subset.loc[effect, "p_perm"]\n'
                                         '        if np.isfinite(p_perm):\n'
                                         '            axis.text(\n'
                                         '                estimates[position],\n'
                                         '                position + 0.24,\n'
                                         '                f"perm p={p_perm:.3f}",\n'
                                         '                ha="center",\n'
                                         '                va="bottom",\n'
                                         '                fontsize=8,\n'
                                         '                color=NEUTRAL_COLOR,\n'
                                         '            )\n'
                                         '    style_axis(axis, grid_axis="x")\n'
                                         '    fig.tight_layout()\n'
                                         '    finish_figure(fig, FIG_DIR / "Study1_conditional_valence_results.png")\n'
                                         '\n'
                                         '\n'
                                         'def plot_variance_components(observed_effects, bootstrap_summary):\n'
                                         '    fig, axes = plt.subplots(1, 2, figsize=(13.2, 5.2))\n'
                                         '\n'
                                         '    left_effects = [\n'
                                         '        "marginal_valence_delta_r2",\n'
                                         '        "marginal_arousal_delta_r2",\n'
                                         '        "conditional_valence_given_arousal_delta_r2",\n'
                                         '        "marginal_valence_minus_arousal_delta_r2",\n'
                                         '    ]\n'
                                         '    left_labels = [\n'
                                         '        "Marginal valence",\n'
                                         '        "Marginal arousal",\n'
                                         '        "Unique valence | arousal",\n'
                                         '        "Marginal Δ(valence-arousal)",\n'
                                         '    ]\n'
                                         '    left_colors = [\n'
                                         '        VALENCE_COLOR,\n'
                                         '        AROUSAL_COLOR,\n'
                                         '        CONTRAST_COLOR,\n'
                                         '        NEUTRAL_COLOR,\n'
                                         '    ]\n'
                                         '\n'
                                         '    for position, effect, color in zip(\n'
                                         '        np.arange(len(left_effects)), left_effects, left_colors\n'
                                         '    ):\n'
                                         '        row = bootstrap_summary.loc[\n'
                                         '            bootstrap_summary["effect"].eq(effect)\n'
                                         '        ].iloc[0]\n'
                                         '        estimate = observed_effects[effect]\n'
                                         '        error = np.asarray([\n'
                                         '            [max(0.0, estimate - row["bootstrap_ci_low"])],\n'
                                         '            [max(0.0, row["bootstrap_ci_high"] - estimate)],\n'
                                         '        ])\n'
                                         '        axes[0].errorbar(\n'
                                         '            position,\n'
                                         '            estimate,\n'
                                         '            yerr=error,\n'
                                         '            fmt="o",\n'
                                         '            markersize=8,\n'
                                         '            capsize=4,\n'
                                         '            color=color,\n'
                                         '            ecolor=color,\n'
                                         '            alpha=0.86,\n'
                                         '        )\n'
                                         '\n'
                                         '    axes[0].axhline(0, color=NEUTRAL_COLOR, linestyle="--", linewidth=1)\n'
                                         '    axes[0].set_xticks(np.arange(len(left_labels)))\n'
                                         '    axes[0].set_xticklabels(left_labels, rotation=18)\n'
                                         '    axes[0].set_ylabel("Incremental R²")\n'
                                         '    axes[0].set_title("Additional explained variance")\n'
                                         '    style_axis(axes[0], grid_axis="y")\n'
                                         '\n'
                                         '    right_effects = [\n'
                                         '        "marginal_valence_heterogeneity",\n'
                                         '        "marginal_arousal_heterogeneity",\n'
                                         '        "conditional_valence_given_arousal_heterogeneity",\n'
                                         '    ]\n'
                                         '    right_labels = ["Valence", "Arousal", "Valence | arousal"]\n'
                                         '    right_colors = [VALENCE_COLOR, AROUSAL_COLOR, CONTRAST_COLOR]\n'
                                         '\n'
                                         '    for position, effect, color in zip(\n'
                                         '        np.arange(len(right_effects)), right_effects, right_colors\n'
                                         '    ):\n'
                                         '        row = bootstrap_summary.loc[\n'
                                         '            bootstrap_summary["effect"].eq(effect)\n'
                                         '        ].iloc[0]\n'
                                         '        estimate = observed_effects[effect]\n'
                                         '        error = np.asarray([\n'
                                         '            [max(0.0, estimate - row["bootstrap_ci_low"])],\n'
                                         '            [max(0.0, row["bootstrap_ci_high"] - estimate)],\n'
                                         '        ])\n'
                                         '        axes[1].errorbar(\n'
                                         '            position,\n'
                                         '            estimate,\n'
                                         '            yerr=error,\n'
                                         '            fmt="o",\n'
                                         '            markersize=8,\n'
                                         '            capsize=4,\n'
                                         '            color=color,\n'
                                         '            ecolor=color,\n'
                                         '            alpha=0.86,\n'
                                         '        )\n'
                                         '\n'
                                         '    axes[1].axhline(0, color=NEUTRAL_COLOR, linestyle="--", linewidth=1)\n'
                                         '    axes[1].set_xticks(np.arange(len(right_labels)))\n'
                                         '    axes[1].set_xticklabels(right_labels)\n'
                                         '    axes[1].set_ylabel("Sum of squared movie-slope deviations")\n'
                                         '    axes[1].set_title("Cross-movie slope heterogeneity")\n'
                                         '    style_axis(axes[1], grid_axis="y")\n'
                                         '\n'
                                         '    fig.suptitle("Study 1 variance and heterogeneity diagnostics", y=1.02)\n'
                                         '    fig.tight_layout()\n'
                                         '    finish_figure(fig, FIG_DIR / '
                                         '"Study1_variance_components_joint_valence.png")\n'
                                         '\n'
                                         '\n'
                                         '\n'
                                         'def merge_results(observed_effects, permutation_summary, '
                                         'bootstrap_summary):\n'
                                         '    effects = sorted(set(\n'
                                         '        list(observed_effects)\n'
                                         '        + permutation_summary["effect"].tolist()\n'
                                         '        + bootstrap_summary["effect"].tolist()\n'
                                         '    ))\n'
                                         '    rows = []\n'
                                         '    for effect in effects:\n'
                                         '        row = {\n'
                                         '            "study": "Study1",\n'
                                         '            "effect": effect,\n'
                                         '            "observed_estimate": observed_effects.get(effect, np.nan),\n'
                                         '        }\n'
                                         '        for source, columns in [\n'
                                         '            (permutation_summary, [\n'
                                         '                "p_perm", "permutation_tail", "null_mean", "null_sd",\n'
                                         '                "null_q025", "null_q975", "n_permutations",\n'
                                         '            ]),\n'
                                         '            (bootstrap_summary, [\n'
                                         '                "bootstrap_mean", "bootstrap_bias", "bootstrap_se",\n'
                                         '                "bootstrap_z_approx", "bootstrap_p_normal_approx",\n'
                                         '                "bootstrap_p_sign_approx", "bootstrap_ci_low",\n'
                                         '                "bootstrap_ci_high", "n_bootstrap",\n'
                                         '            ]),\n'
                                         '        ]:\n'
                                         '            source_row = source.loc[source["effect"].eq(effect)]\n'
                                         '            if not source_row.empty:\n'
                                         '                for column in columns:\n'
                                         '                    if column in source_row.columns:\n'
                                         '                        row[column] = source_row.iloc[0][column]\n'
                                         '        rows.append(row)\n'
                                         '\n'
                                         '    output = pd.DataFrame(rows)\n'
                                         '    output["inference_role"] = "descriptive_or_secondary"\n'
                                         '    output.loc[\n'
                                         '        output["effect"].eq("marginal_valence_pooled_slope"),\n'
                                         '        "inference_role",\n'
                                         '    ] = "primary_marginal_valence"\n'
                                         '    output.loc[\n'
                                         '        output["effect"].eq("marginal_valence_heterogeneity"),\n'
                                         '        "inference_role",\n'
                                         '    ] = "primary_generalization"\n'
                                         '    output.loc[\n'
                                         '        output["effect"].eq("marginal_arousal_pooled_slope"),\n'
                                         '        "inference_role",\n'
                                         '    ] = "secondary_affect"\n'
                                         '    output.loc[\n'
                                         '        output["effect"].str.startswith(\n'
                                         '            "conditional_valence_given_arousal",\n'
                                         '            na=False,\n'
                                         '        ),\n'
                                         '        "inference_role",\n'
                                         '    ] = "unique_valence_controlling_arousal"\n'
                                         '    output.loc[\n'
