                                     '\n'
                                     'MODEL_COVARIATES = [\n'
                                     '    "brightness_z",\n'
                                     '    "audio_rms_z",\n'
                                     '    "optical_flow_z",\n'
                                     '    "linear_time",\n'
                                     '    "quadratic_time",\n'
                                     ']\n'
                                     '\n'
                                     '# Set an integer for a quick test; retain None for the final analysis.\n'
                                     'MAX_COMMON_SUBJECTS = None\n'
                                     '\n'
                                     'N_PERMUTATIONS = 10000\n'
                                     'N_BOOTSTRAP = 10000\n'
                                     'RANDOM_SEED = 42\n'
                                     '\n'
                                     '# None means automatic estimation: first lag where |ACF| < ACF_THRESHOLD,\n'
                                     '# taking the maximum across valence and fear within each session.\n'
                                     'FIXED_BLOCK_LEN_BY_SESSION = {\n'
                                     '    "horror01": 6,\n'
                                     '    "horror02": 6,\n'
                                     '}\n'
                                     'ACF_THRESHOLD = 0.10\n'
                                     '\n'
                                     '# Each session contributes one equally weighted replication to the pooled '
                                     'slope.\n'
                                     'STANDARDIZE_WITHIN_SESSION = True\n'
                                     '\n'
                                     '# Cache controls.\n'
                                     'REBUILD_PAIR_CACHE = True\n'
                                     'LOAD_PAIR_CACHE_TO_RAM = False\n'
                                     'RESUME_RESAMPLING = False\n'
                                     '\n'
                                     '# Progress display: update one terminal line rather than printing each '
                                     'iteration.\n'
                                     'NEURAL_LOAD_PROGRESS_EVERY = 5\n'
                                     'CACHE_PROGRESS_EVERY = 10\n'
                                     'PERM_PROGRESS_EVERY = 25\n'
                                     'BOOT_PROGRESS_EVERY = 25\n'
                                     'CHECKPOINT_EVERY = 100\n'
                                     'PROGRESS_LINE_WIDTH = 160\n'
                                     '\n'
                                     '# Analysis switches.\n'
                                     'RUN_PERMUTATION = True\n'
                                     'RUN_BOOTSTRAP = True\n'
                                     '\n'
                                     '\n'
                                     'RUN_DATA_DIAGNOSTICS = True\n'
                                     'SAVE_OBSERVED_WINDOW_TABLE = True\n'
                                     'SHOW_PLOTS = True\n'
                                     '\n'
                                     '# Figure style.\n'
                                     'VALENCE_COLOR = "#E978A8"      # pink\n'
                                     'FEAR_COLOR = "#45B8AC"         # jade / turquoise\n'
                                     'NEURAL_COLOR = "#6B7280"\n'
                                     'NEUTRAL_COLOR = "#5E6673"\n'
                                     'PLOT_ALPHA = 0.60\n'
                                     'GRID_ALPHA = 0.20\n'
                                     'DIAGNOSTIC_ACF_MAX_LAG = 80\n'
                                     'DIAGNOSTIC_SCATTER_SIZE = 16\n'
                                     '\n'
                                     'AFFECT_COLORS = {\n'
                                     '    "valence": VALENCE_COLOR,\n'
                                     '    "fear": FEAR_COLOR,\n'
                                     '}\n'
                                     '\n'
                                     'AFFECT_DIVERGING_CMAP = LinearSegmentedColormap.from_list(\n'
                                     '    "fear_white_valence",\n'
                                     '    [FEAR_COLOR, "#FFFFFF", VALENCE_COLOR],\n'
                                     ')\n'
                                     '\n'
                                     'plt.rcParams.update({\n'
                                     '    "figure.dpi": 120,\n'
                                     '    "axes.titlesize": 13,\n'
                                     '    "axes.labelsize": 11,\n'
                                     '    "xtick.labelsize": 10,\n'
                                     '    "ytick.labelsize": 10,\n'
                                     '    "legend.fontsize": 9,\n'
                                     '})\n'
                                     '\n'
                                     '# Used only if atlas parsing fails. Zero-based Shen268 DMN node indices.\n'
                                     'DMN_NODES_FALLBACK_ZERO_BASED = [\n'
                                     '    2, 4, 5, 12, 48, 49, 84, 85, 89, 95,\n'
                                     '    114, 133, 137, 140, 202, 221, 222, 224, 226, 238,\n'
                                     ']\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# BASIC HELPERS\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def fisher_z(r):\n'
                                     '    r = np.asarray(r, dtype=np.float64)\n'
                                     '    return np.arctanh(np.clip(r, -0.999999, 0.999999))\n'
                                     '\n'
                                     '\n'
                                     'def inv_fisher_z(z):\n'
                                     '    return np.tanh(z)\n'
                                     '\n'
                                     '\n'
                                     'def zscore_1d(values):\n'
                                     '    values = np.asarray(values, dtype=np.float64)\n'
                                     '    mean = np.nanmean(values)\n'
                                     '    sd = np.nanstd(values, ddof=1)\n'
                                     '    if not np.isfinite(sd) or sd == 0:\n'
                                     '        return np.zeros_like(values, dtype=np.float64)\n'
                                     '    return (values - mean) / sd\n'
                                     '\n'
                                     '\n'
                                     'def normalize_subject_id(value):\n'
                                     '    """Normalize local participant-label variants to a consistent string '
                                     'form."""\n'
                                     '    text = str(value).strip()\n'
                                     '    text = re.sub(r"\\.0$", "", text)\n'
                                     '    text = re.sub(r"^sub-", "", text, flags=re.IGNORECASE)\n'
                                     '\n'
                                     '    if re.fullmatch(r"\\d+", text):\n'
                                     '        text = text.zfill(2)\n'
                                     '\n'
                                     '    return f"sub-{text}"\n'
                                     '\n'
                                     '\n'
                                     'def get_subject_id_from_path(path):\n'
                                     '    match = re.search(r"sub-([A-Za-z0-9]+)", path.name, flags=re.IGNORECASE)\n'
                                     '    if match is None:\n'
                                     '        raise ValueError(f"Cannot parse participant ID from: {path}")\n'
                                     '    return normalize_subject_id(match.group(1))\n'
                                     '\n'
                                     '\n'
                                     'def load_participant_config():\n'
                                     '    raw = os.environ.get(PARTICIPANT_CONFIG_ENV, "").strip()\n'
                                     '    path_value = os.environ.get(PARTICIPANT_CONFIG_PATH_ENV, "").strip()\n'
                                     '    if raw and path_value:\n'
                                     '        raise ValueError(\n'
                                     '            f"Set only one of {PARTICIPANT_CONFIG_ENV} or '
                                     '{PARTICIPANT_CONFIG_PATH_ENV}."\n'
                                     '        )\n'
                                     '    if raw:\n'
                                     '        config = json.loads(raw)\n'
                                     '    elif path_value:\n'
                                     '        path = Path(path_value).expanduser()\n'
                                     '        if not path.exists():\n'
                                     '            raise FileNotFoundError(\n'
                                     '                f"Participant configuration not found: {path}. "\n'
                                     '                "Keep this file outside the public repository or list it in '
                                     '.gitignore."\n'
                                     '            )\n'
                                     '        config = json.loads(path.read_text(encoding="utf-8"))\n'
                                     '    else:\n'
                                     '        config = {}\n'
                                     '    study = dict(config.get("study2", {}))\n'
                                     '    mode = study.get("mode", DEPENDENCE_MODE)\n'
                                     '    if mode != DEPENDENCE_MODE:\n'
                                     '        raise ValueError(\n'
                                     '            f"Study 2 requires mode={DEPENDENCE_MODE!r}; found {mode!r}."\n'
                                     '        )\n'
                                     '    return study\n'
                                     '\n'
                                     '\n'
                                     'def configured_common_ids():\n'
                                     '    values = load_participant_config().get("common_ids")\n'
                                     '    if values is None:\n'
                                     '        raise ValueError(\n'
                                     '            "Study 2 matched-modalities analysis requires local pseudonymous "\n'
                                     '            "matching IDs under study2.common_ids in the local participant "\n'
                                     '            "configuration. The public repository intentionally contains no '
                                     'IDs."\n'
                                     '        )\n'
                                     '    ids = [normalize_subject_id(value) for value in values]\n'
                                     '    assert_unique_ids(ids, "local Study 2 common_ids")\n'
                                     '    if len(ids) < 2:\n'
                                     '        raise ValueError("At least two matched participants are required.")\n'
                                     '    return ids\n'
                                     '\n'
                                     '\n'
                                     'def id_fingerprint(ids):\n'
                                     '    """Compatibility stub; ID-derived fingerprints are not persisted."""\n'
                                     '    return None\n'
                                     '\n'
                                     'def assert_unique_ids(ids, label):\n'
                                     '    series = pd.Series([normalize_subject_id(value) for value in ids])\n'
                                     '    duplicated = series[series.duplicated()].unique().tolist()\n'
                                     '    if duplicated:\n'
                                     '        raise ValueError(f"Duplicated participant IDs in {label}: '
                                     '{duplicated[:10]}")\n'
                                     '\n'
                                     '\n'
                                     'def save_json(obj, path):\n'
                                     '    with open(path, "w", encoding="utf-8") as file:\n'
                                     '        json.dump(obj, file, ensure_ascii=False, indent=2)\n'
                                     '\n'
                                     '\n'
                                     'def load_json(path):\n'
                                     '    with open(path, "r", encoding="utf-8") as file:\n'
                                     '        return json.load(file)\n'
                                     '\n'
                                     '\n'
                                     'def safe_quantile(values, probs=(0.025, 0.975)):\n'
                                     '    values = np.asarray(values, dtype=float)\n'
                                     '    values = values[np.isfinite(values)]\n'
                                     '    if len(values) == 0:\n'
                                     '        return np.nan, np.nan\n'
                                     '    return tuple(np.quantile(values, probs))\n'
                                     '\n'
                                     '\n'
                                     'def two_sided_resampling_p(null_values, observed):\n'
                                     '    null_values = np.asarray(null_values, dtype=float)\n'
                                     '    null_values = null_values[np.isfinite(null_values)]\n'
                                     '    if len(null_values) == 0 or not np.isfinite(observed):\n'
                                     '        return np.nan\n'
                                     '    return float(\n'
                                     '        (1 + np.sum(np.abs(null_values) >= abs(observed)))\n'
                                     '        / (len(null_values) + 1)\n'
                                     '    )\n'
                                     '\n'
                                     '\n'
                                     'def upper_tail_resampling_p(null_values, observed):\n'
                                     '    null_values = np.asarray(null_values, dtype=float)\n'
                                     '    null_values = null_values[np.isfinite(null_values)]\n'
                                     '    if len(null_values) == 0 or not np.isfinite(observed):\n'
                                     '        return np.nan\n'
                                     '    return float(\n'
                                     '        (1 + np.sum(null_values >= observed))\n'
                                     '        / (len(null_values) + 1)\n'
                                     '    )\n'
                                     '\n'
                                     '\n'
                                     'def sign_based_p(values):\n'
                                     '    values = np.asarray(values, dtype=float)\n'
                                     '    values = values[np.isfinite(values)]\n'
                                     '    if len(values) == 0:\n'
                                     '        return np.nan\n'
                                     '    p_le = (np.sum(values <= 0) + 1) / (len(values) + 1)\n'
                                     '    p_ge = (np.sum(values >= 0) + 1) / (len(values) + 1)\n'
                                     '    return float(min(1.0, 2.0 * min(p_le, p_ge)))\n'
                                     '\n'
                                     '\n'
                                     'def print_section(title, width=108):\n'
                                     '    print("\\n" + "=" * width)\n'
                                     '    print(title)\n'
                                     '    print("=" * width)\n'
                                     '\n'
                                     '\n'
                                     'def format_elapsed(seconds):\n'
                                     '    seconds = max(0.0, float(seconds))\n'
                                     '    if seconds < 60:\n'
                                     '        return f"{seconds:5.1f}s"\n'
                                     '    minutes, seconds = divmod(seconds, 60)\n'
                                     '    if minutes < 60:\n'
                                     '        return f"{int(minutes):02d}:{seconds:04.1f}"\n'
                                     '    hours, minutes = divmod(minutes, 60)\n'
                                     '    return f"{int(hours):02d}:{int(minutes):02d}:{seconds:04.1f}"\n'
                                     '\n'
                                     '\n'
                                     'def print_progress(label, current, total, start_time=None, extra="", '
                                     'done=False):\n'
                                     '    total = max(int(total), 1)\n'
                                     '    current = int(current)\n'
                                     '    percent = 100.0 * current / total\n'
                                     '\n'
                                     '    timing = ""\n'
                                     '    if start_time is not None:\n'
                                     '        elapsed = time.time() - start_time\n'
                                     '        timing = f" | elapsed={format_elapsed(elapsed)}"\n'
                                     '        if 0 < current < total:\n'
                                     '            eta = elapsed * (total - current) / current\n'
                                     '            timing += f" | ETA={format_elapsed(eta)}"\n'
                                     '\n'
                                     '    extra_text = f" | {extra}" if extra else ""\n'
                                     '    message = (\n'
                                     '        f"{label} | {current:,}/{total:,} ({percent:6.2f}%)"\n'
                                     '        f"{timing}{extra_text}"\n'
                                     '    )\n'
                                     '    padded = f"{message:<{PROGRESS_LINE_WIDTH}}"\n'
                                     '    print(padded, end="\\n" if done else "\\r", flush=True)\n'
                                     '\n'
                                     '\n'
                                     'def style_axis(axis, grid_axis=None):\n'
                                     '    axis.spines["top"].set_visible(False)\n'
                                     '    axis.spines["right"].set_visible(False)\n'
                                     '    if grid_axis is not None:\n'
                                     '        axis.grid(axis=grid_axis, alpha=GRID_ALPHA, linewidth=0.8)\n'
                                     '\n'
                                     '\n'
                                     'def finish_figure(fig, output_path):\n'
                                     '    fig.patch.set_facecolor("white")\n'
                                     '    fig.savefig(output_path, dpi=400, bbox_inches="tight", facecolor="white")\n'
                                     '    if SHOW_PLOTS:\n'
                                     '        plt.show()\n'
                                     '    plt.close(fig)\n'
                                     '    print(f"[FIGURE SAVED] {output_path}")\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# INPUT DISCOVERY AND ATLAS\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def validate_paths():\n'
                                     '    required_paths = [BRAIN_DIR, BASE_DIR, SHEN_ATLAS_PATH]\n'
                                     '    required_paths.extend(\n'
                                     '        BEHAVIOR_PATHS[session][affect]\n'
                                     '        for session in SESSIONS\n'
                                     '        for affect in AFFECTS\n'
                                     '    )\n'
                                     '\n'
                                     '    missing = [path for path in required_paths if not path.exists()]\n'
                                     '    if missing:\n'
                                     '        raise FileNotFoundError(\n'
                                     '            "Required paths are missing:\\n" + "\\n".join(map(str, missing))\n'
                                     '        )\n'
                                     '\n'
                                     '\n'
                                     'def get_brain_files(session):\n'
                                     '    patterns = [\n'
                                     '        f"sub-*_{session}_6mmblur-regression_shen268.csv",\n'
                                     '        f"sub-*{session}*shen268.csv",\n'
                                     '    ]\n'
                                     '\n'
                                     '    matches = []\n'
                                     '    for pattern in patterns:\n'
                                     '        matches.extend(BRAIN_DIR.rglob(pattern))\n'
                                     '\n'
                                     '    files = sorted({path for path in matches if not '
                                     'path.name.startswith("._")})\n'
                                     '    if len(files) < 2:\n'
                                     '        raise ValueError(\n'
                                     '            f"Need at least two neural files for {session}; found {len(files)} '
                                     '"\n'
                                     '            f"under {BRAIN_DIR}"\n'
                                     '        )\n'
                                     '\n'
                                     '    id_to_file = {}\n'
                                     '    for path in files:\n'
                                     '        subject_id = get_subject_id_from_path(path)\n'
                                     '        if subject_id in id_to_file:\n'
                                     '            raise ValueError(\n'
                                     '                f"Multiple neural files found for {subject_id}, {session}:\\n"\n'
                                     '                f"  {id_to_file[subject_id]}\\n  {path}"\n'
                                     '            )\n'
                                     '        id_to_file[subject_id] = path\n'
                                     '\n'
                                     '    return id_to_file\n'
                                     '\n'
                                     '\n'
                                     'def discover_covariate_file(session):\n'
                                     '    search_roots = [LOWLEVEL_DIR / session, LOWLEVEL_DIR]\n'
                                     '    matches = []\n'
                                     '\n'
                                     '    for root in search_roots:\n'
                                     '        if root.exists():\n'
                                     '            matches.extend(root.rglob(f"{session}_window-*TR_step-1TR.csv"))\n'
                                     '\n'
                                     '    matches = sorted(set(matches))\n'
                                     '    if len(matches) != 1:\n'
                                     '        message = (\n'
                                     '            f"Expected exactly one window-level audiovisual covariate file for '
                                     '"\n'
                                     '            f"{session}, but found {len(matches)}.\\n"\n'
                                     '            f"Search root: {LOWLEVEL_DIR}\\n"\n'
                                     '            f"Expected filename pattern: {session}_window-*TR_step-1TR.csv"\n'
                                     '        )\n'
                                     '        if matches:\n'
                                     '            message += "\\nMatches:\\n" + "\\n".join(map(str, matches))\n'
                                     '        raise FileNotFoundError(message)\n'
                                     '\n'
                                     '    path = matches[0]\n'
                                     '    match = re.search(r"window-(\\d+)TR_step-1TR", path.name)\n'
                                     '    if match is None:\n'
                                     '        raise ValueError(f"Cannot infer window size from covariate filename: '
                                     '{path}")\n'
                                     '\n'
                                     '    window_size = int(match.group(1))\n'
                                     '    return path, window_size\n'
                                     '\n'
                                     '\n'
                                     'def load_atlas():\n'
                                     '    atlas = pd.read_csv(SHEN_ATLAS_PATH)\n'
                                     '    required = ["ROI_num", "NTW"]\n'
                                     '    missing = [column for column in required if column not in atlas.columns]\n'
                                     '    if missing:\n'
                                     '        raise ValueError(\n'
                                     '            f"shen268.csv is missing columns: {missing}. "\n'
                                     '            f"Available: {list(atlas.columns)}"\n'
                                     '        )\n'
                                     '\n'
                                     '    atlas = atlas.copy()\n'
                                     '    atlas["NTW"] = atlas["NTW"].astype(str).str.strip()\n'
                                     '    return atlas\n'
                                     '\n'
                                     '\n'
                                     'def candidate_columns_from_atlas_rows(atlas_rows):\n'
                                     '    roi_num = (\n'
                                     '        pd.to_numeric(atlas_rows["ROI_num"], errors="coerce")\n'
                                     '        .dropna()\n'
                                     '        .astype(int)\n'
                                     '    )\n'
                                     '    return [\n'
                                     '        [str(value) for value in roi_num],\n'
                                     '        [str(value - 1) for value in roi_num],\n'
                                     '        [str(value) for value in atlas_rows.index],\n'
                                     '        [str(value + 1) for value in atlas_rows.index],\n'
                                     '    ]\n'
                                     '\n'
                                     '\n'
                                     'def resolve_dmn_columns(atlas, neural_columns):\n'
                                     '    neural_columns = [str(column) for column in neural_columns]\n'
                                     '    dmn_rows = atlas.loc[\n'
                                     '        atlas["NTW"].astype(str).str.casefold().eq("dmn")\n'
                                     '    ].copy()\n'
                                     '\n'
                                     '    if dmn_rows.empty:\n'
                                     '        raise ValueError("No DMN rows found in shen268.csv")\n'
                                     '\n'
                                     '    candidates = candidate_columns_from_atlas_rows(dmn_rows)\n'
                                     '    best = max(\n'
                                     '        candidates,\n'
                                     '        key=lambda columns: sum(column in neural_columns for column in '
                                     'columns),\n'
                                     '    )\n'
                                     '    matched = [column for column in best if column in neural_columns]\n'
                                     '\n'
                                     '    if not matched:\n'
                                     '        matched = [\n'
                                     '            str(value)\n'
                                     '            for value in DMN_NODES_FALLBACK_ZERO_BASED\n'
                                     '            if str(value) in neural_columns\n'
                                     '        ]\n'
                                     '\n'
                                     '    if not matched:\n'
                                     '        raise ValueError(\n'
                                     '            "No neural columns matched the whole-DMN definition. "\n'
                                     '            "Check shen268.csv ROI indexing and neural CSV column names."\n'
                                     '        )\n'
                                     '\n'
                                     '    metadata = pd.DataFrame([{\n'
                                     '        "roi": "DMN",\n'
                                     '        "n_atlas_rows": len(dmn_rows),\n'
                                     '        "n_matched_columns": len(matched),\n'
                                     '        "matched_columns": ", ".join(matched),\n'
                                     '    }])\n'
                                     '\n'
                                     '    print(f"[ROI MATCH] Whole DMN: {len(matched)} columns -> {matched}")\n'
                                     '    return matched, metadata\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# MATCHED PARTICIPANT LOADING\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def load_behavior_matrix(path, label):\n'
                                     '    """Read one merged behavioral CSV directly as participants x time '
                                     'points."""\n'
                                     '    path = Path(path)\n'
                                     '    df = pd.read_csv(path)\n'
                                     '    df.columns = [str(column).strip() for column in df.columns]\n'
                                     '\n'
                                     '    # Prefer an explicit participant-ID column. If pandas wrote the participant\n'
                                     '    # index as an unnamed first column, accept it only when it contains sub-* '
                                     'IDs.\n'
                                     '    subject_candidates = [\n'
                                     '        column\n'
                                     '        for column in df.columns\n'
                                     '        if column.lower() in {\n'
                                     '            "subject", "subject_id", "participant", "participant_id", "sub"\n'
                                     '        }\n'
                                     '    ]\n'
                                     '    if subject_candidates:\n'
                                     '        subject_column = subject_candidates[0]\n'
                                     '    else:\n'
                                     '        first_column = df.columns[0]\n'
                                     '        first_values = df[first_column].astype(str).str.strip()\n'
                                     '        normalized_first = first_values.map(normalize_subject_id)\n'
                                     '        if normalized_first.str.startswith("sub-").all():\n'
                                     '            subject_column = first_column\n'
                                     '        else:\n'
                                     '            raise ValueError(\n'
                                     '                f"No participant-ID column found in {path}. Columns begin with: '
                                     '"\n'
                                     '                f"{df.columns[:8].tolist()}"\n'
                                     '            )\n'
                                     '\n'
                                     '    ids = np.asarray(\n'
                                     '        [normalize_subject_id(value) for value in df[subject_column]],\n'
                                     '        dtype=str,\n'
                                     '    )\n'
                                     '    assert_unique_ids(ids, label)\n'
                                     '\n'
                                     '    time_frame = df.drop(columns=[subject_column]).copy()\n'
                                     '    # Drop only accidental pandas index columns; never delete genuine time '
                                     'columns.\n'
                                     '    for column in list(time_frame.columns):\n'
                                     '        if not column.lower().startswith("unnamed:"):\n'
                                     '            continue\n'
                                     '        numeric = pd.to_numeric(time_frame[column], errors="coerce")\n'
                                     '        sequential = (\n'
                                     '            numeric.notna().all()\n'
                                     '            and np.array_equal(numeric.to_numpy(), np.arange(len(numeric)))\n'
                                     '        )\n'
                                     '        if sequential or time_frame[column].isna().all():\n'
                                     '            time_frame = time_frame.drop(columns=[column])\n'
                                     '\n'
                                     '    values = (\n'
                                     '        time_frame\n'
                                     '        .apply(pd.to_numeric, errors="coerce")\n'
                                     '        .to_numpy(dtype=np.float64)\n'
                                     '    )\n'
                                     '\n'
                                     '    source_timepoints = int(values.shape[1])\n'
                                     '    if source_timepoints < 3:\n'
                                     '        raise ValueError(f"Behavior matrix has too few raw time points: '
                                     '{path}")\n'
                                     '\n'
                                     '    # IMPORTANT: do not align inside the file loader.  Raw A/B matrices are\n'
                                     '    # returned unchanged here.  The fixed front-9 operation is applied once,\n'
                                     '    # centrally, inside prepare_all_data() before participant matching or any\n'
                                     '    # length validation.  This makes the alignment step explicit and auditable.\n'
                                     '    print(\n'
                                     '        f"[BEHAVIOR RAW LOAD] {label}: path={path} | "\n'
                                     '        f"participants={len(ids)} | raw TR={source_timepoints} | "\n'
                                     '        f"ID column={subject_column!r}"\n'
                                     '    )\n'
                                     '\n'
                                     '    return {\n'
                                     '        subject_id: values[index].copy()\n'
                                     '        for index, subject_id in enumerate(ids)\n'
                                     '    }\n'
                                     '\n'
                                     '\n'
                                     'def load_all_behavior_maps():\n'
                                     '    output = {session: {} for session in SESSIONS}\n'
                                     '    for session in SESSIONS:\n'
                                     '        for affect in AFFECTS:\n'
                                     '            path = BEHAVIOR_PATHS[session][affect]\n'
                                     '            output[session][affect] = load_behavior_matrix(\n'
                                     '                path,\n'
                                     '                f"{session}-{affect}",\n'
                                     '            )\n'
                                     '            first = next(iter(output[session][affect].values()))\n'
                                     '            print(\n'
                                     '                f"[BEHAVIOR RAW] {session} | {affect}: "\n'
                                     '                f"n={len(output[session][affect])}, raw TR={len(first)}"\n'
                                     '            )\n'
                                     '    return output\n'
                                     '\n'
                                     '\n'
                                     'def apply_behavior_front9_in_prepare(behavior_maps):\n'
                                     '    """Drop exactly the first 9 behavioral TRs once, before matching/checks."""\n'
                                     '    aligned = {session: {} for session in SESSIONS}\n'
                                     '    front_drop = int(BEHAVIOR_FRONT_DROP_TR)\n'
                                     '\n'
                                     '    for session in SESSIONS:\n'
                                     '        for affect in AFFECTS:\n'
                                     '            source_map = behavior_maps[session][affect]\n'
                                     '            raw_lengths = sorted({len(np.asarray(v)) for v in '
                                     'source_map.values()})\n'
                                     '            if len(raw_lengths) != 1:\n'
                                     '                raise ValueError(\n'
                                     '                    f"[BEHAVIOR ALIGNMENT ERROR] {session}-{affect}: "\n'
                                     '                    f"participant raw lengths differ: {raw_lengths}"\n'
                                     '                )\n'
                                     '            raw_tr = int(raw_lengths[0])\n'
                                     '            if raw_tr <= front_drop:\n'
                                     '                raise ValueError(\n'
                                     '                    f"[BEHAVIOR ALIGNMENT ERROR] {session}-{affect}: "\n'
                                     '                    f"raw TR={raw_tr} cannot drop first {front_drop} TRs"\n'
                                     '                )\n'
                                     '\n'
                                     '            aligned_map = {\n'
                                     '                subject_id: np.asarray(values, '
                                     'dtype=np.float64)[front_drop:].copy()\n'
                                     '                for subject_id, values in source_map.items()\n'
                                     '            }\n'
                                     '            aligned_lengths = sorted({len(v) for v in aligned_map.values()})\n'
                                     '            if len(aligned_lengths) != 1:\n'
                                     '                raise RuntimeError(\n'
                                     '                    f"[BEHAVIOR ALIGNMENT ERROR] {session}-{affect}: "\n'
                                     '                    f"aligned lengths differ: {aligned_lengths}"\n'
                                     '                )\n'
                                     '            aligned_tr = int(aligned_lengths[0])\n'
                                     '            if aligned_tr != raw_tr - front_drop:\n'
                                     '                raise RuntimeError(\n'
                                     '                    f"[BEHAVIOR ALIGNMENT ERROR] {session}-{affect}: "\n'
                                     '                    f"raw TR={raw_tr}, drop={front_drop}, aligned '
                                     'TR={aligned_tr}"\n'
                                     '                )\n'
                                     '\n'
                                     '            aligned[session][affect] = aligned_map\n'
                                     '            print(\n'
                                     '                f"[BEHAVIOR FRONT-9 APPLIED IN PREPARE] {session}-{affect}: "\n'
                                     '                f"raw TR={raw_tr} -> drop first {front_drop} -> "\n'
                                     '                f"aligned TR={aligned_tr}; tail dropped=0; '
                                     'n={len(aligned_map)}"\n'
                                     '            )\n'
                                     '\n'
                                     '    return aligned\n'
                                     '\n'
                                     '\n'
                                     'def determine_common_subjects(brain_files, behavior_maps):\n'
                                     '    """Validate the matched-participant list across all local '
                                     'sources."""\n'
                                     '    source_sets = {\n'
                                     '        f"neural_{session}": set(brain_files[session]) for session in SESSIONS\n'
                                     '    }\n'
                                     '    source_sets.update({\n'
                                     '        f"behavior_{session}_{affect}": set(behavior_maps[session][affect])\n'
                                     '        for session in SESSIONS for affect in AFFECTS\n'
                                     '    })\n'
                                     '\n'
                                     '    required_ids = configured_common_ids()\n'
                                     '    if MAX_COMMON_SUBJECTS is not None:\n'
                                     '        required_ids = required_ids[: int(MAX_COMMON_SUBJECTS)]\n'
                                     '    required_set = set(required_ids)\n'
                                     '\n'
                                     '    rows = []\n'
                                     '    missing_sources = []\n'
                                     '    for source, available_ids in source_sets.items():\n'
                                     '        n_missing = len(required_set - available_ids)\n'
                                     '        rows.append({\n'
                                     '            "source": source,\n'
                                     '            "n_available": len(available_ids),\n'
                                     '            "n_required": len(required_ids),\n'
                                     '            "n_required_present": len(required_set & available_ids),\n'
                                     '            "n_missing_required": n_missing,\n'
                                     '            "n_extra_not_used": len(available_ids - required_set),\n'
                                     '        })\n'
                                     '        if n_missing:\n'
                                     '            missing_sources.append((source, n_missing))\n'
                                     '\n'
                                     '    summary = pd.DataFrame(rows)\n'
                                     '    summary.to_csv(OUT_DIR / "Study2_participant_matching_summary.csv", '
                                     'index=False)\n'
                                     '    print_section("MATCHED-PARTICIPANT VALIDATION")\n'
                                     '    print(summary.to_string(index=False))\n'
                                     '    if missing_sources:\n'
                                     '        detail = "; ".join(f"{source}: {count} missing" for source, count in '
                                     'missing_sources)\n'
                                     '        raise ValueError(\n'
                                     '            "[PARTICIPANT MATCHING ERROR] One or more locally configured matched '
                                     '"\n'
                                     '            f"participants are absent from the input sources ({detail}). "\n'
                                     '            "Participant identifiers are intentionally not printed."\n'
                                     '        )\n'
                                     '    common_ids = np.asarray(required_ids, dtype=str)\n'
                                     '    print(f"[MATCHED PARTICIPANTS] n={len(common_ids)}; IDs withheld")\n'
                                     '    return common_ids, summary\n'
                                     '\n'
                                     '\n'
                                     '\n'
                                     'def load_matched_neural_matrices(brain_files, common_ids, atlas):\n'
                                     '    """Load the participant-level whole-DMN time series for both sessions."""\n'
                                     '    first_path = brain_files[SESSIONS[0]][common_ids[0]]\n'
                                     '    first_df = pd.read_csv(first_path)\n'
                                     '    first_df.columns = first_df.columns.astype(str)\n'
                                     '    dmn_columns, roi_metadata = resolve_dmn_columns(atlas, first_df.columns)\n'
                                     '    roi_metadata.to_csv(\n'
                                     '        OUT_DIR / "Study2_DMN_definition_summary.csv",\n'
                                     '        index=False,\n'
                                     '    )\n'
                                     '\n'
                                     '    whole_matrices = {}\n'
                                     '    lengths = {}\n'
                                     '\n'
                                     '    for session in SESSIONS:\n'
                                     '        whole_rows = []\n'
                                     '        load_start = time.time()\n'
                                     '\n'
                                     '        for index, subject_id in enumerate(common_ids, start=1):\n'
                                     '            path = brain_files[session][subject_id]\n'
                                     '            df = pd.read_csv(path)\n'
                                     '            df.columns = df.columns.astype(str)\n'
                                     '            missing = [column for column in dmn_columns if column not in '
                                     'df.columns]\n'
                                     '            if missing:\n'
                                     '                raise ValueError(f"{path} is missing DMN columns: '
                                     '{missing[:10]}")\n'
                                     '\n'
                                     '            roi_values = (\n'
                                     '                df[dmn_columns]\n'
                                     '                .apply(pd.to_numeric, errors="coerce")\n'
                                     '                .to_numpy(dtype=np.float64)\n'
                                     '            )\n'
                                     '            # Neural files are already trimmed and aligned upstream.\n'
                                     '            # Use every available row without additional front/back trimming.\n'
                                     '            whole_rows.append(np.nanmean(roi_values, axis=1))\n'
                                     '\n'
                                     '            if index % NEURAL_LOAD_PROGRESS_EVERY == 0 or index == '
                                     'len(common_ids):\n'
                                     '                print_progress(\n'
                                     '                    label=f"[NEURAL LOAD] {session}",\n'
                                     '                    current=index,\n'
                                     '                    total=len(common_ids),\n'
                                     '                    start_time=load_start,\n'
                                     '                    extra="participant loaded",\n'
                                     '                    done=(index == len(common_ids)),\n'
                                     '                )\n'
                                     '\n'
                                     '        unique_lengths = sorted({len(row) for row in whole_rows})\n'
                                     '        if len(unique_lengths) != 1:\n'
                                     '            raise ValueError(\n'
                                     '                f"[ALIGNMENT ERROR] Neural lengths differ across participants "\n'
                                     '                f"within {session}: {unique_lengths}. No automatic truncation "\n'
                                     '                f"is performed because all files must already be aligned."\n'
                                     '            )\n'
                                     '\n'
                                     '        whole_matrices[session] = np.vstack(whole_rows)\n'
                                     '        lengths[session] = whole_matrices[session].shape[1]\n'
                                     '\n'
                                     '    return whole_matrices, lengths, roi_metadata\n'
                                     '\n'
                                     'def build_matched_behavior_matrices(behavior_maps, common_ids):\n'
                                     '    matrices = {session: {} for session in SESSIONS}\n'
                                     '    lengths = {session: {} for session in SESSIONS}\n'
                                     '\n'
                                     '    for session in SESSIONS:\n'
                                     '        for affect in AFFECTS:\n'
                                     '            rows = [behavior_maps[session][affect][subject] for subject in '
                                     'common_ids]\n'
                                     '            unique_lengths = sorted({len(row) for row in rows})\n'
                                     '            if len(unique_lengths) != 1:\n'
                                     '                raise ValueError(\n'
                                     '                    f"[ALIGNMENT ERROR] Behavioral lengths differ across "\n'
                                     '                    f"participants within {session}-{affect}: {unique_lengths}. '
                                     '"\n'
                                     '                    f"No automatic truncation is performed because all files "\n'
                                     '                    f"must already be aligned."\n'
                                     '                )\n'
                                     '\n'
                                     '            matrices[session][affect] = np.vstack(rows)\n'
                                     '            lengths[session][affect] = matrices[session][affect].shape[1]\n'
                                     '\n'
                                     '    return matrices, lengths\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# WINDOW-LEVEL AUDIOVISUAL COVARIATES\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def find_covariate_column(df, target):\n'
                                     '    return next(\n'
                                     '        (column for column in COVARIATE_ALIASES[target] if column in '
                                     'df.columns),\n'
                                     '        None,\n'
                                     '    )\n'
                                     '\n'
                                     '\n'
                                     'def load_aligned_window_covariates(session, path, n_windows):\n'
                                     '    """Drop exactly the first eight covariate-window rows, then require '
                                     'equality.\n'
                                     '\n'
                                     '    Neural and behavioral series are used exactly as stored. Only the\n'
                                     '    window-level audiovisual covariate table is shifted: its first eight rows\n'
                                     '    are removed because they precede the retained neural/behavioral timeline.\n'
                                     '    No tail rows are removed and no other modality is trimmed.\n'
                                     '    """\n'
                                     '    df = pd.read_csv(path)\n'
                                     '    source_rows = int(len(df))\n'
                                     '    n_windows = int(n_windows)\n'
                                     '    front_drop_rows = int(COVARIATE_FRONT_DROP_ROWS)\n'
                                     '\n'
                                     '    if source_rows <= front_drop_rows:\n'
                                     '        raise ValueError(\n'
                                     '            f"[ALIGNMENT ERROR] {session}: covariate file has only "\n'
                                     '            f"{source_rows} rows, so the first {front_drop_rows} rows cannot "\n'
                                     '            f"be removed. File: {path}"\n'
                                     '        )\n'
                                     '\n'
                                     '    df = df.iloc[front_drop_rows:, :].copy().reset_index(drop=True)\n'
                                     '    aligned_rows = int(len(df))\n'
                                     '\n'
                                     '    print(\n'
                                     '        f"[COVARIATE FRONT-8 ALIGN] {session}: source rows={source_rows}; "\n'
                                     '        f"drop first {front_drop_rows}; aligned rows={aligned_rows}; "\n'
                                     '        f"expected windows={n_windows}; tail rows dropped=0"\n'
                                     '    )\n'
                                     '\n'
                                     '    if aligned_rows != n_windows:\n'
                                     '        raise ValueError(\n'
                                     '            f"[ALIGNMENT ERROR] {session}: after dropping exactly the first "\n'
                                     '            f"{front_drop_rows} covariate rows, aligned rows={aligned_rows}, "\n'
                                     '            f"but neural/behavioral data require {n_windows} windows. "\n'
                                     '            f"No neural, behavioral, or covariate-tail trimming is performed. "\n'
                                     '            f"File: {path}"\n'
                                     '        )\n'
                                     '\n'
                                     '    output = pd.DataFrame({\n'
                                     '        "session": session,\n'
                                     '        "window": np.arange(n_windows),\n'
                                     '    })\n'
                                     '\n'
                                     '    for target in LOWLEVEL_TARGET_COLS:\n'
                                     '        source = find_covariate_column(df, target)\n'
                                     '        if source is None:\n'
                                     '            raise ValueError(\n'
                                     '                f"{target} not found in {path}. Available columns: '
                                     '{list(df.columns)}"\n'
                                     '            )\n'
                                     '        values = pd.to_numeric(df[source], errors="coerce").to_numpy(float)\n'
                                     '        output[target] = zscore_1d(values)\n'
                                     '\n'
                                     '    linear_time = np.linspace(-1, 1, n_windows)\n'
                                     '    output["linear_time"] = linear_time\n'
                                     '    output["quadratic_time"] = zscore_1d(linear_time ** 2)\n'
                                     '    return output, source_rows, aligned_rows, front_drop_rows\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# WINDOW × DISTINCT-PAIR CACHE\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def cache_paths(name):\n'
                                     '    return {\n'
                                     '        "z": CACHE_DIR / f"{name}_pair_z.npy",\n'
                                     '        "valid": CACHE_DIR / f"{name}_pair_valid.npy",\n'
                                     '        "meta": CACHE_DIR / f"{name}_meta.json",\n'
                                     '    }\n'
                                     '\n'
                                     '\n'
                                     'def cache_metadata_matches(meta, ids, n_time, window_size):\n'
                                     '    # Participant identities are intentionally not persisted. Public-release\n'
                                     '    # runs rebuild pairwise caches, so only non-identifying shape checks '
                                     'remain.\n'
                                     '    return (\n'
                                     '        meta.get("n_subjects") == int(len(ids))\n'
                                     '        and meta.get("n_time") == int(n_time)\n'
                                     '        and meta.get("window_size") == int(window_size)\n'
                                     '    )\n'
                                     '\n'
                                     '\n'
                                     '\n'
                                     'def load_cache_arrays(paths, all_valid):\n'
                                     '    mmap_mode = None if LOAD_PAIR_CACHE_TO_RAM else "r"\n'
                                     '    z_values = np.load(paths["z"], mmap_mode=mmap_mode)\n'
                                     '    valid_values = (\n'
                                     '        None if all_valid else np.load(paths["valid"], mmap_mode=mmap_mode)\n'
                                     '    )\n'
                                     '    return z_values, valid_values\n'
                                     '\n'
                                     '\n'
                                     'def compute_pairwise_window_cache(values, ids, window_size, name):\n'
                                     '    values = np.asarray(values, dtype=np.float64, order="C")\n'
                                     '    ids = np.asarray(ids, dtype=str)\n'
                                     '\n'
                                     '    n_subjects, n_time = values.shape\n'
                                     '    n_windows = n_time - window_size + 1\n'
                                     '    if n_windows < 1:\n'
                                     '        raise ValueError(f"Window exceeds available time for {name}")\n'
                                     '\n'
                                     '    pair_i, pair_j = np.triu_indices(n_subjects, k=1)\n'
                                     '    n_pairs = len(pair_i)\n'
                                     '    paths = cache_paths(name)\n'
                                     '\n'
                                     '    can_load = (\n'
                                     '        not REBUILD_PAIR_CACHE\n'
                                     '        and all(path.exists() for path in paths.values())\n'
                                     '    )\n'
                                     '\n'
                                     '    if can_load:\n'
                                     '        meta = load_json(paths["meta"])\n'
                                     '        if cache_metadata_matches(meta, ids, n_time, window_size, name):\n'
                                     '            z_values, valid_values = load_cache_arrays(\n'
                                     '                paths,\n'
                                     '                bool(meta["all_pairs_valid"]),\n'
                                     '            )\n'
                                     '            print(\n'
                                     '                f"[CACHE LOAD] {name}: windows={n_windows}, pairs={n_pairs:,}"\n'
                                     '            )\n'
                                     '            return {\n'
                                     '                "name": name,\n'
                                     '                "subject_ids": ids,\n'
                                     '                "pair_i": pair_i,\n'
                                     '                "pair_j": pair_j,\n'
                                     '                "z": z_values,\n'
                                     '                "valid": valid_values,\n'
                                     '                "all_pairs_valid": bool(meta["all_pairs_valid"]),\n'
                                     '                "n_windows": n_windows,\n'
                                     '                "n_pairs": n_pairs,\n'
                                     '            }\n'
                                     '        warnings.warn(f"Cache metadata mismatch for {name}; rebuilding.")\n'
                                     '\n'
                                     '    z_memmap = np.lib.format.open_memmap(\n'
                                     '        paths["z"], mode="w+", dtype=np.float32, shape=(n_windows, n_pairs)\n'
                                     '    )\n'
                                     '    valid_memmap = np.lib.format.open_memmap(\n'
                                     '        paths["valid"], mode="w+", dtype=np.uint8, shape=(n_windows, n_pairs)\n'
                                     '    )\n'
                                     '\n'
                                     '    all_valid = True\n'
                                     '    cache_start = time.time()\n'
                                     '\n'
                                     '    for window in range(n_windows):\n'
                                     '        x = values[:, window:window + window_size]\n'
                                     '        sd = np.nanstd(x, axis=1, ddof=1)\n'
                                     '        valid_subject = (\n'
                                     '            np.all(np.isfinite(x), axis=1)\n'
                                     '            & np.isfinite(sd)\n'
                                     '            & (sd > 0)\n'
                                     '        )\n'
                                     '\n'
                                     '        standardized = np.zeros_like(x, dtype=np.float64)\n'
                                     '        valid_x = x[valid_subject]\n'
                                     '        if len(valid_x):\n'
                                     '            standardized[valid_subject] = (\n'
                                     '                valid_x - valid_x.mean(axis=1, keepdims=True)\n'
                                     '            ) / valid_x.std(axis=1, ddof=1, keepdims=True)\n'
                                     '\n'
                                     '        correlation = (standardized @ standardized.T) / (window_size - 1)\n'
                                     '        pair_valid = valid_subject[pair_i] & valid_subject[pair_j]\n'
                                     '\n'
                                     '        row = np.zeros(n_pairs, dtype=np.float32)\n'
                                     '        row[pair_valid] = fisher_z(\n'
                                     '            correlation[pair_i[pair_valid], pair_j[pair_valid]]\n'
                                     '        ).astype(np.float32)\n'
                                     '\n'
                                     '        z_memmap[window] = row\n'
                                     '        valid_memmap[window] = pair_valid.astype(np.uint8)\n'
                                     '        all_valid &= bool(np.all(pair_valid))\n'
                                     '\n'
                                     '        completed = window + 1\n'
                                     '        if completed % CACHE_PROGRESS_EVERY == 0 or completed == n_windows:\n'
                                     '            print_progress(\n'
                                     '                label=f"[CACHE BUILD] {name}",\n'
                                     '                current=completed,\n'
                                     '                total=n_windows,\n'
                                     '                start_time=cache_start,\n'
                                     '                extra=f"pairs={n_pairs:,}",\n'
                                     '                done=(completed == n_windows),\n'
                                     '            )\n'
                                     '\n'
                                     '    z_memmap.flush()\n'
                                     '    valid_memmap.flush()\n'
                                     '\n'
                                     '    meta = {\n'
                                     '        "name": name,\n'
                                     '        "n_subjects": n_subjects,\n'
                                     '        "n_time": n_time,\n'
                                     '        "window_size": window_size,\n'
                                     '        "n_windows": n_windows,\n'
                                     '        "n_pairs": n_pairs,\n'
                                     '        "all_pairs_valid": bool(all_valid),\n'
                                     '        "alignment_policy_version": CHEN_ALIGNMENT_POLICY_VERSION,\n'
                                     '    }\n'
                                     '    save_json(meta, paths["meta"])\n'
                                     '\n'
                                     '    z_values, valid_values = load_cache_arrays(paths, all_valid)\n'
                                     '    print(\n'
                                     '        f"[CACHE READY] {name}: subjects={n_subjects}, pairs={n_pairs:,}, "\n'
                                     '        f"windows={n_windows}, all_valid={all_valid}"\n'
                                     '    )\n'
                                     '\n'
                                     '    return {\n'
                                     '        "name": name,\n'
                                     '        "subject_ids": ids,\n'
                                     '        "pair_i": pair_i,\n'
                                     '        "pair_j": pair_j,\n'
                                     '        "z": z_values,\n'
                                     '        "valid": valid_values,\n'
                                     '        "all_pairs_valid": all_valid,\n'
                                     '        "n_windows": n_windows,\n'
                                     '        "n_pairs": n_pairs,\n'
                                     '    }\n'
                                     '\n'
                                     '\n'
                                     'def weighted_window_mean(cache, participant_weights):\n'
                                     '    participant_weights = np.asarray(participant_weights, dtype=np.float64)\n'
                                     '    if len(participant_weights) != len(cache["subject_ids"]):\n'
                                     '        raise ValueError(\n'
                                     '            f"Weight length mismatch for {cache[\'name\']}: "\n'
                                     '            f"{len(participant_weights)} vs {len(cache[\'subject_ids\'])}"\n'
                                     '        )\n'
                                     '\n'
                                     '    pair_weights = (\n'
                                     '        participant_weights[cache["pair_i"]]\n'
                                     '        * participant_weights[cache["pair_j"]]\n'
                                     '    )\n'
                                     '    total_weight = pair_weights.sum()\n'
                                     '    if not np.isfinite(total_weight) or total_weight <= 0:\n'
                                     '        raise ValueError(f"No positive distinct-pair weight for '
                                     '{cache[\'name\']}")\n'
                                     '\n'
                                     '    pair_weights_32 = pair_weights.astype(np.float32, copy=False)\n'
                                     '    numerator = np.asarray(cache["z"] @ pair_weights_32, dtype=np.float64)\n'
                                     '\n'
                                     '    if cache["all_pairs_valid"]:\n'
                                     '        denominator = np.full(cache["n_windows"], total_weight, '
                                     'dtype=np.float64)\n'
                                     '    else:\n'
                                     '        denominator = np.asarray(\n'
                                     '            cache["valid"] @ pair_weights_32,\n'
                                     '            dtype=np.float64,\n'
                                     '        )\n'
                                     '\n'
                                     '    with np.errstate(divide="ignore", invalid="ignore"):\n'
                                     '        result = numerator / denominator\n'
                                     '    result[denominator <= 0] = np.nan\n'
                                     '    return result\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# PREPARE MATCHED CACHES\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def prepare_all_data():\n'
                                     '    print_section("DIRECT-BEHAVIOR STUDY 2 V4 ISOLATED — participants")\n'
                                     '    print(\n'
                                     '        "[DIRECT BEHAVIOR V4 ISOLATED ACTIVE] exact A/B CSV paths; required '
                                     'matched sample; "\n'
                                     '        "behavior front-drop=9 inside prepare_all_data before all checks; '
                                     'covariate front-drop=8"\n'
                                     '    )\n'
                                     '    print(f"[FRESH RUN ID] {RUN_ID}")\n'
                                     '    print(f"[SOURCE FILE] {Path(__file__).resolve()}")\n'
                                     '    print(f"[ALIGNMENT VERSION] {CHEN_ALIGNMENT_POLICY_VERSION}")\n'
                                     '    print(f"[DEPENDENCE MODE] {DEPENDENCE_MODE}; participant IDs supplied '
                                     'locally")\n'
                                     '    print(\n'
                                     '        "[TEMPORAL POLICY] neural unchanged; raw behavior drops first 9 TR "\n'
                                     '        "inside prepare_all_data before participant matching and length checks; '
                                     '"\n'
                                     '        "covariates drop first 8 rows; no tail trimming"\n'
                                     '    )\n'
                                     '    print(f"[FRESH CACHE DIR] {CACHE_DIR}")\n'
                                     '    validate_paths()\n'
                                     '    atlas = load_atlas()\n'
                                     '    brain_files = {session: get_brain_files(session) for session in SESSIONS}\n'
                                     '\n'
                                     '    # Load the four direct A/B CSV files as raw 206/201-point matrices first,\n'
                                     '    # then apply the fixed front-9 alignment HERE, before participant matching,\n'
                                     '    # matrix construction, cache lookup, or any temporal-length validation.\n'
                                     '    raw_behavior_maps = load_all_behavior_maps()\n'
                                     '    behavior_maps = apply_behavior_front9_in_prepare(raw_behavior_maps)\n'
                                     '\n'
                                     '    common_ids, matching_summary = determine_common_subjects(\n'
                                     '        brain_files,\n'
                                     '        behavior_maps,\n'
                                     '    )\n'
                                     '\n'
                                     '    neural_whole_matrices, neural_lengths, roi_metadata = (\n'
                                     '        load_matched_neural_matrices(brain_files, common_ids, atlas)\n'
                                     '    )\n'
                                     '    behavior_matrices, behavior_lengths = build_matched_behavior_matrices(\n'
                                     '        behavior_maps,\n'
                                     '        common_ids,\n'
                                     '    )\n'
                                     '\n'
                                     '    covariate_paths = {}\n'
                                     '    window_size_by_session = {}\n'
                                     '    for session in SESSIONS:\n'
                                     '        path, window_size = discover_covariate_file(session)\n'
                                     '        covariate_paths[session] = path\n'
                                     '        window_size_by_session[session] = window_size\n'
                                     '        print(\n'
                                     '            f"[COVARIATE FILE] {session}: {path} | window={window_size} TR | "\n'
                                     '            f"drop exactly first {COVARIATE_FRONT_DROP_ROWS} covariate rows '
                                     'only"\n'
                                     '        )\n'
                                     '\n'
                                     '    neural_caches = {}\n'
                                     '    behavior_caches = {session: {} for session in SESSIONS}\n'
                                     '    covariates = {}\n'
                                     '    n_time_by_session = {}\n'
                                     '\n'
                                     '    alignment_rows = []\n'
                                     '\n'
                                     '    for session in SESSIONS:\n'
                                     '        # Neural inputs are used unchanged. Behavioral inputs have already had\n'
                                     '        # their first nine time points removed centrally in prepare_all_data(), '
                                     'and\n'
                                     '        # covariates will have their first eight rows removed below. After '
                                     'these\n'
                                     '        # fixed front offsets, all modalities must match exactly.\n'
                                     '        n_time = int(neural_lengths[session])\n'
                                     '        behavior_session_lengths = {\n'
                                     '            affect: int(behavior_lengths[session][affect])\n'
                                     '            for affect in AFFECTS\n'
                                     '        }\n'
                                     '        window_size = int(window_size_by_session[session])\n'
                                     '        expected_windows = n_time - window_size + 1\n'
                                     '\n'
                                     '        alignment_errors = []\n'
                                     '        for affect, length in behavior_session_lengths.items():\n'
                                     '            if length != n_time:\n'
                                     '                alignment_errors.append(\n'
                                     '                    f"{affect} TR={length} (expected neural TR={n_time})"\n'
                                     '                )\n'
                                     '        if expected_windows < 1:\n'
                                     '            alignment_errors.append(\n'
                                     '                f"window size={window_size} exceeds neural TR={n_time}"\n'
                                     '            )\n'
                                     '\n'
                                     '        if alignment_errors:\n'
                                     '            details = "; ".join(alignment_errors)\n'
                                     '            raise ValueError(\n'
                                     '                f"[ALIGNMENT ERROR] {session}: neural and behavioral lengths "\n'
                                     '                f"are not aligned. neural TR={n_time}; valence TR="\n'
                                     '                f"{behavior_session_lengths[\'valence\']}; fear TR="\n'
                                     '                f"{behavior_session_lengths[\'fear\']}; window '
                                     'size={window_size}. "\n'
                                     '                f"Details: {details}. Only the fixed behavioral front-9 and "\n'
                                     '                f"covariate front-8 alignment rules are permitted."\n'
                                     '            )\n'
                                     '\n'
                                     '        n_time_by_session[session] = n_time\n'
                                     '\n'
                                     '        neural_caches[session] = compute_pairwise_window_cache(\n'
                                     '            neural_whole_matrices[session],\n'
                                     '            common_ids,\n'
                                     '            window_size,\n'
                                     '            f"neural_DMN_{session}",\n'
                                     '        )\n'
                                     '\n'
                                     '        n_windows = int(neural_caches[session]["n_windows"])\n'
                                     '        if n_windows != expected_windows:\n'
                                     '            raise RuntimeError(\n'
                                     '                f"[ALIGNMENT ERROR] {session}: neural cache windows={n_windows}, '
                                     '"\n'
                                     '                f"but expected {expected_windows} from neural TR={n_time} and "\n'
                                     '                f"window size={window_size}."\n'
                                     '            )\n'
                                     '\n'
                                     '        (\n'
                                     '            covariates[session],\n'
                                     '            covariate_source_rows,\n'
                                     '            covariate_aligned_rows,\n'
                                     '            covariate_front_dropped_rows,\n'
                                     '        ) = load_aligned_window_covariates(\n'
                                     '            session,\n'
                                     '            covariate_paths[session],\n'
                                     '            n_windows,\n'
                                     '        )\n'
                                     '\n'
                                     '        row = {\n'
                                     '            "dataset": session,\n'
                                     '            "policy": "neural unchanged; behavior drop first 9 TR in both '
                                     'sessions; covariates drop first 8 rows; no tail trimming",\n'
                                     '            "neural_source_tr": n_time,\n'
                                     '            "neural_used_tr": n_time,\n'
                                     '            "behavior_front_dropped_tr": int(BEHAVIOR_FRONT_DROP_TR),\n'
                                     '            "behavior_tail_dropped_tr": 0,\n'
                                     '            "window_size_tr": window_size,\n'
                                     '            "neural_windows": n_windows,\n'
                                     '            "covariate_source_windows": covariate_source_rows,\n'
                                     '            "covariate_front_dropped_windows": '
                                     'int(covariate_front_dropped_rows),\n'
                                     '            "covariate_tail_dropped_windows": 0,\n'
                                     '            "covariate_used_windows": int(len(covariates[session])),\n'
                                     '        }\n'
                                     '\n'
                                     '        for affect in AFFECTS:\n'
                                     '            behavior_caches[session][affect] = compute_pairwise_window_cache(\n'
                                     '                behavior_matrices[session][affect],\n'
                                     '                common_ids,\n'
                                     '                window_size,\n'
                                     '                f"behavior_{affect}_{session}",\n'
                                     '            )\n'
                                     '            if behavior_caches[session][affect]["n_windows"] != n_windows:\n'
                                     '                raise ValueError(f"Window mismatch: {session}-{affect}")\n'
                                     '            row[f"behavior_{affect}_source_tr"] = '
                                     'behavior_session_lengths[affect]\n'
                                     '            row[f"behavior_{affect}_used_tr"] = '
                                     'behavior_session_lengths[affect]\n'
                                     '            row[f"behavior_{affect}_used_windows"] = int(\n'
                                     '                behavior_caches[session][affect]["n_windows"]\n'
                                     '            )\n'
                                     '\n'
                                     '        alignment_rows.append(row)\n'
                                     '\n'
                                     '    return {\n'
                                     '        "common_ids": common_ids,\n'
                                     '        "matching_summary": matching_summary,\n'
                                     '        "neural_caches": neural_caches,\n'
                                     '        "behavior_caches": behavior_caches,\n'
                                     '        "covariates": covariates,\n'
                                     '        "n_time_by_session": n_time_by_session,\n'
                                     '        "window_size_by_session": window_size_by_session,\n'
                                     '        "covariate_paths": covariate_paths,\n'
                                     '        "roi_metadata": roi_metadata,\n'
                                     '        "alignment_summary": pd.DataFrame(alignment_rows),\n'
                                     '        "alignment_policy_version": CHEN_ALIGNMENT_POLICY_VERSION,\n'
                                     '    }\n'
                                     '\n'
                                     'def standardize_window_table(df):\n'
                                     '    output = df.copy()\n'
                                     '    columns = ["z_neural_ISC", "z_valence_ISC", "z_fear_ISC"]\n'
                                     '\n'
                                     '    for column in columns:\n'
                                     '        output[f"raw_{column}"] = output[column]\n'
                                     '        if STANDARDIZE_WITHIN_SESSION:\n'
                                     '            output[column] = output.groupby(\n'
                                     '                "session",\n'
                                     '                observed=True,\n'
                                     '            )[column].transform(\n'
                                     '                lambda values: zscore_1d(values.to_numpy(float))\n'
                                     '            )\n'
                                     '\n'
                                     '    return output\n'
                                     '\n'
                                     '\n'
                                     'def build_window_table(prepared, participant_weights):\n'
                                     '    tables = []\n'
                                     '\n'
                                     '    for session in SESSIONS:\n'
                                     '        neural_z = weighted_window_mean(\n'
                                     '            prepared["neural_caches"][session],\n'
                                     '            participant_weights,\n'
                                     '        )\n'
                                     '\n'
                                     '        table = prepared["covariates"][session].copy()\n'
                                     '        table["z_neural_ISC"] = neural_z\n'
                                     '        table["neural_ISC_r"] = inv_fisher_z(neural_z)\n'
                                     '\n'
                                     '        for affect in AFFECTS:\n'
                                     '            affect_z = weighted_window_mean(\n'
                                     '                prepared["behavior_caches"][session][affect],\n'
                                     '                participant_weights,\n'
                                     '            )\n'
                                     '            table[f"z_{affect}_ISC"] = affect_z\n'
                                     '            table[f"{affect}_ISC_r"] = inv_fisher_z(affect_z)\n'
                                     '\n'
                                     '        tables.append(table)\n'
                                     '\n'
                                     '    output = pd.concat(tables, ignore_index=True)\n'
                                     '    output["session"] = pd.Categorical(\n'
                                     '        output["session"],\n'
                                     '        categories=SESSIONS,\n'
                                     '        ordered=False,\n'
                                     '    )\n'
                                     '    output = output.sort_values(["session", "window"]).reset_index(drop=True)\n'
                                     '    return standardize_window_table(output)\n'
                                     '\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# MARGINAL MODELS ONLY\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def build_numpy_reduced_design(df):\n'
                                     '    needed = ["z_neural_ISC", "session", *MODEL_COVARIATES]\n'
                                     '    data = df[needed].dropna().copy()\n'
                                     '\n'
                                     '    session = data["session"].astype(str).to_numpy()\n'
                                     '    h02 = (session == "horror02").astype(float)\n'
                                     '\n'
                                     '    columns = [np.ones(len(data)), h02]\n'
                                     '    names = ["Intercept", "horror02"]\n'
                                     '\n'
                                     '    for covariate in MODEL_COVARIATES:\n'
                                     '        values = data[covariate].to_numpy(float)\n'
                                     '        columns.extend([values, h02 * values])\n'
                                     '        names.extend([covariate, f"horror02:{covariate}"])\n'
                                     '\n'
                                     '    return np.column_stack(columns), data["z_neural_ISC"].to_numpy(float), '
                                     'names, data\n'
                                     '\n'
                                     '\n'
                                     'def build_numpy_marginal_design(df, affect):\n'
                                     '    predictor = f"z_{affect}_ISC"\n'
                                     '    needed = ["z_neural_ISC", predictor, "session", *MODEL_COVARIATES]\n'
                                     '    data = df[needed].dropna().copy()\n'
                                     '\n'
                                     '    session = data["session"].astype(str).to_numpy()\n'
                                     '    h02 = (session == "horror02").astype(float)\n'
                                     '    x = data[predictor].to_numpy(float)\n'
                                     '\n'
                                     '    columns = [np.ones(len(data)), h02, x, h02 * x]\n'
                                     '    names = ["Intercept", "horror02", predictor, f"horror02:{predictor}"]\n'
                                     '\n'
                                     '    for covariate in MODEL_COVARIATES:\n'
                                     '        values = data[covariate].to_numpy(float)\n'
                                     '        columns.extend([values, h02 * values])\n'
                                     '        names.extend([covariate, f"horror02:{covariate}"])\n'
                                     '\n'
                                     '    return np.column_stack(columns), data["z_neural_ISC"].to_numpy(float), '
                                     'names, data\n'
                                     '\n'
                                     '\n'
                                     'def calculate_r_squared(y, fitted, n_parameters):\n'
                                     '    y = np.asarray(y, dtype=float)\n'
                                     '    fitted = np.asarray(fitted, dtype=float)\n'
                                     '    residual = y - fitted\n'
                                     '    sse = float(np.dot(residual, residual))\n'
                                     '    centered = y - np.mean(y)\n'
                                     '    sst = float(np.dot(centered, centered))\n'
                                     '\n'
                                     '    if sst <= 0:\n'
                                     '        return np.nan, np.nan\n'
                                     '\n'
                                     '    r2 = 1.0 - sse / sst\n'
                                     '    n = len(y)\n'
                                     '    if n <= n_parameters + 1:\n'
                                     '        adjusted = np.nan\n'
                                     '    else:\n'
                                     '        adjusted = 1.0 - (1.0 - r2) * (n - 1) / (n - n_parameters)\n'
                                     '    return float(r2), float(adjusted)\n'
                                     '\n'
                                     '\n'
                                     'def fit_numpy_marginal_effects(df, affect):\n'
                                     '    # The full and reduced models must use exactly the same complete-case rows.\n'
                                     '    # During participant bootstrap, some weighted ISC windows can become NaN\n'
                                     '    # for one affect even when neural ISC and covariates remain valid. Building\n'
                                     '    # the reduced model directly from the original dataframe would therefore\n'
                                     '    # retain extra rows and make the two outcomes misaligned.\n'
                                     '    design, outcome, names, complete_case_data = build_numpy_marginal_design(\n'
                                     '        df,\n'
                                     '        affect,\n'
                                     '    )\n'
                                     '    beta, _, rank, _ = np.linalg.lstsq(design, outcome, rcond=None)\n'
                                     '    if rank < design.shape[1]:\n'
                                     '        raise np.linalg.LinAlgError(\n'
                                     '            f"Rank-deficient marginal design for {affect}: "\n'
                                     '            f"{rank}/{design.shape[1]}"\n'
                                     '        )\n'
                                     '\n'
                                     '    # Build the covariate-only model from the already filtered full-model data.\n'
                                     '    # This guarantees identical observations for full/reduced R² and ΔR².\n'
                                     '    reduced_design, reduced_outcome, _, _ = build_numpy_reduced_design(\n'
                                     '        complete_case_data\n'
                                     '    )\n'
                                     '    if (\n'
                                     '        len(outcome) != len(reduced_outcome)\n'
                                     '        or not np.allclose(outcome, reduced_outcome, equal_nan=True)\n'
                                     '    ):\n'
                                     '        raise ValueError(\n'
                                     '            f"Full and reduced model rows are not aligned for {affect}: "\n'
                                     '            f"full n={len(outcome)}, reduced n={len(reduced_outcome)}"\n'
                                     '        )\n'
                                     '    reduced_beta = np.linalg.lstsq(\n'
                                     '        reduced_design,\n'
                                     '        reduced_outcome,\n'
                                     '        rcond=None,\n'
                                     '    )[0]\n'
                                     '\n'
                                     '    index = {name: position for position, name in enumerate(names)}\n'
                                     '    predictor = f"z_{affect}_ISC"\n'
                                     '\n'
                                     '    h01 = beta[index[predictor]]\n'
                                     '    h02 = h01 + beta[index[f"horror02:{predictor}"]]\n'
                                     '    pooled = (h01 + h02) / 2.0\n'
                                     '    difference = h01 - h02\n'
                                     '\n'
                                     '    full_r2, full_adjusted_r2 = calculate_r_squared(\n'
                                     '        outcome,\n'
                                     '        design @ beta,\n'
                                     '        design.shape[1],\n'
                                     '    )\n'
                                     '    reduced_r2, reduced_adjusted_r2 = calculate_r_squared(\n'
                                     '        outcome,\n'
                                     '        reduced_design @ reduced_beta,\n'
                                     '        reduced_design.shape[1],\n'
                                     '    )\n'
                                     '\n'
                                     '    return {\n'
                                     '        f"marginal_{affect}_horror01_slope": float(h01),\n'
                                     '        f"marginal_{affect}_horror02_slope": float(h02),\n'
                                     '        f"marginal_{affect}_pooled_slope": float(pooled),\n'
                                     '        f"marginal_{affect}_horror01_minus_horror02": float(difference),\n'
                                     '        f"marginal_{affect}_full_r2": full_r2,\n'
                                     '        f"marginal_{affect}_full_adjusted_r2": full_adjusted_r2,\n'
                                     '        f"marginal_{affect}_reduced_r2": reduced_r2,\n'
                                     '        f"marginal_{affect}_reduced_adjusted_r2": reduced_adjusted_r2,\n'
                                     '        f"marginal_{affect}_delta_r2": float(full_r2 - reduced_r2),\n'
                                     '    }\n'
                                     '\n'
                                     '\n'
                                     'def fit_all_effects(df):\n'
                                     '    output = {}\n'
                                     '    for affect in AFFECTS:\n'
                                     '        output.update(fit_numpy_marginal_effects(df, affect))\n'
                                     '    return output\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# ACF-INFORMED TEMPORAL PERMUTATION\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def estimate_block_length_from_acf(values, threshold=0.10):\n'
                                     '    values = np.asarray(values, dtype=float)\n'
                                     '    values = values[np.isfinite(values)]\n'
                                     '    n = len(values)\n'
                                     '    if n < 3:\n'
                                     '        return max(1, n)\n'
                                     '\n'
                                     '    values = values - np.mean(values)\n'
                                     '    denominator = np.sum(values ** 2)\n'
                                     '    if denominator <= 0 or not np.isfinite(denominator):\n'
                                     '        return n\n'
                                     '\n'
                                     '    for lag in range(1, n):\n'
                                     '        acf_lag = np.sum(values[:-lag] * values[lag:]) / denominator\n'
                                     '        if abs(acf_lag) < threshold:\n'
                                     '            return lag\n'
                                     '    return n\n'
                                     '\n'
                                     '\n'
                                     'def choose_block_lengths(observed_df):\n'
                                     '    rows = []\n'
                                     '    result = {}\n'
                                     '\n'
                                     '    for session in SESSIONS:\n'
                                     '        subset = observed_df.loc[observed_df["session"].eq(session)]\n'
                                     '        estimated = {\n'
                                     '            affect: estimate_block_length_from_acf(\n'
                                     '                subset[f"z_{affect}_ISC"].to_numpy(float),\n'
                                     '                threshold=ACF_THRESHOLD,\n'
                                     '            )\n'
                                     '            for affect in AFFECTS\n'
                                     '        }\n'
                                     '        estimated_max = max(estimated.values())\n'
                                     '        configured = FIXED_BLOCK_LEN_BY_SESSION.get(session)\n'
                                     '        final = estimated_max if configured is None else int(configured)\n'
                                     '        final = max(1, min(final, len(subset) - 1))\n'
                                     '        result[session] = final\n'
                                     '\n'
                                     '        rows.append({\n'
                                     '            "session": session,\n'
                                     '            **{f"{affect}_acf_lag": estimated[affect] for affect in AFFECTS},\n'
                                     '            "estimated_max_lag": estimated_max,\n'
                                     '            "configured_block_len": configured,\n'
                                     '            "final_block_len": final,\n'
                                     '        })\n'
                                     '\n'
                                     '    summary = pd.DataFrame(rows)\n'
                                     '    summary.to_csv(OUT_DIR / "Study2_acf_block_length_summary.csv", '
                                     'index=False)\n'
                                     '    return result, summary\n'
                                     '\n'
                                     '\n'
                                     'def block_permutation_indices(n, block_len, block_order):\n'
                                     '    blocks = [\n'
                                     '        np.arange(start, min(start + block_len, n))\n'
                                     '        for start in range(0, n, block_len)\n'
                                     '    ]\n'
                                     '    order = np.asarray(block_order, dtype=int)\n'
                                     '    if len(order) != len(blocks):\n'
                                     '        raise ValueError(f"Block-order length mismatch: {len(order)} vs '
                                     '{len(blocks)}")\n'
                                     '    return np.concatenate([blocks[index] for index in order])\n'
                                     '\n'
                                     '\n'
                                     'def generate_permutation_plan(block_lengths, n_windows_by_session):\n'
                                     '    path = DRAW_DIR / "Study2_block_order_permutation_plan.npz"\n'
                                     '    metadata_path = DRAW_DIR / "Study2_block_order_permutation_plan.json"\n'
                                     '    n_blocks = {\n'
                                     '        session: math.ceil(n_windows_by_session[session] / '
                                     'block_lengths[session])\n'
                                     '        for session in SESSIONS\n'
                                     '    }\n'
                                     '    expected_metadata = {\n'
                                     '        "method": "random_block_order",\n'
                                     '        "n_permutations": int(N_PERMUTATIONS),\n'
                                     '        "seed": int(RANDOM_SEED + 20000),\n'
                                     '        "block_lengths": {session: int(v) for session, v in '
                                     'block_lengths.items()},\n'
                                     '        "n_windows_by_session": {\n'
                                     '            session: int(v) for session, v in n_windows_by_session.items()\n'
                                     '        },\n'
                                     '        "n_blocks": {session: int(v) for session, v in n_blocks.items()},\n'
                                     '    }\n'
                                     '    if path.exists() and metadata_path.exists() and RESUME_RESAMPLING:\n'
                                     '        metadata = load_json(metadata_path)\n'
                                     '        if metadata == expected_metadata:\n'
                                     '            loaded = np.load(path)\n'
                                     '            plan = {session: loaded[session] for session in SESSIONS}\n'
                                     '            if all(\n'
                                     '                plan[session].shape == (N_PERMUTATIONS, n_blocks[session])\n'
                                     '                for session in SESSIONS\n'
                                     '            ):\n'
                                     '                print(f"[PERM PLAN LOAD] {path}")\n'
                                     '                return plan\n'
                                     '\n'
                                     '    rng = np.random.default_rng(RANDOM_SEED + 20000)\n'
                                     '    plan = {}\n'
                                     '    for session in SESSIONS:\n'
                                     '        identity = np.arange(n_blocks[session], dtype=np.int16)\n'
                                     '        orders = np.empty((N_PERMUTATIONS, n_blocks[session]), dtype=np.int16)\n'
                                     '        for index in range(N_PERMUTATIONS):\n'
                                     '            order = rng.permutation(n_blocks[session]).astype(np.int16)\n'
                                     '            while np.array_equal(order, identity):\n'
                                     '                order = rng.permutation(n_blocks[session]).astype(np.int16)\n'
                                     '            orders[index] = order\n'
                                     '        plan[session] = orders\n'
                                     '    np.savez_compressed(path, **plan)\n'
                                     '    save_json(expected_metadata, metadata_path)\n'
                                     '    print(f"[PERM PLAN SAVED] {path}")\n'
                                     '    return plan\n'
                                     '\n'
                                     '\n'
                                     'def residualize_vector(values, covariates):\n'
                                     '    values = np.asarray(values, dtype=float)\n'
                                     '    covariates = np.asarray(covariates, dtype=float)\n'
                                     '    valid = np.isfinite(values) & np.all(np.isfinite(covariates), axis=1)\n'
                                     '    output = np.full(len(values), np.nan, dtype=float)\n'
                                     '\n'
                                     '    if valid.sum() < 3:\n'
                                     '        return output\n'
                                     '\n'
                                     '    c = covariates[valid]\n'
                                     '    means = np.mean(c, axis=0)\n'
                                     '    sds = np.std(c, axis=0, ddof=1)\n'
                                     '    keep = np.isfinite(sds) & (sds > 0)\n'
                                     '    c = (c[:, keep] - means[keep]) / sds[keep]\n'
                                     '\n'
                                     '    design = np.column_stack([np.ones(valid.sum()), c])\n'
                                     '    beta = np.linalg.lstsq(design, values[valid], rcond=None)[0]\n'
                                     '    output[valid] = values[valid] - design @ beta\n'
                                     '    return output\n'
                                     '\n'
                                     '\n'
                                     'def prepare_partial_series_for_permutation(df):\n'
                                     '    prepared = {affect: {} for affect in AFFECTS}\n'
                                     '\n'
                                     '    for session in SESSIONS:\n'
                                     '        subset = (\n'
                                     '            df.loc[df["session"].eq(session)]\n'
                                     '            .sort_values("window")\n'
                                     '            .reset_index(drop=True)\n'
                                     '        )\n'
                                     '        covariates = subset[MODEL_COVARIATES].to_numpy(float)\n'
                                     '        y = residualize_vector(\n'
                                     '            subset["z_neural_ISC"].to_numpy(float),\n'
                                     '            covariates,\n'
                                     '        )\n'
                                     '\n'
                                     '        for affect in AFFECTS:\n'
                                     '            x = residualize_vector(\n'
                                     '                subset[f"z_{affect}_ISC"].to_numpy(float),\n'
                                     '                covariates,\n'
                                     '            )\n'
                                     '            valid = np.isfinite(y) & np.isfinite(x)\n'
                                     '            prepared[affect][session] = {\n'
                                     '                "y": y[valid],\n'
                                     '                "x": x[valid],\n'
                                     '            }\n'
                                     '\n'
                                     '    return prepared\n'
                                     '\n'
                                     '\n'
                                     'def residual_marginal_metrics(partial_series, shifted_x):\n'
                                     '    slopes = []\n'
                                     '    partial_r2 = []\n'
                                     '\n'
                                     '    for session in SESSIONS:\n'
                                     '        y = partial_series[session]["y"]\n'
                                     '        x = shifted_x[session]\n'
                                     '        denominator = float(np.dot(x, x))\n'
                                     '        slope = np.nan if denominator <= 0 else float(np.dot(x, y) / '
                                     'denominator)\n'
                                     '        slopes.append(slope)\n'
                                     '\n'
                                     '        if np.nanstd(x, ddof=1) == 0 or np.nanstd(y, ddof=1) == 0:\n'
                                     '            partial_r2.append(np.nan)\n'
                                     '        else:\n'
                                     '            correlation = float(np.corrcoef(x, y)[0, 1])\n'
                                     '            partial_r2.append(correlation ** 2)\n'
                                     '\n'
                                     '    h01, h02 = slopes\n'
                                     '    r2_h01, r2_h02 = partial_r2\n'
                                     '    return {\n'
                                     '        "horror01_slope": float(h01),\n'
                                     '        "horror02_slope": float(h02),\n'
                                     '        "pooled_slope": float((h01 + h02) / 2.0),\n'
                                     '        "horror01_minus_horror02": float(h01 - h02),\n'
                                     '        "horror01_partial_r2": float(r2_h01),\n'
                                     '        "horror02_partial_r2": float(r2_h02),\n'
                                     '        "pooled_partial_r2": float(np.nanmean([r2_h01, r2_h02])),\n'
                                     '    }\n'
                                     '\n'
                                     '\n'
                                     'PERMUTATION_METRICS = []\n'
                                     'for _affect in AFFECTS:\n'
                                     '    PERMUTATION_METRICS.extend([\n'
                                     '        f"marginal_{_affect}_horror01_slope",\n'
                                     '        f"marginal_{_affect}_horror02_slope",\n'
                                     '        f"marginal_{_affect}_pooled_slope",\n'
                                     '        f"marginal_{_affect}_horror01_minus_horror02",\n'
                                     '        f"marginal_{_affect}_horror01_partial_r2",\n'
                                     '        f"marginal_{_affect}_horror02_partial_r2",\n'
                                     '        f"marginal_{_affect}_pooled_partial_r2",\n'
                                     '    ])\n'
                                     '\n'
                                     '\n'
                                     'def permutation_draw_paths():\n'
                                     '    return {\n'
                                     '        "draws": DRAW_DIR / "Study2_block_order_permutation_draws.npy",\n'
                                     '        "progress": DRAW_DIR / "Study2_block_order_permutation_progress.json",\n'
                                     '        "metrics": DRAW_DIR / "Study2_block_order_permutation_metrics.json",\n'
                                     '    }\n'
                                     '\n'
                                     '\n'
                                     'def run_temporal_permutation(observed_df, block_lengths, permutation_plan):\n'
                                     '    partial = prepare_partial_series_for_permutation(observed_df)\n'
                                     '\n'
                                     '    observed_metrics = {}\n'
                                     '    for affect in AFFECTS:\n'
                                     '        original = {\n'
                                     '            session: partial[affect][session]["x"]\n'
                                     '            for session in SESSIONS\n'
                                     '        }\n'
                                     '        metrics = residual_marginal_metrics(partial[affect], original)\n'
                                     '        for key, value in metrics.items():\n'
                                     '            observed_metrics[f"marginal_{affect}_{key}"] = value\n'
                                     '\n'
                                     '    paths = permutation_draw_paths()\n'
                                     '    n_metrics = len(PERMUTATION_METRICS)\n'
                                     '    start_index = 0\n'
                                     '\n'
                                     '    if (\n'
                                     '        RESUME_RESAMPLING\n'
                                     '        and paths["draws"].exists()\n'
                                     '        and paths["progress"].exists()\n'
                                     '        and paths["metrics"].exists()\n'
                                     '        and load_json(paths["metrics"]) == PERMUTATION_METRICS\n'
                                     '    ):\n'
                                     '        draws = np.lib.format.open_memmap(\n'
                                     '            paths["draws"],\n'
                                     '            mode="r+",\n'
                                     '            dtype=np.float64,\n'
                                     '            shape=(N_PERMUTATIONS, n_metrics),\n'
                                     '        )\n'
                                     '        start_index = int(load_json(paths["progress"]).get("completed", 0))\n'
                                     '        print(f"[PERM RESUME] starting at {start_index}")\n'
                                     '    else:\n'
                                     '        draws = np.lib.format.open_memmap(\n'
                                     '            paths["draws"],\n'
                                     '            mode="w+",\n'
                                     '            dtype=np.float64,\n'
                                     '            shape=(N_PERMUTATIONS, n_metrics),\n'
                                     '        )\n'
                                     '        save_json(PERMUTATION_METRICS, paths["metrics"])\n'
                                     '        save_json({"completed": 0}, paths["progress"])\n'
                                     '\n'
                                     '    permutation_start = time.time()\n'
                                     '    if start_index > 0:\n'
                                     '        print_progress(\n'
                                     '            "[TEMPORAL PERMUTATION]",\n'
                                     '            start_index,\n'
                                     '            N_PERMUTATIONS,\n'
                                     '            start_time=permutation_start,\n'
                                     '            extra="resumed",\n'
                                     '            done=(start_index >= N_PERMUTATIONS),\n'
                                     '        )\n'
                                     '\n'
                                     '    for permutation_index in range(start_index, N_PERMUTATIONS):\n'
                                     '        current = {}\n'
                                     '\n'
                                     '        for affect in AFFECTS:\n'
                                     '            shifted = {}\n'
                                     '            for session_index, session in enumerate(SESSIONS):\n'
                                     '                n = len(partial[affect][session]["y"])\n'
                                     '                indices = block_permutation_indices(\n'
                                     '                    n,\n'
                                     '                    block_lengths[session],\n'
                                     '                    permutation_plan[session][permutation_index],\n'
                                     '                )\n'
                                     '                shifted[session] = partial[affect][session]["x"][indices]\n'
                                     '\n'
                                     '            metrics = residual_marginal_metrics(partial[affect], shifted)\n'
                                     '            for key, value in metrics.items():\n'
                                     '                current[f"marginal_{affect}_{key}"] = value\n'
                                     '\n'
                                     '        draws[permutation_index] = [\n'
                                     '            current[metric] for metric in PERMUTATION_METRICS\n'
                                     '        ]\n'
                                     '\n'
                                     '        completed = permutation_index + 1\n'
                                     '        if completed % CHECKPOINT_EVERY == 0 or completed == N_PERMUTATIONS:\n'
                                     '            draws.flush()\n'
                                     '            save_json({"completed": completed}, paths["progress"])\n'
                                     '\n'
                                     '        if completed % PERM_PROGRESS_EVERY == 0 or completed == N_PERMUTATIONS:\n'
                                     '            print_progress(\n'
                                     '                "[TEMPORAL PERMUTATION]",\n'
                                     '                completed,\n'
                                     '                N_PERMUTATIONS,\n'
                                     '                start_time=permutation_start,\n'
                                     '                extra=(\n'
                                     '                    f"valence={current[\'marginal_valence_pooled_slope\']:+.3f}, '
                                     '"\n'
                                     '                    f"fear={current[\'marginal_fear_pooled_slope\']:+.3f}"\n'
                                     '                ),\n'
                                     '                done=(completed == N_PERMUTATIONS),\n'
                                     '            )\n'
                                     '\n'
                                     '    draws_array = np.asarray(draws)\n'
                                     '    summary_rows = []\n'
                                     '\n'
                                     '    for metric_index, metric in enumerate(PERMUTATION_METRICS):\n'
                                     '        null_values = draws_array[:, metric_index]\n'
                                     '        observed = float(observed_metrics[metric])\n'
                                     '\n'
                                     '        if metric.endswith("partial_r2"):\n'
                                     '            p_value = upper_tail_resampling_p(null_values, observed)\n'
                                     '            tail = "upper"\n'
                                     '        else:\n'
                                     '            p_value = two_sided_resampling_p(null_values, observed)\n'
                                     '            tail = "two-sided"\n'
                                     '\n'
                                     '        null_low, null_high = safe_quantile(null_values)\n'
                                     '        summary_rows.append({\n'
                                     '            "effect": metric,\n'
                                     '            "observed_estimate": observed,\n'
                                     '            "p_perm": p_value,\n'
                                     '            "permutation_tail": tail,\n'
                                     '            "null_mean": float(np.nanmean(null_values)),\n'
                                     '            "null_sd": float(np.nanstd(null_values, ddof=1)),\n'
                                     '            "null_q025": null_low,\n'
                                     '            "null_q975": null_high,\n'
                                     '            "n_permutations": int(np.isfinite(null_values).sum()),\n'
                                     '        })\n'
                                     '\n'
                                     '    summary = pd.DataFrame(summary_rows)\n'
                                     '    summary.to_csv(OUT_DIR / "Study2_block_order_permutation_summary.csv", '
                                     'index=False)\n'
                                     '    return observed_metrics, draws_array, summary\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# FULLY MATCHED PARTICIPANT BOOTSTRAP\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def draw_multinomial_weights(rng, n_subjects):\n'
                                     '    while True:\n'
                                     '        counts = rng.multinomial(\n'
                                     '            n_subjects,\n'
                                     '            np.full(n_subjects, 1.0 / n_subjects),\n'
                                     '        ).astype(np.int16)\n'
                                     '        if np.count_nonzero(counts) >= 2:\n'
                                     '            return counts\n'
                                     '\n'
                                     '\n'
                                     'def generate_bootstrap_weight_plan(prepared):\n'
                                     '    path = DRAW_DIR / "Study2_matched_participant_bootstrap_weights.npy"\n'
                                     '    metadata_path = DRAW_DIR / '
                                     '"Study2_matched_participant_bootstrap_weights.json"\n'
                                     '\n'
                                     '    n_subjects = len(prepared["common_ids"])\n'
                                     '    expected_metadata = {\n'
                                     '        "n_bootstrap": int(N_BOOTSTRAP),\n'
                                     '        "seed": int(RANDOM_SEED + 10000),\n'
                                     '        "n_subjects": int(n_subjects),\n'
                                     '    }\n'
                                     '\n'
                                     '    if path.exists() and metadata_path.exists() and RESUME_RESAMPLING:\n'
                                     '        metadata = load_json(metadata_path)\n'
                                     '        if metadata == expected_metadata:\n'
                                     '            weights = np.load(path)\n'
                                     '            if weights.shape == (N_BOOTSTRAP, n_subjects):\n'
                                     '                print(f"[BOOT PLAN LOAD] {path}")\n'
                                     '                return weights\n'
                                     '\n'
                                     '    rng = np.random.default_rng(RANDOM_SEED + 10000)\n'
                                     '    weights = np.empty((N_BOOTSTRAP, n_subjects), dtype=np.int16)\n'
                                     '    start = time.time()\n'
                                     '\n'
                                     '    for index in range(N_BOOTSTRAP):\n'
                                     '        weights[index] = draw_multinomial_weights(rng, n_subjects)\n'
                                     '        completed = index + 1\n'
                                     '        if completed % BOOT_PROGRESS_EVERY == 0 or completed == N_BOOTSTRAP:\n'
                                     '            print_progress(\n'
                                     '                "[BOOTSTRAP PLAN]",\n'
                                     '                completed,\n'
                                     '                N_BOOTSTRAP,\n'
                                     '                start_time=start,\n'
                                     '                extra=f"fully matched n={n_subjects}",\n'
                                     '                done=(completed == N_BOOTSTRAP),\n'
                                     '            )\n'
                                     '\n'
                                     '    np.save(path, weights)\n'
                                     '    save_json(expected_metadata, metadata_path)\n'
                                     '    print(f"[BOOT PLAN SAVED] {path}")\n'
                                     '    return weights\n'
                                     '\n'
                                     '\n'
                                     'BOOTSTRAP_METRICS = []\n'
                                     'for _affect in AFFECTS:\n'
                                     '    BOOTSTRAP_METRICS.extend([\n'
                                     '        f"marginal_{_affect}_horror01_slope",\n'
                                     '        f"marginal_{_affect}_horror02_slope",\n'
                                     '        f"marginal_{_affect}_pooled_slope",\n'
                                     '        f"marginal_{_affect}_horror01_minus_horror02",\n'
                                     '        f"marginal_{_affect}_full_r2",\n'
                                     '        f"marginal_{_affect}_full_adjusted_r2",\n'
                                     '        f"marginal_{_affect}_reduced_r2",\n'
                                     '        f"marginal_{_affect}_reduced_adjusted_r2",\n'
                                     '        f"marginal_{_affect}_delta_r2",\n'
                                     '    ])\n'
                                     '\n'
                                     '\n'
                                     'def bootstrap_draw_paths():\n'
                                     '    return {\n'
                                     '        "draws": DRAW_DIR / '
                                     '"Study2_matched_participant_bootstrap_draws_v2.npy",\n'
                                     '        "progress": DRAW_DIR / '
                                     '"Study2_matched_participant_bootstrap_progress_v2.json",\n'
                                     '        "metrics": DRAW_DIR / '
                                     '"Study2_matched_participant_bootstrap_metrics_v2.json",\n'
                                     '    }\n'
                                     '\n'
                                     '\n'
                                     'def run_participant_bootstrap(\n'
                                     '    prepared,\n'
                                     '    observed_effects,\n'
                                     '    bootstrap_plan,\n'
                                     '):\n'
                                     '    paths = bootstrap_draw_paths()\n'
                                     '    n_metrics = len(BOOTSTRAP_METRICS)\n'
                                     '    start_index = 0\n'
                                     '\n'
                                     '    can_resume = (\n'
                                     '        RESUME_RESAMPLING\n'
                                     '        and paths["draws"].exists()\n'
                                     '        and paths["progress"].exists()\n'
                                     '        and paths["metrics"].exists()\n'
                                     '        and load_json(paths["metrics"]) == BOOTSTRAP_METRICS\n'
                                     '    )\n'
                                     '\n'
                                     '    if can_resume:\n'
                                     '        draws = np.lib.format.open_memmap(\n'
                                     '            paths["draws"],\n'
                                     '            mode="r+",\n'
                                     '            dtype=np.float64,\n'
                                     '            shape=(N_BOOTSTRAP, n_metrics),\n'
                                     '        )\n'
                                     '        start_index = int(load_json(paths["progress"]).get("completed", 0))\n'
                                     '        print(f"[BOOT RESUME] starting at {start_index}")\n'
                                     '    else:\n'
                                     '        draws = np.lib.format.open_memmap(\n'
                                     '            paths["draws"],\n'
                                     '            mode="w+",\n'
                                     '            dtype=np.float64,\n'
                                     '            shape=(N_BOOTSTRAP, n_metrics),\n'
                                     '        )\n'
                                     '        save_json(BOOTSTRAP_METRICS, paths["metrics"])\n'
                                     '        save_json({"completed": 0}, paths["progress"])\n'
                                     '\n'
                                     '    start_time = time.time()\n'
                                     '    for bootstrap_index in range(start_index, N_BOOTSTRAP):\n'
                                     '        participant_weights = bootstrap_plan[bootstrap_index]\n'
                                     '        boot_df = build_window_table(prepared, participant_weights)\n'
                                     '        metrics = fit_all_effects(boot_df)\n'
                                     '        draws[bootstrap_index] = [\n'
                                     '            metrics[metric] for metric in BOOTSTRAP_METRICS\n'
                                     '        ]\n'
                                     '\n'
                                     '        completed = bootstrap_index + 1\n'
                                     '        if completed % CHECKPOINT_EVERY == 0 or completed == N_BOOTSTRAP:\n'
                                     '            draws.flush()\n'
                                     '            save_json({"completed": completed}, paths["progress"])\n'
                                     '        if completed % BOOT_PROGRESS_EVERY == 0 or completed == N_BOOTSTRAP:\n'
                                     '            print_progress(\n'
                                     '                "[MATCHED PARTICIPANT BOOTSTRAP]",\n'
                                     '                completed,\n'
                                     '                N_BOOTSTRAP,\n'
                                     '                start_time=start_time,\n'
                                     '                extra=(\n'
                                     '                    f"valence={metrics[\'marginal_valence_pooled_slope\']:+.3f}, '
                                     '"\n'
                                     '                    f"fear={metrics[\'marginal_fear_pooled_slope\']:+.3f}"\n'
                                     '                ),\n'
                                     '                done=(completed == N_BOOTSTRAP),\n'
                                     '            )\n'
                                     '\n'
                                     '    draws_array = np.asarray(draws)\n'
                                     '    summary_rows = []\n'
                                     '    for metric_index, metric in enumerate(BOOTSTRAP_METRICS):\n'
                                     '        values = draws_array[:, metric_index]\n'
                                     '        values = values[np.isfinite(values)]\n'
                                     '        observed = float(observed_effects[metric])\n'
                                     '        mean_value = float(np.mean(values))\n'
                                     '        standard_error = float(np.std(values, ddof=1))\n'
                                     '        ci_low, ci_high = safe_quantile(values)\n'
                                     '        if standard_error > 0 and np.isfinite(standard_error):\n'
                                     '            z_approx = observed / standard_error\n'
                                     '            p_normal = math.erfc(abs(z_approx) / math.sqrt(2.0))\n'
                                     '        else:\n'
                                     '            z_approx = np.nan\n'
                                     '            p_normal = np.nan\n'
                                     '        sign_p = np.nan if metric.endswith("r2") else sign_based_p(values)\n'
                                     '        summary_rows.append({\n'
                                     '            "effect": metric,\n'
                                     '            "observed_estimate": observed,\n'
                                     '            "bootstrap_mean": mean_value,\n'
                                     '            "bootstrap_bias": mean_value - observed,\n'
                                     '            "bootstrap_se": standard_error,\n'
                                     '            "bootstrap_z_approx": z_approx,\n'
                                     '            "bootstrap_p_normal_approx": p_normal,\n'
                                     '            "bootstrap_p_sign_approx": sign_p,\n'
                                     '            "bootstrap_ci_low": ci_low,\n'
                                     '            "bootstrap_ci_high": ci_high,\n'
                                     '            "n_bootstrap": len(values),\n'
                                     '        })\n'
                                     '\n'
                                     '    summary = pd.DataFrame(summary_rows)\n'
                                     '    summary.to_csv(\n'
                                     '        OUT_DIR / "Study2_matched_participant_bootstrap_summary.csv",\n'
                                     '        index=False,\n'
                                     '    )\n'
                                     '    return draws_array, summary\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# DIAGNOSTIC FIGURES\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def autocorrelation(values, max_lag):\n'
                                     '    values = np.asarray(values, dtype=float)\n'
                                     '    values = values[np.isfinite(values)]\n'
                                     '    values = values - np.mean(values)\n'
                                     '    denominator = np.dot(values, values)\n'
                                     '    if denominator <= 0:\n'
                                     '        return np.full(max_lag + 1, np.nan)\n'
                                     '\n'
                                     '    acf = [1.0]\n'
                                     '    for lag in range(1, max_lag + 1):\n'
                                     '        if lag >= len(values):\n'
                                     '            acf.append(np.nan)\n'
                                     '        else:\n'
                                     '            acf.append(float(np.dot(values[:-lag], values[lag:]) / '
                                     'denominator))\n'
                                     '    return np.asarray(acf)\n'
                                     '\n'
                                     '\n'
                                     'def create_dataset_overview(prepared, observed_df, block_lengths):\n'
                                     '    rows = []\n'
                                     '    n_subjects = len(prepared["common_ids"])\n'
                                     '    n_pairs = n_subjects * (n_subjects - 1) // 2\n'
                                     '\n'
                                     '    for session in SESSIONS:\n'
                                     '        subset = observed_df.loc[observed_df["session"].eq(session)]\n'
                                     '        rows.append({\n'
                                     '            "session": session,\n'
                                     '            "label": SESSION_LABELS[session],\n'
                                     '            "matched_participants": n_subjects,\n'
                                     '            "distinct_pairs": n_pairs,\n'
                                     '            "trimmed_timepoints": prepared["n_time_by_session"][session],\n'
                                     '            "window_size_TR": prepared["window_size_by_session"][session],\n'
                                     '            "n_windows": len(subset),\n'
                                     '            "block_length_windows": block_lengths[session],\n'
                                     '            "covariate_file": str(prepared["covariate_paths"][session]),\n'
                                     '        })\n'
                                     '\n'
                                     '    summary = pd.DataFrame(rows)\n'
                                     '    summary.to_csv(OUT_DIR / "DMN_dataset_overview.csv", index=False)\n'
                                     '\n'
                                     '    display = summary.drop(columns=["covariate_file"]).copy()\n'
                                     '    fig, axis = plt.subplots(figsize=(11.5, 2.6))\n'
                                     '    axis.axis("off")\n'
                                     '    table = axis.table(\n'
                                     '        cellText=display.values,\n'
                                     '        colLabels=display.columns,\n'
                                     '        cellLoc="center",\n'
                                     '        loc="center",\n'
                                     '    )\n'
                                     '    table.auto_set_font_size(False)\n'
                                     '    table.set_fontsize(9)\n'
                                     '    table.scale(1, 1.5)\n'
                                     '    axis.set_title(\n'
                                     '        "HMT horror DMN analysis: fully matched participant structure",\n'
                                     '        pad=14,\n'
                                     '    )\n'
                                     '    fig.tight_layout()\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_dataset_overview.png")\n'
                                     '    return summary\n'
                                     '\n'
                                     '\n'
                                     'def plot_dataset_timeseries(observed_df):\n'
                                     '    fig, axes = plt.subplots(len(SESSIONS), 1, figsize=(12.5, 6.5), '
                                     'sharex=False)\n'
                                     '\n'
                                     '    for axis, session in zip(axes, SESSIONS):\n'
                                     '        subset = observed_df.loc[observed_df["session"].eq(session)].copy()\n'
                                     '        progress = np.linspace(0, 100, len(subset))\n'
                                     '\n'
                                     '        axis.plot(\n'
                                     '            progress,\n'
                                     '            subset["z_neural_ISC"],\n'
                                     '            color=NEURAL_COLOR,\n'
                                     '            alpha=0.75,\n'
                                     '            linewidth=1.4,\n'
                                     '            label="DMN neural ISC",\n'
                                     '        )\n'
                                     '        axis.plot(\n'
                                     '            progress,\n'
                                     '            subset["z_valence_ISC"],\n'
                                     '            color=VALENCE_COLOR,\n'
                                     '            alpha=PLOT_ALPHA,\n'
                                     '            linewidth=1.4,\n'
                                     '            label="Valence ISC",\n'
                                     '        )\n'
                                     '        axis.plot(\n'
                                     '            progress,\n'
                                     '            subset["z_fear_ISC"],\n'
                                     '            color=FEAR_COLOR,\n'
                                     '            alpha=PLOT_ALPHA,\n'
                                     '            linewidth=1.4,\n'
                                     '            label="Fear ISC",\n'
                                     '        )\n'
                                     '        axis.axhline(0, color=NEUTRAL_COLOR, linestyle="--", linewidth=0.8)\n'
                                     '        axis.set_title(SESSION_LABELS[session])\n'
                                     '        axis.set_ylabel("Within-session z score")\n'
                                     '        style_axis(axis, grid_axis="y")\n'
                                     '\n'
                                     '    axes[-1].set_xlabel("Movie progress (%)")\n'
                                     '    axes[0].legend(ncol=3, frameon=False, loc="upper right")\n'
                                     '    fig.suptitle("Window-wise DMN and affective synchrony", y=1.01)\n'
                                     '    fig.tight_layout()\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_dataset_timeseries.png")\n'
                                     '\n'
                                     '\n'
                                     'def plot_dataset_distributions(observed_df):\n'
                                     '    variables = ["z_neural_ISC", "z_valence_ISC", "z_fear_ISC"]\n'
                                     '    labels = ["DMN neural", "Valence", "Fear"]\n'
                                     '    colors = [NEURAL_COLOR, VALENCE_COLOR, FEAR_COLOR]\n'
                                     '\n'
                                     '    fig, axes = plt.subplots(1, len(SESSIONS), figsize=(11.5, 4.6), '
                                     'sharey=True)\n'
                                     '\n'
                                     '    for axis, session in zip(axes, SESSIONS):\n'
                                     '        subset = observed_df.loc[observed_df["session"].eq(session)]\n'
                                     '        data = [subset[column].dropna().to_numpy(float) for column in '
                                     'variables]\n'
                                     '        box = axis.boxplot(data, patch_artist=True, labels=labels, '
                                     'showfliers=True)\n'
                                     '        for patch, color in zip(box["boxes"], colors):\n'
                                     '            patch.set_facecolor(color)\n'
                                     '            patch.set_alpha(PLOT_ALPHA)\n'
                                     '        axis.axhline(0, color=NEUTRAL_COLOR, linestyle="--", linewidth=0.8)\n'
                                     '        axis.set_title(SESSION_LABELS[session])\n'
                                     '        axis.tick_params(axis="x", rotation=15)\n'
                                     '        style_axis(axis, grid_axis="y")\n'
                                     '\n'
                                     '    axes[0].set_ylabel("Within-session z score")\n'
                                     '    fig.suptitle("Window-level ISC distributions", y=1.01)\n'
                                     '    fig.tight_layout()\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_dataset_distributions.png")\n'
                                     '\n'
                                     '\n'
                                     'def plot_dataset_acf(observed_df, block_lengths):\n'
                                     '    fig, axes = plt.subplots(1, len(SESSIONS), figsize=(12.5, 4.7), '
                                     'sharey=True)\n'
                                     '\n'
                                     '    for axis, session in zip(axes, SESSIONS):\n'
                                     '        subset = observed_df.loc[observed_df["session"].eq(session)]\n'
                                     '        maximum_lag = min(DIAGNOSTIC_ACF_MAX_LAG, len(subset) - 1)\n'
                                     '        lags = np.arange(maximum_lag + 1)\n'
                                     '\n'
                                     '        series = [\n'
                                     '            ("z_neural_ISC", "DMN neural", NEURAL_COLOR),\n'
                                     '            ("z_valence_ISC", "Valence", VALENCE_COLOR),\n'
                                     '            ("z_fear_ISC", "Fear", FEAR_COLOR),\n'
                                     '        ]\n'
                                     '        for column, label, color in series:\n'
                                     '            axis.plot(\n'
                                     '                lags,\n'
                                     '                autocorrelation(subset[column].to_numpy(float), maximum_lag),\n'
                                     '                label=label,\n'
                                     '                color=color,\n'
                                     '                alpha=PLOT_ALPHA,\n'
                                     '                linewidth=1.7,\n'
                                     '            )\n'
                                     '\n'
                                     '        axis.axhline(ACF_THRESHOLD, color=NEUTRAL_COLOR, linestyle=":", '
                                     'linewidth=1)\n'
                                     '        axis.axhline(-ACF_THRESHOLD, color=NEUTRAL_COLOR, linestyle=":", '
                                     'linewidth=1)\n'
                                     '        axis.axvline(\n'
                                     '            block_lengths[session],\n'
                                     '            color="black",\n'
                                     '            linestyle="--",\n'
                                     '            linewidth=1.2,\n'
                                     '            label=f"Block={block_lengths[session]}",\n'
                                     '        )\n'
                                     '        axis.set_title(SESSION_LABELS[session])\n'
                                     '        axis.set_xlabel("Lag (windows)")\n'
                                     '        style_axis(axis, grid_axis="y")\n'
                                     '\n'
                                     '    axes[0].set_ylabel("Autocorrelation")\n'
                                     '    axes[0].legend(frameon=False, fontsize=8)\n'
                                     '    fig.suptitle("Temporal autocorrelation and selected block lengths", y=1.01)\n'
                                     '    fig.tight_layout()\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_dataset_ACF.png")\n'
                                     '\n'
                                     '\n'
                                     'def plot_valence_fear_relationship(observed_df):\n'
                                     '    fig, axes = plt.subplots(1, len(SESSIONS), figsize=(11.5, 4.7), sharex=True, '
                                     'sharey=True)\n'
                                     '\n'
                                     '    for axis, session in zip(axes, SESSIONS):\n'
                                     '        subset = observed_df.loc[observed_df["session"].eq(session)]\n'
                                     '        x = subset["z_valence_ISC"].to_numpy(float)\n'
                                     '        y = subset["z_fear_ISC"].to_numpy(float)\n'
                                     '        valid = np.isfinite(x) & np.isfinite(y)\n'
                                     '        correlation = np.corrcoef(x[valid], y[valid])[0, 1]\n'
                                     '\n'
                                     '        axis.scatter(\n'
                                     '            x[valid],\n'
                                     '            y[valid],\n'
                                     '            s=DIAGNOSTIC_SCATTER_SIZE,\n'
                                     '            color=FEAR_COLOR,\n'
                                     '            alpha=PLOT_ALPHA,\n'
                                     '            edgecolors="none",\n'
                                     '        )\n'
                                     '        if valid.sum() >= 3:\n'
                                     '            slope, intercept = np.polyfit(x[valid], y[valid], 1)\n'
                                     '            x_line = np.linspace(np.min(x[valid]), np.max(x[valid]), 100)\n'
                                     '            axis.plot(x_line, intercept + slope * x_line, color=NEUTRAL_COLOR, '
                                     'linewidth=1.5)\n'
                                     '\n'
                                     '        axis.set_title(f"{SESSION_LABELS[session]}: r={correlation:.3f}")\n'
                                     '        axis.set_xlabel("Valence ISC (z)")\n'
                                     '        style_axis(axis, grid_axis="both")\n'
                                     '\n'
                                     '    axes[0].set_ylabel("Fear ISC (z)")\n'
                                     '    fig.suptitle("Descriptive valence–fear relationship", y=1.01)\n'
                                     '    fig.tight_layout()\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_valence_fear_relationship.png")\n'
                                     '\n'
                                     '\n'
                                     'def plot_partial_neural_affect_relationships(observed_df):\n'
                                     '    fig, axes = plt.subplots(\n'
                                     '        len(AFFECTS),\n'
                                     '        len(SESSIONS),\n'
                                     '        figsize=(12.0, 8.0),\n'
                                     '        sharex=False,\n'
                                     '        sharey=False,\n'
                                     '    )\n'
                                     '\n'
                                     '    for row_index, affect in enumerate(AFFECTS):\n'
                                     '        for column_index, session in enumerate(SESSIONS):\n'
                                     '            axis = axes[row_index, column_index]\n'
                                     '            subset = (\n'
                                     '                observed_df.loc[observed_df["session"].eq(session)]\n'
                                     '                .sort_values("window")\n'
                                     '                .reset_index(drop=True)\n'
                                     '            )\n'
                                     '            covariates = subset[MODEL_COVARIATES].to_numpy(float)\n'
                                     '            x = residualize_vector(\n'
                                     '                subset[f"z_{affect}_ISC"].to_numpy(float),\n'
                                     '                covariates,\n'
                                     '            )\n'
                                     '            y = residualize_vector(\n'
                                     '                subset["z_neural_ISC"].to_numpy(float),\n'
                                     '                covariates,\n'
                                     '            )\n'
                                     '            valid = np.isfinite(x) & np.isfinite(y)\n'
                                     '            correlation = np.corrcoef(x[valid], y[valid])[0, 1]\n'
                                     '\n'
                                     '            color = AFFECT_COLORS[affect]\n'
                                     '            axis.scatter(\n'
                                     '                x[valid],\n'
                                     '                y[valid],\n'
                                     '                s=DIAGNOSTIC_SCATTER_SIZE,\n'
                                     '                color=color,\n'
                                     '                alpha=PLOT_ALPHA,\n'
                                     '                edgecolors="none",\n'
                                     '            )\n'
                                     '            if valid.sum() >= 3:\n'
                                     '                slope, intercept = np.polyfit(x[valid], y[valid], 1)\n'
                                     '                x_line = np.linspace(np.min(x[valid]), np.max(x[valid]), 100)\n'
                                     '                axis.plot(x_line, intercept + slope * x_line, color=color, '
                                     'linewidth=1.6)\n'
                                     '\n'
                                     '            axis.set_title(\n'
                                     '                f"{SESSION_LABELS[session]} | {AFFECT_LABELS[affect]} | "\n'
                                     '                f"partial r={correlation:.3f}"\n'
                                     '            )\n'
                                     '            axis.set_xlabel(f"Residual {AFFECT_LABELS[affect]} ISC")\n'
                                     '            axis.set_ylabel("Residual DMN ISC")\n'
                                     '            style_axis(axis, grid_axis="both")\n'
                                     '\n'
                                     '    fig.suptitle(\n'
                                     '        "Covariate-adjusted DMN–affect relationships",\n'
                                     '        y=1.01,\n'
                                     '    )\n'
                                     '    fig.tight_layout()\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_partial_neural_affect_relationships.png")\n'
                                     '\n'
                                     '\n'
                                     'def plot_predictor_correlation_heatmaps(observed_df):\n'
                                     '    columns = [\n'
                                     '        "z_neural_ISC",\n'
                                     '        "z_valence_ISC",\n'
                                     '        "z_fear_ISC",\n'
                                     '        "brightness_z",\n'
                                     '        "audio_rms_z",\n'
                                     '        "optical_flow_z",\n'
                                     '    ]\n'
                                     '    labels = ["DMN", "Valence", "Fear", "Brightness", "Audio", "Flow"]\n'
                                     '\n'
                                     '    fig, axes = plt.subplots(1, len(SESSIONS), figsize=(13.0, 5.2))\n'
                                     '\n'
                                     '    for axis, session in zip(axes, SESSIONS):\n'
                                     '        subset = observed_df.loc[observed_df["session"].eq(session), columns]\n'
                                     '        correlation = subset.corr().to_numpy(float)\n'
                                     '        image = axis.imshow(\n'
                                     '            correlation,\n'
                                     '            cmap=AFFECT_DIVERGING_CMAP,\n'
                                     '            vmin=-1,\n'
                                     '            vmax=1,\n'
                                     '            aspect="auto",\n'
                                     '        )\n'
                                     '        axis.set_xticks(np.arange(len(labels)))\n'
                                     '        axis.set_xticklabels(labels, rotation=35, ha="right")\n'
                                     '        axis.set_yticks(np.arange(len(labels)))\n'
                                     '        axis.set_yticklabels(labels)\n'
                                     '        axis.set_title(SESSION_LABELS[session])\n'
                                     '\n'
                                     '        for row in range(len(labels)):\n'
                                     '            for column in range(len(labels)):\n'
                                     '                value = correlation[row, column]\n'
                                     '                axis.text(\n'
                                     '                    column,\n'
                                     '                    row,\n'
                                     '                    f"{value:.2f}",\n'
                                     '                    ha="center",\n'
                                     '                    va="center",\n'
                                     '                    fontsize=8,\n'
                                     '                    color="white" if abs(value) > 0.55 else NEUTRAL_COLOR,\n'
                                     '                )\n'
                                     '\n'
                                     '        for spine in axis.spines.values():\n'
                                     '            spine.set_visible(False)\n'
                                     '\n'
                                     '    fig.colorbar(image, ax=axes.ravel().tolist(), shrink=0.80, label="Pearson '
                                     'r")\n'
                                     '    fig.suptitle("Window-level predictor correlations", y=1.02)\n'
                                     '    fig.subplots_adjust(wspace=0.35, top=0.86, bottom=0.20)\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_predictor_correlation_heatmaps.png")\n'
                                     '\n'
                                     '\n'
                                     'def run_dataset_diagnostics(prepared, observed_df, block_lengths):\n'
                                     '    print_section("DATASET DIAGNOSTICS")\n'
                                     '    create_dataset_overview(prepared, observed_df, block_lengths)\n'
                                     '    plot_dataset_timeseries(observed_df)\n'
                                     '    plot_dataset_distributions(observed_df)\n'
                                     '    plot_dataset_acf(observed_df, block_lengths)\n'
                                     '    plot_valence_fear_relationship(observed_df)\n'
                                     '    plot_partial_neural_affect_relationships(observed_df)\n'
                                     '    plot_predictor_correlation_heatmaps(observed_df)\n'
                                     '\n'
                                     '    descriptive_rows = []\n'
                                     '    for session in SESSIONS:\n'
                                     '        subset = observed_df.loc[observed_df["session"].eq(session)]\n'
                                     '        for variable in ["z_neural_ISC", "z_valence_ISC", "z_fear_ISC"]:\n'
                                     '            values = subset[variable].to_numpy(float)\n'
                                     '            descriptive_rows.append({\n'
                                     '                "session": session,\n'
                                     '                "variable": variable,\n'
                                     '                "n_windows": int(np.isfinite(values).sum()),\n'
                                     '                "mean": float(np.nanmean(values)),\n'
                                     '                "sd": float(np.nanstd(values, ddof=1)),\n'
                                     '                "minimum": float(np.nanmin(values)),\n'
                                     '                "maximum": float(np.nanmax(values)),\n'
                                     '                "skew": float(pd.Series(values).skew()),\n'
                                     '                "kurtosis": float(pd.Series(values).kurt()),\n'
                                     '            })\n'
                                     '    pd.DataFrame(descriptive_rows).to_csv(\n'
                                     '        OUT_DIR / "DMN_dataset_descriptive_summary.csv",\n'
                                     '        index=False,\n'
                                     '    )\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# RESULT FIGURES\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def plot_resampling_distributions(\n'
                                     '    observed_effects,\n'
                                     '    permutation_draws,\n'
                                     '    bootstrap_draws,\n'
                                     '):\n'
                                     '    permutation_index = {\n'
                                     '        metric: index for index, metric in enumerate(PERMUTATION_METRICS)\n'
                                     '    }\n'
                                     '    bootstrap_index = {\n'
                                     '        metric: index for index, metric in enumerate(BOOTSTRAP_METRICS)\n'
                                     '    }\n'
                                     '\n'
                                     '    fig, axes = plt.subplots(len(AFFECTS), 2, figsize=(12.5, 7.6))\n'
                                     '\n'
                                     '    for row_index, affect in enumerate(AFFECTS):\n'
                                     '        metric = f"marginal_{affect}_pooled_slope"\n'
                                     '        observed = observed_effects[metric]\n'
                                     '        color = AFFECT_COLORS[affect]\n'
                                     '\n'
                                     '        axis_perm = axes[row_index, 0]\n'
                                     '        null_values = permutation_draws[:, permutation_index[metric]]\n'
                                     '        axis_perm.hist(\n'
                                     '            null_values,\n'
                                     '            bins=50,\n'
                                     '            color=color,\n'
                                     '            alpha=PLOT_ALPHA,\n'
                                     '            edgecolor="white",\n'
                                     '            linewidth=0.4,\n'
                                     '        )\n'
                                     '        axis_perm.axvline(observed, color=color, linewidth=2.2)\n'
                                     '        axis_perm.axvline(-abs(observed), color=NEUTRAL_COLOR, linestyle="--", '
                                     'linewidth=1)\n'
                                     '        axis_perm.set_title(\n'
                                     '            f"{AFFECT_LABELS[affect]} pooled slope\\nTemporal permutation null"\n'
                                     '        )\n'
                                     '        axis_perm.set_xlabel("Null pooled slope")\n'
                                     '        axis_perm.set_ylabel("Frequency")\n'
                                     '        style_axis(axis_perm, grid_axis="y")\n'
                                     '\n'
                                     '        axis_boot = axes[row_index, 1]\n'
                                     '        boot_values = bootstrap_draws[:, bootstrap_index[metric]]\n'
                                     '        axis_boot.hist(\n'
                                     '            boot_values,\n'
                                     '            bins=50,\n'
                                     '            color=color,\n'
                                     '            alpha=PLOT_ALPHA,\n'
                                     '            edgecolor="white",\n'
                                     '            linewidth=0.4,\n'
                                     '        )\n'
                                     '        axis_boot.axvline(observed, color=color, linewidth=2.2)\n'
                                     '        axis_boot.axvline(0, color=NEUTRAL_COLOR, linestyle="--", linewidth=1)\n'
                                     '        axis_boot.set_title(\n'
                                     '            f"{AFFECT_LABELS[affect]} pooled slope\\nMatched participant '
                                     'bootstrap"\n'
                                     '        )\n'
                                     '        axis_boot.set_xlabel("Bootstrap pooled slope")\n'
                                     '        axis_boot.set_ylabel("Frequency")\n'
                                     '        style_axis(axis_boot, grid_axis="y")\n'
                                     '\n'
                                     '    fig.suptitle("Temporal and participant uncertainty", y=1.01)\n'
                                     '    fig.tight_layout()\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_resampling_distributions.png")\n'
                                     '\n'
                                     '\n'
                                     'def plot_bootstrap_session_pairing(bootstrap_draws):\n'
                                     '    index = {metric: i for i, metric in enumerate(BOOTSTRAP_METRICS)}\n'
                                     '    fig, axes = plt.subplots(1, len(AFFECTS), figsize=(11.5, 4.8))\n'
                                     '\n'
                                     '    for axis, affect in zip(axes, AFFECTS):\n'
                                     '        h01 = bootstrap_draws[:, index[f"marginal_{affect}_horror01_slope"]]\n'
                                     '        h02 = bootstrap_draws[:, index[f"marginal_{affect}_horror02_slope"]]\n'
                                     '        valid = np.isfinite(h01) & np.isfinite(h02)\n'
                                     '        correlation = np.corrcoef(h01[valid], h02[valid])[0, 1]\n'
                                     '        color = AFFECT_COLORS[affect]\n'
                                     '\n'
                                     '        axis.scatter(\n'
                                     '            h01[valid],\n'
                                     '            h02[valid],\n'
                                     '            s=10,\n'
                                     '            color=color,\n'
                                     '            alpha=0.22,\n'
                                     '            edgecolors="none",\n'
                                     '        )\n'
                                     '        minimum = min(np.min(h01[valid]), np.min(h02[valid]))\n'
                                     '        maximum = max(np.max(h01[valid]), np.max(h02[valid]))\n'
                                     '        axis.plot([minimum, maximum], [minimum, maximum], color=NEUTRAL_COLOR, '
                                     'linestyle="--")\n'
                                     '        axis.set_title(\n'
                                     '            f"{AFFECT_LABELS[affect]} bootstrap slopes\\nr={correlation:.3f}"\n'
                                     '        )\n'
                                     '        axis.set_xlabel("Horror 1 slope")\n'
                                     '        axis.set_ylabel("Horror 2 slope")\n'
                                     '        style_axis(axis, grid_axis="both")\n'
                                     '\n'
                                     '    fig.suptitle("Paired-session covariance under matched participant '
                                     'resampling", y=1.01)\n'
                                     '    fig.tight_layout()\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_bootstrap_session_pairing.png")\n'
                                     '\n'
                                     '\n'
                                     'def plot_explained_variance(observed_effects, bootstrap_summary):\n'
                                     '    fig, axis = plt.subplots(figsize=(7.4, 4.8))\n'
                                     '    positions = np.arange(len(AFFECTS))\n'
                                     '    observed = []\n'
                                     '    lower = []\n'
                                     '    upper = []\n'
                                     '\n'
                                     '    for affect in AFFECTS:\n'
                                     '        metric = f"marginal_{affect}_delta_r2"\n'
                                     '        observed.append(observed_effects[metric])\n'
                                     '        row = '
                                     'bootstrap_summary.loc[bootstrap_summary["effect"].eq(metric)].iloc[0]\n'
                                     '        lower.append(row["bootstrap_ci_low"])\n'
                                     '        upper.append(row["bootstrap_ci_high"])\n'
                                     '\n'
                                     '    observed = np.asarray(observed, dtype=float)\n'
                                     '    lower = np.asarray(lower, dtype=float)\n'
                                     '    upper = np.asarray(upper, dtype=float)\n'
                                     '    errors = np.vstack([observed - lower, upper - observed])\n'
                                     '\n'
                                     '    for position, estimate, error, affect in zip(\n'
                                     '        positions,\n'
                                     '        observed,\n'
                                     '        errors.T,\n'
                                     '        AFFECTS,\n'
                                     '    ):\n'
                                     '        color = AFFECT_COLORS[affect]\n'
                                     '        axis.errorbar(\n'
                                     '            position,\n'
                                     '            estimate,\n'
                                     '            yerr=np.asarray(error).reshape(2, 1),\n'
                                     '            fmt="o",\n'
                                     '            markersize=9,\n'
                                     '            capsize=5,\n'
                                     '            color=color,\n'
                                     '            ecolor=color,\n'
                                     '            alpha=PLOT_ALPHA,\n'
                                     '            linewidth=2,\n'
                                     '        )\n'
                                     '\n'
                                     '    axis.axhline(0, color=NEUTRAL_COLOR, linestyle="--", linewidth=1)\n'
                                     '    axis.set_xticks(positions)\n'
                                     '    axis.set_xticklabels([AFFECT_LABELS[affect] for affect in AFFECTS])\n'
                                     '    axis.set_ylabel("Incremental ΔR² beyond covariates")\n'
                                     '    axis.set_title("Additional model variance explained")\n'
                                     '    style_axis(axis, grid_axis="y")\n'
                                     '    fig.tight_layout()\n'
                                     '    finish_figure(fig, FIG_DIR / "DMN_incremental_delta_R2.png")\n'
                                     '\n'
                                     '\n'
                                     '# =============================================================================\n'
                                     '# MERGE RESULTS\n'
                                     '# =============================================================================\n'
                                     '\n'
                                     '\n'
                                     'def merge_results(\n'
                                     '    observed_effects,\n'
                                     '    permutation_summary,\n'
                                     '    bootstrap_summary,\n'
                                     '):\n'
                                     '    effects = sorted(set(\n'
                                     '        list(observed_effects)\n'
                                     '        + permutation_summary["effect"].tolist()\n'
                                     '        + bootstrap_summary["effect"].tolist()\n'
                                     '    ))\n'
                                     '\n'
                                     '    rows = []\n'
                                     '    for effect in effects:\n'
                                     '        row = {\n'
                                     '            "effect": effect,\n'
                                     '            "observed_estimate": observed_effects.get(effect, np.nan),\n'
                                     '        }\n'
                                     '\n'
                                     '        permutation_row = permutation_summary.loc[\n'
                                     '            permutation_summary["effect"].eq(effect)\n'
                                     '        ]\n'
                                     '        if not permutation_row.empty:\n'
                                     '            for column in [\n'
                                     '                "p_perm", "permutation_tail", "null_mean", "null_sd",\n'
                                     '                "null_q025", "null_q975", "n_permutations",\n'
                                     '            ]:\n'
                                     '                row[column] = permutation_row.iloc[0][column]\n'
                                     '\n'
                                     '        bootstrap_row = bootstrap_summary.loc[\n'
                                     '            bootstrap_summary["effect"].eq(effect)\n'
                                     '        ]\n'
                                     '        if not bootstrap_row.empty:\n'
                                     '            for column in [\n'
                                     '                "bootstrap_mean", "bootstrap_bias", "bootstrap_se",\n'
                                     '                "bootstrap_z_approx", "bootstrap_p_normal_approx",\n'
                                     '                "bootstrap_p_sign_approx", "bootstrap_ci_low",\n'
                                     '                "bootstrap_ci_high", "n_bootstrap",\n'
                                     '            ]:\n'
                                     '                row[column] = bootstrap_row.iloc[0][column]\n'
                                     '\n'
                                     '        rows.append(row)\n'
                                     '\n'
                                     '    output = pd.DataFrame(rows)\n'
                                     '    output["study"] = "Study2"\n'
                                     '    output["inference_role"] = "descriptive_or_secondary"\n'
                                     '    output.loc[\n'
                                     '        output["effect"].eq("marginal_valence_pooled_slope"),\n'
                                     '        "inference_role",\n'
                                     '    ] = "primary_replication"\n'
                                     '    output.loc[\n'
                                     '        output["effect"].eq("marginal_fear_pooled_slope"),\n'
                                     '        "inference_role",\n'
                                     '    ] = "category_level_extension"\n'
                                     '    output.loc[\n'
                                     '        output["effect"].str.endswith("horror01_minus_horror02", na=False),\n'
                                     '        "inference_role",\n'
                                     '    ] = "session_generalization"\n'
                                     '    return output\n'
                                     '\n'
                                     'def save_manuscript_tables(final_summary):\n'
                                     '    session_effects = [\n'
                                     '        f"marginal_{affect}_{session}_slope"\n'
                                     '        for affect in AFFECTS\n'
                                     '        for session in SESSIONS\n'
                                     '    ]\n'
                                     '    pooled_effects = []\n'
                                     '    for affect in AFFECTS:\n'
                                     '        pooled_effects.extend([\n'
                                     '            f"marginal_{affect}_pooled_slope",\n'
                                     '            f"marginal_{affect}_horror01_minus_horror02",\n'
                                     '            f"marginal_{affect}_pooled_partial_r2",\n'
                                     '            f"marginal_{affect}_delta_r2",\n'
                                     '        ])\n'
