                                     '        "bootstrap_p_sign_approx",\n'
                                     '    ]\n'
                                     '    columns = [column for column in columns if column in final_summary.columns]\n'
                                     '    session_table = final_summary.loc[\n'
                                     '        final_summary["effect"].isin(session_effects), columns\n'
                                     '    ].copy()\n'
                                     '    pooled_table = final_summary.loc[\n'
                                     '        final_summary["effect"].isin(pooled_effects), columns\n'
                                     '    ].copy()\n'
                                     '    session_table.to_csv(\n'
                                     '        OUT_DIR / "Study2_session_specific_results.csv", index=False\n'
                                     '    )\n'
