                                                                                       '    SCRIPT_DIR.parents[1],\n'
                                                                                       ')\n'
                                                                                       'DATA_ROOT = '
                                                                                       'Path(os.environ.get("VISC_DATA_DIR", '
                                                                                       'PROJECT_ROOT / '
                                                                                       '"data")).expanduser()\n'
                                                                                       'RESULTS_ROOT = Path(\n'
                                                                                       '    '
                                                                                       'os.environ.get("VISC_RESULTS_DIR", '
                                                                                       'PROJECT_ROOT / "results")\n'
                                                                                       ').expanduser()\n'
                                                                                       'STUDY1_SCRIPT = SCRIPT_DIR / '
                                                                                       '"Study1_DMN_independent_modalities.py"\n'
                                                                                       'STUDY2_SCRIPT = SCRIPT_DIR / '
                                                                                       '"Study2_DMN_matched_modalities.py"\n'
                                                                                       '\n'
                                                                                       'EXPECTED_STUDY1_ALIGNMENT_VERSION '
                                                                                       '= '
                                                                                       '"study1_independent_modalities_alignment_v1"\n'
                                                                                       'EXPECTED_STUDY2_ALIGNMENT_VERSION '
                                                                                       '= '
                                                                                       '"study2_matched_modalities_front_alignment_v1"\n'
                                                                                       '\n'
                                                                                       'N_RESAMPLES = 10_000\n'
                                                                                       'RANDOM_SEED = 91_407\n'
                                                                                       'ACF_THRESHOLD = 0.10\n'
                                                                                       '\n'
                                                                                       '# Atlas used for the '
                                                                                       'regional-level DMN definition '
