                                                                                       '"shen268.csv"\n'
                                                                                       'RUN_REGIONAL_LEVEL_ANALYSIS = '
                                                                                       'True\n'
                                                                                       'RUN_ALL_FIVE_VALENCE_ANALYSIS '
                                                                                       '= True\n'
                                                                                       'REGIONAL_FDR_ALPHA = 0.05\n'
                                                                                       '\n'
                                                                                       '# Explicit movieBD source and '
                                                                                       'cache audit. The unique cache '
                                                                                       'directory prevents\n'
                                                                                       '# accidental reuse of legacy '
                                                                                       'pairwise-ISC caches generated '
                                                                                       'from older files.\n'
                                                                                       'EXPECTED_MOVIEBD_DIR = Path(\n'
                                                                                       '    '
                                                                                       'os.environ.get("STUDY1_BD_BRAIN_DIR", '
                                                                                       'DATA_ROOT / "brain" / '
                                                                                       '"study1_movieBD")\n'
                                                                                       ')\n'
                                                                                       'MOVIEBD_CACHE_DIR_NAME = '
                                                                                       '"pairwise_cache_cc700_recomputed"\n'
                                                                                       'FORCE_REBUILD_PAIR_CACHE = '
                                                                                       'True\n'
                                                                                       '\n'
                                                                                       'ALL_FIVE_DATASETS = [\n'
                                                                                       '    "movieTP",\n'
                                                                                       '    "movieDM",\n'
                                                                                       '    "movieBD",\n'
                                                                                       '    "horror01",\n'
                                                                                       '    "horror02",\n'
                                                                                       ']\n'
                                                                                       'REGIONAL_SAVE_DYAD_SLOPES = '
                                                                                       'False\n'
                                                                                       'REGIONAL_SAVE_RESAMPLING_DRAWS '
                                                                                       '= False\n'
                                                                                       'REGIONAL_SAVE_FIGURES = False\n'
                                                                                       '\n'
                                                                                       '# Resume the comparatively '
                                                                                       'expensive behavioral-bootstrap '
                                                                                       'residual trajectories.\n'
                                                                                       'RESUME = False\n'
                                                                                       'CHECKPOINT_EVERY = 100\n'
                                                                                       'PROGRESS_EVERY = 50\n'
                                                                                       '\n'
                                                                                       '# Keep all dyads for final '
                                                                                       'analysis.  Integers are '
                                                                                       'available only for smoke '
                                                                                       'tests.\n'
                                                                                       'MAX_DYADS_BY_DATASET: '
                                                                                       'dict[str, int | None] = {\n'
                                                                                       '    "movieTP": None,\n'
                                                                                       '    "movieDM": None,\n'
                                                                                       '    "movieBD": None,\n'
                                                                                       '    "horror01": None,\n'
                                                                                       '    "horror02": None,\n'
                                                                                       '}\n'
                                                                                       '\n'
                                                                                       'OUT_DIR: Path | None = None\n'
                                                                                       'DRAW_DIR: Path | None = None\n'
                                                                                       'FIG_DIR: Path | None = None\n'
                                                                                       '\n'
                                                                                       'NEUTRAL_COLOR = "#5E6673"\n'
                                                                                       'VALENCE_COLOR = "#E978A8"\n'
                                                                                       'SECONDARY_COLOR = "#45B8AC"\n'
                                                                                       'DYAD_DISTRIBUTION_COLOR = '
                                                                                       '"#B8BEC8"\n'
                                                                                       '\n'
                                                                                       '# Dyad-slope distribution '
                                                                                       'figures. Violin densities use '
                                                                                       'every dyad. The\n'
                                                                                       '# overlaid points are a '
                                                                                       'deterministic visual subsample '
                                                                                       'that always includes\n'
                                                                                       '# the observed minimum and '
                                                                                       'maximum for each stimulus. The '
                                                                                       'common x-axis is\n'
                                                                                       '# symmetric around zero and is '
                                                                                       'based on the largest absolute '
                                                                                       'raw endpoint\n'
                                                                                       '# across all stimuli in the '
                                                                                       'figure, while also retaining '
                                                                                       'every model CI.\n'
                                                                                       'DYAD_SLOPE_FIG_MAX_POINTS_PER_STIMULUS '
                                                                                       '= 600\n'
                                                                                       'DYAD_SLOPE_FIG_VIOLIN_EVALUATION_POINTS '
                                                                                       '= 200\n'
                                                                                       'DYAD_SLOPE_FIG_SAVE_PDF = '
                                                                                       'True\n'
                                                                                       'DYAD_SLOPE_FIG_XLIM_PADDING_FRACTION '
                                                                                       '= 0.04\n'
                                                                                       '\n'
                                                                                       'plt.rcParams.update({\n'
                                                                                       '    "figure.dpi": 120,\n'
                                                                                       '    "axes.titlesize": 12,\n'
                                                                                       '    "axes.labelsize": 10,\n'
                                                                                       '    "xtick.labelsize": 9,\n'
                                                                                       '    "ytick.labelsize": 9,\n'
                                                                                       '    "legend.fontsize": 9,\n'
                                                                                       '})\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '# DATA CONTAINERS\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '@dataclass\n'
                                                                                       'class TemporalComponent:\n'
                                                                                       '    """One signed '
                                                                                       'temporal-slope component '
                                                                                       'contributing to a dyad '
                                                                                       'outcome."""\n'
                                                                                       '\n'
                                                                                       '    x_observed: np.ndarray\n'
                                                                                       '    neural_residuals: '
                                                                                       'np.ndarray  # windows x dyads\n'
                                                                                       '    sign: float\n'
                                                                                       '    bootstrap_key: str\n'
                                                                                       '    permutation_key: str\n'
                                                                                       '    # Optional dynamic control '
                                                                                       'for behavior-bootstrap draws.  '
                                                                                       'This is used for\n'
                                                                                       '    # conditional valence: '
                                                                                       'neural residualization must be '
                                                                                       'updated when the\n'
                                                                                       '    # bootstrapped arousal '
                                                                                       'control changes.\n'
                                                                                       '    bootstrap_neural_base: '
                                                                                       'np.ndarray | None = None\n'
                                                                                       '    '
                                                                                       'bootstrap_additional_control_key: '
                                                                                       'str | None = None\n'
                                                                                       '    # Fixed nuisance-covariate '
                                                                                       'matrix for the exact retained '
                                                                                       'timeline. This is\n'
                                                                                       '    # used to re-residualize '
                                                                                       'temporally permuted behavioral '
                                                                                       'predictors at their\n'
                                                                                       '    # destination time points '
                                                                                       'before null slopes are '
                                                                                       'computed.\n'
                                                                                       '    nuisance_controls: '
                                                                                       'np.ndarray | None = None\n'
                                                                                       '\n'
                                                                                       '    def validate(self, '
                                                                                       'n_dyads: int) -> None:\n'
                                                                                       '        x = '
                                                                                       'np.asarray(self.x_observed, '
                                                                                       'dtype=float)\n'
                                                                                       '        y = '
                                                                                       'np.asarray(self.neural_residuals)\n'
                                                                                       '        if x.ndim != 1:\n'
                                                                                       '            raise '
                                                                                       'ValueError("x_observed must be '
                                                                                       'one-dimensional")\n'
                                                                                       '        if y.ndim != 2:\n'
                                                                                       '            raise '
                                                                                       'ValueError("neural_residuals '
                                                                                       'must be two-dimensional")\n'
                                                                                       '        if y.shape[0] != '
                                                                                       'len(x):\n'
                                                                                       '            raise '
                                                                                       'ValueError(f"Temporal length '
                                                                                       'mismatch: {y.shape[0]} vs '
                                                                                       '{len(x)}")\n'
                                                                                       '        if y.shape[1] != '
                                                                                       'n_dyads:\n'
                                                                                       '            raise '
                                                                                       'ValueError(f"Dyad count '
                                                                                       'mismatch: {y.shape[1]} vs '
                                                                                       '{n_dyads}")\n'
                                                                                       '        if not '
                                                                                       'np.all(np.isfinite(x)):\n'
                                                                                       '            raise '
                                                                                       'ValueError("Observed '
                                                                                       'behavioral residual contains '
                                                                                       'non-finite values")\n'
                                                                                       '        if not '
                                                                                       'np.all(np.isfinite(y)):\n'
                                                                                       '            raise '
                                                                                       'ValueError("Neural residual '
                                                                                       'matrix contains non-finite '
                                                                                       'values")\n'
                                                                                       '        if '
                                                                                       'self.bootstrap_neural_base is '
                                                                                       'not None:\n'
                                                                                       '            base = '
                                                                                       'np.asarray(self.bootstrap_neural_base)\n'
                                                                                       '            if base.shape != '
                                                                                       'y.shape or not '
                                                                                       'np.all(np.isfinite(base)):\n'
                                                                                       '                raise '
                                                                                       'ValueError("Invalid bootstrap '
                                                                                       'neural base matrix")\n'
                                                                                       '            if '
                                                                                       'self.bootstrap_additional_control_key '
                                                                                       'is None:\n'
                                                                                       '                raise '
                                                                                       'ValueError("Dynamic bootstrap '
                                                                                       'neural residualization '
                                                                                       'requires a control key")\n'
                                                                                       '        if '
                                                                                       'self.nuisance_controls is not '
                                                                                       'None:\n'
                                                                                       '            controls = '
                                                                                       'np.asarray(self.nuisance_controls, '
                                                                                       'dtype=float)\n'
                                                                                       '            if controls.ndim '
                                                                                       '!= 2 or controls.shape[0] != '
                                                                                       'len(x):\n'
                                                                                       '                raise '
                                                                                       'ValueError("Invalid '
                                                                                       'nuisance-control matrix")\n'
                                                                                       '            if not '
                                                                                       'np.all(np.isfinite(controls)):\n'
                                                                                       '                raise '
                                                                                       'ValueError("Nuisance-control '
                                                                                       'matrix contains non-finite '
                                                                                       'values")\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '@dataclass\n'
                                                                                       'class DyadFamilyDataset:\n'
                                                                                       '    dataset: str\n'
                                                                                       '    study: str\n'
                                                                                       '    subject_i: np.ndarray\n'
                                                                                       '    subject_j: np.ndarray\n'
                                                                                       '    components: '
                                                                                       'list[TemporalComponent]\n'
                                                                                       '    dyad_slopes: np.ndarray\n'
                                                                                       '    n_windows: int\n'
                                                                                       '    metadata: dict[str, '
                                                                                       'object] = '
                                                                                       'field(default_factory=dict)\n'
                                                                                       '\n'
                                                                                       '    def validate(self) -> '
                                                                                       'None:\n'
                                                                                       '        n = '
                                                                                       'len(self.dyad_slopes)\n'
                                                                                       '        if len(self.subject_i) '
                                                                                       '!= n or len(self.subject_j) != '
                                                                                       'n:\n'
                                                                                       '            raise '
                                                                                       'ValueError(f"{self.dataset}: '
                                                                                       'subject/slopes length '
                                                                                       'mismatch")\n'
                                                                                       '        if not '
                                                                                       'np.all(np.isfinite(self.dyad_slopes)):\n'
                                                                                       '            raise '
                                                                                       'ValueError(f"{self.dataset}: '
                                                                                       'non-finite dyad slopes")\n'
                                                                                       '        for component in '
                                                                                       'self.components:\n'
                                                                                       '            '
                                                                                       'component.validate(n)\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '@dataclass\n'
                                                                                       'class MixedFit:\n'
                                                                                       '    name: str\n'
                                                                                       '    result: object\n'
                                                                                       '    fixed_names: list[str]\n'
                                                                                       '    fixed_design: np.ndarray\n'
                                                                                       '    subject_design: '
                                                                                       'sparse.csr_matrix\n'
                                                                                       '    pair_design: '
                                                                                       'sparse.csr_matrix | None\n'
                                                                                       '    dataset_design: '
                                                                                       'sparse.csr_matrix | None\n'
                                                                                       '    subject_variance: float\n'
                                                                                       '    pair_variance: float\n'
                                                                                       '    dataset_variance: float\n'
                                                                                       '    residual_variance: float\n'
                                                                                       '    n_repeated_pair_levels: '
                                                                                       'int\n'
                                                                                       '    converged: bool\n'
                                                                                       '    warnings_text: str\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '# GENERAL UTILITIES\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def load_python_module(path: '
                                                                                       'Path, module_name: str) -> '
                                                                                       'ModuleType:\n'
                                                                                       '    if not path.exists():\n'
                                                                                       '        raise '
                                                                                       'FileNotFoundError(\n'
                                                                                       '            f"Required source '
                                                                                       'script not found: {path}\\n"\n'
                                                                                       '            "Place this script '
                                                                                       'beside the two source '
                                                                                       'pipelines."\n'
                                                                                       '        )\n'
                                                                                       '    spec = '
                                                                                       'importlib.util.spec_from_file_location(module_name, '
                                                                                       'path)\n'
                                                                                       '    if spec is None or '
                                                                                       'spec.loader is None:\n'
                                                                                       '        raise '
                                                                                       'ImportError(f"Cannot import '
                                                                                       'source script: {path}")\n'
                                                                                       '    module = '
                                                                                       'importlib.util.module_from_spec(spec)\n'
                                                                                       '    sys.modules[module_name] = '
                                                                                       'module\n'
                                                                                       '    try:\n'
                                                                                       '        '
                                                                                       'spec.loader.exec_module(module)\n'
                                                                                       '    except Exception:\n'
                                                                                       '        '
                                                                                       'sys.modules.pop(module_name, '
                                                                                       'None)\n'
                                                                                       '        raise\n'
                                                                                       '    return module\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def save_json(obj, path: Path) '
                                                                                       '-> None:\n'
                                                                                       '    with open(path, "w", '
                                                                                       'encoding="utf-8") as file:\n'
                                                                                       '        json.dump(obj, file, '
                                                                                       'ensure_ascii=False, indent=2)\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def load_json(path: Path):\n'
                                                                                       '    with open(path, "r", '
                                                                                       'encoding="utf-8") as file:\n'
                                                                                       '        return '
                                                                                       'json.load(file)\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def print_section(title: str, '
                                                                                       'width: int = 118) -> None:\n'
                                                                                       '    print("\\n" + "=" * '
                                                                                       'width)\n'
                                                                                       '    print(title)\n'
                                                                                       '    print("=" * width)\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def format_elapsed(seconds: '
                                                                                       'float) -> str:\n'
                                                                                       '    seconds = max(0.0, '
                                                                                       'float(seconds))\n'
                                                                                       '    if seconds < 60:\n'
                                                                                       '        return '
                                                                                       'f"{seconds:5.1f}s"\n'
                                                                                       '    minutes, seconds = '
                                                                                       'divmod(seconds, 60)\n'
                                                                                       '    if minutes < 60:\n'
                                                                                       '        return '
                                                                                       'f"{int(minutes):02d}:{seconds:04.1f}"\n'
                                                                                       '    hours, minutes = '
                                                                                       'divmod(minutes, 60)\n'
                                                                                       '    return '
                                                                                       'f"{int(hours):02d}:{int(minutes):02d}:{seconds:04.1f}"\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def print_progress(label: str, '
                                                                                       'current: int, total: int, '
                                                                                       'start: float, extra="") -> '
                                                                                       'None:\n'
                                                                                       '    elapsed = time.time() - '
                                                                                       'start\n'
                                                                                       '    pct = 100.0 * current / '
                                                                                       'max(total, 1)\n'
                                                                                       '    eta = elapsed * (total - '
                                                                                       'current) / current if 0 < '
                                                                                       'current < total else 0.0\n'
                                                                                       '    message = (\n'
                                                                                       '        f"{label} | '
                                                                                       '{current:,}/{total:,} '
                                                                                       '({pct:6.2f}%) "\n'
                                                                                       '        f"| '
                                                                                       'elapsed={format_elapsed(elapsed)}"\n'
                                                                                       '    )\n'
                                                                                       '    if current < total:\n'
                                                                                       '        message += f" | '
                                                                                       'ETA={format_elapsed(eta)}"\n'
                                                                                       '    if extra:\n'
                                                                                       '        message += f" | '
                                                                                       '{extra}"\n'
                                                                                       '    print(f"{message:<180}", '
                                                                                       'end="\\n" if current == total '
                                                                                       'else "\\r", flush=True)\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def two_sided_p(null_values: '
                                                                                       'np.ndarray, observed: float) '
                                                                                       '-> float:\n'
                                                                                       '    values = '
                                                                                       'np.asarray(null_values, '
                                                                                       'dtype=float)\n'
                                                                                       '    values = '
                                                                                       'values[np.isfinite(values)]\n'
                                                                                       '    if len(values) == 0 or not '
                                                                                       'np.isfinite(observed):\n'
                                                                                       '        return np.nan\n'
                                                                                       '    return float((1 + '
                                                                                       'np.sum(np.abs(values) >= '
                                                                                       'abs(observed))) / (len(values) '
                                                                                       '+ 1))\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def bootstrap_sign_p(values: '
                                                                                       'np.ndarray) -> float:\n'
                                                                                       '    values = '
                                                                                       'np.asarray(values, '
                                                                                       'dtype=float)\n'
                                                                                       '    values = '
                                                                                       'values[np.isfinite(values)]\n'
                                                                                       '    if len(values) == 0:\n'
                                                                                       '        return np.nan\n'
                                                                                       '    p_le = (1 + np.sum(values '
                                                                                       '<= 0)) / (len(values) + 1)\n'
                                                                                       '    p_ge = (1 + np.sum(values '
                                                                                       '>= 0)) / (len(values) + 1)\n'
                                                                                       '    return float(min(1.0, 2.0 '
                                                                                       '* min(p_le, p_ge)))\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def quantile_interval(values: '
                                                                                       'np.ndarray, probs=(0.025, '
                                                                                       '0.975)) -> tuple[float, '
                                                                                       'float]:\n'
                                                                                       '    values = '
                                                                                       'np.asarray(values, '
                                                                                       'dtype=float)\n'
                                                                                       '    values = '
                                                                                       'values[np.isfinite(values)]\n'
                                                                                       '    if len(values) == 0:\n'
                                                                                       '        return np.nan, np.nan\n'
                                                                                       '    q = np.quantile(values, '
                                                                                       'probs)\n'
                                                                                       '    return float(q[0]), '
                                                                                       'float(q[1])\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def zscore_vector(values: '
                                                                                       'np.ndarray) -> np.ndarray:\n'
                                                                                       '    values = '
                                                                                       'np.asarray(values, '
                                                                                       'dtype=float)\n'
                                                                                       '    mean = np.nanmean(values)\n'
                                                                                       '    sd = np.nanstd(values, '
                                                                                       'ddof=1)\n'
                                                                                       '    if not np.isfinite(sd) or '
                                                                                       'sd <= 0:\n'
                                                                                       '        return '
                                                                                       'np.full_like(values, np.nan, '
                                                                                       'dtype=float)\n'
                                                                                       '    return (values - mean) / '
                                                                                       'sd\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'zscore_cache_columns(cache, '
                                                                                       'max_dyads: int | None = '
                                                                                       'None):\n'
                                                                                       '    """\n'
                                                                                       '    Convert a windows x dyads '
                                                                                       'Fisher-z cache into '
                                                                                       'within-dyad standardized\n'
                                                                                       '    trajectories.  Dyads with '
                                                                                       'any invalid window or zero '
                                                                                       'temporal variance are\n'
                                                                                       '    removed.  Study 2 neural '
                                                                                       'dyads are subsequently '
                                                                                       're-standardized on the\n'
                                                                                       '    dynamically retained and '
                                                                                       'concatenated session '
                                                                                       'timeline.\n'
                                                                                       '    """\n'
                                                                                       '    values = '
                                                                                       'np.asarray(cache["z"], '
                                                                                       'dtype=np.float32)\n'
                                                                                       '    n_pairs = values.shape[1]\n'
                                                                                       '\n'
                                                                                       '    if '
                                                                                       'cache["all_pairs_valid"]:\n'
                                                                                       '        complete = '
                                                                                       'np.ones(n_pairs, dtype=bool)\n'
                                                                                       '    else:\n'
                                                                                       '        valid = '
                                                                                       'np.asarray(cache["valid"], '
                                                                                       'dtype=bool)\n'
                                                                                       '        complete = '
                                                                                       'np.all(valid, axis=0)\n'
                                                                                       '\n'
                                                                                       '    mean = np.mean(values[:, '
                                                                                       'complete], axis=0, '
                                                                                       'dtype=np.float64)\n'
                                                                                       '    sd = np.std(values[:, '
                                                                                       'complete], axis=0, ddof=1, '
                                                                                       'dtype=np.float64)\n'
                                                                                       '    positive = np.isfinite(sd) '
                                                                                       '& (sd > 0)\n'
                                                                                       '    complete_indices = '
                                                                                       'np.flatnonzero(complete)[positive]\n'
                                                                                       '\n'
                                                                                       '    if max_dyads is not None:\n'
                                                                                       '        complete_indices = '
                                                                                       'complete_indices[: '
                                                                                       'int(max_dyads)]\n'
                                                                                       '\n'
                                                                                       '    selected = values[:, '
                                                                                       'complete_indices].astype(np.float64, '
                                                                                       'copy=False)\n'
                                                                                       '    selected_mean = '
                                                                                       'np.mean(selected, axis=0)\n'
                                                                                       '    selected_sd = '
                                                                                       'np.std(selected, axis=0, '
                                                                                       'ddof=1)\n'
                                                                                       '    standardized = ((selected '
                                                                                       '- selected_mean) / '
                                                                                       'selected_sd).astype(np.float32)\n'
                                                                                       '\n'
                                                                                       '    pair_i = '
                                                                                       'np.asarray(cache["pair_i"], '
                                                                                       'dtype=int)[complete_indices]\n'
                                                                                       '    pair_j = '
                                                                                       'np.asarray(cache["pair_j"], '
                                                                                       'dtype=int)[complete_indices]\n'
                                                                                       '    return standardized, '
                                                                                       'pair_i, pair_j, '
                                                                                       'complete_indices\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'residualize_vector_and_matrix(\n'
                                                                                       '    x: np.ndarray,\n'
                                                                                       '    y: np.ndarray,\n'
                                                                                       '    controls: np.ndarray,\n'
                                                                                       ') -> tuple[np.ndarray, '
                                                                                       'np.ndarray]:\n'
                                                                                       '    """FWL residualization '
                                                                                       'using one shared projection '
                                                                                       'for vector and matrix."""\n'
                                                                                       '    x = np.asarray(x, '
                                                                                       'dtype=float)\n'
                                                                                       '    y = np.asarray(y, '
                                                                                       'dtype=np.float32)\n'
                                                                                       '    controls = '
                                                                                       'np.asarray(controls, '
                                                                                       'dtype=float)\n'
                                                                                       '\n'
                                                                                       '    if x.ndim != 1 or y.ndim '
                                                                                       '!= 2 or controls.ndim != 2:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Invalid '
                                                                                       'residualization dimensions")\n'
                                                                                       '    if len(x) != y.shape[0] or '
                                                                                       'len(x) != controls.shape[0]:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Residualization '
                                                                                       'row mismatch")\n'
                                                                                       '    if not '
                                                                                       'np.all(np.isfinite(x)) or not '
                                                                                       'np.all(np.isfinite(y)):\n'
                                                                                       '        raise '
                                                                                       'ValueError("Residualization '
                                                                                       'inputs contain non-finite '
                                                                                       'values")\n'
                                                                                       '    if not '
                                                                                       'np.all(np.isfinite(controls)):\n'
                                                                                       '        raise '
                                                                                       'ValueError("Control matrix '
                                                                                       'contains non-finite values")\n'
                                                                                       '\n'
                                                                                       '    means = np.mean(controls, '
                                                                                       'axis=0)\n'
                                                                                       '    sds = np.std(controls, '
                                                                                       'axis=0, ddof=1)\n'
                                                                                       '    keep = np.isfinite(sds) & '
                                                                                       '(sds > 0)\n'
                                                                                       '    c = (controls[:, keep] - '
                                                                                       'means[keep]) / sds[keep]\n'
                                                                                       '    design = '
                                                                                       'np.column_stack([np.ones(len(x)), '
                                                                                       'c])\n'
                                                                                       '    q, _ = '
                                                                                       'np.linalg.qr(design, '
                                                                                       'mode="reduced")\n'
                                                                                       '\n'
                                                                                       '    x_res = x - q @ (q.T @ x)\n'
                                                                                       '    y_res = '
                                                                                       'y.astype(np.float64, '
                                                                                       'copy=False) - q @ (q.T @ y)\n'
                                                                                       '    return '
                                                                                       'x_res.astype(np.float64), '
                                                                                       'y_res.astype(np.float32)\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'residualize_bootstrap_vector_allow_missing(\n'
                                                                                       '    x: np.ndarray,\n'
                                                                                       '    controls: np.ndarray,\n'
                                                                                       ') -> tuple[np.ndarray, '
                                                                                       'np.ndarray]:\n'
                                                                                       '    """\n'
                                                                                       '    Residualize a bootstrap '
                                                                                       'behavioral trajectory on the '
                                                                                       'finite window subset.\n'
                                                                                       '\n'
                                                                                       '    Participant bootstrap '
                                                                                       'weights can occasionally leave '
                                                                                       'no positively weighted\n'
                                                                                       '    valid dyad at an isolated '
                                                                                       'window, producing NaN from '
                                                                                       'weighted_window_mean.\n'
                                                                                       '    Such a window contains no '
                                                                                       'estimable behavioral ISC for '
                                                                                       'that draw and is\n'
                                                                                       '    therefore excluded from '
                                                                                       "that draw's temporal slope.  "
                                                                                       'The returned vector is\n'
                                                                                       '    zero at excluded windows; '
                                                                                       'in the subsequent dot-product '
                                                                                       'slope calculation,\n'
                                                                                       '    this is exactly equivalent '
                                                                                       'to omitting those rows from '
                                                                                       'both the numerator\n'
                                                                                       '    and predictor sum of '
                                                                                       'squares.  No interpolation or '
                                                                                       'value imputation is used.\n'
                                                                                       '\n'
                                                                                       '    Returns\n'
                                                                                       '    -------\n'
                                                                                       '    residual : ndarray, shape '
                                                                                       '(n_windows,)\n'
                                                                                       '        Residualized predictor '
                                                                                       'with zero contribution at '
                                                                                       'non-estimable windows.\n'
                                                                                       '    valid : ndarray of bool\n'
                                                                                       '        Windows used in the '
                                                                                       'residualization for this '
                                                                                       'bootstrap draw.\n'
                                                                                       '    """\n'
                                                                                       '    x = np.asarray(x, '
                                                                                       'dtype=float)\n'
                                                                                       '    controls = '
                                                                                       'np.asarray(controls, '
                                                                                       'dtype=float)\n'
                                                                                       '    if x.ndim != 1 or '
                                                                                       'controls.ndim != 2:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Invalid bootstrap '
                                                                                       'residualization dimensions")\n'
                                                                                       '    if len(x) != '
                                                                                       'controls.shape[0]:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Bootstrap '
                                                                                       'residualization row '
                                                                                       'mismatch")\n'
                                                                                       '\n'
                                                                                       '    valid = np.isfinite(x) & '
                                                                                       'np.all(np.isfinite(controls), '
                                                                                       'axis=1)\n'
                                                                                       '    output = np.zeros(len(x), '
                                                                                       'dtype=np.float64)\n'
                                                                                       '\n'
                                                                                       '    # Require at least one '
                                                                                       'residual degree of freedom '
                                                                                       'beyond the nominal\n'
                                                                                       '    # intercept-plus-controls '
                                                                                       'design.  In normal runs almost '
                                                                                       'every window is\n'
                                                                                       '    # valid; this guard only '
                                                                                       'prevents pathological '
                                                                                       'bootstrap draws from failing.\n'
                                                                                       '    minimum_required = max(3, '
                                                                                       'controls.shape[1] + 2)\n'
                                                                                       '    if int(np.sum(valid)) < '
                                                                                       'minimum_required:\n'
                                                                                       '        return output, valid\n'
                                                                                       '\n'
                                                                                       '    residual, _ = '
                                                                                       'residualize_vector_and_matrix(\n'
                                                                                       '        x[valid],\n'
                                                                                       '        x[valid, '
                                                                                       'None].astype(np.float32),\n'
                                                                                       '        controls[valid],\n'
                                                                                       '    )\n'
                                                                                       '    output[valid] = residual\n'
                                                                                       '    return output, valid\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'bootstrap_validity_key(bootstrap_key: '
                                                                                       'str) -> str:\n'
                                                                                       '    """Companion memmap key '
                                                                                       'storing the finite-window mask '
                                                                                       'for a bootstrap predictor."""\n'
                                                                                       '    return '
                                                                                       'f"{bootstrap_key}::valid"\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'nuisance_orthonormal_basis(\n'
                                                                                       '    controls: np.ndarray,\n'
                                                                                       '    valid: np.ndarray | None = '
                                                                                       'None,\n'
                                                                                       ') -> tuple[np.ndarray, '
                                                                                       'np.ndarray]:\n'
                                                                                       '    """Return a nuisance-space '
                                                                                       'QR basis and the rows on which '
                                                                                       'it was built."""\n'
                                                                                       '    controls = '
                                                                                       'np.asarray(controls, '
                                                                                       'dtype=float)\n'
                                                                                       '    if controls.ndim != 2:\n'
                                                                                       '        raise '
                                                                                       'ValueError("controls must be '
                                                                                       'two-dimensional")\n'
                                                                                       '    n = controls.shape[0]\n'
                                                                                       '\n'
                                                                                       '    if valid is None:\n'
                                                                                       '        valid = np.ones(n, '
                                                                                       'dtype=bool)\n'
                                                                                       '    else:\n'
                                                                                       '        valid = '
                                                                                       'np.asarray(valid, dtype=bool)\n'
                                                                                       '        if valid.shape != '
                                                                                       '(n,):\n'
                                                                                       '            raise '
                                                                                       'ValueError("valid mask has the '
                                                                                       'wrong shape")\n'
                                                                                       '\n'
                                                                                       '    valid &= '
                                                                                       'np.all(np.isfinite(controls), '
                                                                                       'axis=1)\n'
                                                                                       '    minimum_required = max(3, '
                                                                                       'controls.shape[1] + 2)\n'
                                                                                       '    if int(valid.sum()) < '
                                                                                       'minimum_required:\n'
                                                                                       '        return '
                                                                                       'np.empty((int(valid.sum()), '
                                                                                       '0), dtype=float), valid\n'
                                                                                       '\n'
                                                                                       '    subset = controls[valid]\n'
                                                                                       '    means = np.mean(subset, '
                                                                                       'axis=0)\n'
                                                                                       '    sds = np.std(subset, '
                                                                                       'axis=0, ddof=1)\n'
                                                                                       '    keep = np.isfinite(sds) & '
                                                                                       '(sds > 0)\n'
                                                                                       '    standardized = (subset[:, '
                                                                                       'keep] - means[keep]) / '
                                                                                       'sds[keep]\n'
                                                                                       '    design = '
                                                                                       'np.column_stack([np.ones(len(subset)), '
                                                                                       'standardized])\n'
                                                                                       '    q, _ = '
                                                                                       'np.linalg.qr(design, '
                                                                                       'mode="reduced")\n'
                                                                                       '    return q, valid\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'residualize_draw_matrix_against_controls(\n'
                                                                                       '    draws: np.ndarray,\n'
                                                                                       '    controls: np.ndarray,\n'
                                                                                       '    valid_masks: np.ndarray | '
                                                                                       'None = None,\n'
                                                                                       ') -> tuple[np.ndarray, '
                                                                                       'np.ndarray]:\n'
                                                                                       '    """Re-residualize row-wise '
                                                                                       'permuted predictors at '
                                                                                       'destination time points.\n'
                                                                                       '\n'
                                                                                       '    Parameters\n'
                                                                                       '    ----------\n'
                                                                                       '    draws\n'
                                                                                       '        Draws x windows matrix '
                                                                                       'after temporal permutation.\n'
                                                                                       '    controls\n'
                                                                                       '        Windows x '
                                                                                       'nuisance-covariates matrix for '
                                                                                       'the destination timeline.\n'
                                                                                       '    valid_masks\n'
                                                                                       '        Draws x windows mask. '
                                                                                       'Invalid bootstrap windows '
                                                                                       'remain zero and are\n'
                                                                                       '        omitted from both the '
                                                                                       'nuisance projection and the '
                                                                                       'temporal slope.\n'
                                                                                       '\n'
                                                                                       '    Returns\n'
                                                                                       '    -------\n'
                                                                                       '    residualized, valid_draw\n'
                                                                                       '        Residualized draws and '
                                                                                       'a draw-level indicator that '
                                                                                       'the projected\n'
                                                                                       '        predictor has positive '
                                                                                       'residual sum of squares.\n'
                                                                                       '    """\n'
                                                                                       '    draws = np.asarray(draws, '
                                                                                       'dtype=float)\n'
                                                                                       '    controls = '
                                                                                       'np.asarray(controls, '
                                                                                       'dtype=float)\n'
                                                                                       '    if draws.ndim != 2 or '
                                                                                       'controls.ndim != 2:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Invalid '
                                                                                       'draw/control dimensions")\n'
                                                                                       '    if draws.shape[1] != '
                                                                                       'controls.shape[0]:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Draw/control '
                                                                                       'time-length mismatch")\n'
                                                                                       '\n'
                                                                                       '    if valid_masks is None:\n'
                                                                                       '        valid_masks = '
                                                                                       'np.isfinite(draws)\n'
                                                                                       '    else:\n'
                                                                                       '        valid_masks = '
                                                                                       'np.asarray(valid_masks, '
                                                                                       'dtype=bool) & '
                                                                                       'np.isfinite(draws)\n'
                                                                                       '        if valid_masks.shape '
                                                                                       '!= draws.shape:\n'
                                                                                       '            raise '
                                                                                       'ValueError("valid_masks shape '
                                                                                       'mismatch")\n'
                                                                                       '\n'
                                                                                       '    output = '
                                                                                       'np.zeros_like(draws, '
                                                                                       'dtype=float)\n'
                                                                                       '    draw_valid = '
                                                                                       'np.zeros(draws.shape[0], '
                                                                                       'dtype=bool)\n'
                                                                                       '\n'
                                                                                       '    complete = '
                                                                                       'np.all(valid_masks, axis=1)\n'
                                                                                       '    if np.any(complete):\n'
                                                                                       '        q, basis_valid = '
                                                                                       'nuisance_orthonormal_basis(controls)\n'
                                                                                       '        if q.shape[1] > 0 and '
                                                                                       'np.all(basis_valid):\n'
                                                                                       '            values = '
                                                                                       'draws[complete]\n'
                                                                                       '            residuals = values '
                                                                                       '- (values @ q) @ q.T\n'
                                                                                       '            output[complete] = '
                                                                                       'residuals\n'
                                                                                       '            denom = '
                                                                                       'np.sum(residuals * residuals, '
                                                                                       'axis=1)\n'
                                                                                       '            '
                                                                                       'draw_valid[complete] = '
                                                                                       'np.isfinite(denom) & (denom > '
                                                                                       '0)\n'
                                                                                       '\n'
                                                                                       '    partial_rows = '
                                                                                       'np.flatnonzero(~complete)\n'
                                                                                       '    for row in partial_rows:\n'
                                                                                       '        q, valid = '
                                                                                       'nuisance_orthonormal_basis(controls, '
                                                                                       'valid_masks[row])\n'
                                                                                       '        if q.shape[1] == 0:\n'
                                                                                       '            continue\n'
                                                                                       '        values = draws[row, '
                                                                                       'valid]\n'
                                                                                       '        residuals = values - q '
                                                                                       '@ (q.T @ values)\n'
                                                                                       '        output[row, valid] = '
                                                                                       'residuals\n'
                                                                                       '        denom = '
                                                                                       'float(residuals @ residuals)\n'
                                                                                       '        draw_valid[row] = '
                                                                                       'np.isfinite(denom) and denom > '
                                                                                       '0\n'
                                                                                       '\n'
                                                                                       '    return output, draw_valid\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'residualize_draws_against_dynamic_control(\n'
                                                                                       '    draws: np.ndarray,\n'
                                                                                       '    controls: np.ndarray,\n'
                                                                                       '    valid_masks: np.ndarray,\n'
                                                                                       ') -> tuple[np.ndarray, '
                                                                                       'np.ndarray]:\n'
                                                                                       '    """Residualize each draw '
                                                                                       'against its own '
                                                                                       'already-nuisance-residualized '
                                                                                       'control."""\n'
                                                                                       '    draws = np.asarray(draws, '
                                                                                       'dtype=float)\n'
                                                                                       '    controls = '
                                                                                       'np.asarray(controls, '
                                                                                       'dtype=float)\n'
                                                                                       '    valid_masks = '
                                                                                       'np.asarray(valid_masks, '
                                                                                       'dtype=bool)\n'
                                                                                       '    if draws.shape != '
                                                                                       'controls.shape or draws.shape '
                                                                                       '!= valid_masks.shape:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Dynamic-control '
                                                                                       'dimensions do not match")\n'
                                                                                       '\n'
                                                                                       '    x = np.where(valid_masks, '
                                                                                       'draws, 0.0)\n'
                                                                                       '    c = np.where(valid_masks, '
                                                                                       'controls, 0.0)\n'
                                                                                       '    denominators = np.sum(c * '
                                                                                       'c, axis=1)\n'
                                                                                       '    numerators = np.sum(x * c, '
                                                                                       'axis=1)\n'
                                                                                       '    valid = '
                                                                                       'np.isfinite(denominators) & '
                                                                                       '(denominators > 0)\n'
                                                                                       '    output = np.zeros_like(x)\n'
                                                                                       '    output[valid] = (\n'
                                                                                       '        x[valid]\n'
                                                                                       '        - c[valid] * '
                                                                                       '(numerators[valid] / '
                                                                                       'denominators[valid])[:, None]\n'
                                                                                       '    )\n'
                                                                                       '    x_denom = np.sum(output * '
                                                                                       'output, axis=1)\n'
                                                                                       '    valid &= '
                                                                                       'np.isfinite(x_denom) & '
                                                                                       '(x_denom > 0)\n'
                                                                                       '    return output, valid\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'neural_bootstrap_key(dataset: '
                                                                                       'str) -> str:\n'
                                                                                       '    """Key used for the '
                                                                                       'dataset-specific neural '
                                                                                       'participant count matrix."""\n'
                                                                                       '    return '
                                                                                       'f"neural::{dataset}"\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'dyad_bootstrap_multipliers(\n'
                                                                                       '    subject_weight_rows: '
                                                                                       'np.ndarray,\n'
                                                                                       '    pair_i: np.ndarray,\n'
                                                                                       '    pair_j: np.ndarray,\n'
                                                                                       ') -> tuple[np.ndarray, '
                                                                                       'np.ndarray]:\n'
                                                                                       '    """Convert subject-level '
                                                                                       'bootstrap counts into '
                                                                                       'normalized dyad multipliers.\n'
                                                                                       '\n'
                                                                                       '    A participant bootstrap '
                                                                                       'draw with counts c_i induces '
                                                                                       'dyad multiplicity\n'
                                                                                       '    c_i * c_j for every '
                                                                                       'distinct observed pair. The '
                                                                                       'multipliers are normalized\n'
                                                                                       '    within the selected dyad '
                                                                                       'set so the fixed observed GLS '
                                                                                       'weight scale is\n'
                                                                                       '    preserved while still '
                                                                                       'up/down-weighting the neural '
                                                                                       'dyad residuals.\n'
                                                                                       '    """\n'
                                                                                       '    rows = '
                                                                                       'np.asarray(subject_weight_rows, '
                                                                                       'dtype=np.float32)\n'
                                                                                       '    if rows.ndim == 1:\n'
                                                                                       '        rows = rows[None, :]\n'
                                                                                       '    pair_i = '
                                                                                       'np.asarray(pair_i, dtype=int)\n'
                                                                                       '    pair_j = '
                                                                                       'np.asarray(pair_j, dtype=int)\n'
                                                                                       '    if pair_i.shape != '
                                                                                       'pair_j.shape:\n'
                                                                                       '        raise '
                                                                                       'ValueError("pair_i and pair_j '
                                                                                       'must have matching shape")\n'
                                                                                       '    if len(pair_i) == 0:\n'
                                                                                       '        raise ValueError("At '
                                                                                       'least one selected neural dyad '
                                                                                       'is required")\n'
                                                                                       '    if np.max(pair_i) >= '
                                                                                       'rows.shape[1] or '
                                                                                       'np.max(pair_j) >= '
                                                                                       'rows.shape[1]:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Neural bootstrap '
                                                                                       'count matrix is too narrow for '
                                                                                       'dyad indices")\n'
                                                                                       '\n'
                                                                                       '    dyad_weights = rows[:, '
                                                                                       'pair_i] * rows[:, pair_j]\n'
                                                                                       '    mean_weight = '
                                                                                       'np.mean(dyad_weights, axis=1)\n'
                                                                                       '    valid = '
                                                                                       'np.isfinite(mean_weight) & '
                                                                                       '(mean_weight > 0)\n'
                                                                                       '    multipliers = '
                                                                                       'np.zeros_like(dyad_weights, '
                                                                                       'dtype=np.float32)\n'
                                                                                       '    multipliers[valid] = '
                                                                                       'dyad_weights[valid] / '
                                                                                       'mean_weight[valid, None]\n'
                                                                                       '    return multipliers, valid\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'neural_bootstrap_aggregates(\n'
                                                                                       '    neural_residuals: '
                                                                                       'np.ndarray,\n'
                                                                                       '    weight_slice: np.ndarray,\n'
                                                                                       '    dyad_multipliers: '
                                                                                       'np.ndarray,\n'
                                                                                       ') -> np.ndarray:\n'
                                                                                       '    """Apply draw-specific '
                                                                                       'dyad multipliers before fixed '
                                                                                       'GLS aggregation."""\n'
                                                                                       '    y = '
                                                                                       'np.asarray(neural_residuals, '
                                                                                       'dtype=np.float32)\n'
                                                                                       '    weights = '
                                                                                       'np.asarray(weight_slice, '
                                                                                       'dtype=np.float32)\n'
                                                                                       '    multipliers = '
                                                                                       'np.asarray(dyad_multipliers, '
                                                                                       'dtype=np.float32)\n'
                                                                                       '    if weights.ndim == 1:\n'
                                                                                       '        weights = weights[:, '
                                                                                       'None]\n'
                                                                                       '    if y.ndim != 2 or '
                                                                                       'weights.ndim != 2 or '
                                                                                       'multipliers.ndim != 2:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Invalid neural '
                                                                                       'bootstrap aggregation '
                                                                                       'dimensions")\n'
                                                                                       '    if y.shape[1] != '
                                                                                       'weights.shape[0] or y.shape[1] '
                                                                                       '!= multipliers.shape[1]:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Neural residual, '
                                                                                       'GLS weight, and multiplier '
                                                                                       'dyad counts differ")\n'
                                                                                       '    effective_weights = '
                                                                                       'multipliers[:, :, None] * '
                                                                                       'weights[None, :, :]\n'
                                                                                       '    return '
                                                                                       'np.einsum("td,ndc->ntc", y, '
                                                                                       'effective_weights, '
                                                                                       'optimize=True)\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'build_neural_bootstrap_plans(\n'
                                                                                       '    S1,\n'
                                                                                       '    S2,\n'
                                                                                       '    s1_bootstrap_plan: '
                                                                                       'dict[str, np.ndarray],\n'
                                                                                       '    s2_bootstrap_plan: '
                                                                                       'np.ndarray,\n'
                                                                                       '    s1_prepared=None,\n'
                                                                                       '    s2_prepared=None,\n'
                                                                                       ') -> dict[str, np.ndarray]:\n'
                                                                                       '    """Map dependency-aware '
                                                                                       'source bootstrap plans to '
                                                                                       'neural datasets."""\n'
                                                                                       '    if s1_prepared is None or '
                                                                                       's2_prepared is None:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Prepared Study 1 '
                                                                                       'and Study 2 data are '
                                                                                       'required.")\n'
                                                                                       '\n'
                                                                                       '    def map_rows(master_ids, '
                                                                                       'rows, target_ids):\n'
                                                                                       '        master_ids = '
                                                                                       'np.asarray(master_ids, '
                                                                                       'dtype=str)\n'
                                                                                       '        target_ids = '
                                                                                       'np.asarray(target_ids, '
                                                                                       'dtype=str)\n'
                                                                                       '        lookup = {sid: i for '
                                                                                       'i, sid in '
                                                                                       'enumerate(master_ids)}\n'
                                                                                       '        missing = [sid for sid '
                                                                                       'in target_ids if sid not in '
                                                                                       'lookup]\n'
                                                                                       '        if missing:\n'
                                                                                       '            raise KeyError(\n'
                                                                                       '                '
                                                                                       'f"{len(missing)} target '
                                                                                       'participant IDs are absent '
                                                                                       'from the master mapping; "\n'
                                                                                       '                "IDs '
                                                                                       'withheld."\n'
                                                                                       '            )\n'
                                                                                       '        index = '
                                                                                       'np.asarray([lookup[sid] for '
                                                                                       'sid in target_ids], '
                                                                                       'dtype=int)\n'
                                                                                       '        return '
                                                                                       'np.asarray(rows)[:, index]\n'
                                                                                       '\n'
                                                                                       '    plans = {\n'
                                                                                       '        '
                                                                                       'neural_bootstrap_key(dataset): '
                                                                                       'np.asarray(\n'
                                                                                       '            '
                                                                                       's1_bootstrap_plan["neural_by_dataset"][dataset]\n'
                                                                                       '        )\n'
                                                                                       '        for dataset in '
                                                                                       'S1.MOVIES\n'
                                                                                       '    }\n'
                                                                                       '    for dataset in '
                                                                                       'S2.SESSIONS:\n'
                                                                                       '        target_ids = '
                                                                                       's2_prepared["neural_caches"][dataset]["subject_ids"]\n'
                                                                                       '        '
                                                                                       'plans[neural_bootstrap_key(dataset)] '
                                                                                       '= map_rows(\n'
                                                                                       '            '
                                                                                       's2_prepared["common_ids"], '
                                                                                       's2_bootstrap_plan, target_ids\n'
                                                                                       '        )\n'
                                                                                       '    for key, plan in '
                                                                                       'plans.items():\n'
                                                                                       '        if len(plan) < '
                                                                                       'N_RESAMPLES:\n'
                                                                                       '            raise '
                                                                                       'ValueError(f"{key}: neural '
                                                                                       'bootstrap plan is shorter than '
                                                                                       'N_RESAMPLES")\n'
                                                                                       '    return plans\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'estimate_acf_length_gap_aware(\n'
                                                                                       '    values: np.ndarray,\n'
                                                                                       '    original_windows: '
                                                                                       'np.ndarray,\n'
                                                                                       '    threshold: float = '
                                                                                       'ACF_THRESHOLD,\n'
                                                                                       ') -> int:\n'
                                                                                       '    """Estimate residual ACF '
                                                                                       'length using only pairs at the '
                                                                                       'true original lag.\n'
                                                                                       '\n'
                                                                                       '    With no deleted windows, '
                                                                                       'this is identical to '
                                                                                       '``estimate_acf_length``.\n'
                                                                                       '    With gaps, a pair '
                                                                                       'contributes at lag k only when '
                                                                                       'its original window\n'
                                                                                       '    indices differ by exactly '
                                                                                       'k; compressed adjacency is '
                                                                                       'never treated as a\n'
                                                                                       '    one-window lag.\n'
                                                                                       '    """\n'
                                                                                       '    x = np.asarray(values, '
                                                                                       'dtype=float)\n'
                                                                                       '    windows = '
                                                                                       'np.asarray(original_windows, '
                                                                                       'dtype=int)\n'
                                                                                       '    if x.ndim != 1 or '
                                                                                       'windows.ndim != 1 or len(x) != '
                                                                                       'len(windows):\n'
                                                                                       '        raise '
                                                                                       'ValueError("values and '
                                                                                       'original_windows must be '
                                                                                       'matched vectors")\n'
                                                                                       '\n'
                                                                                       '    finite = np.isfinite(x)\n'
                                                                                       '    x = x[finite]\n'
                                                                                       '    windows = windows[finite]\n'
                                                                                       '    if len(x) < 4:\n'
                                                                                       '        return 1\n'
                                                                                       '    if np.any(np.diff(windows) '
                                                                                       '<= 0):\n'
                                                                                       '        raise '
                                                                                       'ValueError("original_windows '
                                                                                       'must be strictly increasing")\n'
                                                                                       '\n'
                                                                                       '    x = x - np.mean(x)\n'
                                                                                       '    denominator = float(x @ '
                                                                                       'x)\n'
                                                                                       '    if denominator <= 0:\n'
                                                                                       '        return 1\n'
                                                                                       '\n'
                                                                                       '    lookup = {int(window): '
                                                                                       'index for index, window in '
                                                                                       'enumerate(windows)}\n'
                                                                                       '    max_lag = max(1, '
                                                                                       'min(len(x) // 2, 100))\n'
                                                                                       '    last_tested = 1\n'
                                                                                       '    for lag in range(1, '
                                                                                       'max_lag + 1):\n'
                                                                                       '        left = []\n'
                                                                                       '        right = []\n'
                                                                                       '        for index, window in '
                                                                                       'enumerate(windows):\n'
                                                                                       '            partner = '
                                                                                       'lookup.get(int(window + lag))\n'
                                                                                       '            if partner is not '
                                                                                       'None:\n'
                                                                                       '                '
                                                                                       'left.append(index)\n'
                                                                                       '                '
                                                                                       'right.append(partner)\n'
                                                                                       '        if not left:\n'
                                                                                       '            continue\n'
                                                                                       '        last_tested = lag\n'
                                                                                       '        acf = float(\n'
                                                                                       '            x[np.asarray(left, '
                                                                                       'dtype=int)] @ '
                                                                                       'x[np.asarray(right, '
                                                                                       'dtype=int)]\n'
                                                                                       '            / denominator\n'
                                                                                       '        )\n'
                                                                                       '        if abs(acf) < '
                                                                                       'threshold:\n'
                                                                                       '            return lag\n'
                                                                                       '    return int(last_tested)\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def count_segment_blocks(\n'
                                                                                       '    segments: '
                                                                                       'list[np.ndarray],\n'
                                                                                       '    block_length: int,\n'
                                                                                       ') -> int:\n'
                                                                                       '    return '
                                                                                       'int(sum(math.ceil(len(segment) '
                                                                                       '/ block_length) for segment in '
                                                                                       'segments))\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'dyad_slopes_from_components(components: '
                                                                                       'Iterable[TemporalComponent]) '
                                                                                       '-> np.ndarray:\n'
                                                                                       '    output = None\n'
                                                                                       '    for component in '
                                                                                       'components:\n'
                                                                                       '        x = '
                                                                                       'np.asarray(component.x_observed, '
                                                                                       'dtype=float)\n'
                                                                                       '        y = '
                                                                                       'np.asarray(component.neural_residuals, '
                                                                                       'dtype=np.float32)\n'
                                                                                       '        denominator = float(x '
                                                                                       '@ x)\n'
                                                                                       '        if not '
                                                                                       'np.isfinite(denominator) or '
                                                                                       'denominator <= 0:\n'
                                                                                       '            raise '
                                                                                       'ValueError("Non-positive '
                                                                                       'predictor residual sum of '
                                                                                       'squares")\n'
                                                                                       '        slopes = (y.T @ x / '
                                                                                       'denominator).astype(np.float64)\n'
                                                                                       '        signed = '
                                                                                       'float(component.sign) * '
                                                                                       'slopes\n'
                                                                                       '        output = signed if '
                                                                                       'output is None else output + '
                                                                                       'signed\n'
                                                                                       '    if output is None:\n'
                                                                                       '        raise ValueError("At '
                                                                                       'least one temporal component '
                                                                                       'is required")\n'
                                                                                       '    return output\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'estimate_acf_length(values: '
                                                                                       'np.ndarray, threshold: float = '
                                                                                       'ACF_THRESHOLD) -> int:\n'
                                                                                       '    """First positive lag at '
                                                                                       'which absolute ACF falls below '
                                                                                       'the threshold."""\n'
                                                                                       '    x = np.asarray(values, '
                                                                                       'dtype=float)\n'
                                                                                       '    x = x[np.isfinite(x)]\n'
                                                                                       '    if len(x) < 4:\n'
                                                                                       '        return 1\n'
                                                                                       '    x = x - np.mean(x)\n'
                                                                                       '    denominator = float(x @ '
                                                                                       'x)\n'
                                                                                       '    if denominator <= 0:\n'
                                                                                       '        return 1\n'
                                                                                       '    max_lag = max(1, '
                                                                                       'min(len(x) // 2, 100))\n'
                                                                                       '    for lag in range(1, '
                                                                                       'max_lag + 1):\n'
                                                                                       '        acf = float(x[:-lag] @ '
                                                                                       'x[lag:] / denominator)\n'
                                                                                       '        if abs(acf) < '
                                                                                       'threshold:\n'
                                                                                       '            return lag\n'
                                                                                       '    return max_lag\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'contiguous_position_segments(window_numbers: '
                                                                                       'np.ndarray) -> '
                                                                                       'list[np.ndarray]:\n'
                                                                                       '    windows = '
                                                                                       'np.asarray(window_numbers, '
                                                                                       'dtype=int)\n'
                                                                                       '    if windows.ndim != 1 or '
                                                                                       'len(windows) == 0:\n'
                                                                                       '        raise '
                                                                                       'ValueError("Non-empty '
                                                                                       'one-dimensional windows '
                                                                                       'required")\n'
                                                                                       '    if np.any(np.diff(windows) '
                                                                                       '<= 0):\n'
                                                                                       '        raise '
                                                                                       'ValueError("Window numbers '
                                                                                       'must be strictly increasing")\n'
                                                                                       '    split_after = '
                                                                                       'np.flatnonzero(np.diff(windows) '
                                                                                       '!= 1) + 1\n'
                                                                                       '    return [x for x in '
                                                                                       'np.split(np.arange(len(windows), '
                                                                                       'dtype=int), split_after) if '
                                                                                       'len(x)]\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def random_block_indices(n: '
                                                                                       'int, block_length: int, rng: '
                                                                                       'np.random.Generator) -> '
                                                                                       'np.ndarray:\n'
                                                                                       '    blocks = [\n'
                                                                                       '        np.arange(start, '
                                                                                       'min(start + block_length, n), '
                                                                                       'dtype=np.int32)\n'
                                                                                       '        for start in range(0, '
                                                                                       'n, block_length)\n'
                                                                                       '    ]\n'
                                                                                       '    order = '
                                                                                       'np.arange(len(blocks))\n'
                                                                                       '    if len(blocks) > 1:\n'
                                                                                       '        while '
                                                                                       'np.array_equal(order, '
                                                                                       'np.arange(len(blocks))):\n'
                                                                                       '            order = '
                                                                                       'rng.permutation(len(blocks))\n'
                                                                                       '    return '
                                                                                       'np.concatenate([blocks[int(index)] '
                                                                                       'for index in order])\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'generate_block_index_plan(\n'
                                                                                       '    n: int,\n'
                                                                                       '    block_length: int,\n'
                                                                                       '    n_draws: int,\n'
                                                                                       '    seed: int,\n'
                                                                                       '    segments: list[np.ndarray] '
                                                                                       '| None = None,\n'
                                                                                       ') -> np.ndarray:\n'
                                                                                       '    rng = '
                                                                                       'np.random.default_rng(seed)\n'
                                                                                       '    output = '
                                                                                       'np.empty((n_draws, n), '
                                                                                       'dtype=np.int32)\n'
                                                                                       '    if segments is None:\n'
                                                                                       '        segments = '
                                                                                       '[np.arange(n, dtype=int)]\n'
                                                                                       '    for draw in '
                                                                                       'range(n_draws):\n'
                                                                                       '        pieces = []\n'
                                                                                       '        for positions in '
                                                                                       'segments:\n'
                                                                                       '            local = '
                                                                                       'random_block_indices(len(positions), '
                                                                                       'block_length, rng)\n'
                                                                                       '            '
                                                                                       'pieces.append(np.asarray(positions, '
                                                                                       'dtype=np.int32)[local])\n'
                                                                                       '        output[draw] = '
                                                                                       'np.concatenate(pieces)\n'
                                                                                       '    return output\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'cache_window_validity_summary(cache) '
                                                                                       '-> tuple[np.ndarray, '
                                                                                       'np.ndarray]:\n'
                                                                                       '    """Return valid '
                                                                                       'distinct-pair and '
                                                                                       'valid-participant counts for '
                                                                                       'each window."""\n'
                                                                                       '    n_windows = '
                                                                                       'int(cache["n_windows"])\n'
                                                                                       '    n_subjects = '
                                                                                       'len(cache["subject_ids"])\n'
                                                                                       '    pair_i = '
                                                                                       'np.asarray(cache["pair_i"], '
                                                                                       'dtype=int)\n'
                                                                                       '    pair_j = '
                                                                                       'np.asarray(cache["pair_j"], '
                                                                                       'dtype=int)\n'
                                                                                       '\n'
                                                                                       '    if '
                                                                                       'cache["all_pairs_valid"]:\n'
                                                                                       '        pair_counts = '
                                                                                       'np.full(n_windows, '
                                                                                       'len(pair_i), dtype=int)\n'
                                                                                       '        subject_counts = '
                                                                                       'np.full(n_windows, n_subjects, '
                                                                                       'dtype=int)\n'
                                                                                       '        return pair_counts, '
                                                                                       'subject_counts\n'
                                                                                       '\n'
                                                                                       '    valid = '
                                                                                       'np.asarray(cache["valid"], '
                                                                                       'dtype=bool)\n'
                                                                                       '    pair_counts = '
                                                                                       'valid.sum(axis=1).astype(int)\n'
                                                                                       '    subject_counts = '
                                                                                       'np.zeros(n_windows, '
                                                                                       'dtype=int)\n'
                                                                                       '    for row in '
                                                                                       'range(n_windows):\n'
                                                                                       '        valid_pairs = '
                                                                                       'np.flatnonzero(valid[row])\n'
                                                                                       '        if len(valid_pairs) == '
                                                                                       '0:\n'
                                                                                       '            continue\n'
                                                                                       '        members = '
                                                                                       'np.concatenate([pair_i[valid_pairs], '
                                                                                       'pair_j[valid_pairs]])\n'
                                                                                       '        subject_counts[row] = '
                                                                                       'int(np.unique(members).size)\n'
                                                                                       '    return pair_counts, '
                                                                                       'subject_counts\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'finite_group_isc_column(subset: '
                                                                                       'pd.DataFrame, affect: str) -> '
                                                                                       'np.ndarray:\n'
                                                                                       '    """Finite mask for the '
                                                                                       'observed group-level '
                                                                                       'behavioral ISC column."""\n'
                                                                                       '    for column in '
                                                                                       '(f"raw_z_{affect}_ISC", '
                                                                                       'f"z_{affect}_ISC"):\n'
                                                                                       '        if column in '
                                                                                       'subset.columns:\n'
                                                                                       '            return '
                                                                                       'np.isfinite(subset[column].to_numpy(float))\n'
                                                                                       '    raise KeyError(f"No '
                                                                                       'observed ISC column found for '
                                                                                       'affect={affect!r}")\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'restandardize_retained_isc_columns(\n'
                                                                                       '    frame: pd.DataFrame,\n'
                                                                                       '    columns: Iterable[str],\n'
                                                                                       ') -> pd.DataFrame:\n'
                                                                                       '    """Re-standardize ISC '
                                                                                       'columns on the retained '
                                                                                       'compressed timeline.\n'
                                                                                       '\n'
                                                                                       '    If a raw counterpart such '
                                                                                       'as raw_z_valence_ISC exists, '
                                                                                       'it is used as the\n'
                                                                                       '    source. Otherwise the '
                                                                                       'current standardized column is '
                                                                                       're-standardized after\n'
                                                                                       '    window deletion.\n'
                                                                                       '    """\n'
                                                                                       '    for column in columns:\n'
                                                                                       '        raw_column = '
                                                                                       'f"raw_{column}"\n'
                                                                                       '        if raw_column in '
                                                                                       'frame.columns:\n'
                                                                                       '            source = '
                                                                                       'raw_column\n'
                                                                                       '        elif column in '
                                                                                       'frame.columns:\n'
                                                                                       '            source = column\n'
                                                                                       '        else:\n'
                                                                                       '            continue\n'
                                                                                       '        frame[column] = '
                                                                                       'zscore_vector(frame[source].to_numpy(float))\n'
                                                                                       '    return frame\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '# CROSSED-RANDOM-EFFECTS MIXED '
                                                                                       'MODELS\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '# MIXED-MODEL '
                                                                                       'DEPENDENCE DESIGN\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '# The public repository does '
                                                                                       'not contain participant '
                                                                                       'identities, repeated-dyad\n'
                                                                                       '# identities, or the '
                                                                                       'study-specific dataset '
                                                                                       'membership pattern. Before '
                                                                                       'running\n'
                                                                                       '# Stage 2, provide a local CSV '
                                                                                       'through '
                                                                                       'VISC_MIXED_MODEL_DESIGN_PATH.\n'
                                                                                       '# Required columns (one row '
                                                                                       'per Stage-1 dyad '
                                                                                       'coefficient):\n'
                                                                                       '#   dataset_key, '
                                                                                       'local_subject_i, '
                                                                                       'local_subject_j,\n'
                                                                                       '#   crossed_participant_i, '
                                                                                       'crossed_participant_j,\n'
                                                                                       '#   repeated_dyad_id, '
                                                                                       'dataset_fixed_level\n'
                                                                                       '# Values may be arbitrary '
                                                                                       'pseudonyms. The file should '
                                                                                       'remain local.\n'
                                                                                       'MIXED_MODEL_DESIGN_PATH_ENV = '
                                                                                       '"VISC_MIXED_MODEL_DESIGN_PATH"\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def _canonical_pair(a, b):\n'
                                                                                       '    a, b = str(a), str(b)\n'
                                                                                       '    return '
                                                                                       '"||".join(sorted((a, b)))\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'load_mixed_model_design() '
                                                                                       '-> pd.DataFrame:\n'
                                                                                       '    path_value = '
                                                                                       'os.environ.get(MIXED_MODEL_DESIGN_PATH_ENV, '
                                                                                       '"").strip()\n'
                                                                                       '    if not path_value:\n'
                                                                                       '        raise '
                                                                                       'FileNotFoundError(\n'
                                                                                       '            "Stage-2 '
                                                                                       'mixed-effects inference '
                                                                                       'requires a local design CSV. '
                                                                                       '"\n'
                                                                                       '            f"Set '
                                                                                       '{MIXED_MODEL_DESIGN_PATH_ENV}. '
                                                                                       'The public repository '
                                                                                       'intentionally "\n'
                                                                                       '            "does not contain '
                                                                                       'participant, repeated-dyad, or '
                                                                                       'dataset-membership IDs."\n'
                                                                                       '        )\n'
                                                                                       '    path = '
                                                                                       'Path(path_value).expanduser()\n'
                                                                                       '    if not path.exists():\n'
                                                                                       '        raise '
                                                                                       'FileNotFoundError(\n'
                                                                                       '            "Local '
                                                                                       'mixed-model design CSV was not '
                                                                                       'found. Keep it outside the '
                                                                                       'public "\n'
                                                                                       '            "repository or '
                                                                                       'list it in .gitignore."\n'
                                                                                       '        )\n'
                                                                                       '    design = pd.read_csv(path, '
                                                                                       'dtype=str).fillna("")\n'
                                                                                       '    required = [\n'
                                                                                       '        "dataset_key", '
                                                                                       '"local_subject_i", '
                                                                                       '"local_subject_j",\n'
                                                                                       '        '
                                                                                       '"crossed_participant_i", '
                                                                                       '"crossed_participant_j",\n'
                                                                                       '        "repeated_dyad_id", '
                                                                                       '"dataset_fixed_level",\n'
                                                                                       '    ]\n'
                                                                                       '    missing = [c for c in '
                                                                                       'required if c not in '
                                                                                       'design.columns]\n'
                                                                                       '    if missing:\n'
                                                                                       '        raise '
                                                                                       'ValueError(f"Local '
                                                                                       'mixed-model design is missing '
                                                                                       'columns: {missing}")\n'
                                                                                       '    if '
                                                                                       'any((design[c].astype(str).str.strip() '
                                                                                       '== "").any() for c in '
                                                                                       'required):\n'
                                                                                       '        raise '
                                                                                       'ValueError("Local '
                                                                                       'mixed-model design contains '
                                                                                       'blank required values.")\n'
                                                                                       '    design = design.copy()\n'
                                                                                       '    design["_local_pair_key"] '
                                                                                       '= [\n'
                                                                                       '        _canonical_pair(a, b)\n'
                                                                                       '        for a, b in '
                                                                                       'zip(design["local_subject_i"], '
                                                                                       'design["local_subject_j"])\n'
                                                                                       '    ]\n'
                                                                                       '    keys = '
                                                                                       'design[["dataset_key", '
                                                                                       '"_local_pair_key"]]\n'
                                                                                       '    if '
                                                                                       'keys.duplicated().any():\n'
                                                                                       '        raise ValueError(\n'
                                                                                       '            "Local '
                                                                                       'mixed-model design must '
                                                                                       'contain exactly one row per '
                                                                                       'dataset × dyad."\n'
                                                                                       '        )\n'
                                                                                       '    # Each internal dataset '
                                                                                       'key must map to exactly one '
                                                                                       'fixed-effect level.\n'
                                                                                       '    n_levels = '
                                                                                       'design.groupby("dataset_key")["dataset_fixed_level"].nunique()\n'
                                                                                       '    if (n_levels != 1).any():\n'
                                                                                       '        raise ValueError(\n'
                                                                                       '            "Each dataset_key '
                                                                                       'must map to exactly one '
                                                                                       'dataset_fixed_level."\n'
                                                                                       '        )\n'
                                                                                       '    return design\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'apply_mixed_model_design(frame: '
                                                                                       'pd.DataFrame) -> '
                                                                                       'pd.DataFrame:\n'
                                                                                       '    design = '
                                                                                       'load_mixed_model_design()\n'
                                                                                       '    work = frame.copy()\n'
                                                                                       '    work["_local_pair_key"] = '
                                                                                       '[\n'
                                                                                       '        _canonical_pair(a, b)\n'
                                                                                       '        for a, b in '
                                                                                       'zip(work["subject_i"], '
                                                                                       'work["subject_j"])\n'
                                                                                       '    ]\n'
                                                                                       '    merged = work.merge(\n'
                                                                                       '        design[\n'
                                                                                       '            [\n'
                                                                                       '                "dataset_key", '
                                                                                       '"_local_pair_key",\n'
                                                                                       '                '
                                                                                       '"crossed_participant_i", '
                                                                                       '"crossed_participant_j",\n'
                                                                                       '                '
                                                                                       '"repeated_dyad_id", '
                                                                                       '"dataset_fixed_level",\n'
                                                                                       '            ]\n'
                                                                                       '        ],\n'
                                                                                       '        left_on=["dataset", '
                                                                                       '"_local_pair_key"],\n'
                                                                                       '        '
                                                                                       'right_on=["dataset_key", '
                                                                                       '"_local_pair_key"],\n'
                                                                                       '        how="left",\n'
                                                                                       '        '
                                                                                       'validate="many_to_one",\n'
                                                                                       '    )\n'
                                                                                       '    if '
                                                                                       'merged["repeated_dyad_id"].isna().any():\n'
                                                                                       '        raise ValueError(\n'
                                                                                       '            "Local '
                                                                                       'mixed-model design does not '
                                                                                       'cover every Stage-1 dataset × '
                                                                                       'dyad row."\n'
                                                                                       '        )\n'
                                                                                       '    merged["subject_i"] = '
                                                                                       'merged["crossed_participant_i"].astype(str)\n'
                                                                                       '    merged["subject_j"] = '
                                                                                       'merged["crossed_participant_j"].astype(str)\n'
                                                                                       '    merged["pair_id"] = '
                                                                                       'merged["repeated_dyad_id"].astype(str)\n'
                                                                                       '    # `dataset` remains the '
                                                                                       'internal analysis key; '
                                                                                       'dataset_fixed_level is '
                                                                                       'retained\n'
                                                                                       '    # only as a '
                                                                                       'dependency-aware audit that '
                                                                                       'the stimulus/dataset '
                                                                                       'fixed-effect\n'
                                                                                       '    # membership was '
                                                                                       'explicitly supplied in the '
                                                                                       'local design file.\n'
                                                                                       '    return '
                                                                                       'merged.drop(columns=["dataset_key", '
                                                                                       '"_local_pair_key"])\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def combine_family_datasets(\n'
                                                                                       '    family_datasets: dict[str, '
                                                                                       'DyadFamilyDataset],\n'
                                                                                       '    dataset_order: list[str],\n'
                                                                                       '):\n'
                                                                                       '    rows = []\n'
                                                                                       '    slices = {}\n'
                                                                                       '    start = 0\n'
                                                                                       '    for dataset in '
                                                                                       'dataset_order:\n'
                                                                                       '        item = '
                                                                                       'family_datasets[dataset]\n'
                                                                                       '        item.validate()\n'
                                                                                       '        n = '
                                                                                       'len(item.dyad_slopes)\n'
                                                                                       '        stop = start + n\n'
                                                                                       '        slices[dataset] = '
                                                                                       'slice(start, stop)\n'
                                                                                       '        subject_i = '
                                                                                       'np.asarray(item.subject_i, '
                                                                                       'dtype=object)\n'
                                                                                       '        subject_j = '
                                                                                       'np.asarray(item.subject_j, '
                                                                                       'dtype=object)\n'
                                                                                       '        pair_ids = '
                                                                                       'np.asarray([\n'
                                                                                       '            "PAIR::" + '
                                                                                       '"||".join(sorted((str(a), '
                                                                                       'str(b))))\n'
                                                                                       '            for a, b in '
                                                                                       'zip(subject_i, subject_j)\n'
                                                                                       '        ], dtype=object)\n'
                                                                                       '        '
                                                                                       'rows.append(pd.DataFrame({\n'
                                                                                       '            "dataset": '
                                                                                       'dataset,\n'
                                                                                       '            "subject_i": '
                                                                                       'subject_i,\n'
                                                                                       '            "subject_j": '
                                                                                       'subject_j,\n'
                                                                                       '            "pair_id": '
                                                                                       'pair_ids,\n'
                                                                                       '            "dyad_slope": '
                                                                                       'item.dyad_slopes,\n'
                                                                                       '        }))\n'
                                                                                       '        start = stop\n'
                                                                                       '    frame = pd.concat(rows, '
                                                                                       'ignore_index=True)\n'
                                                                                       '    frame = '
                                                                                       'apply_mixed_model_design(frame)\n'
                                                                                       '    return frame, slices\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'subject_incidence_matrix(frame: '
                                                                                       'pd.DataFrame):\n'
                                                                                       '    labels = '
                                                                                       'sorted(set(frame["subject_i"]).union(set(frame["subject_j"])))\n'
                                                                                       '    mapping = {label: index '
                                                                                       'for index, label in '
                                                                                       'enumerate(labels)}\n'
                                                                                       '    n = len(frame)\n'
                                                                                       '    rows = '
                                                                                       'np.repeat(np.arange(n, '
                                                                                       'dtype=np.int32), 2)\n'
                                                                                       '    columns = np.empty(2 * n, '
                                                                                       'dtype=np.int32)\n'
                                                                                       '    columns[0::2] = '
                                                                                       '[mapping[x] for x in '
                                                                                       'frame["subject_i"]]\n'
                                                                                       '    columns[1::2] = '
                                                                                       '[mapping[x] for x in '
                                                                                       'frame["subject_j"]]\n'
                                                                                       '    values = np.ones(2 * n, '
                                                                                       'dtype=float)\n'
                                                                                       '    matrix = '
                                                                                       'sparse.csr_matrix((values, '
                                                                                       '(rows, columns)), shape=(n, '
                                                                                       'len(labels)))\n'
                                                                                       '    return matrix, labels\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'repeated_pair_incidence_matrix(frame: '
                                                                                       'pd.DataFrame):\n'
                                                                                       '    """One-hot incidence for '
                                                                                       'dyads observed in at least two '
                                                                                       'dataset rows.\n'
                                                                                       '\n'
                                                                                       '    A pair-specific random '
                                                                                       'intercept is meaningful only '
                                                                                       'when the same canonical\n'
                                                                                       '    dyad occurs in multiple '
                                                                                       'stimuli.  Singleton pair '
                                                                                       'columns would be perfectly\n'
                                                                                       '    confounded with residual '
                                                                                       'variance, so they are '
                                                                                       'intentionally omitted.\n'
                                                                                       '    """\n'
                                                                                       '    counts = '
                                                                                       'frame["pair_id"].value_counts()\n'
                                                                                       '    labels = '
                                                                                       'sorted(counts.index[counts.gt(1)].tolist())\n'
                                                                                       '    if not labels:\n'
                                                                                       '        return None, []\n'
                                                                                       '    mapping = {label: index '
                                                                                       'for index, label in '
                                                                                       'enumerate(labels)}\n'
                                                                                       '    selected = '
                                                                                       'frame["pair_id"].isin(mapping).to_numpy()\n'
                                                                                       '    rows = '
                                                                                       'np.flatnonzero(selected).astype(np.int32)\n'
                                                                                       '    columns = np.asarray(\n'
                                                                                       '        [mapping[label] for '
                                                                                       'label in frame.loc[selected, '
                                                                                       '"pair_id"]],\n'
                                                                                       '        dtype=np.int32,\n'
                                                                                       '    )\n'
                                                                                       '    matrix = '
                                                                                       'sparse.csr_matrix(\n'
                                                                                       '        (np.ones(len(rows), '
                                                                                       'dtype=float), (rows, '
                                                                                       'columns)),\n'
                                                                                       '        shape=(len(frame), '
                                                                                       'len(labels)),\n'
                                                                                       '    )\n'
                                                                                       '    return matrix, labels\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'dataset_incidence_matrix(frame: '
                                                                                       'pd.DataFrame, dataset_order: '
                                                                                       'list[str]):\n'
                                                                                       '    """Build stimulus/dataset '
                                                                                       'fixed-effect incidence from '
                                                                                       'the local design."""\n'
                                                                                       '    if "dataset_fixed_level" '
                                                                                       'not in frame.columns:\n'
                                                                                       '        raise ValueError(\n'
                                                                                       '            '
                                                                                       '"dataset_fixed_level is '
                                                                                       'required from the local '
                                                                                       'mixed-model design."\n'
                                                                                       '        )\n'
                                                                                       '    fixed_order = []\n'
                                                                                       '    for dataset in '
                                                                                       'dataset_order:\n'
                                                                                       '        levels = frame.loc[\n'
                                                                                       '            '
                                                                                       'frame["dataset"].astype(str).eq(str(dataset)), '
                                                                                       '"dataset_fixed_level"\n'
                                                                                       '        '
                                                                                       '].astype(str).unique().tolist()\n'
                                                                                       '        if len(levels) != 1:\n'
                                                                                       '            raise ValueError(\n'
                                                                                       '                f"{dataset}: '
                                                                                       'expected exactly one local '
                                                                                       'dataset_fixed_level; found '
                                                                                       '{len(levels)}."\n'
                                                                                       '            )\n'
                                                                                       '        '
                                                                                       'fixed_order.append(levels[0])\n'
                                                                                       '    if len(set(fixed_order)) '
                                                                                       '!= len(fixed_order):\n'
                                                                                       '        raise '
                                                                                       'ValueError("dataset_fixed_level '
                                                                                       'values must be unique across '
                                                                                       'fixed-effect levels.")\n'
                                                                                       '    mapping = {label: index '
                                                                                       'for index, label in '
                                                                                       'enumerate(fixed_order)}\n'
                                                                                       '    columns = np.asarray(\n'
                                                                                       '        [mapping[str(x)] for x '
                                                                                       'in '
                                                                                       'frame["dataset_fixed_level"]], '
                                                                                       'dtype=np.int32\n'
                                                                                       '    )\n'
                                                                                       '    rows = '
                                                                                       'np.arange(len(frame), '
                                                                                       'dtype=np.int32)\n'
                                                                                       '    matrix = '
                                                                                       'sparse.csr_matrix(\n'
                                                                                       '        (np.ones(len(frame)), '
                                                                                       '(rows, columns)),\n'
                                                                                       '        shape=(len(frame), '
                                                                                       'len(fixed_order)),\n'
                                                                                       '    )\n'
                                                                                       '    return matrix\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def fit_mixed_model(\n'
                                                                                       '    name: str,\n'
                                                                                       '    y: np.ndarray,\n'
                                                                                       '    fixed_design: np.ndarray,\n'
                                                                                       '    fixed_names: list[str],\n'
                                                                                       '    subject_design: '
                                                                                       'sparse.csr_matrix,\n'
                                                                                       '    subject_names: list[str],\n'
                                                                                       '    pair_design: '
                                                                                       'sparse.csr_matrix | None = '
                                                                                       'None,\n'
                                                                                       '    pair_names: list[str] | '
                                                                                       'None = None,\n'
                                                                                       '    dataset_design: '
                                                                                       'sparse.csr_matrix | None = '
                                                                                       'None,\n'
                                                                                       '    dataset_names: list[str] | '
                                                                                       'None = None,\n'
                                                                                       ') -> MixedFit:\n'
                                                                                       '    y = np.asarray(y, '
                                                                                       'dtype=float)\n'
                                                                                       '    fixed_design = '
                                                                                       'np.asarray(fixed_design, '
                                                                                       'dtype=float)\n'
                                                                                       '    if len(y) != '
                                                                                       'fixed_design.shape[0] or '
                                                                                       'len(y) != '
                                                                                       'subject_design.shape[0]:\n'
                                                                                       '        raise '
                                                                                       'ValueError(f"{name}: '
                                                                                       'mixed-model dimension '
                                                                                       'mismatch")\n'
                                                                                       '    if pair_design is not None '
                                                                                       'and pair_design.shape[0] != '
                                                                                       'len(y):\n'
                                                                                       '        raise '
                                                                                       'ValueError(f"{name}: '
                                                                                       'pair-design row mismatch")\n'
                                                                                       '\n'
                                                                                       '    vc_names = []\n'
                                                                                       '    vc_colnames = []\n'
                                                                                       '    vc_mats = []\n'
                                                                                       '    if dataset_design is not '
                                                                                       'None:\n'
                                                                                       '        if dataset_names is '
                                                                                       'None:\n'
                                                                                       '            raise '
                                                                                       'ValueError("dataset_names '
                                                                                       'required with '
                                                                                       'dataset_design")\n'
                                                                                       '        '
                                                                                       'vc_names.append("dataset")\n'
                                                                                       '        '
                                                                                       'vc_colnames.append([dataset_names])\n'
                                                                                       '        '
                                                                                       'vc_mats.append([dataset_design])\n'
                                                                                       '    if pair_design is not None '
                                                                                       'and pair_design.shape[1] > 0:\n'
                                                                                       '        if pair_names is '
                                                                                       'None:\n'
                                                                                       '            raise '
                                                                                       'ValueError("pair_names '
                                                                                       'required with pair_design")\n'
                                                                                       '        '
                                                                                       'vc_names.append("pair")\n'
                                                                                       '        '
                                                                                       'vc_colnames.append([pair_names])\n'
                                                                                       '        '
                                                                                       'vc_mats.append([pair_design])\n'
                                                                                       '    '
                                                                                       'vc_names.append("subject")\n'
                                                                                       '    '
                                                                                       'vc_colnames.append([subject_names])\n'
                                                                                       '    '
                                                                                       'vc_mats.append([subject_design])\n'
                                                                                       '\n'
                                                                                       '    vc_spec = VCSpec(vc_names, '
                                                                                       'vc_colnames, vc_mats)\n'
                                                                                       '    groups = np.zeros(len(y), '
                                                                                       'dtype=int)\n'
                                                                                       '    model = MixedLM(\n'
                                                                                       '        y,\n'
                                                                                       '        fixed_design,\n'
                                                                                       '        groups=groups,\n'
                                                                                       '        exog_re=None,\n'
                                                                                       '        exog_vc=vc_spec,\n'
                                                                                       '        use_sqrt=True,\n'
                                                                                       '    )\n'
                                                                                       '\n'
                                                                                       '    warning_messages = []\n'
                                                                                       '    result = None\n'
                                                                                       '    last_error = None\n'
                                                                                       '    for methods in (["lbfgs"], '
                                                                                       '["bfgs"], ["cg"], ["lbfgs", '
                                                                                       '"bfgs", "cg"]):\n'
                                                                                       '        try:\n'
                                                                                       '            with '
                                                                                       'warnings.catch_warnings(record=True) '
                                                                                       'as caught:\n'
                                                                                       '                '
                                                                                       'warnings.simplefilter("always")\n'
                                                                                       '                result = '
                                                                                       'model.fit(\n'
                                                                                       '                    '
                                                                                       'reml=True,\n'
                                                                                       '                    '
                                                                                       'method=methods,\n'
                                                                                       '                    '
                                                                                       'maxiter=1000,\n'
                                                                                       '                    '
                                                                                       'disp=False,\n'
                                                                                       '                )\n'
                                                                                       '                '
                                                                                       'warning_messages.extend(str(item.message) '
                                                                                       'for item in caught)\n'
                                                                                       '            if '
                                                                                       'bool(getattr(result, '
                                                                                       '"converged", False)):\n'
                                                                                       '                break\n'
                                                                                       '        except Exception as '
                                                                                       'error:\n'
                                                                                       '            last_error = '
                                                                                       'error\n'
                                                                                       '            '
                                                                                       'warning_messages.append(f"{methods}: '
                                                                                       '{error}")\n'
                                                                                       '            result = None\n'
                                                                                       '\n'
                                                                                       '    if result is None:\n'
                                                                                       '        raise '
                                                                                       'RuntimeError(f"{name}: MixedLM '
                                                                                       'failed: {last_error}")\n'
                                                                                       '\n'
                                                                                       '    variance_map = {\n'
                                                                                       '        vc_name: float(value)\n'
                                                                                       '        for vc_name, value in '
                                                                                       'zip(result.model.exog_vc.names, '
                                                                                       'result.vcomp)\n'
                                                                                       '    }\n'
                                                                                       '    return MixedFit(\n'
                                                                                       '        name=name,\n'
                                                                                       '        result=result,\n'
                                                                                       '        '
                                                                                       'fixed_names=fixed_names,\n'
                                                                                       '        '
                                                                                       'fixed_design=fixed_design,\n'
                                                                                       '        '
                                                                                       'subject_design=subject_design,\n'
                                                                                       '        '
                                                                                       'pair_design=pair_design,\n'
                                                                                       '        '
                                                                                       'dataset_design=dataset_design,\n'
                                                                                       '        '
                                                                                       'subject_variance=float(variance_map.get("subject", '
                                                                                       '0.0)),\n'
                                                                                       '        '
                                                                                       'pair_variance=float(variance_map.get("pair", '
                                                                                       '0.0)),\n'
                                                                                       '        '
                                                                                       'dataset_variance=float(variance_map.get("dataset", '
                                                                                       '0.0)),\n'
                                                                                       '        '
                                                                                       'residual_variance=float(result.scale),\n'
                                                                                       '        '
                                                                                       'n_repeated_pair_levels=(0 if '
                                                                                       'pair_design is None else '
                                                                                       'int(pair_design.shape[1])),\n'
                                                                                       '        '
                                                                                       'converged=bool(getattr(result, '
                                                                                       '"converged", False)),\n'
                                                                                       '        warnings_text=" | '
                                                                                       '".join(dict.fromkeys(warning_messages)),\n'
                                                                                       '    )\n'
                                                                                       '\n'
                                                                                       'def make_vinverse_solver(\n'
                                                                                       '    residual_variance: float,\n'
                                                                                       '    subject_design: '
                                                                                       'sparse.csr_matrix,\n'
                                                                                       '    subject_variance: float,\n'
                                                                                       '    pair_design: '
                                                                                       'sparse.csr_matrix | None,\n'
                                                                                       '    pair_variance: float,\n'
                                                                                       '    dataset_design: '
                                                                                       'sparse.csr_matrix | None,\n'
                                                                                       '    dataset_variance: float,\n'
                                                                                       '):\n'
                                                                                       '    sigma2 = '
                                                                                       'float(residual_variance)\n'
                                                                                       '    if not np.isfinite(sigma2) '
                                                                                       'or sigma2 <= 0:\n'
                                                                                       '        raise '
                                                                                       'ValueError(f"Invalid residual '
                                                                                       'variance: {sigma2}")\n'
                                                                                       '\n'
                                                                                       '    matrices = []\n'
                                                                                       '    component_variances = []\n'
                                                                                       '    if subject_variance > '
                                                                                       '1e-12:\n'
                                                                                       '        '
                                                                                       'matrices.append(subject_design)\n'
                                                                                       '        '
                                                                                       'component_variances.extend([float(subject_variance)] '
                                                                                       '* subject_design.shape[1])\n'
                                                                                       '    if pair_design is not None '
                                                                                       'and pair_design.shape[1] > 0 '
                                                                                       'and pair_variance > 1e-12:\n'
                                                                                       '        '
                                                                                       'matrices.append(pair_design)\n'
                                                                                       '        '
                                                                                       'component_variances.extend([float(pair_variance)] '
                                                                                       '* pair_design.shape[1])\n'
                                                                                       '    if dataset_design is not '
                                                                                       'None and dataset_variance > '
                                                                                       '1e-12:\n'
                                                                                       '        '
                                                                                       'matrices.append(dataset_design)\n'
                                                                                       '        '
                                                                                       'component_variances.extend([float(dataset_variance)] '
                                                                                       '* dataset_design.shape[1])\n'
                                                                                       '\n'
                                                                                       '    if not matrices:\n'
                                                                                       '        return lambda b: '
                                                                                       'np.asarray(b, dtype=float) / '
                                                                                       'sigma2\n'
                                                                                       '\n'
                                                                                       '    z = '
                                                                                       'sparse.hstack(matrices, '
                                                                                       'format="csr")\n'
                                                                                       '    g = '
                                                                                       'np.asarray(component_variances, '
                                                                                       'dtype=float)\n'
                                                                                       '    k_matrix = (z.T @ '
                                                                                       'z).toarray() / sigma2\n'
                                                                                       '    '
                                                                                       'k_matrix[np.diag_indices_from(k_matrix)] '
                                                                                       '+= 1.0 / g\n'
                                                                                       '    factor = '
                                                                                       'cho_factor(k_matrix, '
                                                                                       'lower=True, '
                                                                                       'check_finite=False)\n'
                                                                                       '\n'
                                                                                       '    def solve(b):\n'
                                                                                       '        b = np.asarray(b, '
                                                                                       'dtype=float)\n'
                                                                                       '        one_dimensional = '
                                                                                       'b.ndim == 1\n'
                                                                                       '        if one_dimensional:\n'
                                                                                       '            b = b[:, None]\n'
                                                                                       '        ztb = z.T @ b\n'
                                                                                       '        '
                                                                                       'correction_coefficients = '
                                                                                       'cho_solve(factor, ztb, '
                                                                                       'check_finite=False)\n'
                                                                                       '        correction = z @ '
                                                                                       'correction_coefficients\n'
                                                                                       '        output = b / sigma2 - '
                                                                                       'correction / (sigma2 ** 2)\n'
                                                                                       '        return output[:, 0] if '
                                                                                       'one_dimensional else output\n'
                                                                                       '\n'
                                                                                       '    return solve\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'fixed_effect_weight_matrix(fit: '
                                                                                       'MixedFit) -> np.ndarray:\n'
                                                                                       '    solve = '
                                                                                       'make_vinverse_solver(\n'
                                                                                       '        '
                                                                                       'fit.residual_variance,\n'
                                                                                       '        fit.subject_design,\n'
                                                                                       '        fit.subject_variance,\n'
                                                                                       '        fit.pair_design,\n'
                                                                                       '        fit.pair_variance,\n'
                                                                                       '        fit.dataset_design,\n'
                                                                                       '        fit.dataset_variance,\n'
                                                                                       '    )\n'
                                                                                       '    vinv_x = '
                                                                                       'solve(fit.fixed_design)\n'
                                                                                       '    information = '
                                                                                       'fit.fixed_design.T @ vinv_x\n'
                                                                                       '    information_inverse = '
                                                                                       'np.linalg.pinv(information, '
                                                                                       'rcond=1e-12)\n'
                                                                                       '    weights = vinv_x @ '
                                                                                       'information_inverse\n'
                                                                                       '    return np.asarray(weights, '
                                                                                       'dtype=float)\n'
                                                                                       '\n'
                                                                                       'def fit_family_models(\n'
                                                                                       '    family_name: str,\n'
                                                                                       '    family_datasets: dict[str, '
                                                                                       'DyadFamilyDataset],\n'
                                                                                       '    dataset_order: list[str],\n'
                                                                                       '    pooled_strategy: str = '
                                                                                       '"fixed_dataset_average",\n'
                                                                                       '):\n'
                                                                                       '    frame, slices = '
                                                                                       'combine_family_datasets(family_datasets, '
                                                                                       'dataset_order)\n'
                                                                                       '    subject_design, '
                                                                                       'subject_names = '
                                                                                       'subject_incidence_matrix(frame)\n'
                                                                                       '    pair_design, pair_names = '
                                                                                       'repeated_pair_incidence_matrix(frame)\n'
                                                                                       '    dataset_design = '
                                                                                       'dataset_incidence_matrix(frame, '
                                                                                       'dataset_order)\n'
                                                                                       '    y = '
                                                                                       'frame["dyad_slope"].to_numpy(float)\n'
                                                                                       '\n'
                                                                                       '    # Dataset-fixed model with '
                                                                                       'shared crossed-subject VC and '
                                                                                       'repeated-pair VC.\n'
                                                                                       '    fixed_fit = '
                                                                                       'fit_mixed_model(\n'
                                                                                       '        f"{family_name} | '
                                                                                       'dataset fixed",\n'
                                                                                       '        y,\n'
                                                                                       '        '
                                                                                       'dataset_design.toarray(),\n'
                                                                                       '        dataset_order,\n'
                                                                                       '        subject_design,\n'
                                                                                       '        subject_names,\n'
                                                                                       '        '
                                                                                       'pair_design=pair_design,\n'
                                                                                       '        '
                                                                                       'pair_names=pair_names,\n'
                                                                                       '    )\n'
                                                                                       '\n'
                                                                                       '    # The primary estimand in '
                                                                                       'this final pipeline is the '
                                                                                       'equal-weight average\n'
                                                                                       '    # across the observed '
                                                                                       'datasets/sessions. A '
                                                                                       'random-dataset model remains\n'
                                                                                       '    # available as an optional '
                                                                                       'sensitivity mode, but is not '
                                                                                       'used in the final\n'
                                                                                       '    # Study 1, Study 2, '
                                                                                       'regional, or all-five '
                                                                                       'analyses.\n'
                                                                                       '    if pooled_strategy == '
                                                                                       '"random_dataset":\n'
                                                                                       '        pooled_fit = '
                                                                                       'fit_mixed_model(\n'
                                                                                       '            f"{family_name} | '
                                                                                       'dataset random",\n'
                                                                                       '            y,\n'
                                                                                       '            np.ones((len(y), '
                                                                                       '1), dtype=float),\n'
                                                                                       '            ["pooled_mean"],\n'
                                                                                       '            subject_design,\n'
                                                                                       '            subject_names,\n'
                                                                                       '            '
                                                                                       'pair_design=pair_design,\n'
                                                                                       '            '
                                                                                       'pair_names=pair_names,\n'
                                                                                       '            '
                                                                                       'dataset_design=dataset_design,\n'
                                                                                       '            '
                                                                                       'dataset_names=dataset_order,\n'
                                                                                       '        )\n'
                                                                                       '    elif pooled_strategy == '
                                                                                       '"fixed_dataset_average":\n'
                                                                                       '        pooled_fit = None\n'
                                                                                       '    else:\n'
                                                                                       '        raise ValueError(\n'
                                                                                       '            "pooled_strategy '
                                                                                       "must be 'random_dataset' or "
                                                                                       '"\n'
                                                                                       '            '
                                                                                       '"\'fixed_dataset_average\'"\n'
                                                                                       '        )\n'
                                                                                       '\n'
                                                                                       '    return frame, slices, '
                                                                                       'fixed_fit, pooled_fit\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '# APPLY MIXED-MODEL WEIGHTS TO '
                                                                                       'BOOTSTRAP AND TEMPORAL NULL '
                                                                                       'DRAWS\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def calculate_weighted_draws(\n'
                                                                                       '    family_datasets: dict[str, '
                                                                                       'DyadFamilyDataset],\n'
                                                                                       '    dataset_order: list[str],\n'
                                                                                       '    slices: dict[str, slice],\n'
                                                                                       '    weights: np.ndarray,\n'
                                                                                       '    bootstrap_maps: dict[str, '
                                                                                       'np.ndarray],\n'
                                                                                       '    permutation_plans: '
                                                                                       'dict[str, np.ndarray],\n'
                                                                                       '    neural_bootstrap_plans: '
                                                                                       'dict[str, np.ndarray] | None = '
                                                                                       'None,\n'
                                                                                       '    bootstrap_row_indices: '
                                                                                       'dict[str, np.ndarray] | None = '
                                                                                       'None,\n'
                                                                                       '    chunk_size: int = 250,\n'
                                                                                       '):\n'
                                                                                       '    """Apply observed GLS '
                                                                                       'weights to neural+behavior '
                                                                                       'bootstrap and joint-null '
                                                                                       'draws.\n'
                                                                                       '\n'
                                                                                       '    The joint temporal null is '
                                                                                       'generated in four steps:\n'
                                                                                       '\n'
                                                                                       '    1. select behavioral and '
                                                                                       'neural participant-bootstrap '
                                                                                       'trajectories;\n'
                                                                                       '    2. apply the intact-block '
                                                                                       'permutation plan;\n'
                                                                                       '    3. re-residualize the '
                                                                                       'permuted predictor against '
                                                                                       'nuisance covariates at the\n'
                                                                                       '       destination time '
                                                                                       'points;\n'
                                                                                       '    4. compute the temporal '
                                                                                       'slope and apply the observed '
                                                                                       'mixed-model GLS weights.\n'
                                                                                       '\n'
                                                                                       '    For conditional valence, '
                                                                                       'the correspondingly permuted '
                                                                                       'arousal residual is\n'
                                                                                       '    also re-residualized at '
                                                                                       'the destination time points '
                                                                                       'and then included as a\n'
                                                                                       '    draw-specific additional '
                                                                                       'control for both the valence '
                                                                                       'predictor and the\n'
                                                                                       '    neural aggregate.\n'
                                                                                       '    """\n'
                                                                                       '    weights = '
                                                                                       'np.asarray(weights, '
                                                                                       'dtype=float)\n'
                                                                                       '    if weights.ndim == 1:\n'
                                                                                       '        weights = weights[:, '
                                                                                       'None]\n'
                                                                                       '    n_coefficients = '
                                                                                       'weights.shape[1]\n'
                                                                                       '\n'
                                                                                       '    observed = '
                                                                                       'np.zeros(n_coefficients, '
                                                                                       'dtype=float)\n'
                                                                                       '    bootstrap_aligned = '
                                                                                       'np.zeros((N_RESAMPLES, '
                                                                                       'n_coefficients), dtype=float)\n'
                                                                                       '    joint_null = '
                                                                                       'np.zeros((N_RESAMPLES, '
                                                                                       'n_coefficients), dtype=float)\n'
                                                                                       '\n'
                                                                                       '    if bootstrap_row_indices '
                                                                                       'is None:\n'
                                                                                       '        bootstrap_row_indices '
                                                                                       '= {\n'
                                                                                       '            item.study: '
                                                                                       'np.arange(N_RESAMPLES, '
                                                                                       'dtype=int)\n'
                                                                                       '            for item in '
                                                                                       'family_datasets.values()\n'
                                                                                       '        }\n'
                                                                                       '\n'
                                                                                       '    for dataset in '
                                                                                       'dataset_order:\n'
                                                                                       '        item = '
                                                                                       'family_datasets[dataset]\n'
                                                                                       '        weight_slice = '
                                                                                       'weights[slices[dataset]]\n'
                                                                                       '        study_rows = '
                                                                                       'np.asarray(bootstrap_row_indices[item.study], '
                                                                                       'dtype=int)\n'
                                                                                       '        neural_plan = None\n'
                                                                                       '        pair_i = None\n'
                                                                                       '        pair_j = None\n'
                                                                                       '        if '
                                                                                       'neural_bootstrap_plans is not '
                                                                                       'None:\n'
                                                                                       '            neural_plan = '
                                                                                       'neural_bootstrap_plans.get(neural_bootstrap_key(dataset))\n'
                                                                                       '            if neural_plan is '
                                                                                       'None:\n'
                                                                                       '                raise '
                                                                                       'KeyError(f"Missing neural '
                                                                                       'bootstrap plan for '
                                                                                       '{dataset}")\n'
                                                                                       '            neural_plan = '
                                                                                       'np.asarray(neural_plan)\n'
                                                                                       '            pair_i = '
                                                                                       'np.asarray(item.metadata.get("selected_pair_i"), '
                                                                                       'dtype=int)\n'
                                                                                       '            pair_j = '
                                                                                       'np.asarray(item.metadata.get("selected_pair_j"), '
                                                                                       'dtype=int)\n'
                                                                                       '            if pair_i.shape != '
                                                                                       'pair_j.shape or pair_i.shape '
                                                                                       '!= item.dyad_slopes.shape:\n'
                                                                                       '                raise '
                                                                                       'ValueError(f"{dataset}: '
                                                                                       'invalid selected dyad '
                                                                                       'metadata")\n'
                                                                                       '            if '
                                                                                       'len(neural_plan) < '
                                                                                       'N_RESAMPLES:\n'
                                                                                       '                raise '
                                                                                       'ValueError(f"{dataset}: neural '
                                                                                       'bootstrap plan is too short")\n'
                                                                                       '\n'
                                                                                       '        for component in '
                                                                                       'item.components:\n'
                                                                                       '            neural_aggregate = '
                                                                                       '(\n'
                                                                                       '                '
                                                                                       'np.asarray(component.neural_residuals, '
                                                                                       'dtype=np.float32)\n'
                                                                                       '                @ '
                                                                                       'weight_slice\n'
                                                                                       '            )\n'
                                                                                       '            x_observed = '
                                                                                       'np.asarray(component.x_observed, '
                                                                                       'dtype=float)\n'
                                                                                       '            '
                                                                                       'observed_denominator = '
                                                                                       'float(x_observed @ '
                                                                                       'x_observed)\n'
                                                                                       '            if not '
                                                                                       'np.isfinite(observed_denominator) '
                                                                                       'or observed_denominator <= 0:\n'
                                                                                       '                raise '
                                                                                       'ValueError(\n'
                                                                                       '                    '
                                                                                       'f"{dataset} '
                                                                                       '{component.bootstrap_key}: '
                                                                                       'invalid observed denominator"\n'
                                                                                       '                )\n'
                                                                                       '            observed += (\n'
                                                                                       '                '
                                                                                       'float(component.sign)\n'
                                                                                       '                * (x_observed '
                                                                                       '@ neural_aggregate)\n'
                                                                                       '                / '
                                                                                       'observed_denominator\n'
                                                                                       '            )\n'
                                                                                       '\n'
                                                                                       '            x_boot_map = '
                                                                                       'bootstrap_maps[component.bootstrap_key]\n'
                                                                                       '            x_valid_map = '
                                                                                       'bootstrap_maps.get(\n'
                                                                                       '                '
                                                                                       'bootstrap_validity_key(component.bootstrap_key)\n'
                                                                                       '            )\n'
                                                                                       '            plan = '
                                                                                       'permutation_plans[component.permutation_key]\n'
                                                                                       '            if len(x_boot_map) '
                                                                                       '< N_RESAMPLES or len(plan) < '
                                                                                       'N_RESAMPLES:\n'
                                                                                       '                raise '
                                                                                       'ValueError("Insufficient '
                                                                                       'bootstrap/permutation rows")\n'
                                                                                       '\n'
                                                                                       '            nuisance_controls '
                                                                                       '= (\n'
                                                                                       '                None\n'
                                                                                       '                if '
                                                                                       'component.nuisance_controls is '
                                                                                       'None\n'
                                                                                       '                else '
                                                                                       'np.asarray(component.nuisance_controls, '
                                                                                       'dtype=float)\n'
                                                                                       '            )\n'
                                                                                       '            if (\n'
                                                                                       '                '
                                                                                       'nuisance_controls is not None\n'
                                                                                       '                and '
                                                                                       'nuisance_controls.shape[0] != '
                                                                                       'len(x_observed)\n'
                                                                                       '            ):\n'
                                                                                       '                raise '
                                                                                       'ValueError("Nuisance-control '
                                                                                       'time length does not match '
                                                                                       'component")\n'
                                                                                       '\n'
                                                                                       '            '
                                                                                       'dynamic_base_aggregate = None\n'
                                                                                       '            '
                                                                                       'dynamic_control_map = None\n'
                                                                                       '            '
                                                                                       'dynamic_control_valid_map = '
                                                                                       'None\n'
                                                                                       '            if '
                                                                                       'component.bootstrap_neural_base '
                                                                                       'is not None:\n'
                                                                                       '                '
                                                                                       'dynamic_base_aggregate = (\n'
                                                                                       '                    '
                                                                                       'np.asarray(component.bootstrap_neural_base, '
                                                                                       'dtype=np.float32)\n'
                                                                                       '                    @ '
                                                                                       'weight_slice\n'
                                                                                       '                )\n'
                                                                                       '                '
                                                                                       'dynamic_control_map = '
                                                                                       'bootstrap_maps[\n'
                                                                                       '                    '
                                                                                       'component.bootstrap_additional_control_key\n'
                                                                                       '                ]\n'
                                                                                       '                '
                                                                                       'dynamic_control_valid_map = '
                                                                                       'bootstrap_maps.get(\n'
                                                                                       '                    '
                                                                                       'bootstrap_validity_key(\n'
                                                                                       '                        '
                                                                                       'component.bootstrap_additional_control_key\n'
                                                                                       '                    )\n'
                                                                                       '                )\n'
                                                                                       '\n'
                                                                                       '            for chunk_start in '
                                                                                       'range(0, N_RESAMPLES, '
                                                                                       'chunk_size):\n'
                                                                                       '                chunk_stop = '
                                                                                       'min(chunk_start + chunk_size, '
                                                                                       'N_RESAMPLES)\n'
                                                                                       '                draw_indices = '
                                                                                       'np.arange(chunk_start, '
                                                                                       'chunk_stop, dtype=int)\n'
                                                                                       '                '
                                                                                       'selected_boot_rows = '
                                                                                       'study_rows[draw_indices]\n'
                                                                                       '                n_chunk = '
                                                                                       'len(draw_indices)\n'
                                                                                       '\n'
                                                                                       '                x_draws = '
                                                                                       'np.asarray(\n'
                                                                                       '                    '
                                                                                       'x_boot_map[selected_boot_rows],\n'
                                                                                       '                    '
                                                                                       'dtype=float,\n'
                                                                                       '                )\n'
                                                                                       '                if x_valid_map '
                                                                                       'is None:\n'
                                                                                       '                    '
                                                                                       'x_valid_masks = '
                                                                                       'np.isfinite(x_draws)\n'
                                                                                       '                else:\n'
                                                                                       '                    '
                                                                                       'x_valid_masks = (\n'
                                                                                       '                        '
                                                                                       'np.asarray(\n'
                                                                                       '                            '
                                                                                       'x_valid_map[selected_boot_rows],\n'
                                                                                       '                            '
                                                                                       'dtype=float,\n'
                                                                                       '                        )\n'
                                                                                       '                        > 0.5\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'x_valid_masks &= '
                                                                                       'np.isfinite(x_draws)\n'
                                                                                       '                x_draws = '
                                                                                       'np.where(x_valid_masks, '
                                                                                       'x_draws, 0.0)\n'
                                                                                       '\n'
                                                                                       '                if neural_plan '
                                                                                       'is None:\n'
                                                                                       '                    '
                                                                                       'neural_draw_valid = '
                                                                                       'np.ones(n_chunk, dtype=bool)\n'
                                                                                       '                    '
                                                                                       'neural_aggregate_draws = '
                                                                                       'np.broadcast_to(\n'
                                                                                       '                        '
                                                                                       'neural_aggregate[None, :, :],\n'
                                                                                       '                        '
                                                                                       '(n_chunk, '
                                                                                       '*neural_aggregate.shape),\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'dynamic_base_aggregate_draws = '
                                                                                       '(\n'
                                                                                       '                        None\n'
                                                                                       '                        if '
                                                                                       'dynamic_base_aggregate is '
                                                                                       'None\n'
                                                                                       '                        else '
                                                                                       'np.broadcast_to(\n'
                                                                                       '                            '
                                                                                       'dynamic_base_aggregate[None, '
                                                                                       ':, :],\n'
                                                                                       '                            '
                                                                                       '(n_chunk, '
                                                                                       '*dynamic_base_aggregate.shape),\n'
                                                                                       '                        )\n'
                                                                                       '                    )\n'
                                                                                       '                else:\n'
                                                                                       '                    '
                                                                                       'dyad_multipliers, '
                                                                                       'neural_draw_valid = '
                                                                                       'dyad_bootstrap_multipliers(\n'
                                                                                       '                        '
                                                                                       'neural_plan[selected_boot_rows],\n'
                                                                                       '                        '
                                                                                       'pair_i,\n'
                                                                                       '                        '
                                                                                       'pair_j,\n'
                                                                                       '                    )\n'
                                                                                       '                    if '
                                                                                       'component.bootstrap_neural_base '
                                                                                       'is None:\n'
                                                                                       '                        '
                                                                                       'neural_aggregate_draws = '
                                                                                       'neural_bootstrap_aggregates(\n'
                                                                                       '                            '
                                                                                       'component.neural_residuals,\n'
                                                                                       '                            '
                                                                                       'weight_slice,\n'
                                                                                       '                            '
                                                                                       'dyad_multipliers,\n'
                                                                                       '                        )\n'
                                                                                       '                        '
                                                                                       'dynamic_base_aggregate_draws = '
                                                                                       'None\n'
                                                                                       '                    else:\n'
                                                                                       '                        '
                                                                                       'neural_aggregate_draws = None\n'
                                                                                       '                        '
                                                                                       'dynamic_base_aggregate_draws = '
                                                                                       'neural_bootstrap_aggregates(\n'
                                                                                       '                            '
                                                                                       'component.bootstrap_neural_base,\n'
                                                                                       '                            '
                                                                                       'weight_slice,\n'
                                                                                       '                            '
                                                                                       'dyad_multipliers,\n'
                                                                                       '                        )\n'
                                                                                       '\n'
                                                                                       '                # '
                                                                                       '-------------------------------------------------------------\n'
                                                                                       '                # Aligned '
                                                                                       'neural+behavior participant '
                                                                                       'bootstrap\n'
                                                                                       '                # '
                                                                                       '-------------------------------------------------------------\n'
                                                                                       '                if '
                                                                                       'dynamic_base_aggregate is '
                                                                                       'None:\n'
                                                                                       '                    '
                                                                                       'aligned_denominators = '
                                                                                       'np.sum(x_draws * x_draws, '
                                                                                       'axis=1)\n'
                                                                                       '                    '
                                                                                       'aligned_valid = (\n'
                                                                                       '                        '
                                                                                       'np.isfinite(aligned_denominators)\n'
                                                                                       '                        & '
                                                                                       '(aligned_denominators > 0)\n'
                                                                                       '                        & '
                                                                                       'neural_draw_valid\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'aligned_numerators = '
                                                                                       'np.einsum(\n'
                                                                                       '                        '
                                                                                       '"ct,ctp->cp",\n'
                                                                                       '                        '
                                                                                       'x_draws,\n'
                                                                                       '                        '
                                                                                       'neural_aggregate_draws,\n'
                                                                                       '                        '
                                                                                       'optimize=True,\n'
                                                                                       '                    )\n'
                                                                                       '                else:\n'
                                                                                       '                    '
                                                                                       'control_draws = np.asarray(\n'
                                                                                       '                        '
                                                                                       'dynamic_control_map[selected_boot_rows],\n'
                                                                                       '                        '
                                                                                       'dtype=float,\n'
                                                                                       '                    )\n'
                                                                                       '                    if '
                                                                                       'dynamic_control_valid_map is '
                                                                                       'None:\n'
                                                                                       '                        '
                                                                                       'control_valid_masks = '
                                                                                       'np.isfinite(control_draws)\n'
                                                                                       '                    else:\n'
                                                                                       '                        '
                                                                                       'control_valid_masks = (\n'
                                                                                       '                            '
                                                                                       'np.asarray(\n'
                                                                                       '                                '
                                                                                       'dynamic_control_valid_map[selected_boot_rows],\n'
                                                                                       '                                '
                                                                                       'dtype=float,\n'
                                                                                       '                            )\n'
                                                                                       '                            > '
                                                                                       '0.5\n'
                                                                                       '                        )\n'
                                                                                       '                        '
                                                                                       'control_valid_masks &= '
                                                                                       'np.isfinite(control_draws)\n'
                                                                                       '\n'
                                                                                       '                    '
                                                                                       'aligned_masks = x_valid_masks '
                                                                                       '& control_valid_masks\n'
                                                                                       '                    x_aligned '
                                                                                       '= np.where(aligned_masks, '
                                                                                       'x_draws, 0.0)\n'
                                                                                       '                    '
                                                                                       'control_aligned = np.where(\n'
                                                                                       '                        '
                                                                                       'aligned_masks,\n'
                                                                                       '                        '
                                                                                       'control_draws,\n'
                                                                                       '                        0.0,\n'
                                                                                       '                    )\n'
                                                                                       '\n'
                                                                                       '                    '
                                                                                       'aligned_denominators = '
                                                                                       'np.sum(\n'
                                                                                       '                        '
                                                                                       'x_aligned * x_aligned,\n'
                                                                                       '                        '
                                                                                       'axis=1,\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'control_denominators = '
                                                                                       'np.sum(\n'
                                                                                       '                        '
                                                                                       'control_aligned * '
                                                                                       'control_aligned,\n'
                                                                                       '                        '
                                                                                       'axis=1,\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'aligned_valid = (\n'
                                                                                       '                        '
                                                                                       'np.isfinite(aligned_denominators)\n'
                                                                                       '                        & '
                                                                                       '(aligned_denominators > 0)\n'
                                                                                       '                        & '
                                                                                       'np.isfinite(control_denominators)\n'
                                                                                       '                        & '
                                                                                       '(control_denominators > 0)\n'
                                                                                       '                        & '
                                                                                       'neural_draw_valid\n'
                                                                                       '                    )\n'
                                                                                       '\n'
                                                                                       '                    '
                                                                                       'projection_coefficients = '
                                                                                       'np.zeros(\n'
                                                                                       '                        '
                                                                                       '(n_chunk, n_coefficients),\n'
                                                                                       '                        '
                                                                                       'dtype=float,\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'projection_coefficients[aligned_valid] '
                                                                                       '= (\n'
                                                                                       '                        '
                                                                                       'np.einsum(\n'
                                                                                       '                            '
                                                                                       '"ct,ctp->cp",\n'
                                                                                       '                            '
                                                                                       'control_aligned[aligned_valid],\n'
                                                                                       '                            '
                                                                                       'dynamic_base_aggregate_draws[aligned_valid],\n'
                                                                                       '                            '
                                                                                       'optimize=True,\n'
                                                                                       '                        )\n'
                                                                                       '                    ) / '
                                                                                       'control_denominators[aligned_valid, '
                                                                                       'None]\n'
                                                                                       '                    '
                                                                                       'neural_aligned = (\n'
                                                                                       '                        '
                                                                                       'dynamic_base_aggregate_draws\n'
                                                                                       '                        - '
                                                                                       'control_aligned[:, :, None]\n'
                                                                                       '                        * '
                                                                                       'projection_coefficients[:, '
                                                                                       'None, :]\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'aligned_numerators = '
                                                                                       'np.einsum(\n'
                                                                                       '                        '
                                                                                       '"ct,ctp->cp",\n'
                                                                                       '                        '
                                                                                       'x_aligned,\n'
                                                                                       '                        '
                                                                                       'neural_aligned,\n'
                                                                                       '                        '
                                                                                       'optimize=True,\n'
                                                                                       '                    )\n'
                                                                                       '\n'
                                                                                       '                aligned_values '
                                                                                       '= np.full(\n'
                                                                                       '                    (n_chunk, '
                                                                                       'n_coefficients),\n'
                                                                                       '                    np.nan,\n'
                                                                                       '                    '
                                                                                       'dtype=float,\n'
                                                                                       '                )\n'
                                                                                       '                '
                                                                                       'aligned_values[aligned_valid] '
                                                                                       '= (\n'
                                                                                       '                    '
                                                                                       'aligned_numerators[aligned_valid]\n'
                                                                                       '                    / '
                                                                                       'aligned_denominators[aligned_valid, '
                                                                                       'None]\n'
                                                                                       '                )\n'
                                                                                       '                '
                                                                                       'bootstrap_aligned[chunk_start:chunk_stop] '
                                                                                       '+= (\n'
                                                                                       '                    '
                                                                                       'float(component.sign) * '
                                                                                       'aligned_values\n'
                                                                                       '                )\n'
                                                                                       '\n'
                                                                                       '                # '
                                                                                       '-------------------------------------------------------------\n'
                                                                                       '                # Joint '
                                                                                       'neural+behavior bootstrap + '
                                                                                       'temporal-null draw\n'
                                                                                       '                # '
                                                                                       '-------------------------------------------------------------\n'
                                                                                       '                index_rows = '
                                                                                       'np.asarray(plan[draw_indices], '
                                                                                       'dtype=int)\n'
                                                                                       '                row_selector = '
                                                                                       'np.arange(n_chunk, '
                                                                                       'dtype=int)[:, None]\n'
                                                                                       '\n'
                                                                                       '                permuted_x = '
                                                                                       'x_draws[row_selector, '
                                                                                       'index_rows]\n'
                                                                                       '                '
                                                                                       'permuted_x_valid = '
                                                                                       'x_valid_masks[row_selector, '
                                                                                       'index_rows]\n'
                                                                                       '\n'
                                                                                       '                if '
                                                                                       'dynamic_base_aggregate is '
                                                                                       'None:\n'
                                                                                       '                    if '
                                                                                       'nuisance_controls is None:\n'
                                                                                       '                        x_null '
                                                                                       '= np.where(\n'
                                                                                       '                            '
                                                                                       'permuted_x_valid,\n'
                                                                                       '                            '
                                                                                       'permuted_x,\n'
                                                                                       '                            '
                                                                                       '0.0,\n'
                                                                                       '                        )\n'
                                                                                       '                        '
                                                                                       'nuisance_valid = '
                                                                                       'np.ones(n_chunk, dtype=bool)\n'
                                                                                       '                    else:\n'
                                                                                       '                        '
                                                                                       'x_null, nuisance_valid = (\n'
                                                                                       '                            '
                                                                                       'residualize_draw_matrix_against_controls(\n'
                                                                                       '                                '
                                                                                       'permuted_x,\n'
                                                                                       '                                '
                                                                                       'nuisance_controls,\n'
                                                                                       '                                '
                                                                                       'permuted_x_valid,\n'
                                                                                       '                            )\n'
                                                                                       '                        )\n'
                                                                                       '\n'
                                                                                       '                    '
                                                                                       'null_denominators = '
                                                                                       'np.sum(x_null * x_null, '
                                                                                       'axis=1)\n'
                                                                                       '                    null_valid '
                                                                                       '= (\n'
                                                                                       '                        '
                                                                                       'nuisance_valid\n'
                                                                                       '                        & '
                                                                                       'np.isfinite(null_denominators)\n'
                                                                                       '                        & '
                                                                                       '(null_denominators > 0)\n'
                                                                                       '                        & '
                                                                                       'neural_draw_valid\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'null_numerators = np.einsum(\n'
                                                                                       '                        '
                                                                                       '"ct,ctp->cp",\n'
                                                                                       '                        '
                                                                                       'x_null,\n'
                                                                                       '                        '
                                                                                       'neural_aggregate_draws,\n'
                                                                                       '                        '
                                                                                       'optimize=True,\n'
                                                                                       '                    )\n'
                                                                                       '\n'
                                                                                       '                else:\n'
                                                                                       '                    '
                                                                                       'permuted_control = '
                                                                                       'control_draws[\n'
                                                                                       '                        '
                                                                                       'row_selector,\n'
                                                                                       '                        '
                                                                                       'index_rows,\n'
                                                                                       '                    ]\n'
                                                                                       '                    '
                                                                                       'permuted_control_valid = '
                                                                                       'control_valid_masks[\n'
                                                                                       '                        '
                                                                                       'row_selector,\n'
                                                                                       '                        '
                                                                                       'index_rows,\n'
                                                                                       '                    ]\n'
                                                                                       '                    null_masks '
                                                                                       '= permuted_x_valid & '
                                                                                       'permuted_control_valid\n'
                                                                                       '\n'
                                                                                       '                    if '
                                                                                       'nuisance_controls is None:\n'
                                                                                       '                        '
                                                                                       'x_fixed_residual = np.where(\n'
                                                                                       '                            '
                                                                                       'null_masks,\n'
                                                                                       '                            '
                                                                                       'permuted_x,\n'
                                                                                       '                            '
                                                                                       '0.0,\n'
                                                                                       '                        )\n'
                                                                                       '                        '
                                                                                       'control_fixed_residual = '
                                                                                       'np.where(\n'
                                                                                       '                            '
                                                                                       'null_masks,\n'
                                                                                       '                            '
                                                                                       'permuted_control,\n'
                                                                                       '                            '
                                                                                       '0.0,\n'
                                                                                       '                        )\n'
                                                                                       '                        '
                                                                                       'fixed_valid = np.ones(n_chunk, '
                                                                                       'dtype=bool)\n'
                                                                                       '                    else:\n'
                                                                                       '                        (\n'
                                                                                       '                            '
                                                                                       'x_fixed_residual,\n'
                                                                                       '                            '
                                                                                       'x_fixed_valid,\n'
                                                                                       '                        ) = '
                                                                                       'residualize_draw_matrix_against_controls(\n'
                                                                                       '                            '
                                                                                       'permuted_x,\n'
                                                                                       '                            '
                                                                                       'nuisance_controls,\n'
                                                                                       '                            '
                                                                                       'null_masks,\n'
                                                                                       '                        )\n'
                                                                                       '                        (\n'
                                                                                       '                            '
                                                                                       'control_fixed_residual,\n'
                                                                                       '                            '
                                                                                       'control_fixed_valid,\n'
                                                                                       '                        ) = '
                                                                                       'residualize_draw_matrix_against_controls(\n'
                                                                                       '                            '
                                                                                       'permuted_control,\n'
                                                                                       '                            '
                                                                                       'nuisance_controls,\n'
                                                                                       '                            '
                                                                                       'null_masks,\n'
                                                                                       '                        )\n'
                                                                                       '                        '
                                                                                       'fixed_valid = x_fixed_valid & '
                                                                                       'control_fixed_valid\n'
                                                                                       '\n'
                                                                                       '                    (\n'
                                                                                       '                        '
                                                                                       'x_null,\n'
                                                                                       '                        '
                                                                                       'dynamic_valid,\n'
                                                                                       '                    ) = '
                                                                                       'residualize_draws_against_dynamic_control(\n'
                                                                                       '                        '
                                                                                       'x_fixed_residual,\n'
                                                                                       '                        '
                                                                                       'control_fixed_residual,\n'
                                                                                       '                        '
                                                                                       'null_masks,\n'
                                                                                       '                    )\n'
                                                                                       '                    null_valid '
                                                                                       '= fixed_valid & dynamic_valid\n'
                                                                                       '                    '
                                                                                       'null_denominators = '
                                                                                       'np.sum(x_null * x_null, '
                                                                                       'axis=1)\n'
                                                                                       '                    null_valid '
                                                                                       '&= (\n'
                                                                                       '                        '
                                                                                       'np.isfinite(null_denominators)\n'
                                                                                       '                        & '
                                                                                       '(null_denominators > 0)\n'
                                                                                       '                    )\n'
                                                                                       '\n'
                                                                                       '                    '
                                                                                       'control_denominators_null = '
                                                                                       'np.sum(\n'
                                                                                       '                        '
                                                                                       'control_fixed_residual\n'
                                                                                       '                        * '
                                                                                       'control_fixed_residual,\n'
                                                                                       '                        '
                                                                                       'axis=1,\n'
                                                                                       '                    )\n'
                                                                                       '                    null_valid '
                                                                                       '&= (\n'
                                                                                       '                        '
                                                                                       'np.isfinite(control_denominators_null)\n'
                                                                                       '                        & '
                                                                                       '(control_denominators_null > '
                                                                                       '0)\n'
                                                                                       '                        & '
                                                                                       'neural_draw_valid\n'
                                                                                       '                    )\n'
                                                                                       '\n'
                                                                                       '                    '
                                                                                       'projection_coefficients_null = '
                                                                                       'np.zeros(\n'
                                                                                       '                        '
                                                                                       '(n_chunk, n_coefficients),\n'
                                                                                       '                        '
                                                                                       'dtype=float,\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'projection_coefficients_null[null_valid] '
                                                                                       '= (\n'
                                                                                       '                        '
                                                                                       'np.einsum(\n'
                                                                                       '                            '
                                                                                       '"ct,ctp->cp",\n'
                                                                                       '                            '
                                                                                       'control_fixed_residual[null_valid],\n'
                                                                                       '                            '
                                                                                       'dynamic_base_aggregate_draws[null_valid],\n'
                                                                                       '                            '
                                                                                       'optimize=True,\n'
                                                                                       '                        )\n'
                                                                                       '                    ) / '
                                                                                       'control_denominators_null[null_valid, '
                                                                                       'None]\n'
                                                                                       '                    '
                                                                                       'neural_null = (\n'
                                                                                       '                        '
                                                                                       'dynamic_base_aggregate_draws\n'
                                                                                       '                        - '
                                                                                       'control_fixed_residual[:, :, '
                                                                                       'None]\n'
                                                                                       '                        * '
                                                                                       'projection_coefficients_null[:, '
                                                                                       'None, :]\n'
                                                                                       '                    )\n'
                                                                                       '                    '
                                                                                       'null_numerators = np.einsum(\n'
                                                                                       '                        '
                                                                                       '"ct,ctp->cp",\n'
                                                                                       '                        '
                                                                                       'x_null,\n'
                                                                                       '                        '
                                                                                       'neural_null,\n'
                                                                                       '                        '
                                                                                       'optimize=True,\n'
                                                                                       '                    )\n'
                                                                                       '\n'
                                                                                       '                null_values = '
                                                                                       'np.full(\n'
                                                                                       '                    (n_chunk, '
                                                                                       'n_coefficients),\n'
                                                                                       '                    np.nan,\n'
                                                                                       '                    '
                                                                                       'dtype=float,\n'
                                                                                       '                )\n'
                                                                                       '                '
                                                                                       'null_values[null_valid] = (\n'
                                                                                       '                    '
                                                                                       'null_numerators[null_valid]\n'
                                                                                       '                    / '
                                                                                       'null_denominators[null_valid, '
                                                                                       'None]\n'
                                                                                       '                )\n'
                                                                                       '                '
                                                                                       'joint_null[chunk_start:chunk_stop] '
                                                                                       '+= (\n'
                                                                                       '                    '
                                                                                       'float(component.sign) * '
                                                                                       'null_values\n'
                                                                                       '                )\n'
                                                                                       '\n'
                                                                                       '    return observed, '
                                                                                       'bootstrap_aligned, joint_null\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'model_fixed_covariance(fit: '
                                                                                       'MixedFit) -> np.ndarray:\n'
                                                                                       '    k = len(fit.fixed_names)\n'
                                                                                       '    covariance = '
                                                                                       'np.asarray(fit.result.cov_params(), '
                                                                                       'dtype=float)\n'
                                                                                       '    return covariance[:k, :k]\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def summarize_fixed_model(\n'
                                                                                       '    step: str,\n'
                                                                                       '    family: str,\n'
                                                                                       '    dataset_order: list[str],\n'
                                                                                       '    fit: MixedFit,\n'
                                                                                       '    observed: np.ndarray,\n'
                                                                                       '    behavior_bootstrap: '
                                                                                       'np.ndarray,\n'
                                                                                       '    joint_null: np.ndarray,\n'
                                                                                       '):\n'
                                                                                       '    model_estimates = '
                                                                                       'np.asarray(fit.result.fe_params, '
                                                                                       'dtype=float)\n'
                                                                                       '    covariance = '
                                                                                       'model_fixed_covariance(fit)\n'
                                                                                       '    rows = []\n'
                                                                                       '\n'
                                                                                       '    if not '
                                                                                       'np.allclose(observed, '
                                                                                       'model_estimates, atol=2e-5, '
                                                                                       'rtol=2e-5):\n'
                                                                                       '        raise RuntimeError(\n'
                                                                                       '            f"{step} {family}: '
                                                                                       'fixed-weight reconstruction '
                                                                                       'does not match MixedLM: "\n'
                                                                                       '            f"{observed} vs '
                                                                                       '{model_estimates}"\n'
                                                                                       '        )\n'
                                                                                       '\n'
                                                                                       '    for index, dataset in '
                                                                                       'enumerate(dataset_order):\n'
                                                                                       '        estimate = '
                                                                                       'float(model_estimates[index])\n'
                                                                                       '        se = '
                                                                                       'float(np.sqrt(max(covariance[index, '
                                                                                       'index], 0.0)))\n'
                                                                                       '        z = estimate / se if '
                                                                                       'se > 0 else np.nan\n'
                                                                                       '        ci_low = estimate - '
                                                                                       '1.96 * se\n'
                                                                                       '        ci_high = estimate + '
                                                                                       '1.96 * se\n'
                                                                                       '        boot_low, boot_high = '
                                                                                       'quantile_interval(behavior_bootstrap[:, '
                                                                                       'index])\n'
                                                                                       '        null_low, null_high = '
                                                                                       'quantile_interval(joint_null[:, '
                                                                                       'index])\n'
                                                                                       '        rows.append({\n'
                                                                                       '            "step": step,\n'
                                                                                       '            "family": family,\n'
                                                                                       '            "result_type": '
                                                                                       '"dataset_effect",\n'
                                                                                       '            '
                                                                                       '"dataset_or_contrast": '
                                                                                       'dataset,\n'
                                                                                       '            "estimate": '
                                                                                       'estimate,\n'
                                                                                       '            "mixed_model_se": '
                                                                                       'se,\n'
                                                                                       '            "mixed_model_z": '
                                                                                       'z,\n'
                                                                                       '            '
                                                                                       '"mixed_model_p_normal": '
                                                                                       'float(2 * norm.sf(abs(z))) if '
                                                                                       'np.isfinite(z) else np.nan,\n'
                                                                                       '            '
                                                                                       '"mixed_model_ci_low": ci_low,\n'
                                                                                       '            '
                                                                                       '"mixed_model_ci_high": '
                                                                                       'ci_high,\n'
                                                                                       '            '
                                                                                       '"participant_bootstrap_mean_fixed_weights": '
                                                                                       'float(np.nanmean(behavior_bootstrap[:, '
                                                                                       'index])),\n'
                                                                                       '            '
                                                                                       '"participant_bootstrap_ci_low_fixed_weights": '
                                                                                       'boot_low,\n'
                                                                                       '            '
                                                                                       '"participant_bootstrap_ci_high_fixed_weights": '
                                                                                       'boot_high,\n'
                                                                                       '            '
                                                                                       '"participant_bootstrap_p_sign_fixed_weights": '
                                                                                       'bootstrap_sign_p(behavior_bootstrap[:, '
                                                                                       'index]),\n'
                                                                                       '            '
                                                                                       '"p_joint_participant_temporal": '
                                                                                       'two_sided_p(joint_null[:, '
                                                                                       'index], estimate),\n'
                                                                                       '            "joint_null_mean": '
                                                                                       'float(np.nanmean(joint_null[:, '
                                                                                       'index])),\n'
                                                                                       '            "joint_null_sd": '
                                                                                       'float(np.nanstd(joint_null[:, '
                                                                                       'index], ddof=1)),\n'
                                                                                       '            "joint_null_q025": '
                                                                                       'null_low,\n'
                                                                                       '            "joint_null_q975": '
                                                                                       'null_high,\n'
                                                                                       '            '
                                                                                       '"subject_variance": '
                                                                                       'fit.subject_variance,\n'
                                                                                       '            "pair_variance": '
                                                                                       'fit.pair_variance,\n'
                                                                                       '            '
                                                                                       '"dataset_variance": 0.0,\n'
                                                                                       '            '
                                                                                       '"residual_variance": '
                                                                                       'fit.residual_variance,\n'
                                                                                       '            '
                                                                                       '"n_repeated_pair_levels": '
                                                                                       'fit.n_repeated_pair_levels,\n'
                                                                                       '            '
                                                                                       '"n_dataset_levels": '
                                                                                       'len(dataset_order),\n'
                                                                                       '            "n_dyads": '
                                                                                       'int(fit.fixed_design.shape[0]),\n'
                                                                                       '            "model": "dataset '
                                                                                       'fixed effects + shared '
                                                                                       'crossed-subject VC + '
                                                                                       'repeated-dyad pair VC",\n'
                                                                                       '            "converged": '
                                                                                       'fit.converged,\n'
                                                                                       '            "model_warnings": '
                                                                                       'fit.warnings_text,\n'
                                                                                       '        })\n'
                                                                                       '\n'
                                                                                       '    # Omnibus equality test '
                                                                                       'across dataset-specific '
                                                                                       'effects.\n'
                                                                                       '    if len(dataset_order) > '
                                                                                       '1:\n'
                                                                                       '        contrast_matrix = '
                                                                                       'np.zeros((len(dataset_order) - '
                                                                                       '1, len(dataset_order)))\n'
                                                                                       '        for row_index in '
                                                                                       'range(len(dataset_order) - '
                                                                                       '1):\n'
                                                                                       '            '
                                                                                       'contrast_matrix[row_index, 0] '
                                                                                       '= -1.0\n'
                                                                                       '            '
                                                                                       'contrast_matrix[row_index, '
                                                                                       'row_index + 1] = 1.0\n'
                                                                                       '        contrast_values = '
                                                                                       'contrast_matrix @ '
                                                                                       'model_estimates\n'
                                                                                       '        contrast_covariance = '
                                                                                       'contrast_matrix @ covariance @ '
                                                                                       'contrast_matrix.T\n'
                                                                                       '        '
                                                                                       'inverse_contrast_covariance = '
                                                                                       'np.linalg.pinv(contrast_covariance, '
                                                                                       'rcond=1e-12)\n'
                                                                                       '        omnibus_q = '
                                                                                       'float(contrast_values @ '
                                                                                       'inverse_contrast_covariance @ '
                                                                                       'contrast_values)\n'
                                                                                       '        omnibus_df = '
                                                                                       'int(len(dataset_order) - 1)\n'
                                                                                       '        bootstrap_contrasts = '
                                                                                       'behavior_bootstrap @ '
                                                                                       'contrast_matrix.T\n'
                                                                                       '        joint_contrasts = '
                                                                                       'joint_null @ '
                                                                                       'contrast_matrix.T\n'
                                                                                       '        bootstrap_q = '
                                                                                       'np.einsum(\n'
                                                                                       '            "ni,ij,nj->n",\n'
                                                                                       '            '
                                                                                       'bootstrap_contrasts,\n'
                                                                                       '            '
                                                                                       'inverse_contrast_covariance,\n'
                                                                                       '            '
                                                                                       'bootstrap_contrasts,\n'
                                                                                       '            optimize=True,\n'
                                                                                       '        )\n'
                                                                                       '        joint_q = np.einsum(\n'
                                                                                       '            "ni,ij,nj->n",\n'
                                                                                       '            joint_contrasts,\n'
                                                                                       '            '
                                                                                       'inverse_contrast_covariance,\n'
                                                                                       '            joint_contrasts,\n'
                                                                                       '            optimize=True,\n'
                                                                                       '        )\n'
                                                                                       '        q_low, q_high = '
                                                                                       'quantile_interval(joint_q)\n'
                                                                                       '        rows.append({\n'
                                                                                       '            "step": step,\n'
                                                                                       '            "family": family,\n'
                                                                                       '            "result_type": '
                                                                                       '"dataset_omnibus_heterogeneity",\n'
                                                                                       '            '
                                                                                       '"dataset_or_contrast": "all '
                                                                                       'dataset effects equal",\n'
                                                                                       '            "estimate": '
                                                                                       'omnibus_q,\n'
                                                                                       '            "mixed_model_se": '
                                                                                       'np.nan,\n'
                                                                                       '            "mixed_model_z": '
                                                                                       'np.nan,\n'
                                                                                       '            '
                                                                                       '"mixed_model_p_normal": '
                                                                                       'float(chi2.sf(omnibus_q, '
                                                                                       'df=omnibus_df)),\n'
                                                                                       '            '
                                                                                       '"mixed_model_ci_low": np.nan,\n'
                                                                                       '            '
                                                                                       '"mixed_model_ci_high": '
                                                                                       'np.nan,\n'
                                                                                       '            '
                                                                                       '"participant_bootstrap_mean_fixed_weights": '
                                                                                       'float(np.nanmean(bootstrap_q)),\n'
                                                                                       '            '
                                                                                       '"participant_bootstrap_ci_low_fixed_weights": '
                                                                                       'quantile_interval(bootstrap_q)[0],\n'
                                                                                       '            '
                                                                                       '"participant_bootstrap_ci_high_fixed_weights": '
                                                                                       'quantile_interval(bootstrap_q)[1],\n'
                                                                                       '            '
                                                                                       '"participant_bootstrap_p_sign_fixed_weights": '
                                                                                       'np.nan,\n'
                                                                                       '            '
                                                                                       '"p_joint_participant_temporal": '
                                                                                       'float(\n'
                                                                                       '                (1 + '
                                                                                       'np.sum(joint_q >= omnibus_q)) '
                                                                                       '/ (len(joint_q) + 1)\n'
                                                                                       '            ),\n'
                                                                                       '            "joint_null_mean": '
                                                                                       'float(np.nanmean(joint_q)),\n'
                                                                                       '            "joint_null_sd": '
                                                                                       'float(np.nanstd(joint_q, '
                                                                                       'ddof=1)),\n'
                                                                                       '            "joint_null_q025": '
                                                                                       'q_low,\n'
                                                                                       '            "joint_null_q975": '
                                                                                       'q_high,\n'
                                                                                       '            '
                                                                                       '"subject_variance": '
                                                                                       'fit.subject_variance,\n'
                                                                                       '            "pair_variance": '
                                                                                       'fit.pair_variance,\n'
                                                                                       '            '
                                                                                       '"dataset_variance": 0.0,\n'
                                                                                       '            '
                                                                                       '"residual_variance": '
                                                                                       'fit.residual_variance,\n'
                                                                                       '            '
                                                                                       '"n_repeated_pair_levels": '
                                                                                       'fit.n_repeated_pair_levels,\n'
                                                                                       '            '
                                                                                       '"n_dataset_levels": '
                                                                                       'len(dataset_order),\n'
                                                                                       '            "n_dyads": '
                                                                                       'int(fit.fixed_design.shape[0]),\n'
                                                                                       '            "model": f"Wald '
                                                                                       'equality test from '
                                                                                       'dataset-fixed '
                                                                                       'subject+repeated-pair CRE '
                                                                                       'model; df={omnibus_df}",\n'
                                                                                       '            "converged": '
                                                                                       'fit.converged,\n'
                                                                                       '            "model_warnings": '
                                                                                       'fit.warnings_text,\n'
                                                                                       '        })\n'
                                                                                       '\n'
                                                                                       '    # Pairwise dataset '
                                                                                       'contrasts from the joint fixed '
                                                                                       'model.\n'
                                                                                       '    for i in '
                                                                                       'range(len(dataset_order)):\n'
                                                                                       '        for j in range(i + 1, '
                                                                                       'len(dataset_order)):\n'
                                                                                       '            c = '
                                                                                       'np.zeros(len(dataset_order))\n'
                                                                                       '            c[j] = 1.0\n'
                                                                                       '            c[i] = -1.0\n'
                                                                                       '            estimate = float(c '
                                                                                       '@ model_estimates)\n'
                                                                                       '            variance = float(c '
                                                                                       '@ covariance @ c)\n'
                                                                                       '            se = '
                                                                                       'float(np.sqrt(max(variance, '
                                                                                       '0.0)))\n'
                                                                                       '            z = estimate / se '
                                                                                       'if se > 0 else np.nan\n'
                                                                                       '            boot = '
                                                                                       'behavior_bootstrap @ c\n'
                                                                                       '            null = joint_null '
                                                                                       '@ c\n'
                                                                                       '            boot_low, '
                                                                                       'boot_high = '
                                                                                       'quantile_interval(boot)\n'
                                                                                       '            null_low, '
                                                                                       'null_high = '
                                                                                       'quantile_interval(null)\n'
                                                                                       '            rows.append({\n'
                                                                                       '                "step": step,\n'
                                                                                       '                "family": '
                                                                                       'family,\n'
                                                                                       '                "result_type": '
                                                                                       '"dataset_contrast",\n'
                                                                                       '                '
                                                                                       '"dataset_or_contrast": '
                                                                                       'f"{dataset_order[j]} - '
                                                                                       '{dataset_order[i]}",\n'
                                                                                       '                "estimate": '
                                                                                       'estimate,\n'
                                                                                       '                '
                                                                                       '"mixed_model_se": se,\n'
                                                                                       '                '
                                                                                       '"mixed_model_z": z,\n'
                                                                                       '                '
                                                                                       '"mixed_model_p_normal": '
                                                                                       'float(2 * norm.sf(abs(z))) if '
                                                                                       'np.isfinite(z) else np.nan,\n'
                                                                                       '                '
                                                                                       '"mixed_model_ci_low": estimate '
                                                                                       '- 1.96 * se,\n'
                                                                                       '                '
                                                                                       '"mixed_model_ci_high": '
                                                                                       'estimate + 1.96 * se,\n'
                                                                                       '                '
                                                                                       '"participant_bootstrap_mean_fixed_weights": '
                                                                                       'float(np.nanmean(boot)),\n'
                                                                                       '                '
                                                                                       '"participant_bootstrap_ci_low_fixed_weights": '
                                                                                       'boot_low,\n'
                                                                                       '                '
                                                                                       '"participant_bootstrap_ci_high_fixed_weights": '
                                                                                       'boot_high,\n'
                                                                                       '                '
                                                                                       '"participant_bootstrap_p_sign_fixed_weights": '
                                                                                       'bootstrap_sign_p(boot),\n'
                                                                                       '                '
                                                                                       '"p_joint_participant_temporal": '
                                                                                       'two_sided_p(null, estimate),\n'
                                                                                       '                '
                                                                                       '"joint_null_mean": '
                                                                                       'float(np.nanmean(null)),\n'
                                                                                       '                '
                                                                                       '"joint_null_sd": '
                                                                                       'float(np.nanstd(null, '
                                                                                       'ddof=1)),\n'
                                                                                       '                '
                                                                                       '"joint_null_q025": null_low,\n'
                                                                                       '                '
                                                                                       '"joint_null_q975": null_high,\n'
                                                                                       '                '
                                                                                       '"subject_variance": '
                                                                                       'fit.subject_variance,\n'
                                                                                       '                '
                                                                                       '"pair_variance": '
                                                                                       'fit.pair_variance,\n'
                                                                                       '                '
                                                                                       '"dataset_variance": 0.0,\n'
                                                                                       '                '
                                                                                       '"residual_variance": '
                                                                                       'fit.residual_variance,\n'
                                                                                       '                '
                                                                                       '"n_repeated_pair_levels": '
                                                                                       'fit.n_repeated_pair_levels,\n'
                                                                                       '                '
                                                                                       '"n_dataset_levels": '
                                                                                       'len(dataset_order),\n'
                                                                                       '                "n_dyads": '
                                                                                       'int(fit.fixed_design.shape[0]),\n'
                                                                                       '                "model": '
                                                                                       '"contrast from dataset-fixed '
                                                                                       'subject+repeated-pair CRE '
                                                                                       'model",\n'
                                                                                       '                "converged": '
                                                                                       'fit.converged,\n'
                                                                                       '                '
                                                                                       '"model_warnings": '
                                                                                       'fit.warnings_text,\n'
                                                                                       '            })\n'
                                                                                       '    return rows\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'summarize_pooled_fixed_average(\n'
                                                                                       '    step: str,\n'
                                                                                       '    family: str,\n'
                                                                                       '    dataset_order: list[str],\n'
                                                                                       '    fixed_fit: MixedFit,\n'
                                                                                       '    contrast: np.ndarray,\n'
                                                                                       '    observed: np.ndarray,\n'
                                                                                       '    behavior_bootstrap: '
                                                                                       'np.ndarray,\n'
                                                                                       '    joint_null: np.ndarray,\n'
                                                                                       '):\n'
                                                                                       '    """\n'
                                                                                       '    Summarize an equal-weight '
                                                                                       'mean of dataset/session fixed '
                                                                                       'effects.\n'
                                                                                       '\n'
                                                                                       '    This is used whenever the '
                                                                                       'target is the equal-weight '
                                                                                       'mean across the\n'
                                                                                       '    observed '
                                                                                       'datasets/sessions. The '
                                                                                       'estimate is conditional on '
                                                                                       'those observed\n'
                                                                                       '    levels and does not '
                                                                                       'estimate a random-stimulus '
                                                                                       'population variance.\n'
                                                                                       '    """\n'
                                                                                       '    contrast = '
                                                                                       'np.asarray(contrast, '
                                                                                       'dtype=float)\n'
                                                                                       '    if contrast.shape != '
                                                                                       '(len(dataset_order),):\n'
                                                                                       '        raise '
                                                                                       'ValueError("Invalid pooled '
                                                                                       'fixed-effect contrast shape")\n'
                                                                                       '    if not '
                                                                                       'np.isclose(np.sum(contrast), '
                                                                                       '1.0):\n'
                                                                                       '        raise '
                                                                                       'ValueError("Pooled '
                                                                                       'fixed-effect contrast must sum '
                                                                                       'to one")\n'
                                                                                       '\n'
                                                                                       '    fixed_estimates = '
                                                                                       'np.asarray(fixed_fit.result.fe_params, '
                                                                                       'dtype=float)\n'
                                                                                       '    estimate = float(contrast '
                                                                                       '@ fixed_estimates)\n'
                                                                                       '    if not '
                                                                                       'np.isclose(observed[0], '
                                                                                       'estimate, atol=2e-5, '
                                                                                       'rtol=2e-5):\n'
                                                                                       '        raise RuntimeError(\n'
                                                                                       '            f"{step} {family}: '
                                                                                       'fixed-average reconstruction '
                                                                                       'mismatch: "\n'
                                                                                       '            f"{observed[0]} vs '
                                                                                       '{estimate}"\n'
                                                                                       '        )\n'
                                                                                       '\n'
                                                                                       '    covariance = '
                                                                                       'model_fixed_covariance(fixed_fit)\n'
                                                                                       '    variance = float(contrast '
                                                                                       '@ covariance @ contrast)\n'
                                                                                       '    se = '
                                                                                       'float(np.sqrt(max(variance, '
                                                                                       '0.0)))\n'
                                                                                       '    z = estimate / se if se > '
                                                                                       '0 else np.nan\n'
                                                                                       '\n'
                                                                                       '    boot = '
                                                                                       'behavior_bootstrap[:, 0]\n'
                                                                                       '    null = joint_null[:, 0]\n'
                                                                                       '    boot_low, boot_high = '
                                                                                       'quantile_interval(boot)\n'
                                                                                       '    null_low, null_high = '
                                                                                       'quantile_interval(null)\n'
                                                                                       '\n'
                                                                                       '    return {\n'
                                                                                       '        "step": step,\n'
                                                                                       '        "family": family,\n'
                                                                                       '        "result_type": '
                                                                                       '"pooled_fixed_dataset_mean",\n'
                                                                                       '        "dataset_or_contrast": '
                                                                                       '"equal_weight_pooled_mean",\n'
                                                                                       '        "estimate": estimate,\n'
                                                                                       '        "mixed_model_se": se,\n'
                                                                                       '        "mixed_model_z": z,\n'
                                                                                       '        '
                                                                                       '"mixed_model_p_normal": '
                                                                                       'float(2 * norm.sf(abs(z))) if '
                                                                                       'np.isfinite(z) else np.nan,\n'
                                                                                       '        "mixed_model_ci_low": '
                                                                                       'estimate - 1.96 * se,\n'
                                                                                       '        "mixed_model_ci_high": '
                                                                                       'estimate + 1.96 * se,\n'
                                                                                       '        '
                                                                                       '"participant_bootstrap_mean_fixed_weights": '
                                                                                       'float(np.nanmean(boot)),\n'
                                                                                       '        '
                                                                                       '"participant_bootstrap_ci_low_fixed_weights": '
                                                                                       'boot_low,\n'
                                                                                       '        '
                                                                                       '"participant_bootstrap_ci_high_fixed_weights": '
                                                                                       'boot_high,\n'
                                                                                       '        '
                                                                                       '"participant_bootstrap_p_sign_fixed_weights": '
                                                                                       'bootstrap_sign_p(boot),\n'
                                                                                       '        '
                                                                                       '"p_joint_participant_temporal": '
                                                                                       'two_sided_p(null, estimate),\n'
                                                                                       '        "joint_null_mean": '
                                                                                       'float(np.nanmean(null)),\n'
                                                                                       '        "joint_null_sd": '
                                                                                       'float(np.nanstd(null, '
                                                                                       'ddof=1)),\n'
                                                                                       '        "joint_null_q025": '
                                                                                       'null_low,\n'
                                                                                       '        "joint_null_q975": '
                                                                                       'null_high,\n'
                                                                                       '        "subject_variance": '
                                                                                       'fixed_fit.subject_variance,\n'
                                                                                       '        "pair_variance": '
                                                                                       'fixed_fit.pair_variance,\n'
                                                                                       '        "dataset_variance": '
                                                                                       '0.0,\n'
                                                                                       '        "residual_variance": '
                                                                                       'fixed_fit.residual_variance,\n'
                                                                                       '        '
                                                                                       '"n_repeated_pair_levels": '
                                                                                       'fixed_fit.n_repeated_pair_levels,\n'
                                                                                       '        "n_dataset_levels": '
                                                                                       'len(dataset_order),\n'
                                                                                       '        "n_dyads": '
                                                                                       'int(fixed_fit.fixed_design.shape[0]),\n'
                                                                                       '        "model": (\n'
                                                                                       '            "equal-weight '
                                                                                       'linear contrast of '
                                                                                       'dataset/session fixed effects '
                                                                                       '+ "\n'
                                                                                       '            "shared '
                                                                                       'crossed-subject VC + '
                                                                                       'repeated-dyad pair VC"\n'
                                                                                       '        ),\n'
                                                                                       '        "converged": '
                                                                                       'fixed_fit.converged,\n'
                                                                                       '        "model_warnings": '
                                                                                       'fixed_fit.warnings_text,\n'
                                                                                       '    }\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def summarize_pooled_model(\n'
                                                                                       '    step: str,\n'
                                                                                       '    family: str,\n'
                                                                                       '    dataset_order: list[str],\n'
                                                                                       '    fit: MixedFit,\n'
                                                                                       '    observed: np.ndarray,\n'
                                                                                       '    behavior_bootstrap: '
                                                                                       'np.ndarray,\n'
                                                                                       '    joint_null: np.ndarray,\n'
                                                                                       '):\n'
                                                                                       '    estimate = '
                                                                                       'float(fit.result.fe_params[0])\n'
                                                                                       '    if not '
                                                                                       'np.isclose(observed[0], '
                                                                                       'estimate, atol=2e-5, '
                                                                                       'rtol=2e-5):\n'
                                                                                       '        raise RuntimeError(\n'
                                                                                       '            f"{step} {family}: '
                                                                                       'pooled reconstruction '
                                                                                       'mismatch: "\n'
                                                                                       '            f"{observed[0]} vs '
                                                                                       '{estimate}"\n'
                                                                                       '        )\n'
                                                                                       '    covariance = '
                                                                                       'model_fixed_covariance(fit)\n'
                                                                                       '    se = '
                                                                                       'float(np.sqrt(max(covariance[0, '
                                                                                       '0], 0.0)))\n'
                                                                                       '    z = estimate / se if se > '
                                                                                       '0 else np.nan\n'
                                                                                       '    boot = '
                                                                                       'behavior_bootstrap[:, 0]\n'
                                                                                       '    null = joint_null[:, 0]\n'
                                                                                       '    boot_low, boot_high = '
                                                                                       'quantile_interval(boot)\n'
                                                                                       '    null_low, null_high = '
                                                                                       'quantile_interval(null)\n'
                                                                                       '    return {\n'
                                                                                       '        "step": step,\n'
                                                                                       '        "family": family,\n'
                                                                                       '        "result_type": '
                                                                                       '"pooled_random_dataset",\n'
                                                                                       '        "dataset_or_contrast": '
                                                                                       '"pooled_mean",\n'
                                                                                       '        "estimate": estimate,\n'
                                                                                       '        "mixed_model_se": se,\n'
                                                                                       '        "mixed_model_z": z,\n'
                                                                                       '        '
                                                                                       '"mixed_model_p_normal": '
                                                                                       'float(2 * norm.sf(abs(z))) if '
                                                                                       'np.isfinite(z) else np.nan,\n'
                                                                                       '        "mixed_model_ci_low": '
                                                                                       'estimate - 1.96 * se,\n'
                                                                                       '        "mixed_model_ci_high": '
                                                                                       'estimate + 1.96 * se,\n'
                                                                                       '        '
                                                                                       '"participant_bootstrap_mean_fixed_weights": '
                                                                                       'float(np.nanmean(boot)),\n'
                                                                                       '        '
                                                                                       '"participant_bootstrap_ci_low_fixed_weights": '
                                                                                       'boot_low,\n'
                                                                                       '        '
                                                                                       '"participant_bootstrap_ci_high_fixed_weights": '
                                                                                       'boot_high,\n'
                                                                                       '        '
                                                                                       '"participant_bootstrap_p_sign_fixed_weights": '
                                                                                       'bootstrap_sign_p(boot),\n'
                                                                                       '        '
                                                                                       '"p_joint_participant_temporal": '
                                                                                       'two_sided_p(null, estimate),\n'
                                                                                       '        "joint_null_mean": '
                                                                                       'float(np.nanmean(null)),\n'
                                                                                       '        "joint_null_sd": '
                                                                                       'float(np.nanstd(null, '
                                                                                       'ddof=1)),\n'
                                                                                       '        "joint_null_q025": '
                                                                                       'null_low,\n'
                                                                                       '        "joint_null_q975": '
                                                                                       'null_high,\n'
                                                                                       '        "subject_variance": '
                                                                                       'fit.subject_variance,\n'
                                                                                       '        "pair_variance": '
                                                                                       'fit.pair_variance,\n'
                                                                                       '        "dataset_variance": '
                                                                                       'fit.dataset_variance,\n'
                                                                                       '        "residual_variance": '
                                                                                       'fit.residual_variance,\n'
                                                                                       '        '
                                                                                       '"n_repeated_pair_levels": '
                                                                                       'fit.n_repeated_pair_levels,\n'
                                                                                       '        "n_dataset_levels": '
                                                                                       'len(dataset_order),\n'
                                                                                       '        "n_dyads": '
                                                                                       'int(fit.fixed_design.shape[0]),\n'
                                                                                       '        "model": "pooled '
                                                                                       'intercept + crossed-subject VC '
                                                                                       '+ repeated-dyad pair VC + '
                                                                                       'dataset random-intercept VC",\n'
                                                                                       '        "converged": '
                                                                                       'fit.converged,\n'
                                                                                       '        "model_warnings": '
                                                                                       'fit.warnings_text,\n'
                                                                                       '    }\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '# RUN ONE ANALYSIS STEP\n'
                                                                                       '# '
                                                                                       '=============================================================================\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def save_mixed_summary_text(\n'
                                                                                       '    path: Path,\n'
                                                                                       '    family: str,\n'
                                                                                       '    fixed_fit: MixedFit,\n'
                                                                                       '    pooled_fit: MixedFit | '
                                                                                       'None,\n'
                                                                                       '    pooled_strategy: str,\n'
                                                                                       '):\n'
                                                                                       '    with open(path, "w", '
                                                                                       'encoding="utf-8") as file:\n'
                                                                                       '        file.write(f"FAMILY: '
                                                                                       '{family}\\n\\n")\n'
                                                                                       '        '
                                                                                       'file.write("DATASET-FIXED '
                                                                                       'CROSSED-RANDOM-EFFECTS '
                                                                                       'MODEL\\n")\n'
                                                                                       '        file.write("=" * 80 + '
                                                                                       '"\\n")\n'
                                                                                       '        '
                                                                                       'file.write(str(fixed_fit.result.summary()))\n'
                                                                                       '        '
                                                                                       'file.write("\\n\\nWarnings:\\n" '
                                                                                       '+ fixed_fit.warnings_text + '
                                                                                       '"\\n\\n")\n'
                                                                                       '\n'
                                                                                       '        if pooled_strategy == '
                                                                                       '"random_dataset":\n'
                                                                                       '            if pooled_fit is '
                                                                                       'None:\n'
                                                                                       '                raise '
                                                                                       'RuntimeError("Random-dataset '
                                                                                       'pooled fit is missing")\n'
                                                                                       '            file.write("POOLED '
                                                                                       'RANDOM-DATASET '
                                                                                       'CROSSED-RANDOM-EFFECTS '
                                                                                       'MODEL\\n")\n'
                                                                                       '            file.write("=" * '
                                                                                       '80 + "\\n")\n'
                                                                                       '            '
                                                                                       'file.write(str(pooled_fit.result.summary()))\n'
                                                                                       '            '
                                                                                       'file.write("\\n\\nWarnings:\\n" '
                                                                                       '+ pooled_fit.warnings_text + '
                                                                                       '"\\n")\n'
                                                                                       '        elif pooled_strategy '
                                                                                       '== "fixed_dataset_average":\n'
                                                                                       '            file.write("POOLED '
                                                                                       'FIXED-DATASET MEAN\\n")\n'
                                                                                       '            file.write("=" * '
                                                                                       '80 + "\\n")\n'
                                                                                       '            file.write(\n'
                                                                                       '                "The pooled '
                                                                                       'estimate is the equal-weight '
                                                                                       'linear contrast of "\n'
                                                                                       '                "the '
                                                                                       'dataset/session fixed effects '
                                                                                       'from the model above.\\n"\n'
                                                                                       '                "No '
                                                                                       'dataset/session '
                                                                                       'random-intercept variance is '
                                                                                       'estimated.\\n"\n'
                                                                                       '            )\n'
                                                                                       '        else:\n'
                                                                                       '            raise '
                                                                                       'ValueError(f"Unknown '
                                                                                       'pooled_strategy: '
                                                                                       '{pooled_strategy}")\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def save_dyad_slopes(\n'
                                                                                       '    step_tag: str,\n'
                                                                                       '    family: str,\n'
                                                                                       '    frame: pd.DataFrame,\n'
                                                                                       '):\n'
                                                                                       '    frame.to_csv(\n'
                                                                                       '        OUT_DIR / '
                                                                                       'f"{step_tag}_{family}_dyad_slopes.csv.gz",\n'
                                                                                       '        index=False,\n'
                                                                                       '        compression="gzip",\n'
                                                                                       '    )\n'
                                                                                       '\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'pretty_dataset_label(dataset: '
                                                                                       'str) -> str:\n'
                                                                                       '    mapping = {\n'
                                                                                       '        "movieTP": "TP",\n'
                                                                                       '        "movieDM": "DM",\n'
                                                                                       '        "movieBD": "BD",\n'
                                                                                       '        "horror01": "S1",\n'
                                                                                       '        "horror02": "S2",\n'
                                                                                       '    }\n'
                                                                                       '    return '
                                                                                       'mapping.get(str(dataset), '
                                                                                       'str(dataset))\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'pretty_family_label(family: '
                                                                                       'str) -> str:\n'
                                                                                       '    mapping = {\n'
                                                                                       '        "marginal_valence": '
                                                                                       '"Marginal valence",\n'
                                                                                       '        "marginal_arousal": '
                                                                                       '"Marginal arousal",\n'
                                                                                       '        '
                                                                                       '"conditional_valence_given_arousal": '
                                                                                       '"Valence controlling '
                                                                                       'arousal",\n'
                                                                                       '        '
                                                                                       '"marginal_valence_minus_arousal": '
                                                                                       '"Valence minus arousal",\n'
                                                                                       '        "marginal_fear": '
                                                                                       '"Marginal fear",\n'
                                                                                       '    }\n'
                                                                                       '    return mapping.get(family, '
                                                                                       'family.replace("_", " '
                                                                                       '").title())\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'family_figure_color(family: '
                                                                                       'str) -> str:\n'
                                                                                       '    if family in '
                                                                                       '{"marginal_arousal", '
                                                                                       '"marginal_fear"}:\n'
                                                                                       '        return '
                                                                                       'SECONDARY_COLOR\n'
                                                                                       '    return VALENCE_COLOR\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'full_extent_common_slope_xlim(\n'
                                                                                       '    frame: pd.DataFrame,\n'
                                                                                       '    dataset_order: list[str],\n'
                                                                                       '    model_ci_low: np.ndarray,\n'
                                                                                       '    model_ci_high: '
                                                                                       'np.ndarray,\n'
                                                                                       ') -> tuple[float, float, '
                                                                                       'dict[str, tuple[float, '
                                                                                       'float]], float]:\n'
                                                                                       '    """Return symmetric common '
                                                                                       'limits based on every raw dyad '
                                                                                       'endpoint.\n'
                                                                                       '\n'
                                                                                       '    For each stimulus, its '
                                                                                       'finite raw minimum and maximum '
                                                                                       'are calculated. The\n'
                                                                                       '    largest absolute endpoint '
                                                                                       'across all stimuli is used as '
                                                                                       'the common axis\n'
                                                                                       '    reference. Model '
                                                                                       'confidence-interval endpoints '
                                                                                       'and zero are also retained.\n'
                                                                                       '    A small proportional '
                                                                                       'padding is then added. No '
                                                                                       'percentile trimming is used,\n'
                                                                                       '    so no finite dyad slope is '
                                                                                       'intentionally clipped.\n'
                                                                                       '    """\n'
                                                                                       '    extrema: dict[str, '
                                                                                       'tuple[float, float]] = {}\n'
                                                                                       '    anchors = [0.0]\n'
                                                                                       '\n'
                                                                                       '    for dataset in '
                                                                                       'dataset_order:\n'
                                                                                       '        values = frame.loc[\n'
                                                                                       '            '
                                                                                       'frame["dataset"].astype(str).eq(str(dataset)),\n'
                                                                                       '            "dyad_slope",\n'
                                                                                       '        ].to_numpy(float)\n'
                                                                                       '        values = '
                                                                                       'values[np.isfinite(values)]\n'
                                                                                       '        if len(values) == 0:\n'
                                                                                       '            raise '
                                                                                       'ValueError(f"{dataset}: no '
                                                                                       'finite dyad slopes for axis '
                                                                                       'limits")\n'
                                                                                       '        raw_min = '
                                                                                       'float(np.min(values))\n'
                                                                                       '        raw_max = '
                                                                                       'float(np.max(values))\n'
                                                                                       '        extrema[str(dataset)] '
                                                                                       '= (raw_min, raw_max)\n'
                                                                                       '        '
                                                                                       'anchors.extend([raw_min, '
                                                                                       'raw_max])\n'
                                                                                       '\n'
                                                                                       '    '
                                                                                       'anchors.extend(np.asarray(model_ci_low, '
                                                                                       'dtype=float).tolist())\n'
                                                                                       '    '
                                                                                       'anchors.extend(np.asarray(model_ci_high, '
                                                                                       'dtype=float).tolist())\n'
                                                                                       '    anchors = '
                                                                                       'np.asarray(anchors, '
                                                                                       'dtype=float)\n'
                                                                                       '    anchors = '
                                                                                       'anchors[np.isfinite(anchors)]\n'
                                                                                       '    if len(anchors) == 0:\n'
                                                                                       '        return -1.0, 1.0, '
                                                                                       'extrema, 1.0\n'
                                                                                       '\n'
                                                                                       '    reference_max_abs = '
                                                                                       'float(np.max(np.abs(anchors)))\n'
                                                                                       '    if not '
                                                                                       'np.isfinite(reference_max_abs) '
                                                                                       'or reference_max_abs <= 0:\n'
                                                                                       '        reference_max_abs = '
                                                                                       '0.1\n'
                                                                                       '    padded_max_abs = '
                                                                                       'reference_max_abs * (\n'
                                                                                       '        1.0 + '
                                                                                       'float(DYAD_SLOPE_FIG_XLIM_PADDING_FRACTION)\n'
                                                                                       '    )\n'
                                                                                       '    padded_max_abs += '
                                                                                       'np.finfo(float).eps * max(1.0, '
                                                                                       'padded_max_abs)\n'
                                                                                       '    return -padded_max_abs, '
                                                                                       'padded_max_abs, extrema, '
                                                                                       'reference_max_abs\n'
                                                                                       '\n'
                                                                                       'def '
                                                                                       'plot_dyad_slope_distribution_panels(\n'
                                                                                       '    step_name: str,\n'
                                                                                       '    step_tag: str,\n'
                                                                                       '    family: str,\n'
                                                                                       '    frame: pd.DataFrame,\n'
                                                                                       '    dataset_order: list[str],\n'
                                                                                       '    fixed_fit: MixedFit,\n'
                                                                                       '    fixed_joint_null: '
                                                                                       'np.ndarray,\n'
                                                                                       '):\n'
                                                                                       '    """\n'
                                                                                       '    Plot one stimulus panel '
                                                                                       'per row.\n'
                                                                                       '\n'
                                                                                       '    Each violin is estimated '
                                                                                       'from all Stage-1 dyad slopes '
                                                                                       'for that stimulus.\n'
                                                                                       '    Gray points are an '
                                                                                       'equal-size deterministic '
                                                                                       'subsample for visual texture.\n'
                                                                                       '    The colored point and '
                                                                                       'horizontal interval are the '
                                                                                       'stimulus-specific Stage-2\n'
                                                                                       '    fixed effect and its 95% '
                                                                                       'Wald confidence interval. The '
                                                                                       'annotated p value is\n'
                                                                                       '    the joint '
                                                                                       'neural-and-behavior '
                                                                                       'participant bootstrap plus '
                                                                                       'temporal block-permutation p.\n'
                                                                                       '    """\n'
                                                                                       '    model_estimates = '
                                                                                       'np.asarray(fixed_fit.result.fe_params, '
                                                                                       'dtype=float)\n'
                                                                                       '    covariance = '
                                                                                       'model_fixed_covariance(fixed_fit)\n'
                                                                                       '    model_se = '
                                                                                       'np.sqrt(np.maximum(np.diag(covariance), '
                                                                                       '0.0))\n'
                                                                                       '    model_ci_low = '
                                                                                       'model_estimates - 1.96 * '
                                                                                       'model_se\n'
                                                                                       '    model_ci_high = '
                                                                                       'model_estimates + 1.96 * '
                                                                                       'model_se\n'
                                                                                       '\n'
                                                                                       '    if len(model_estimates) != '
                                                                                       'len(dataset_order):\n'
                                                                                       '        raise ValueError(\n'
                                                                                       '            '
                                                                                       'f"{step_tag}-{family}: '
                                                                                       'fixed-effect count does not '
                                                                                       'match dataset order"\n'
                                                                                       '        )\n'
                                                                                       '    fixed_joint_null = '
                                                                                       'np.asarray(fixed_joint_null, '
                                                                                       'dtype=float)\n'
                                                                                       '    if fixed_joint_null.ndim '
                                                                                       '!= 2 or '
                                                                                       'fixed_joint_null.shape[1] != '
                                                                                       'len(dataset_order):\n'
                                                                                       '        raise ValueError(\n'
                                                                                       '            '
                                                                                       'f"{step_tag}-{family}: invalid '
                                                                                       'fixed joint-null array shape '
                                                                                       '"\n'
                                                                                       '            '
                                                                                       'f"{fixed_joint_null.shape}"\n'
                                                                                       '        )\n'
                                                                                       '\n'
                                                                                       '    x_lower, x_upper, '
                                                                                       'dataset_extrema, '
                                                                                       'reference_max_abs = (\n'
                                                                                       '        '
                                                                                       'full_extent_common_slope_xlim(\n'
                                                                                       '            frame,\n'
                                                                                       '            dataset_order,\n'
                                                                                       '            model_ci_low,\n'
                                                                                       '            model_ci_high,\n'
                                                                                       '        )\n'
                                                                                       '    )\n'
                                                                                       '\n'
                                                                                       '    n_panels = '
                                                                                       'len(dataset_order)\n'
                                                                                       '    fig, axes = plt.subplots(\n'
                                                                                       '        nrows=n_panels,\n'
                                                                                       '        ncols=1,\n'
                                                                                       '        figsize=(10.5, '
                                                                                       'max(4.8, 1.75 * n_panels + '
                                                                                       '1.9)),\n'
                                                                                       '        sharex=True,\n'
                                                                                       '        squeeze=False,\n'
                                                                                       '    )\n'
                                                                                       '    axes = axes[:, 0]\n'
                                                                                       '    effect_color = '
                                                                                       'family_figure_color(family)\n'
                                                                                       '    summary_rows = []\n'
                                                                                       '\n'
                                                                                       '    for index, (axis, dataset) '
                                                                                       'in enumerate(zip(axes, '
                                                                                       'dataset_order)):\n'
                                                                                       '        values = frame.loc[\n'
