                                                        '      regional_allfive_valence_all_results_raw_joint_p.csv\n'
                                                        '      '
                                                        'regional_allfive_valence_all_results_joint_p_and_FDR_q.csv\n'
                                                        '      '
                                                        'regional_allfive_valence_pooled_key_results_joint_p_and_FDR_q.csv\n'
                                                        '      regional_allfive_valence_FDR_significant_q_lt_0.05.csv\n'
                                                        '      DMN_BA_regional_definition.csv\n'
                                                        '      BA_*/...\n'
                                                        '"""\n'
                                                        '\n'
                                                        'from pathlib import Path\n'
                                                        'import importlib.util\n'
                                                        'import sys\n'
                                                        'import gc\n'
                                                        '\n'
                                                        'import numpy as np\n'
                                                        'import pandas as pd\n'
                                                        '\n'
                                                        '\n'
                                                        '# '
                                                        '=============================================================================\n'
                                                        '# LOAD THE EXISTING V5 PIPELINE AS A MODULE\n'
                                                        '# '
                                                        '=============================================================================\n'
                                                        '\n'
                                                        'SCRIPT_DIR = Path(__file__).resolve().parent\n'
                                                        'BASE_SCRIPT = (\n'
                                                        '    SCRIPT_DIR\n'
                                                        '    / '
                                                        '"Chen_style_allWindow_DMN_regional_BA_ALLFIVE_DIRECT_BEHAVIOR_V5_NEURAL_SAMPLING.py"\n'
                                                        ')\n'
                                                        '\n'
                                                        'if not BASE_SCRIPT.exists():\n'
                                                        '    raise FileNotFoundError(\n'
                                                        '        f"Base V5 pipeline not found:\\n{BASE_SCRIPT}\\n\\n"\n'
                                                        '        "Place this script beside the existing V5 '
                                                        'all-five/regional pipeline."\n'
                                                        '    )\n'
                                                        '\n'
                                                        'spec = importlib.util.spec_from_file_location(\n'
                                                        '    "chen_v5_base_for_regional_allfive",\n'
                                                        '    BASE_SCRIPT,\n'
                                                        ')\n'
                                                        'if spec is None or spec.loader is None:\n'
                                                        '    raise ImportError(f"Cannot import base V5 pipeline: '
                                                        '{BASE_SCRIPT}")\n'
                                                        '\n'
                                                        'C = importlib.util.module_from_spec(spec)\n'
                                                        'sys.modules["chen_v5_base_for_regional_allfive"] = C\n'
                                                        'spec.loader.exec_module(C)\n'
                                                        '\n'
                                                        '\n'
                                                        '# '
                                                        '=============================================================================\n'
                                                        '# CONFIG\n'
                                                        '# '
                                                        '=============================================================================\n'
                                                        '\n'
                                                        'VARIANT = C.ALL_WINDOW_VARIANT\n'
                                                        '\n'
                                                        '# Reuse existing caches/draws whenever possible.\n'
                                                        'C.RESUME = True\n'
                                                        'C.FORCE_REBUILD_PAIR_CACHE = False\n'
                                                        '\n'
                                                        '# Keep the same five observed datasets and order as the '
                                                        'whole-DMN all-five model.\n'
                                                        'DATASET_ORDER = list(C.ALL_FIVE_DATASETS)\n'
                                                        '\n'
                                                        '# We only need the pooled regional all-five valence '
                                                        'hypothesis.\n'
                                                        'FDR_ALPHA = float(C.REGIONAL_FDR_ALPHA)\n'
                                                        '\n'
                                                        '\n'
                                                        '# '
                                                        '=============================================================================\n'
                                                        '# SMALL HELPERS\n'
                                                        '# '
                                                        '=============================================================================\n'
                                                        '\n'
                                                        'def load_saved_permutation_plans(path: Path) -> dict[str, '
                                                        'np.ndarray]:\n'
                                                        '    """Load the exact temporal block-permutation plans saved '
                                                        'by the V5 run."""\n'
                                                        '    with np.load(path, allow_pickle=False) as archive:\n'
                                                        '        plans = {key: np.asarray(archive[key]) for key in '
                                                        'archive.files}\n'
                                                        '\n'
                                                        '    required = {\n'
                                                        '        "S1::movieTP",\n'
                                                        '        "S1::movieDM",\n'
                                                        '        "S1::movieBD",\n'
                                                        '        "S2::horror01",\n'
                                                        '        "S2::horror02",\n'
                                                        '    }\n'
                                                        '    missing = sorted(required - set(plans))\n'
                                                        '    if missing:\n'
                                                        '        raise RuntimeError(\n'
                                                        '            f"Saved permutation plan is missing required '
                                                        'keys: {missing}"\n'
                                                        '        )\n'
                                                        '    return plans\n'
                                                        '\n'
                                                        '\n'
                                                        'def add_regional_allfive_fdr(results: pd.DataFrame) -> '
                                                        'pd.DataFrame:\n'
                                                        '    """\n'
                                                        '    BH-FDR across the pooled all-five marginal-valence effect '
                                                        'for every BA region.\n'
                                                        '\n'
                                                        '    Dataset-specific effects, heterogeneity tests, and '
                                                        'pairwise dataset contrasts\n'
                                                        '    remain in the table but are not included in this regional '
                                                        'pooled hypothesis\n'
                                                        '    family.\n'
                                                        '    """\n'
                                                        '    output = results.copy()\n'
                                                        '\n'
                                                        '    output["joint_p"] = pd.to_numeric(\n'
                                                        '        output["p_joint_participant_temporal"],\n'
                                                        '        errors="coerce",\n'
                                                        '    )\n'
                                                        '    output["q_joint_fdr_bh"] = np.nan\n'
                                                        '    output["q_fdr_bh"] = np.nan\n'
                                                        '    output["fdr_family"] = pd.Series(pd.NA, '
                                                        'index=output.index, dtype="object")\n'
                                                        '    output["fdr_n_tests"] = 0\n'
                                                        '    output["fdr_alpha"] = FDR_ALPHA\n'
                                                        '    output["fdr_scope"] = pd.Series(pd.NA, '
                                                        'index=output.index, dtype="object")\n'
                                                        '\n'
                                                        '    pooled_mask = (\n'
                                                        '        output["family"].astype(str).eq("marginal_valence")\n'
                                                        '        & '
                                                        'output["result_type"].astype(str).eq("pooled_fixed_dataset_mean")\n'
                                                        '        & output["dataset_or_contrast"].astype(str).eq(\n'
                                                        '            "equal_weight_pooled_mean"\n'
                                                        '        )\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    pooled_indices = output.index[pooled_mask]\n'
                                                        '    if len(pooled_indices) == 0:\n'
                                                        '        raise RuntimeError("No pooled regional all-five '
                                                        'valence rows were found.")\n'
                                                        '\n'
                                                        '    p_values = output.loc[pooled_indices, '
                                                        '"joint_p"].to_numpy(float)\n'
                                                        '    finite = np.isfinite(p_values)\n'
                                                        '    if not np.all(finite):\n'
                                                        '        bad_regions = output.loc[\n'
                                                        '            pooled_indices[~finite],\n'
                                                        '            "ba_label",\n'
                                                        '        ].astype(str).tolist()\n'
                                                        '        raise RuntimeError(\n'
                                                        '            "Non-finite pooled joint p values for regional '
                                                        'all-five effects: "\n'
                                                        '            f"{bad_regions}"\n'
                                                        '        )\n'
                                                        '\n'
                                                        '    q_values = C.benjamini_hochberg(p_values)\n'
                                                        '\n'
                                                        '    family_name = '
                                                        'f"AllFive_regional_pooled_valence_{len(pooled_indices)}"\n'
                                                        '    scope = (\n'
                                                        '        "BH across pooled equal-weight all-five '
                                                        'marginal-valence effects "\n'
                                                        '        f"for {len(pooled_indices)} DMN BA regions"\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    output.loc[pooled_indices, "q_joint_fdr_bh"] = q_values\n'
                                                        '    output.loc[pooled_indices, "q_fdr_bh"] = q_values\n'
                                                        '    output.loc[pooled_indices, "fdr_family"] = family_name\n'
                                                        '    output.loc[pooled_indices, "fdr_n_tests"] = '
                                                        'len(pooled_indices)\n'
                                                        '    output.loc[pooled_indices, "fdr_scope"] = scope\n'
                                                        '\n'
                                                        '    output["fdr_significant_q_lt_0_05"] = (\n'
                                                        '        pd.to_numeric(output["q_joint_fdr_bh"], '
                                                        'errors="coerce") < FDR_ALPHA\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    preferred = [\n'
                                                        '        "analysis_level",\n'
                                                        '        "study_id",\n'
                                                        '        "ba_label",\n'
                                                        '        "region_key",\n'
                                                        '        "n_dmn_rois",\n'
                                                        '        "family",\n'
                                                        '        "result_type",\n'
                                                        '        "dataset_or_contrast",\n'
                                                        '        "estimate",\n'
                                                        '        "mixed_model_se",\n'
                                                        '        "mixed_model_ci_low",\n'
                                                        '        "mixed_model_ci_high",\n'
                                                        '        "p_joint_participant_temporal",\n'
                                                        '        "joint_p",\n'
                                                        '        "q_joint_fdr_bh",\n'
                                                        '        "q_fdr_bh",\n'
                                                        '        "fdr_significant_q_lt_0_05",\n'
                                                        '        "fdr_family",\n'
                                                        '        "fdr_n_tests",\n'
                                                        '        "fdr_alpha",\n'
                                                        '        "fdr_scope",\n'
                                                        '    ]\n'
                                                        '    ordered = [x for x in preferred if x in output.columns]\n'
                                                        '    ordered += [x for x in output.columns if x not in '
                                                        'ordered]\n'
                                                        '    return output[ordered]\n'
                                                        '\n'
                                                        '\n'
                                                        '# '
                                                        '=============================================================================\n'
                                                        '# MAIN\n'
                                                        '# '
                                                        '=============================================================================\n'
                                                        '\n'
                                                        'def main():\n'
                                                        '    C.print_section("REGIONAL ALL-FIVE POOLED VALENCE ONLY | '
                                                        'V5")\n'
                                                        '    print("[TARGET] One equal-weight pooled valence effect '
                                                        'per DMN BA region")\n'
                                                        '    print("[DATASETS] " + ", ".join(DATASET_ORDER))\n'
                                                        '    print(f"[N_RESAMPLES] {C.N_RESAMPLES:,}")\n'
                                                        '    print("[FDR] BH across pooled regional all-five valence '
                                                        'effects only")\n'
                                                        '\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    # Freshly import the exact Study 1 / Study 2 source '
                                                        'modules used by V5\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    S1 = C.load_python_module(\n'
                                                        '        C.STUDY1_SCRIPT,\n'
                                                        '        "study1_regional_allfive_v4_only",\n'
                                                        '    )\n'
                                                        '    S2 = C.load_python_module(\n'
                                                        '        C.STUDY2_SCRIPT,\n'
                                                        '        "study2_regional_allfive_v4_only",\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    if getattr(S1, "CHEN_ALIGNMENT_POLICY_VERSION", None) != '
                                                        'C.EXPECTED_STUDY1_ALIGNMENT_VERSION:\n'
                                                        '        raise RuntimeError(\n'
                                                        '            "The required strict-alignment Study 1 source is '
                                                        'not loaded."\n'
                                                        '        )\n'
                                                        '    if getattr(S2, "CHEN_ALIGNMENT_POLICY_VERSION", None) != '
                                                        'C.EXPECTED_STUDY2_ALIGNMENT_VERSION:\n'
                                                        '        raise RuntimeError(\n'
                                                        '            "The required strict-alignment Study 2 source is '
                                                        'not loaded."\n'
                                                        '        )\n'
                                                        '    if Path(S1.BASE_DIR) != Path(S2.BASE_DIR):\n'
                                                        '        raise ValueError(\n'
                                                        '            f"Study 1 and Study 2 BASE_DIR differ:\\n"\n'
                                                        '            f"{S1.BASE_DIR}\\n{S2.BASE_DIR}"\n'
                                                        '        )\n'
                                                        '\n'
                                                        '    # This is a post-hoc/add-on run: reuse pairwise caches if '
                                                        'present.\n'
                                                        '    S1.REBUILD_PAIR_CACHE = False\n'
                                                        '    S2.REBUILD_PAIR_CACHE = False\n'
                                                        '    S2.RESUME_RESAMPLING = True\n'
                                                        '\n'
                                                        '    # Keep the exact movieBD location and source cache '
                                                        'namespace,\n'
                                                        '    # but do NOT force cache rebuilding.\n'
                                                        '    C.configure_moviebd_source(S1)\n'
                                                        '    S1.REBUILD_PAIR_CACHE = False\n'
                                                        '\n'
                                                        '    root_out_dir = (\n'
                                                        '        C.RESULTS_ROOT\n'
                                                        '        / "slidingWindow_isc"\n'
                                                        '        / '
                                                        '"Chen_style_two_stage_ALLFIVE_NEURAL_BEHAVIOR_SAMPLING_20260807_V5"\n'
                                                        '    )\n'
                                                        '    whole_dmn_out_dir = root_out_dir / "whole_DMN_analysis"\n'
                                                        '    regional_allfive_out_dir = (\n'
                                                        '        root_out_dir / '
                                                        '"regional_all_five_observed_dataset_average"\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    regional_allfive_out_dir.mkdir(parents=True, '
                                                        'exist_ok=True)\n'
                                                        '\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    # Prepare shared source data\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    C.print_section("PREPARING SHARED SOURCE DATA")\n'
                                                        '\n'
                                                        '    s1_prepared = S1.prepare_all_data()\n'
                                                        '    n_behavior = len(s1_prepared["behavior_master_ids"])\n'
                                                        '    s1_unit_neural = {\n'
                                                        '        dataset: np.ones(\n'
                                                        '            '
                                                        'len(s1_prepared["neural_caches"][S1.ROI_NAME][dataset]["subject_ids"]),\n'
                                                        '            dtype=float,\n'
                                                        '        )\n'
                                                        '        for dataset in S1.MOVIES\n'
                                                        '    }\n'
                                                        '\n'
                                                        '    s1_observed_full = S1.build_window_table(\n'
                                                        '        s1_prepared,\n'
                                                        '        S1.ROI_NAME,\n'
                                                        '        s1_unit_neural,\n'
                                                        '        np.ones(n_behavior, dtype=float),\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    s2_prepared = S2.prepare_all_data()\n'
                                                        '    s2_observed_full = S2.build_window_table(\n'
                                                        '        s2_prepared,\n'
                                                        '        np.ones(len(s2_prepared["common_ids"]), '
                                                        'dtype=float),\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    print(\n'
                                                        '        f"[Study 2 N] {len(s2_prepared[\'common_ids\'])} '
                                                        'participants "\n'
                                                        '        f"-> {len(s2_prepared[\'common_ids\']) * '
                                                        '(len(s2_prepared[\'common_ids\']) - 1) // 2:,} "\n'
                                                        '        "dyads/session"\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    # Reconstruct the exact all-window retained timelines.\n'
                                                        '    # We do not need to rerun the whole-DMN mixed models.\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    s1_observed, _ = C.build_variant_window_table(\n'
                                                        '        observed_full=s1_observed_full,\n'
                                                        '        prepared=s1_prepared,\n'
                                                        '        dataset_column="movie",\n'
                                                        '        dataset_order=S1.MOVIES,\n'
                                                        '        affects=S1.AFFECTS,\n'
                                                        '        model_covariates=S1.MODEL_COVARIATES,\n'
                                                        '        behavior_cache_getter=(\n'
                                                        '            lambda p, dataset, affect:\n'
                                                        '            p["behavior_caches"][dataset][affect]\n'
                                                        '        ),\n'
                                                        '        standardized_columns=[\n'
                                                        '            "z_neural_ISC",\n'
                                                        '            "z_valence_ISC",\n'
                                                        '            "z_arousal_ISC",\n'
                                                        '        ],\n'
                                                        '        variant=VARIANT,\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    s2_observed, _ = C.build_variant_window_table(\n'
                                                        '        observed_full=s2_observed_full,\n'
                                                        '        prepared=s2_prepared,\n'
                                                        '        dataset_column="session",\n'
                                                        '        dataset_order=S2.SESSIONS,\n'
                                                        '        affects=S2.AFFECTS,\n'
                                                        '        model_covariates=S2.MODEL_COVARIATES,\n'
                                                        '        behavior_cache_getter=(\n'
                                                        '            lambda p, dataset, affect:\n'
                                                        '            p["behavior_caches"][dataset][affect]\n'
                                                        '        ),\n'
                                                        '        standardized_columns=[\n'
                                                        '            "z_neural_ISC",\n'
                                                        '            "z_valence_ISC",\n'
                                                        '            "z_fear_ISC",\n'
                                                        '        ],\n'
                                                        '        variant=VARIANT,\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    # Reuse the exact 10,000 behavioral-bootstrap residual '
                                                        'trajectories from\n'
                                                        '    # the whole-DMN V5 run. If absent, these functions create '
                                                        'them.\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    C.print_section("LOADING EXISTING BEHAVIOR BOOTSTRAP '
                                                        'RESIDUAL TRAJECTORIES")\n'
                                                        '\n'
                                                        '    whole_draw_dir = whole_dmn_out_dir / "resampling_draws"\n'
                                                        '    whole_draw_dir.mkdir(parents=True, exist_ok=True)\n'
                                                        '\n'
                                                        '    C.DRAW_DIR = whole_draw_dir\n'
                                                        '    C.RESUME = True\n'
                                                        '\n'
                                                        '    C.print_section("BUILDING / LOADING SOURCE PARTICIPANT '
                                                        'BOOTSTRAP PLANS")\n'
                                                        '    s1_bootstrap_plan = '
                                                        'S1.generate_bootstrap_weight_plan(s1_prepared)\n'
                                                        '    s2_bootstrap_plan = '
                                                        'S2.generate_bootstrap_weight_plan(s2_prepared)\n'
                                                        '    neural_bootstrap_plans = C.build_neural_bootstrap_plans(\n'
                                                        '        S1,\n'
                                                        '        S2,\n'
                                                        '        s1_bootstrap_plan,\n'
                                                        '        s2_bootstrap_plan,\n'
                                                        '        s1_prepared=s1_prepared,\n'
                                                        '        s2_prepared=s2_prepared,\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    s1_bootstrap = '
                                                        'C.prepare_study1_behavior_bootstrap_variant(\n'
                                                        '        S1,\n'
                                                        '        s1_prepared,\n'
                                                        '        s1_observed_full,\n'
                                                        '        s1_observed,\n'
                                                        '        VARIANT,\n'
                                                        '        bootstrap_plan=s1_bootstrap_plan,\n'
                                                        '    )\n'
                                                        '    s2_bootstrap = '
                                                        'C.prepare_study2_behavior_bootstrap_variant(\n'
                                                        '        S2,\n'
                                                        '        s2_prepared,\n'
                                                        '        s2_observed_full,\n'
                                                        '        s2_observed,\n'
                                                        '        VARIANT,\n'
                                                        '        bootstrap_plan=s2_bootstrap_plan,\n'
                                                        '    )\n'
                                                        '    bootstrap_maps = {**s1_bootstrap, **s2_bootstrap}\n'
                                                        '\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    # Reuse the exact temporal block-permutation plans from '
                                                        'the V5 run.\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    permutation_path = (\n'
                                                        '        whole_draw_dir / '
                                                        '"Chen_temporal_block_index_plans.npz"\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    if permutation_path.exists():\n'
                                                        '        C.print_section("LOADING EXISTING TEMPORAL '
                                                        'BLOCK-PERMUTATION PLANS")\n'
                                                        '        permutation_plans = '
                                                        'load_saved_permutation_plans(permutation_path)\n'
                                                        '        print(f"[LOADED] {permutation_path}")\n'
                                                        '\n'
                                                        '    else:\n'
                                                        '        # Fallback only if the original whole-DMN permutation '
                                                        'file is absent.\n'
                                                        '        # Rebuild the same deterministic plans from the same '
                                                        'retained timelines.\n'
                                                        '        C.print_section(\n'
                                                        '            "PERMUTATION PLAN NOT FOUND -- REBUILDING '
                                                        'DETERMINISTIC V5 PLANS"\n'
                                                        '        )\n'
                                                        '        fallback_dir = regional_allfive_out_dir / '
                                                        '"_fallback_plan_setup"\n'
                                                        '        fallback_dir.mkdir(parents=True, exist_ok=True)\n'
                                                        '\n'
                                                        '        C.OUT_DIR = fallback_dir\n'
                                                        '        C.DRAW_DIR = whole_draw_dir\n'
                                                        '        C.FIG_DIR = fallback_dir / "figures"\n'
                                                        '        C.FIG_DIR.mkdir(parents=True, exist_ok=True)\n'
                                                        '\n'
                                                        '        (\n'
                                                        '            _,\n'
                                                        '            s1_whole_families,\n'
                                                        '            _,\n'
                                                        '            s1_segments,\n'
                                                        '            s1_blocks,\n'
                                                        '            _,\n'
                                                        '        ) = C.prepare_study1_variant(\n'
                                                        '            S1,\n'
                                                        '            s1_prepared,\n'
                                                        '            s1_observed_full,\n'
                                                        '            VARIANT,\n'
                                                        '        )\n'
                                                        '\n'
                                                        '        (\n'
                                                        '            _,\n'
                                                        '            s2_whole_families,\n'
                                                        '            _,\n'
                                                        '            s2_segments,\n'
                                                        '            s2_blocks,\n'
                                                        '            _,\n'
                                                        '        ) = C.prepare_study2_variant(\n'
                                                        '            S2,\n'
                                                        '            s2_prepared,\n'
                                                        '            s2_observed_full,\n'
                                                        '            VARIANT,\n'
                                                        '        )\n'
                                                        '\n'
                                                        '        permutation_plans = '
                                                        'C.build_permutation_plans_variant(\n'
                                                        '            s1_blocks,\n'
                                                        '            s2_blocks,\n'
                                                        '            s1_whole_families,\n'
                                                        '            s2_whole_families,\n'
                                                        '            s1_segments,\n'
                                                        '            s2_segments,\n'
                                                        '            VARIANT,\n'
                                                        '        )\n'
                                                        '\n'
                                                        '        del s1_whole_families, s2_whole_families\n'
                                                        '        gc.collect()\n'
                                                        '\n'
                                                        '    # Exactly the same cross-study pairing rule as the '
                                                        'whole-DMN all-five run.\n'
                                                        '    independent_bootstrap_rows = (\n'
                                                        '        C.build_independent_cross_study_bootstrap_pairing()\n'
                                                        '    )\n'
                                                        '\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    # Resolve the regional BA definitions.\n'
                                                        '    # '
                                                        '-------------------------------------------------------------------------\n'
                                                        '    s1_regions, s1_region_metadata = '
                                                        'C.resolve_dmn_ba_regions(\n'
