def _code_dir() -> Path:
    if "__file__" in globals():
        return Path(__file__).resolve().parent
    return Path.cwd().resolve()


def _project_root(code_dir: Path) -> Path:
    for parent in [code_dir, *code_dir.parents]:
        if (parent / "data").exists() or (parent / "results").exists():
            return parent
    if code_dir.parent.name == "code":
        return code_dir.parent.parent
    return code_dir.parent


CODE = _code_dir()
ROOT = _project_root(CODE)
DATA = ROOT / "data"
RESULTS = ROOT / "results"


def mixed_model_design_template() -> str:
    """Return a CSV example with fake labels only."""
    return (
        "dataset_key,local_subject_i,local_subject_j,crossed_participant_i,"
        "crossed_participant_j,repeated_dyad_id,dataset_fixed_level\n"
        "dataset_A,local_A01,local_A02,person_001,person_002,dyad_001,level_A\n"
        "dataset_B,local_B01,local_B02,person_001,person_002,dyad_001,level_B\n"
    )


def configure_mixed_model_design(path: str | Path) -> None:
    """Point the bundled primary analysis to a local Stage-2 design CSV."""
    os.environ["VISC_MIXED_MODEL_DESIGN_PATH"] = str(Path(path).expanduser())

